englishA2Plans[83]={"title": "Hospedagem em casa de família", "file": "", "grammar": "Present perfect com particípios irregulares", "goal": "Use have seen, have eaten e have gone para contar novidades.", "words": [["host family", "família anfitriã"], ["guest room", "quarto de hóspedes"], ["curfew", "hora de recolher"], ["make yourself at home", "sinta-se em casa"], ["spare", "extra, de reserva"], ["sheet", "lençol"], ["accent", "sotaque"], ["excited", "animado"]]};
englishA2Content[83]=[[["Noah is an exchange student, and he is excited about his new host family.", "Noah é um intercambista e está animado com sua nova família anfitriã."], ["He has seen his guest room, and there are clean sheets on the bed.", "Ele viu o quarto de hóspedes, e há lençóis limpos na cama."], ["Mrs. Lee has gone to the store for a spare towel.", "A Sra. Lee foi à loja comprar uma toalha extra."], ["Noah has eaten lunch with the family, and he loves the food.", "Noah almoçou com a família, e adora a comida."], ["Everyone likes his accent, but the curfew is ten o'clock.", "Todos gostam do sotaque dele, mas a hora de recolher é às dez."], ["\"Make yourself at home,\" says Mrs. Lee.", "\"Sinta-se em casa\", diz a Sra. Lee."]], [["Welcome, Noah! How was your trip?", "Bem-vindo, Noah! Como foi a viagem?"], ["Long, but good. I've seen a lot of clouds, and I've eaten two sandwiches.", "Longa, mas boa. Eu vi muitas nuvens e comi dois sanduíches."], ["Poor boy! Come in and settle in. Your room is upstairs.", "Coitado! Entre e fique à vontade. Seu quarto fica lá em cima."], ["It's great! It's bigger than my room in the dorm.", "É ótimo! É maior que meu quarto no alojamento."], ["I'm glad. Mr. Lee is not here. He has gone to work, but he's coming home at six.", "Que bom. O Sr. Lee não está aqui. Ele foi trabalhar, mas volta às seis."], ["Okay. What time is the curfew? I want to see the city at night.", "Certo. Qual é o horário de recolher? Quero ver a cidade à noite."], ["The curfew is ten o'clock on school days. Please call me and say you're late.", "O horário é dez horas nos dias de aula. Por favor, me ligue e avise que você vai se atrasar."], ["Sure, no problem. I have your number in my phone.", "Claro, sem problema. Tenho seu número no meu telefone."]], ["/ɜr/ em curfew e first", "Em curfew e work, a língua fica no meio da boca, sem encostar, e o R vem junto da vogal, como um som preso. Não abra um E claro em curfew nem diga uóqui em work.", ["curfew", "work"]], ["Mrs. Lee has ___ to the store.", "gone", "went", "A Sra. Lee foi à loja.", "Depois de has usamos o particípio, e o particípio de go é gone."], [["He has seen his guest room, and there are clean sheets on the bed.", "Ele viu o quarto de hóspedes, e há lençóis limpos na cama."], ["Mrs. Lee has gone to the store for a spare towel.", "A Sra. Lee foi à loja comprar uma toalha extra."]], [{"t": "c", "q": "Noah has ___ lunch with the family.", "o": ["eaten", "ate", "eat"], "pt": "Noah almoçou com a família.", "why": "Depois de has usamos o particípio, e o particípio de eat é eaten."}, {"t": "l", "say": "He has seen his guest room.", "o": ["He has seen his guest room.", "He has seen his best room.", "He has seen her guest room."], "why": "A frase fala do quarto de hóspedes dele (his guest room)."}, {"t": "b", "pt": "A Sra. Lee foi à loja.", "w": ["Mrs.", "Lee", "has", "gone", "to", "the", "store"]}, {"t": "b", "pt": "Eu tomei café da manhã com a família.", "w": ["I", "have", "eaten", "breakfast", "with", "the", "family"]}]];
