englishA2Plans[85]={"title": "Agência dos correios", "file": "", "grammar": "Present perfect em perguntas: Have you ever...?", "goal": "Pergunte sobre experiências usando Have you ever.", "words": [["courier", "entregador"], ["postage", "franquia postal"], ["tracking number", "código de rastreio"], ["sign for", "assinar o recebimento"], ["package", "pacote"], ["fragile", "frágil"], ["weigh", "pesar"], ["insured", "com seguro"]]};
englishA2Content[85]=[[["Tom is at the post office with a parcel for his sister, an exchange student.", "Tom está nos correios com uma encomenda para a irmã, que é intercambista."], ["The clerk needs to weigh it before he sells the postage.", "O atendente precisa pesar a encomenda antes de vender a franquia postal."], ["The parcel is fragile, so Tom wants it insured.", "A encomenda é frágil, então Tom quer que ela tenha seguro."], ["The clerk gives him a tracking number.", "O atendente dá a ele um código de rastreio."], ["Tom has used a courier before, but this is cheaper.", "Tom já usou um entregador antes, mas isto é mais barato."], ["His sister must sign for the parcel on Monday.", "A irmã dele precisa assinar o recebimento da encomenda na segunda."]], [["Hi. I'd like to send this package to my sister's dorm in Chicago.", "Oi. Eu gostaria de enviar este pacote para o alojamento da minha irmã em Chicago."], ["Have you ever sent a package to Chicago?", "Você já enviou um pacote para Chicago alguma vez?"], ["Yes, I have, but it was a letter.", "Já, mas era uma carta."], ["Okay. Please put it on the scale. Let me weigh it. Two pounds. Is anything inside fragile?", "Certo. Por favor, ponha na balança. Deixe-me pesar. Um quilo. Tem algo frágil aí dentro?"], ["Yes, there's a glass bowl. Can you get it insured? I'm a little worried.", "Tem, uma tigela de vidro. Você pode colocar seguro? Estou um pouco preocupado."], ["Of course. Does she live on campus? The postage is fourteen dollars, and you get a tracking number.", "Claro. Ela mora no campus? A franquia é de quatorze dólares, e você recebe um código de rastreio."], ["Have you ever lost a package here?", "Vocês já perderam um pacote aqui alguma vez?"], ["No, we haven't. The courier is very careful, and your sister can sign for it on Monday.", "Não, nunca. O entregador é muito cuidadoso, e sua irmã pode assinar o recebimento na segunda."]], ["/p/ em parcel e post", "Em parcel e post, feche os lábios e solte o ar com um pequeno sopro, como se apagasse uma vela de leve. Em inglês, o P no começo da palavra é mais aspirado que em português.", ["parcel", "post"]], ["___ you ever sent a package?", "Have", "Did", "Você já enviou um pacote alguma vez?", "Para perguntar sobre experiências até hoje, usamos Have you ever + particípio."], [["Have you ever sent a package to Chicago?", "Você já enviou um pacote para Chicago alguma vez?"], ["Have you ever lost a package here?", "Vocês já perderam um pacote aqui alguma vez?"]], [{"t": "c", "q": "Have you ever ___ a courier?", "o": ["used", "use", "using"], "pt": "Você já usou um entregador alguma vez?", "why": "Depois de Have you ever usamos o particípio: used."}, {"t": "l", "say": "Have you ever sent a package?", "o": ["Have you ever sent a package?", "Did you ever send a package?", "Have you ever seen a package?"], "why": "A pergunta usa Have you ever e o particípio sent (enviado)."}, {"t": "b", "pt": "Você já mandou uma encomenda?", "w": ["Have", "you", "ever", "sent", "a", "parcel"]}, {"t": "b", "pt": "Eu já usei um entregador.", "w": ["I", "have", "used", "a", "courier"]}]];
