englishA2Plans[96]={"title": "Viagem de trem entre cidades", "file": "", "grammar": "Past continuous afirmativo", "goal": "Diga o que estava acontecendo em um momento do passado.", "words": [["railway", "ferrovia"], ["timetable", "quadro de horários"], ["carriage", "vagão"], ["on board", "a bordo"], ["scenery", "paisagem"], ["snore", "roncar"], ["announcement", "aviso (no alto-falante)"], ["goats", "cabras"], ["stuck", "parado, preso"]]};
englishA2Content[96]=[[["At nine o'clock, the train was leaving the railway station.", "Às nove horas, o trem estava saindo da estação ferroviária."], ["Sara was sitting in the first carriage.", "Sara estava sentada no primeiro vagão."], ["She was reading about a marathon.", "Ela estava lendo sobre uma maratona."], ["Paul was looking at the timetable.", "Paul estava olhando o quadro de horários."], ["A man next to them was snoring.", "Um homem ao lado deles estava roncando."], ["Outside, goats were eating grass, and the scenery was beautiful.", "Lá fora, cabras estavam comendo grama, e a paisagem estava linda."]], [["Paul, did you hear the announcement? The train is stuck.", "Paul, você ouviu o aviso? O trem está parado."], ["No, I didn't. I was looking at the timetable. What happened?", "Não, não ouvi. Eu estava olhando o quadro de horários. O que aconteceu?"], ["There is a problem on the railway. The conductor is talking to the driver now.", "Há um problema na ferrovia. O condutor está falando com o maquinista agora."], ["Oh no. I was reading about a marathon, so I didn't notice anything.", "Ah, não. Eu estava lendo sobre uma maratona, então não percebi nada."], ["I was texting my coworker, but my phone has no signal.", "Eu estava mandando mensagem para o meu colega de trabalho, mas meu celular está sem sinal."], ["Mine, too. I have canned food in my bag, so we can wait.", "O meu também. Tenho comida enlatada na mochila, então podemos esperar."], ["Look, the conductor is coming. Let's ask him together.", "Olha, o condutor está vindo. Vamos perguntar a ele juntos."], ["Good idea. I'm sure everyone on board wants to know.", "Boa ideia. Tenho certeza de que todo mundo a bordo quer saber."]], ["/ɒ/ em conductor e on board", "Em conductor e board, o /ɒ/ é um \"o\" aberto; no inglês americano soa quase como um \"a\" aberto. Abra bem a boca e deixe a língua baixa.", ["conductor", "board"]], ["In the photo, she ___ out of the window.", "was looking", "were looking", "Na foto, ela estava olhando pela janela.", "Com she usamos was + verbo com -ing; were é para you, we e they."], [["Sara was sitting in the first carriage.", "Sara estava sentada no primeiro vagão."], ["Paul was looking at the timetable.", "Paul estava olhando o quadro de horários."]], [{"t": "c", "q": "The goats ___ on the grass.", "o": ["were eating", "was eating", "were eat"], "pt": "As cabras estavam comendo na grama.", "why": "Goats é plural: were + verbo com -ing."}, {"t": "l", "say": "I was reading the timetable.", "o": ["I was reading the timetable.", "I were reading the timetable.", "I was read the timetable."], "why": "Com I usamos was, e o verbo leva -ing."}, {"t": "b", "pt": "Eles estavam esperando no vagão.", "w": ["They", "were", "waiting", "in", "the", "carriage"]}, {"t": "b", "pt": "Paul estava olhando o quadro de horários.", "w": ["Paul", "was", "looking", "at", "the", "timetable"]}]];
