englishA2Plans[106]={"title": "Promessas de Ano Novo", "file": "", "grammar": "Won't para promessas e recusas", "goal": "Faça promessas e recusas com won't.", "words": [["resolution", "resolução"], ["diet", "dieta"], ["habit", "hábito"], ["stick to", "manter-se fiel a"], ["promise", "prometer"], ["quit", "desistir, parar de"], ["save", "economizar"], ["budget", "orçamento"], ["lazy", "preguiçoso"]]};
englishA2Content[106]=[[["It's December 31, and Nina has a big resolution.", "É 31 de dezembro, e Nina tem uma grande resolução."], ["She is on a diet, so she won't eat cake tonight.", "Ela está de dieta, então não vai comer bolo hoje à noite."], ["Her brother Noah says, \"I won't be lazy this year.\"", "O irmão dela, Noah, diz: \"Eu não vou ser preguiçoso este ano.\""], ["He wants to save money, so he made a budget.", "Ele quer economizar dinheiro, por isso fez um orçamento."], ["Their grandparents also have a vision: more walks and less TV.", "Os avós deles também têm uma visão: mais caminhadas e menos TV."], ["They write their goals on paper, and they promise to stick to them all year.", "Eles escrevem as metas no papel e prometem manter-se fiéis a elas o ano todo."]], [["Noah, what is your resolution for this year?", "Noah, qual é a sua resolução para este ano?"], ["I won't waste money anymore. I want to save for a trip.", "Eu não vou mais desperdiçar dinheiro. Quero economizar para uma viagem."], ["Good plan. Did you make a budget on your tablet?", "Bom plano. Você fez um orçamento no seu tablet?"], ["Yes, I did. And I won't buy another gadget this year.", "Fiz, sim. E não vou comprar outro aparelho eletrônico este ano."], ["That's hard! Last year, you wanted to quit snacks, and then you ate a whole pie.", "Isso é difícil! No ano passado, você queria parar de comer petiscos, e aí comeu uma torta inteira."], ["Ha! This year is different. Bad habit number one: I won't eat in bed anymore.", "Ha! Este ano é diferente. Mau hábito número um: não vou mais comer na cama."], ["Okay. My resolution is to be less lazy. I'm going to run every morning.", "Certo. Minha resolução é ser menos preguiçosa. Vou correr toda manhã."], ["Run in flip-flops? Please buy real shoes first!", "Correr de chinelo? Por favor, compre tênis de verdade primeiro!"], ["Ha, I already have shoes. I only need to stick to my plan.", "Ha, eu já tenho tênis. Só preciso manter o meu plano."], ["Yes, you can do it. Together we can stick to our goals.", "Sim, você consegue. Juntos podemos manter nossas metas."]], ["/z/ em resolution e visit", "O /z/ de resolution e vision é como o 'z' de 'zero': a língua fica no mesmo lugar do 's', mas a garganta vibra. Ponha a mão no pescoço e sinta o zumbido.", ["resolution", "vision"]], ["I promise I ___ be late again.", "won't", "wasn't", "Eu prometo que não vou me atrasar de novo.", "Para fazer uma promessa negativa usamos won't + verbo base."], [["She is on a diet, so she won't eat cake tonight.", "Ela está de dieta, então não vai comer bolo hoje à noite."], ["I won't waste money anymore. I want to save for a trip.", "Eu não vou mais desperdiçar dinheiro. Quero economizar para uma viagem."]], [{"t": "c", "q": "The car is broken. It ___ start.", "o": ["won't", "doesn't", "isn't"], "pt": "O carro está quebrado. Ele não pega.", "why": "Won't também mostra recusa: o carro 'se recusa' a ligar."}, {"t": "l", "say": "I won't eat cake tonight.", "o": ["I won't eat cake tonight.", "I want eat cake tonight.", "I won't eat cake tomorrow."], "why": "Você ouviu won't (promessa negativa), cake e tonight."}, {"t": "b", "pt": "Eu não vou desistir da minha dieta.", "w": ["I", "won't", "quit", "my", "diet"]}, {"t": "b", "pt": "Ele não vai gastar dinheiro nenhum.", "w": ["He", "won't", "spend", "any", "money"]}]];
englishA2PhotoThemes[106]="map";
englishA2Plans[107]={"title": "Sugestões para o fim de semana", "file": "", "grammar": "Shall we e Let's para sugerir", "goal": "Faça sugestões usando Shall we e Let's.", "words": [["picnic basket", "cesta de piquenique"], ["hammock", "rede de descanso"], ["trail map", "mapa de trilha"], ["sounds fun", "parece divertido"], ["hike", "fazer trilha"], ["camp", "acampar"], ["thermos", "garrafa térmica"], ["skate", "andar de patins"], ["campsite", "área de camping"]]};
englishA2Content[107]=[[["It's Saturday morning, and the weather is great.", "É sábado de manhã, e o tempo está ótimo."], ["Eva and Jack have a picnic basket, a hammock, and a trail map.", "Eva e Jack têm uma cesta de piquenique, uma rede e um mapa de trilha."], ["Jack says, \"Let's hike to the lake today.\"", "Jack diz: \"Vamos fazer a trilha até o lago hoje.\""], ["Eva asks, \"Shall we camp there tonight?\"", "Eva pergunta: \"Vamos acampar lá esta noite?\""], ["They put a thermos with hot coffee in the basket.", "Eles põem uma garrafa térmica com café quente na cesta."], ["At the campsite, a pelican watches them, and a nice breeze comes from the lake.", "No camping, um pelicano observa os dois, e uma brisa gostosa vem do lago."]], [["Jack, what are we doing this weekend? The weather is perfect.", "Jack, o que vamos fazer neste fim de semana? O tempo está perfeito."], ["Let's go to the lake. We can hike and have a picnic there.", "Vamos ao lago. Podemos fazer uma trilha e um piquenique lá."], ["Sounds fun! Shall we take the hammock too?", "Parece divertido! Vamos levar a rede também?"], ["Of course. I'll put it in the car with the picnic basket.", "Claro. Eu ponho no carro com a cesta de piquenique."], ["Perfect. Do you have the trail map? I don't want to get lost like last time.", "Perfeito. Você tem o mapa da trilha? Não quero me perder como da última vez."], ["Yes, it's here. Oh, and we should wear good shoes, not flip-flops.", "Tenho, está aqui. Ah, e devemos usar sapatos bons, não chinelos."], ["Right. After the hike, let's camp at the campsite near the river.", "Certo. Depois da trilha, vamos acampar no camping perto do rio."], ["Good. The kids can skate on the path while we rest.", "Bom. As crianças podem andar de patins na trilha enquanto descansamos."], ["The sky is cloudy now, but it should clear up soon, and I'll bring a thermos with hot tea.", "O céu está nublado agora, mas deve abrir logo, e eu levo uma garrafa térmica com chá quente."], ["Yes, I think so. Pack the thermos, and we're ready to go!", "Também acho. Coloque a garrafa térmica e estamos prontos para ir!"]], ["/m/ em hammock e map", "O /m/ fecha os lábios e o som sai pelo nariz, como em 'mapa'. Em hammock e map, o /m/ no meio de hammock é longo e firme, com os lábios bem juntos.", ["hammock", "map"]], ["___ we take the trail map?", "Shall", "Let's", "Vamos levar o mapa da trilha?", "Shall we sugere algo em forma de pergunta; Let's não leva we depois."], [["Let's go to the lake. We can hike and have a picnic there.", "Vamos ao lago. Podemos fazer uma trilha e um piquenique lá."], ["Sounds fun! Shall we take the hammock too?", "Parece divertido! Vamos levar a rede também?"]], [{"t": "c", "q": "Let's ___ to the lake today.", "o": ["go", "going", "to go"], "pt": "Vamos ao lago hoje.", "why": "Depois de Let's usamos o verbo na forma base."}, {"t": "l", "say": "Shall we take the picnic basket?", "o": ["Shall we take the picnic basket?", "Shall we make the picnic basket?", "Shall we take the picnic blanket?"], "why": "Você ouviu Shall we take e picnic basket."}, {"t": "b", "pt": "Vamos fazer trilha até o lago.", "w": ["Let's", "hike", "to", "the", "lake"]}, {"t": "b", "pt": "Vamos acampar neste fim de semana?", "w": ["Shall", "we", "camp", "this", "weekend"]}]];
