englishA2Plans[118]={"title": "Placas de aviso na estrada", "file": "", "grammar": "Must para obrigação forte", "goal": "Leia placas e fale de obrigações com must.", "words": [["detour", "desvio"], ["toll", "pedágio"], ["overpass", "viaduto"], ["exit ramp", "saída de rodovia"], ["merge", "entrar na pista"], ["ahead", "à frente"], ["construction", "obra"], ["slippery", "escorregadio"]]};
englishA2Content[118]=[[["Lia and Ben are driving to the lake on a long highway.", "Lia e Ben estão dirigindo até o lago por uma estrada longa."], ["A sign says, “Construction ahead. You must merge left.”", "Uma placa diz: “Obra à frente. Você deve entrar na pista da esquerda.”"], ["Then a yellow warning sign says the road is slippery.", "Depois uma placa amarela de aviso diz que a estrada está escorregadia."], ["A tall truck takes the exit ramp, and the cars must follow the detour.", "Um caminhão alto pega a saída, e os carros devem seguir o desvio."], ["They go under an overpass and pay the toll with cash.", "Eles passam sob um viaduto e pagam o pedágio em dinheiro."], ["Lia eats a sandwich from the lunchbox while Ben keeps his eyes on the road.", "A Lia come um sanduíche da lancheira enquanto o Ben mantém os olhos na estrada."]], [["Ben, look at that sign. Does it say the road is closed?", "Ben, olhe aquela placa. Ela diz que a estrada está fechada?"], ["It says “Detour.” We must take the exit ramp now.", "Diz “Desvio”. Temos que pegar a saída agora."], ["Okay. Do we have to pay a toll on the other road?", "Certo. Temos que pagar pedágio na outra estrada?"], ["Probably. The sign says drivers must stop at the toll booth.", "Provavelmente. A placa diz que os motoristas devem parar na cabine do pedágio."], ["There's a rumor that the new overpass is faster. Is that true?", "Tem um boato de que o viaduto novo é mais rápido. É verdade?"], ["I don't know. But we must be careful because of the construction ahead.", "Não sei. Mas temos que ter cuidado por causa da obra à frente."], ["Right. Look, there's a slippery road warning! Drive slowly, please.", "Certo. Olha, tem um aviso de pista escorregadia! Dirija devagar, por favor."], ["Don't worry, I will. We'll arrive soon, and I'll pick up some water at the next stop.", "Não se preocupe, vou dirigir. Chegamos logo, e eu pego água na próxima parada."]], ["/ɔl/ em toll e tall", "Em “toll” e “tall” o som /ɔl/ pede a boca bem arredondada, como um “ó” longo, e o “l” final é feito com a ponta da língua atrás dos dentes de cima. Não deixe virar “tou”, como no português.", ["toll", "tall"]], ["Drivers ___ stop at a red light.", "must", "must to", "Os motoristas devem parar no sinal vermelho.", "Must vem direto antes do verbo, sem to."], [["It says “Detour.” We must take the exit ramp now.", "Diz “Desvio”. Temos que pegar a saída agora."], ["I don't know. But we must be careful because of the construction ahead.", "Não sei. Mas temos que ter cuidado por causa da obra à frente."]], [{"t": "c", "q": "You ___ pay the toll here.", "o": ["must", "must to", "are must"], "pt": "Você deve pagar o pedágio aqui.", "why": "Must vem direto antes do verbo, sem to nem be."}, {"t": "l", "say": "We must take the detour.", "o": ["We must take the detour.", "We must take the exit.", "We must make the detour."], "why": "Ouça o verbo take e o substantivo detour."}, {"t": "b", "pt": "Você deve dirigir devagar aqui.", "w": ["You", "must", "drive", "slowly", "here"]}, {"t": "b", "pt": "Os carros devem seguir o desvio agora.", "w": ["Cars", "must", "follow", "the", "detour", "now"]}]];
englishA2PhotoThemes[118]="map";
englishA2Plans[119]={"title": "Revisão: Tarde no parque nacional", "file": "", "grammar": "Revisão: modais, conditionals e will", "goal": "Dê avisos e fale de possibilidades no parque nacional.", "words": [["ranger", "guarda florestal"], ["skewer", "espeto"], ["wildlife", "vida selvagem"], ["stay on the trail", "ficar na trilha"], ["binoculars", "binóculos"], ["creek", "riacho"], ["deer", "veado"], ["mosquito", "mosquito"]]};
englishA2Content[119]=[[["Tom and Rosa spend the afternoon at a national park.", "Tom e Rosa passam a tarde em um parque nacional."], ["A ranger gives them a map and says, “You must stay on the trail.”", "Uma guarda florestal dá um mapa a eles e diz: “Vocês devem ficar na trilha.”"], ["There's a lot of wildlife here, but you mustn't feed the animals.", "Há muita vida selvagem aqui, mas vocês não devem alimentar os animais."], ["They hike to the creek with binoculars, and Rosa sees a deer.", "Eles fazem a trilha até o riacho com binóculos, e a Rosa vê um veado."], ["If you stay quiet, the animals won't run away.", "Se você ficar quieto, os animais não vão fugir."], ["Tonight they will probably camp near the lake and cook skewers over the fire.", "Hoje à noite eles provavelmente vão acampar perto do lago e fazer espetinhos na fogueira."]], [["Excuse me, ranger. Is there any danger on this trail?", "Com licença, guarda. Há algum perigo nesta trilha?"], ["Not much, but you must stay on the trail. There's a lot of wildlife.", "Não muito, mas vocês devem ficar na trilha. Há muita vida selvagem."], ["Do we have a chance to see a deer?", "Temos chance de ver um veado?"], ["You might see one near the creek. Fingers crossed, and bring binoculars!", "Vocês podem ver um perto do riacho. Torcendo, e levem binóculos!"], ["Great. Can we camp near the lake tonight?", "Ótimo. Podemos acampar perto do lago hoje à noite?"], ["Yes, but you can't light a fire unless you sign up at the center first.", "Pode, mas não podem acender fogueira a menos que se inscrevam no centro primeiro."], ["Okay. There's a rumor about mosquitoes by the water. Is that true?", "Certo. Tem um boato sobre mosquitos perto da água. É verdade?"], ["It's true, so bring spray. Have a great hike!", "É verdade, então levem repelente. Boa trilha!"]], ["/dʒ/ em ranger e danger", "O “j” de “ranger” e “danger” soa como o “dj” de “Djavan”: a língua toca o céu da boca e o ar sai com voz. Não é o “j” suave de “janela”.", ["ranger", "danger"]], ["You ___ feed the animals. It's dangerous.", "mustn't", "must", "Você não deve alimentar os animais. É perigoso.", "Mustn't expressa proibição; “It's dangerous” mostra que é proibido."], [["A ranger gives them a map and says, “You must stay on the trail.”", "Uma guarda florestal dá um mapa a eles e diz: “Vocês devem ficar na trilha.”"], ["You might see one near the creek. Fingers crossed, and bring binoculars!", "Vocês podem ver um perto do riacho. Torcendo, e levem binóculos!"]], [{"t": "c", "q": "If we ___ the trail, we'll get lost.", "o": ["leave", "will leave", "left"], "pt": "Se sairmos da trilha, vamos nos perder.", "why": "No first conditional usamos o presente simples depois de if."}, {"t": "l", "say": "You might see a deer near the creek.", "o": ["You might see a deer near the creek.", "You must see a deer near the creek.", "You might see a bear near the creek."], "why": "Ouça might (possibilidade) e a palavra deer."}, {"t": "b", "pt": "Nós temos que ficar na trilha.", "w": ["We", "have", "to", "stay", "on", "the", "trail"]}, {"t": "b", "pt": "Quando chegarmos ao lago, vamos acampar.", "w": ["When", "we", "get", "to", "the", "lake", "we'll", "camp"]}]];
englishA2PhotoThemes[119]="park";
englishA2MiniStories[119]=["O mapa perdido", "Tom and Rosa hike in the national park on Saturday afternoon.~Tom e Rosa fazem uma trilha no parque nacional no sábado à tarde.|Tom has the trail map in his pocket, and Rosa has the binoculars.~Tom tem o mapa da trilha no bolso, e Rosa tem os binóculos.|At the creek, Tom takes out the map to check the way.~No riacho, Tom tira o mapa para conferir o caminho.|Suddenly the wind takes the map, and it falls into the water.~De repente o vento leva o mapa, e ele cai na água.|“Oh no! We have to find it, or we might get lost,” Tom says.~“Ai, não! Temos que achar, ou podemos nos perder”, diz Tom.|Rosa remembers the ranger's words: “You must stay on the trail.”~Rosa lembra das palavras da guarda: “Vocês devem ficar na trilha.”|So they stay on the trail and walk slowly along the creek.~Então eles ficam na trilha e andam devagar ao longo do riacho.|Soon they see a deer, and the deer is standing next to the wet map.~Logo eles veem um veado, e o veado está ao lado do mapa molhado.|Rosa picks it up, and Tom laughs and says, “Thank you, deer!”~Rosa pega o mapa, e Tom ri e diz: “Obrigado, veado!”|When they get back to the camp, they dry the map near the fire and eat dinner.~Quando voltam ao acampamento, eles secam o mapa perto da fogueira e jantam."];
englishA2Plans[120]={"title": "Proibições no laboratório de informática", "file": "", "grammar": "Mustn't para proibição", "goal": "Diga o que é proibido usando mustn't.", "words": [["firewall", "firewall"], ["business card", "cartão de visita"], ["download", "baixar arquivo"], ["log in", "entrar no sistema"], ["scanner", "scanner"], ["username", "nome de usuário"], ["attachment", "anexo"], ["upload", "enviar arquivo"]]};
englishA2Content[120]=[[["Ana works in the school computer lab.", "Ana trabalha no laboratório de informática da escola."], ["Students log in to the network with a username.", "Os alunos entram na rede com um nome de usuário."], ["Today Ben wants to download a game.", "Hoje o Ben quer baixar um jogo."], ["He mustn't do that, because the firewall blocks games.", "Ele não pode fazer isso, porque o firewall bloqueia jogos."], ["Ana shows him a monitor with a red sign.", "A Ana mostra a ele um monitor com um aviso vermelho."], ["Then Ben sends his homework as an attachment.", "Então o Ben envia o dever de casa como anexo."]], [["Hi, Ana. I can't log in to the network. Can you help me?", "Oi, Ana. Não consigo entrar na rede. Você pode me ajudar?"], ["Sure. Let me see your username. You mustn't use capital letters here.", "Claro. Deixa eu ver seu nome de usuário. Aqui você não pode usar letras maiúsculas."], ["Oh, now it works! Can I download a game for the break?", "Ah, agora funcionou! Posso baixar um jogo para o intervalo?"], ["Sorry, but you mustn't download games in the lab. The firewall stops them.", "Desculpe, mas você não pode baixar jogos no laboratório. O firewall bloqueia."], ["Really? Students all over the world play games online.", "Sério? Alunos do mundo todo jogam online."], ["That's true, but this is a school. You mustn't play in class.", "É verdade, mas isto é uma escola. Você não pode jogar na aula."], ["OK, I understand. I need to upload my homework, but the file is big.", "Ok, entendi. Preciso enviar meu dever, mas o arquivo é grande."], ["No problem. Use the scanner and send it as an attachment. The due date is Friday.", "Sem problema. Use o scanner e envie como anexo. O prazo é sexta-feira."], ["Great. I also want to sign up for the remote class. Do you have a business card?", "Ótimo. Também quero me inscrever na aula remota. Você tem um cartão de visita?"], ["Yes, here it is. Call me if you have a problem.", "Tenho sim, aqui está. Me ligue se tiver algum problema."]], ["/ɔr/ em network e work", "O som de 'or' em network e world é o R americano: a língua se curva para trás sem encostar no céu da boca e os lábios ficam levemente arredondados. Não é o 'ór' do português.", ["network", "world"]], ["Students ___ download games in the lab.", "mustn't", "must", "Os alunos não podem baixar jogos no laboratório.", "Mustn't expressa proibição; must expressaria obrigação."], [["He mustn't do that, because the firewall blocks games.", "Ele não pode fazer isso, porque o firewall bloqueia jogos."], ["You mustn't play in class.", "Você não pode jogar na aula."]], [{"t": "c", "q": "You ___ log in with someone else's username.", "o": ["mustn't", "must", "have to"], "pt": "Você não pode entrar com o nome de usuário de outra pessoa.", "why": "Mustn't expressa proibição; must e have to expressariam obrigação."}, {"t": "l", "say": "Students mustn't download games here.", "o": ["Students mustn't download games here.", "Students must download games here.", "Students mustn't download games there."], "why": "A frase ouvida diz que é proibido baixar jogos aqui."}, {"t": "b", "pt": "Você não pode abrir o firewall.", "w": ["You", "mustn't", "open", "the", "firewall"]}, {"t": "b", "pt": "O Ben quer baixar um jogo.", "w": ["Ben", "wants", "to", "download", "a", "game"]}]];
englishA2PhotoThemes[120]="map";
englishA2Plans[121]={"title": "Resfriado e remédio caseiro", "file": "", "grammar": "Should e shouldn't para conselhos", "goal": "Dê conselhos usando should e shouldn't.", "words": [["cough drop", "pastilha para tosse"], ["tissue", "lenço de papel"], ["syrup", "xarope"], ["get some rest", "descansar"], ["thermometer", "termômetro"], ["sneeze", "espirrar"], ["nose", "nariz"], ["sore", "dolorido"], ["steam", "vapor"]]};
englishA2Content[121]=[[["Lia has a cold today, but she has to work from home.", "A Lia está resfriada hoje, mas tem que trabalhar de casa."], ["Her nose is red, and she sneezes all morning.", "O nariz dela está vermelho e ela espirra a manhã toda."], ["She has a sore throat, so she takes a cough drop.", "Ela está com dor de garganta, então toma uma pastilha para tosse."], ["Her brother Noah brings a box of tissues and some syrup.", "O irmão dela, Noah, traz uma caixa de lenços e um pouco de xarope."], ["Lia checks the thermometer and then sits in the steam from a hot bath.", "A Lia olha o termômetro e depois fica no vapor de um banho quente."], ["Noah says, \"You should get some rest.\"", "O Noah diz: \"Você deve descansar.\""]], [["You look tired, Lia. How do you feel today?", "Você parece cansada, Lia. Como você está hoje?"], ["Not great. My nose is red and I have a sore throat.", "Nada bem. Meu nariz está vermelho e estou com dor de garganta."], ["You should stay in bed and get some rest.", "Você deve ficar na cama e descansar."], ["But I have a big workload this week, and I don't want to lose time.", "Mas tenho muito trabalho esta semana e não quero perder tempo."], ["Your health is more important than work. You shouldn't answer emails today.", "Sua saúde é mais importante que o trabalho. Você não deve responder e-mails hoje."], ["You're right. Should I take the syrup now or after lunch?", "Você tem razão. Devo tomar o xarope agora ou depois do almoço?"], ["Take it after lunch. I'll bring you hot tea and a podcast.", "Tome depois do almoço. Vou trazer chá quente e um podcast para você."], ["Yes, please. Thanks, Noah. That sounds nice.", "Sim, por favor. Obrigada, Noah. Parece ótimo."]], ["/θ/ em throat e health", "Para o /θ/ de throat e health, coloque a ponta da língua entre os dentes e solte o ar sem vibrar a voz. Não troque por 's' nem por 't'.", ["throat", "health"]], ["You have a cold, so you ___ get some rest.", "should", "shouldn't", "Você está resfriada, então deve descansar.", "Should dá um conselho a favor de uma ação; shouldn't aconselha contra."], [["You should stay in bed and get some rest.", "Você deve ficar na cama e descansar."], ["You shouldn't answer emails today.", "Você não deve responder e-mails hoje."]], [{"t": "c", "q": "You ___ share your tissue with other people.", "o": ["shouldn't", "should", "are"], "pt": "Você não deve dividir seu lenço com outras pessoas.", "why": "Shouldn't aconselha contra uma ação; depois dele vem o verbo na forma base."}, {"t": "l", "say": "Should I take the syrup now?", "o": ["Should I take the syrup now?", "Should I take the cough drop now?", "Should I take the syrup later?"], "why": "A pergunta ouvida é sobre tomar o xarope agora."}, {"t": "b", "pt": "Você deve descansar.", "w": ["You", "should", "get", "some", "rest"]}, {"t": "b", "pt": "Ela não deve beber água gelada.", "w": ["She", "shouldn't", "drink", "cold", "water"]}]];
englishA2PhotoThemes[121]="health";
englishA2Plans[122]={"title": "Dor de cabeça no trabalho", "file": "", "grammar": "Had better para conselhos fortes", "goal": "Dê um aviso urgente usando had better.", "words": [["migraine", "enxaqueca"], ["painkiller", "analgésico"], ["eyestrain", "cansaço visual"], ["take a break", "fazer uma pausa"], ["forehead", "testa"], ["posture", "postura"], ["blink", "piscar"], ["brightness", "brilho"]]};
englishA2Content[122]=[[["Tom has a headache at work today.", "O Tom está com dor de cabeça no trabalho hoje."], ["He looks at his computer screen for six hours.", "Ele olha para a tela do computador há seis horas."], ["The brightness is too high, and his forehead hurts.", "O brilho está alto demais e a testa dele dói."], ["He thinks it's a migraine, but it's only eyestrain.", "Ele acha que é enxaqueca, mas é só cansaço visual."], ["Rosa says, \"You'd better take a break now.\"", "A Rosa diz: \"É melhor você fazer uma pausa agora.\""], ["Tom stands up, fixes his posture, and blinks slowly.", "O Tom se levanta, ajeita a postura e pisca devagar."]], [["Tom, you look pale. What's wrong?", "Tom, você está pálido. O que houve?"], ["I have a terrible headache, and I feel a little dizzy.", "Estou com uma dor de cabeça terrível e me sinto meio tonto."], ["You'd better take a break right now. You've been at that screen all morning.", "É melhor você fazer uma pausa agora mesmo. Você está nessa tela a manhã toda."], ["I can't. I have a big workload, and a remote meeting at two. I must log in early.", "Não posso. Tenho muito trabalho e uma reunião remota às duas. Preciso entrar no sistema cedo."], ["Then you'd better lower the brightness. It's too high for your eyes.", "Então é melhor diminuir o brilho. Está alto demais para seus olhos."], ["Good idea. Is it a migraine, or is it just eyestrain?", "Boa ideia. É enxaqueca ou só cansaço visual?"], ["I don't know. If it gets worse, you'd better see a doctor.", "Não sei. Se piorar, é melhor você ir ao médico."], ["OK. I'll take a painkiller and drink some water first.", "Certo. Vou tomar um analgésico e beber água primeiro."], ["Good. And please fix your posture. Your back looks tired.", "Bom. E por favor ajeite a postura. Suas costas parecem cansadas."], ["You're right. I'll do it now. Thanks, Rosa.", "Você tem razão. Vou fazer isso agora. Obrigado, Rosa."]], ["/eɪ/ em headache e break", "O /eɪ/ de headache e break é um ditongo: comece com 'ê' e deslize para 'i', como no 'hey'. Não diga 'brék' nem 'brêk' curto.", ["headache", "break"]], ["You ___ take a break now.", "had better", "have better", "É melhor você fazer uma pausa agora.", "Had better + verbo na forma base dá um aviso forte; 'have better' não existe."], [["You'd better take a break right now.", "É melhor você fazer uma pausa agora mesmo."], ["If it gets worse, you'd better see a doctor.", "Se piorar, é melhor você ir ao médico."]], [{"t": "c", "q": "It's late. You'd better ___ now.", "o": ["go home", "to go home", "going home"], "pt": "Está tarde. É melhor você ir para casa agora.", "why": "Depois de had better vem o verbo na forma base, sem to."}, {"t": "l", "say": "You'd better take a painkiller.", "o": ["You'd better take a painkiller.", "You'd better take a break.", "You'd better not take a painkiller."], "why": "O aviso ouvido é tomar um analgésico."}, {"t": "b", "pt": "É melhor você diminuir o brilho.", "w": ["You'd", "better", "lower", "the", "brightness"]}, {"t": "b", "pt": "Eu estou com uma enxaqueca forte.", "w": ["I", "have", "a", "bad", "migraine"]}]];
englishA2PhotoThemes[122]="health";
englishA2Plans[123]={"title": "Pedidos educados no restaurante chinês", "file": "", "grammar": "Would you para pedidos", "goal": "Faça pedidos educados com Would you.", "words": [["wok", "wok"], ["dumpling", "bolinho cozido"], ["fortune cookie", "biscoito da sorte"], ["takeout", "comida para viagem"], ["shrimp", "camarão"], ["beef", "carne bovina"], ["garlic", "alho"], ["spicy", "apimentado"], ["tofu", "tofu"]]};
englishA2Content[123]=[[["Mia and Ben go to a small Chinese restaurant.", "A Mia e o Ben vão a um pequeno restaurante chinês."], ["The cook uses a big wok in the kitchen.", "O cozinheiro usa um wok grande na cozinha."], ["Mia orders beef with garlic, and Ben likes spicy tofu.", "A Mia pede carne com alho e o Ben gosta de tofu apimentado."], ["They also want dumplings with shrimp.", "Eles também querem bolinhos com camarão."], ["Ben cleans his hands with a tissue, and they laugh.", "O Ben limpa as mãos com um lenço de papel e eles riem."], ["At the end, the waiter brings two fortune cookies.", "No final, o garçom traz dois biscoitos da sorte."]], [["Good evening. Are you ready to order, or do you need a few minutes?", "Boa noite. Vocês já podem pedir ou precisam de alguns minutos?"], ["Yes, we are. We need to get some rest tonight. Would you bring the food quickly, please?", "Sim, já. Precisamos descansar hoje à noite. Você poderia trazer a comida rápido, por favor?"], ["Sure. What do you want to eat tonight?", "Claro. O que vocês querem comer hoje?"], ["I want the spicy tofu. Would you make it not too spicy, please?", "Quero o tofu apimentado. Você poderia fazê-lo não muito apimentado, por favor?"], ["No problem. Do you want rice or noodles with it?", "Sem problema. Quer arroz ou macarrão com ele?"], ["Rice, please. Also, would you add shrimp to my beef and garlic?", "Arroz, por favor. E você poderia colocar camarão na minha carne com alho?"], ["Sure. Our dumplings are very good. Can I bring you an order?", "Claro. Nossos bolinhos são muito bons. Posso trazer uma porção?"], ["Yes, we do. We want to take a break from cooking at home.", "Queremos sim. Queremos dar uma pausa na cozinha de casa."], ["Perfect. Do you want chopsticks with your takeout?", "Perfeito. Querem hashi com a comida para viagem?"], ["Yes, please. We want two fortune cookies, too.", "Sim, por favor. Também queremos dois biscoitos da sorte."]], ["/ɪ/ em dumpling e chopsticks", "O /ɪ/ de dumpling e chopsticks é um 'i' curto e relaxado, entre 'i' e 'e', com a boca meio solta. Não alongue como o 'i' de 'sea'.", ["dumpling", "chopsticks"]], ["___ you bring me some chopsticks, please?", "Would", "Want", "Você poderia me trazer uns hashis, por favor?", "Would you + verbo na forma base faz um pedido educado."], [["Would you bring the food quickly, please?", "Você poderia trazer a comida rápido, por favor?"], ["Would you make it not too spicy, please?", "Você poderia fazê-lo não muito apimentado, por favor?"]], [{"t": "c", "q": "___ you add garlic to the dumplings, please?", "o": ["Would", "Are", "Does"], "pt": "Você poderia colocar alho nos bolinhos, por favor?", "why": "Would you + verbo faz um pedido educado; Are e Does não servem aqui."}, {"t": "l", "say": "Would you bring chopsticks, please?", "o": ["Would you bring chopsticks, please?", "Would you like chopsticks, please?", "Do you bring chopsticks, please?"], "why": "A frase ouvida é um pedido: Would you bring...?"}, {"t": "b", "pt": "Você poderia trazer a comida?", "w": ["Would", "you", "bring", "the", "food"]}, {"t": "b", "pt": "Quero dois biscoitos da sorte.", "w": ["I", "want", "two", "fortune", "cookies"]}]];
englishA2PhotoThemes[123]="cup";
englishA2Plans[124]={"title": "Oferecendo ajuda em uma festa", "file": "", "grammar": "Would you like...? e I'll para ofertas", "goal": "Ofereça ajuda e comida com Would you like.", "words": [["coaster", "porta-copo"], ["appetizer", "aperitivo"], ["toothpick", "palito de dente"], ["help yourself", "sirva-se"], ["pretzel", "pretzel"], ["olive", "azeitona"], ["dip", "molho para petiscar"], ["punch", "ponche"], ["cracker", "biscoito salgado"]]};
englishA2Content[124]=[[["Lia has a small party at her apartment.", "A Lia faz uma pequena festa no apartamento dela."], ["Her friends bring takeout, dumplings, and drinks.", "Os amigos dela trazem comida para viagem, bolinhos e bebidas."], ["On the table there are pretzels, olives, and a big dip.", "Na mesa há pretzels, azeitonas e um molho grande."], ["Every appetizer has a toothpick in it.", "Cada aperitivo tem um palito de dente."], ["Tom puts his glass on a coaster.", "O Tom coloca o copo em um porta-copo."], ["Lia says, \"Help yourself, everyone!\"", "A Lia diz: \"Sirvam-se, pessoal!\""]], [["Hi, Tom! Would you like some punch? It's cold.", "Oi, Tom! Você quer um pouco de ponche? Está gelado."], ["Yes, please. Is there any dip for the crackers?", "Quero sim. Tem molho para os biscoitos salgados?"], ["Sure. Help yourself, and I'll get you a small plate.", "Claro. Sirva-se, e eu pego um pratinho para você."], ["Thanks. These olives look great. Did you make the dumplings, too?", "Obrigado. Estas azeitonas estão ótimas. Foi você que fez os bolinhos também?"], ["No, Rosa brought them. Would you like a toothpick for the olives?", "Não, a Rosa trouxe. Você quer um palito para as azeitonas?"], ["No, thanks. I can use my fingers. Where can I put my glass?", "Não, obrigado. Posso usar os dedos. Onde posso colocar meu copo?"], ["Put it on a coaster. They're next to the napkins and the fortune cookies.", "Coloque em um porta-copo. Eles estão ao lado dos guardanapos e dos biscoitos da sorte."], ["Got it. I'm putting my glass on a coaster now.", "Entendi. Estou colocando meu copo em um porta-copo agora."]], ["/ɪ/ em appetizer e napkin", "O /ɪ/ de appetizer e napkin é um 'i' curto e relaxado, quase um 'e' fraco. Em napkin, a última sílaba soa 'kin' curto, sem alongar.", ["appetizer", "napkin"]], ["___ you like a toothpick for the olives?", "Would", "Are", "Você quer um palito para as azeitonas?", "Would you like...? oferece algo de forma educada."], [["Would you like some punch?", "Você quer um pouco de ponche?"], ["I'll get you a small plate.", "Eu pego um pratinho para você."]], [{"t": "c", "q": "Your glass is empty. I ___ get you more punch.", "o": ["'ll", "'m", "does"], "pt": "Seu copo está vazio. Eu pego mais ponche para você.", "why": "I'll + verbo oferece ajuda na hora; I'm e does não formam essa oferta."}, {"t": "l", "say": "Would you like some dip?", "o": ["Would you like some dip?", "Would you like some punch?", "Would you like some crackers?"], "why": "A oferta ouvida é de molho (dip)."}, {"t": "b", "pt": "Você gostaria de um palito?", "w": ["Would", "you", "like", "a", "toothpick"]}, {"t": "b", "pt": "Eu pego um prato para você.", "w": ["I'll", "get", "a", "plate", "for", "you"]}]];
