englishA2Plans[125]={"title": "Loja de eletrônicos", "file": "", "grammar": "I'd like e I'd rather", "goal": "Expresse preferências com I'd like e I'd rather.", "words": [["earbuds", "fones de ouvido"], ["speaker", "caixa de som"], ["adapter", "adaptador"], ["on sale", "em promoção"], ["bluetooth", "bluetooth"], ["upgrade", "atualização para melhor"], ["tag", "etiqueta"], ["mic", "microfone"]]};
englishA2Content[125]=[[["Noah is in an electronics store.", "O Noah está em uma loja de eletrônicos."], ["He needs new earbuds for his phone.", "Ele precisa de fones novos para o celular."], ["The tag says they are on sale today.", "A etiqueta diz que eles estão em promoção hoje."], ["The salesman shows him headphones with a mic and a small speaker.", "O vendedor mostra a ele fones de ouvido com microfone e uma caixa de som pequena."], ["Noah likes the earbuds, but he'd rather have headphones.", "O Noah gosta dos fones pequenos, mas prefere ter fones grandes."], ["He needs an adapter for his old phone, too.", "Ele também precisa de um adaptador para o celular antigo."]], [["Hi! Can I help you find something today?", "Oi! Posso ajudar você a encontrar alguma coisa hoje?"], ["Yes, I'd like some earbuds. Are these on sale?", "Sim, eu gostaria de uns fones. Estes estão em promoção?"], ["Yes, they are. They have bluetooth, and there's a button to mute the sound.", "Estão sim. Eles têm bluetooth e um botão para silenciar o som."], ["Nice. Actually, I'd rather have headphones. Do they have a mic?", "Legal. Na verdade, prefiro ter fones grandes. Eles têm microfone?"], ["This pair does. It's a good upgrade from your old ones.", "Este par tem. É uma boa melhoria em relação aos seus antigos."], ["How much is it? I don't see a tag.", "Quanto custa? Não vejo a etiqueta."], ["It's sixty dollars. Do you need an adapter, too? Your phone is old.", "São sessenta dólares. Você também precisa de um adaptador? Seu celular é antigo."], ["Yes, I'd like one adapter, please.", "Sim, eu gostaria de um adaptador, por favor."], ["Great. Please log in to our website and download the app. If your firewall blocks it, call us.", "Ótimo. Entre no nosso site e baixe o aplicativo. Se o seu firewall bloquear, ligue para nós."], ["OK, I will. Thanks for your help.", "Certo, vou ligar. Obrigado pela ajuda."]], ["/ɛ/ em headphones e speaker", "O /ɛ/ de headphones é o 'é' aberto de 'pé' (o 'ea' não soa 'i'). Em speaker, o 'er' final é o R americano suave, com a língua curvada para trás.", ["headphones", "speaker"]], ["I'd rather ___ headphones than earbuds.", "have", "to have", "Eu prefiro ter fones grandes a fones pequenos.", "Depois de I'd rather vem o verbo na forma base, sem to."], [["Yes, I'd like some earbuds.", "Sim, eu gostaria de uns fones."], ["Actually, I'd rather have headphones.", "Na verdade, prefiro ter fones grandes."]], [{"t": "c", "q": "I ___ pay now.", "o": ["'d rather", "'d rather to", "'m rather"], "pt": "Eu prefiro pagar agora.", "why": "I'd rather + verbo na forma base expressa preferência, sem to."}, {"t": "l", "say": "I'd like some earbuds.", "o": ["I'd like some earbuds.", "I'd like some headphones.", "I'd like some speakers."], "why": "O pedido ouvido é por fones pequenos (earbuds)."}, {"t": "b", "pt": "Eu gostaria de um adaptador.", "w": ["I'd", "like", "an", "adapter"]}, {"t": "b", "pt": "Eu prefiro comprar a caixa de som.", "w": ["I'd", "rather", "buy", "the", "speaker"]}]];
