englishA2Plans[126]={"title": "Dois smartphones lado a lado", "file": "", "grammar": "As...as para igualdade", "goal": "Compare duas coisas iguais usando as...as.", "words": [["screen size", "tamanho de tela"], ["touchscreen", "tela sensível ao toque"], ["camera lens", "lente da câmera"], ["as good as new", "tão bom quanto novo"], ["smartphone", "smartphone"], ["zoom", "zoom"], ["pixel", "pixel"], ["gigabyte", "gigabyte"], ["protector", "película protetora"]]};
englishA2Content[126]=[[["Rosa compares two smartphones in a store.", "A Rosa compara dois smartphones em uma loja."], ["The two phones have the same screen size.", "Os dois celulares têm o mesmo tamanho de tela."], ["The red phone is as big as the blue one.", "O celular vermelho é tão grande quanto o azul."], ["Both have a touchscreen and a good camera lens.", "Os dois têm tela sensível ao toque e uma boa lente de câmera."], ["The old phone on the shelf is as good as new.", "O celular antigo na prateleira é tão bom quanto novo."], ["Rosa also sees earbuds, a speaker, and an adapter on sale.", "A Rosa também vê fones, uma caixa de som e um adaptador em promoção."]], [["Rosa, look at these two phones. They look almost the same.", "Rosa, olhe estes dois celulares. Eles parecem quase iguais."], ["True. This one has a touchscreen as big as that one.", "Verdade. Este tem uma tela sensível ao toque tão grande quanto aquela."], ["What about the camera? I take a lot of photos with my phone.", "E a câmera? Eu tiro muitas fotos com o meu celular."], ["The red camera is as good as the blue one, and it has the same zoom.", "A câmera vermelha é tão boa quanto a azul e tem o mesmo zoom."], ["Really? Is it as expensive as the blue phone?", "Sério? Ela é tão cara quanto o celular azul?"], ["No, it's cheaper. It has 128 gigabytes, but the pixels are smaller.", "Não, é mais barato. Tem 128 gigabytes, mas os pixels são menores."], ["What about the battery? My old phone dies in the afternoon.", "E a bateria? Meu celular antigo descarrega à tarde."], ["It lasts all day, and it charges very fast.", "Dura o dia todo e carrega bem rápido."], ["Great. I'll take the red one, and I want a protector for the screen.", "Ótimo. Vou levar o vermelho e quero uma película para a tela."], ["Sure. I'll bring it from the back, and the earbuds are on sale.", "Claro. Vou trazer dos fundos, e os fones estão em promoção."]], ["/ə/ em battery e camera", "O /ə/ (schwa) é um som fraco e rápido, como o 'a' final de 'casa'. Em battery e camera, as sílabas sem acento viram schwa: 'BÆ-t(ə)-ri' e 'KÆ-m(ə)-rə'.", ["battery", "camera"]], ["The red phone is as big ___ the blue one.", "as", "than", "O celular vermelho é tão grande quanto o azul.", "Na estrutura as...as, o segundo as fecha a comparação; than é para o comparativo."], [["The red phone is as big as the blue one.", "O celular vermelho é tão grande quanto o azul."], ["The red camera is as good as the blue one, and it has the same zoom.", "A câmera vermelha é tão boa quanto a azul e tem o mesmo zoom."]], [{"t": "c", "q": "This speaker is as loud ___ that one.", "o": ["as", "than", "like"], "pt": "Esta caixa de som é tão alta quanto aquela.", "why": "A igualdade usa as + adjetivo + as."}, {"t": "l", "say": "The red phone is as big as the blue one.", "o": ["The red phone is as big as the blue one.", "The red phone is bigger than the blue one.", "The blue phone is as big as the red one."], "why": "A frase ouvida iguala o tamanho do celular vermelho ao do azul."}, {"t": "b", "pt": "Este celular é tão caro quanto aquele.", "w": ["This", "phone", "is", "as", "expensive", "as", "that", "one"]}, {"t": "b", "pt": "Esta tela é tão grande quanto aquela.", "w": ["This", "screen", "is", "as", "big", "as", "that"]}]];
englishA2PhotoThemes[126]="map";
englishA2Plans[127]={"title": "Comparando planos de internet", "file": "", "grammar": "Not as...as", "goal": "Mostre diferença usando not as...as.", "words": [["bandwidth", "largura de banda"], ["router", "roteador"], ["contract", "contrato"], ["monthly fee", "mensalidade"], ["modem", "modem"], ["lag", "lag, atraso"], ["unlimited", "ilimitado"], ["data", "dados"]]};
englishA2Content[127]=[[["Tom checks out two internet plans.", "O Tom analisa dois planos de internet."], ["The blue plan has unlimited data and a free modem.", "O plano azul tem dados ilimitados e um modem grátis."], ["The green plan is not as fast as the blue plan.", "O plano verde não é tão rápido quanto o plano azul."], ["Tom plays games with earbuds and a touchscreen, so lag is a problem.", "O Tom joga com fones e tela sensível ao toque, então o lag é um problema."], ["The green monthly fee is lower, but the contract is long.", "A mensalidade verde é menor, mas o contrato é longo."], ["Tom will keep his router and use the wifi in the garage.", "O Tom vai manter o roteador e usar o wi-fi na garagem."]], [["Hi, I want to change my internet plan. Which one is better?", "Oi, quero mudar meu plano de internet. Qual é melhor?"], ["The blue plan is faster, but it's not as cheap as the green plan.", "O plano azul é mais rápido, mas não é tão barato quanto o verde."], ["How about the bandwidth? My family uses the wifi all day.", "E a largura de banda? Minha família usa o wi-fi o dia todo."], ["The green plan's bandwidth is not as big as the blue plan's.", "A largura de banda do plano verde não é tão grande quanto a do azul."], ["I see. Do I need a new router? The old one is five years old.", "Entendi. Preciso de um roteador novo? O velho tem cinco anos."], ["Your router is fine, but you need a modem and an adapter. They're on sale.", "Seu roteador está bom, mas você precisa de um modem e de um adaptador. Estão em promoção."], ["And the contract? I don't want a long one.", "E o contrato? Não quero um contrato longo."], ["The green contract is one year, and the monthly fee isn't as high as the blue one.", "O contrato verde é de um ano e a mensalidade não é tão alta quanto a do azul."], ["Good. Does the green plan have unlimited data?", "Bom. O plano verde tem dados ilimitados?"], ["Yes, it does, and there's no lag.", "Tem sim, e não há lag."]], ["/aʊ/ em router e out", "O /aʊ/ de router e out é um ditongo: comece com 'a' aberto e deslize para 'u', como o 'au' de 'pau'. Não diga 'rôter' nem 'ót'.", ["router", "out"]], ["The cheap plan is not as fast ___ the blue plan.", "as", "than", "O plano barato não é tão rápido quanto o plano azul.", "Not as...as mostra diferença; o segundo as fecha a estrutura, e than não combina com ela."], [["The green plan's bandwidth is not as big as the blue plan's.", "A largura de banda do plano verde não é tão grande quanto a do azul."], ["The blue plan is faster, but it's not as cheap as the green plan.", "O plano azul é mais rápido, mas não é tão barato quanto o verde."]], [{"t": "c", "q": "This router is not as new ___ that one.", "o": ["as", "than", "like"], "pt": "Este roteador não é tão novo quanto aquele.", "why": "Not as + adjetivo + as mostra que uma coisa tem menos da qualidade."}, {"t": "l", "say": "The green plan is not as fast as the blue plan.", "o": ["The green plan is not as fast as the blue plan.", "The green plan is not as cheap as the blue plan.", "The blue plan is not as fast as the green plan."], "why": "A frase ouvida diz que o plano verde é menos rápido que o azul."}, {"t": "b", "pt": "Este plano não é tão caro quanto aquele.", "w": ["This", "plan", "is", "not", "as", "expensive", "as", "that"]}, {"t": "b", "pt": "A mensalidade não é tão alta.", "w": ["The", "monthly", "fee", "is", "not", "as", "high"]}]];
englishA2PhotoThemes[127]="map";
englishA2Plans[128]={"title": "Cardápio saudável na cantina", "file": "", "grammar": "Less e least", "goal": "Compare quantidade com less e least.", "words": [["calorie", "caloria"], ["fiber", "fibra"], ["protein", "proteína"], ["cut down on", "reduzir o consumo de"], ["beans", "feijão"], ["nuts", "castanhas"], ["baked", "assado"], ["whole grain", "integral"]]};
englishA2Content[128]=[[["Mia checks the school canteen menu today.", "A Mia olha o cardápio da cantina da escola hoje."], ["The fried dumplings have the most calories on the menu.", "Os bolinhos fritos têm o maior número de calorias do cardápio."], ["The baked fish has less salt and more protein.", "O peixe assado tem menos sal e mais proteína."], ["The beans have the least calories and a lot of fiber.", "O feijão tem o menor número de calorias e muita fibra."], ["At home, Mia cooks fried food in a wok, so she wants to cut down on it.", "Em casa, a Mia faz comida frita no wok, então quer reduzir o consumo."], ["She buys beans, nuts, and a small pasta.", "Ela compra feijão, castanhas e um pequeno macarrão."]], [["Hi, Ben. What are you getting for lunch today?", "Oi, Ben. O que você vai pegar no almoço hoje?"], ["I'm not sure. The fried dumplings look great, but I want to cut down on fried food.", "Não sei. Os bolinhos fritos parecem ótimos, mas quero reduzir a comida frita."], ["Sure, the baked fish has less salt and more protein than the dumplings.", "Claro, o peixe assado tem menos sal e mais proteína que os bolinhos."], ["Okay. How about the pasta? Does it have a lot of fiber?", "Certo. E o macarrão? Ele tem muita fibra?"], ["Not really. The beans have the most fiber, and they have the least calories, too.", "Não muito. O feijão tem mais fibra e também o menor número de calorias."], ["Perfect. I'll take the beans and some nuts. Can I get them as takeout? My break is short.", "Perfeito. Vou levar o feijão e algumas castanhas. Posso pedir para viagem? Meu intervalo é curto."], ["Yes, you can. And take a drink with less sugar than a soda.", "Pode sim. E pegue uma bebida com menos açúcar que um refrigerante."], ["Good idea. I usually drink too much sugar.", "Boa ideia. Eu costumo tomar açúcar demais."], ["Me too. I'm going to buy water and a small pasta for my sister.", "Eu também. Vou comprar água e um macarrão pequeno para minha irmã."], ["Okay, let's go to the line, then.", "Certo, então vamos para a fila."]], ["/ʃ/ em sugar e sure", "O /ʃ/ de sugar e sure é o 'ch' de 'chuva': lábios arredondados e ar contínuo, sem 's'. Não diga 'súgar' nem 'sur'; é 'SHU-gar' e 'SHUR'.", ["sugar", "sure"]], ["Of all the food here, the beans have the ___ calories.", "least", "less", "De toda a comida daqui, o feijão tem o menor número de calorias.", "The least indica o menor entre vários itens; less compara só dois."], [["Sure, the baked fish has less salt and more protein than the dumplings.", "Claro, o peixe assado tem menos sal e mais proteína que os bolinhos."], ["The beans have the most fiber, and they have the least calories, too.", "O feijão tem mais fibra e também o menor número de calorias."]], [{"t": "c", "q": "I want ___ sugar in my tea.", "o": ["less", "least", "lesser"], "pt": "Eu quero menos açúcar no meu chá.", "why": "Less + substantivo incontável compara com a quantidade normal; least pede 'the' e vários itens."}, {"t": "l", "say": "The pasta has less fiber than the beans.", "o": ["The pasta has less fiber than the beans.", "The pasta has more fiber than the beans.", "The beans have less fiber than the pasta."], "why": "A frase ouvida diz que o macarrão tem menos fibra que o feijão."}, {"t": "b", "pt": "O peixe tem menos sal.", "w": ["The", "fish", "has", "less", "salt"]}, {"t": "b", "pt": "Eu quero comer menos comida frita.", "w": ["I", "want", "to", "eat", "less", "fried", "food"]}]];
englishA2PhotoThemes[128]="map";
englishA2ExtraWordExamples[128]={"whole grain": ["I eat less white bread and more whole grain bread.", "Como menos pão branco e mais pão integral."]};
englishA2Plans[129]={"title": "Revisão: Dia de feira de produtores", "file": "", "grammar": "Revisão: should, must, have to e when/if", "goal": "Dê conselhos e regras na feira de produtores.", "words": [["peach", "pêssego"], ["organic", "orgânico"], ["sample", "amostra"], ["in season", "na estação"], ["plum", "ameixa"], ["pear", "pera"], ["melon", "melão"], ["spinach", "espinafre"], ["herb", "erva aromática"]]};
englishA2Content[129]=[[["Rosa and Noah visit the farmers market on Saturday.", "A Rosa e o Noah visitam a feira de produtores no sábado."], ["The peaches are in season, so they smell great.", "Os pêssegos estão na estação, então cheiram muito bem."], ["A seller offers a sample of organic melon on a toothpick.", "Um vendedor oferece uma amostra de melão orgânico em um palito."], ["Rosa has to pay in cash because the stand has no card machine.", "A Rosa tem que pagar em dinheiro porque a barraca não tem maquininha de cartão."], ["Noah must carry the heavy bags.", "O Noah precisa carregar as sacolas pesadas."], ["If it rains, they will go home early.", "Se chover, eles vão para casa mais cedo."]], [["Wow, this market is huge. What do you want to buy first?", "Nossa, esta feira é enorme. O que você quer comprar primeiro?"], ["We should buy the peaches. They're in season, and they're on sale.", "Devemos comprar os pêssegos. Estão na estação e em promoção."], ["Good idea. Look, there's a sample of melon here. Help yourself!", "Boa ideia. Olhe, tem uma amostra de melão aqui. Sirva-se!"], ["Mmm, this plum is sweet. Is it organic? Let me ask.", "Hum, esta ameixa é doce. É orgânica? Vou perguntar."], ["Yes, it is. The sign says you must wash the fruit before you eat it.", "É sim. A placa diz que você deve lavar a fruta antes de comer."], ["Of course. If I buy a lot, I have to carry it. Do you have a bag?", "Claro. Se eu comprar muito, tenho que carregar. Você tem uma sacola?"], ["Yes, I have two big ones. We can put them in the car.", "Tenho sim, duas grandes. Podemos colocá-las no carro."], ["Great. I want to cut down on cookies, so I'm buying pears, spinach, and herbs.", "Ótimo. Quero reduzir os biscoitos, então estou comprando peras, espinafre e ervas."], ["Smart. After that, let's order two coffees at the stand and sit down.", "Boa. Depois disso, vamos pedir dois cafés na barraca e sentar."], ["Sure, let's go.", "Claro, vamos."]], ["/ɔr/ em organic e vendor", "O /ɔr/ de organic e order tem 'o' aberto e arredondado seguido do R americano: a língua se curva para trás sem encostar. Não diga 'ór' como em português.", ["organic", "order"]], ["The fruit is dirty, so you ___ wash it.", "must", "mustn't", "A fruta está suja, então você deve lavá-la.", "Must expressa obrigação; mustn't expressaria proibição."], [["We should buy the peaches.", "Devemos comprar os pêssegos."], ["The sign says you must wash the fruit before you eat it.", "A placa diz que você deve lavar a fruta antes de comer."]], [{"t": "c", "q": "If it rains, we ___ go home early.", "o": ["will", "are", "were"], "pt": "Se chover, nós vamos para casa mais cedo.", "why": "If + presente pede will + verbo no resultado."}, {"t": "l", "say": "You should try the organic peaches.", "o": ["You should try the organic peaches.", "You should buy the organic peaches.", "You must try the organic peaches."], "why": "A frase ouvida aconselha provar os pêssegos orgânicos."}, {"t": "b", "pt": "Eu tenho que pagar em dinheiro.", "w": ["I", "have", "to", "pay", "in", "cash"]}, {"t": "b", "pt": "Você deve provar a amostra.", "w": ["You", "should", "try", "the", "sample"]}]];
englishA2PhotoThemes[129]="cup";
englishA2MiniStories[129]=["O pêssego sumido", "Rosa went to the farmers market with her grandpa.~A Rosa foi à feira de produtores com o avô.|She wanted to buy organic peaches for a pie.~Ela queria comprar pêssegos orgânicos para uma torta.|At the first stand, the peaches weren't in season.~Na primeira barraca, os pêssegos não estavam na estação.|The vendor was kind, and he gave her a sample of melon.~O vendedor foi gentil e deu a ela uma amostra de melão.|Then her grandpa found a small stand at the end of the street.~Então o avô achou uma barraca pequena no fim da rua.|There was a basket of sweet peaches on the table.~Havia uma cesta de pêssegos doces na mesa.|Rosa paid and went to look at the herbs.~A Rosa pagou e foi olhar as ervas.|When she got home, the peaches weren't in her bag!~Quando chegou em casa, os pêssegos não estavam na sacola!|She ran back to the stand, and the vendor was holding the peaches.~Ela correu de volta à barraca, e o vendedor estava segurando os pêssegos.|He smiled and gave them to her, and that evening the pie was great.~Ele sorriu e entregou a ela, e naquela noite a torta ficou ótima."];
englishA2Plans[130]={"title": "Disputa de preços no mercado de rua", "file": "", "grammar": "Much/far/a lot + comparativo", "goal": "Intensifique comparativos com much e far.", "words": [["butcher", "açougueiro"], ["haggle", "pechinchar"], ["price tag", "etiqueta de preço"], ["rip-off", "preço abusivo"], ["dozen", "dúzia"], ["coconut", "coco"], ["fresh fish", "peixe fresco"], ["street stall", "barraca de rua"]]};
englishA2Content[130]=[[["Ana is at the street market with her brother Ben.", "Ana está na feira de rua com o irmão Ben."], ["The butcher has good meat, but his price tag is a lot higher than at the store.", "O açougueiro tem carne boa, mas a etiqueta de preço dele é bem mais alta que no mercado."], ["Organic melons are in season, but they cost far more here, and Ana says it's a rip-off.", "Melões orgânicos estão na estação, mas custam muito mais aqui, e Ana diz que é um preço abusivo."], ["Ben likes to haggle, so he asks the man to weigh a dozen coconuts again.", "Ben gosta de pechinchar, então pede ao homem para pesar uma dúzia de cocos de novo."], ["The man gives them a sample of the melon, and it's much sweeter than the last one.", "O homem dá uma amostra do melão a eles, e é bem mais doce que o último."], ["Ana laughs because the deal is far better than before.", "Ana ri porque o negócio é muito melhor que antes."]], [["Excuse me, sir. The price on this melon is a lot higher than yesterday.", "Com licença, senhor. O preço deste melão está bem mais alto que ontem."], ["Really? Melons are much more expensive this week, ma'am.", "É mesmo? Melões estão bem mais caros esta semana, senhora."], ["The butcher next door is much cheaper. Honestly, this looks like a rip-off.", "O açougueiro ao lado é bem mais barato. Sinceramente, isso parece um preço abusivo."], ["Hold on! Let me weigh it again. Maybe the price tag is wrong.", "Espere! Deixe-me pesar de novo. Talvez a etiqueta de preço esteja errada."], ["Okay. Can you give me a better price for the melon and a dozen coconuts?", "Certo. Pode me dar um preço melhor pelo melão e por uma dúzia de cocos?"], ["Hmm. I like to haggle, so tell me your price.", "Hmm. Eu gosto de pechinchar, então diga seu preço."], ["Eight dollars for the melon and the coconuts. Is that okay?", "Oito dólares pelo melão e pelos cocos. Está bom?"], ["Deal! Eight dollars. Thanks for coming to my stall.", "Fechado! Oito dólares. Obrigado por vir à minha barraca."]], ["/ɡ/ em haggle e bargain", "O som /ɡ/ em haggle e again é feito com o fundo da língua tocando o céu da boca, com a garganta vibrando, como o g de gato. Em again, o g é forte: a-GÉN.", ["haggle", "again"]], ["This melon is ___ bigger than that one.", "much", "very", "Este melão é muito maior que aquele.", "Antes de um comparativo usamos much, far ou a lot, e não very."], [["Excuse me, sir. The price on this melon is a lot higher than yesterday.", "Com licença, senhor. O preço deste melão está bem mais alto que ontem."], ["Really? Melons are much more expensive this week, ma'am.", "É mesmo? Melões estão bem mais caros esta semana, senhora."]], [{"t": "c", "q": "The coconuts are ___ cheaper at the market than at the store.", "o": ["far", "very", "so"], "pt": "Os cocos são muito mais baratos na feira do que na loja.", "why": "Far, much e a lot reforçam o comparativo cheaper; very e so não."}, {"t": "l", "say": "The price is a lot higher today.", "o": ["The price is a lot higher today.", "The price is a lot lower today.", "The prices are a lot higher today."], "why": "Ouça higher (mais alto), não lower (mais baixo)."}, {"t": "b", "pt": "O açougueiro é muito mais barato", "w": ["The", "butcher", "is", "much", "cheaper"]}, {"t": "b", "pt": "Esta etiqueta de preço é bem mais alta que ontem", "w": ["This", "price", "tag", "is", "far", "higher", "than", "yesterday"]}]];
englishA2PhotoThemes[130]="cup";
englishA2ExtraWordExamples[130]={"fresh fish": ["The fresh fish is much cheaper at this stall.", "O peixe fresco é bem mais barato nesta barraca."], "street stall": ["This street stall is a lot cheaper than the store.", "Esta barraca de rua é muito mais barata que a loja."]};
englishA2Plans[131]={"title": "Melhor viagem que já fiz", "file": "", "grammar": "Superlativo + present perfect (the best ... I've ever)", "goal": "Diga o melhor que você já fez com ever.", "words": [["guidebook", "guia de viagem"], ["itinerary", "roteiro"], ["landmark", "ponto turístico"], ["off the beaten path", "fora do roteiro comum"], ["canyon", "cânion"], ["sunrise", "nascer do sol"], ["lodge", "pousada de montanha"], ["traveler", "viajante"]]};
englishA2Content[131]=[[["Lia and Noah are looking at photos from their trip.", "Lia e Noah estão olhando fotos da viagem deles."], ["The canyon is the most beautiful place Lia has ever seen.", "O cânion é o lugar mais bonito que Lia já viu."], ["They took the photo at sunrise with a new camera lens.", "Eles tiraram a foto ao nascer do sol com uma lente de câmera nova."], ["Their itinerary had a famous landmark, but they chose a road off the beaten path.", "O roteiro deles tinha um ponto turístico famoso, mas eles escolheram uma estrada fora do roteiro comum."], ["At the lodge, a friendly traveler showed them a map in her guidebook.", "Na pousada, uma viajante simpática mostrou a eles um mapa no guia de viagem dela."], ["It was the best trip they have ever taken.", "Foi a melhor viagem que eles já fizeram."]], [["Look at this photo! The canyon is the most beautiful place I've ever seen.", "Olhe esta foto! O cânion é o lugar mais bonito que eu já vi."], ["Wow, that's amazing. Did you use the new camera lens?", "Uau, que incrível. Você usou a lente nova?"], ["Yes! I took it at sunrise. It's the best photo I've ever taken.", "Sim! Eu tirei ao nascer do sol. É a melhor foto que eu já tirei."], ["Our itinerary was great, but the landmark was very crowded, and lunch was a rip-off.", "Nosso roteiro foi ótimo, mas o ponto turístico estava muito cheio, e o almoço foi um preço abusivo."], ["That's true. I liked the lodge off the beaten path much more.", "É verdade. Eu gostei muito mais da pousada fora do roteiro comum."], ["Same here. And the organic breakfast was delicious, wasn't it?", "Eu também. E o café da manhã orgânico estava delicioso, não estava?"], ["It really was. The traveler at the lodge gave us that tip, remember?", "Estava mesmo. A viajante da pousada nos deu essa dica, lembra?"], ["Of course I do! Let's go again next summer.", "Claro que lembro! Vamos de novo no próximo verão."]], ["/ɪn/ em itinerary e landmark", "O som /ɪ/ em itinerary e landmark é curto e relaxado, entre o i e o e do português; não alongue como em 'sea'. Mantenha a língua baixa e os lábios soltos.", ["itinerary", "landmark"]], ["It's the most beautiful canyon I've ___ seen.", "ever", "never", "É o cânion mais bonito que eu já vi.", "Com superlativo e present perfect, ever significa já em toda a vida; never mudaria o sentido."], [["Look at this photo! The canyon is the most beautiful place I've ever seen.", "Olhe esta foto! O cânion é o lugar mais bonito que eu já vi."], ["Yes! I took it at sunrise. It's the best photo I've ever taken.", "Sim! Eu tirei ao nascer do sol. É a melhor foto que eu já tirei."]], [{"t": "c", "q": "That was the best trip we ___ ever taken.", "o": ["have", "has", "are"], "pt": "Foi a melhor viagem que já fizemos.", "why": "Com we usamos have + particípio: we have ever taken."}, {"t": "l", "say": "It's the best trip I've ever taken.", "o": ["It's the best trip I've ever taken.", "It's the best trip I've never taken.", "It's the best trip he's ever taken."], "why": "Ouça I've ever, não I've never nem he's."}, {"t": "b", "pt": "É o lugar mais bonito que já vi", "w": ["It's", "the", "prettiest", "place", "I've", "ever", "seen"]}, {"t": "b", "pt": "Esse foi o melhor roteiro que já fizemos", "w": ["This", "was", "the", "best", "itinerary", "we've", "ever", "made"]}]];
englishA2PhotoThemes[131]="ticket";
englishA2Plans[132]={"title": "Quanto mais cedo, melhor", "file": "", "grammar": "The + comparativo, the + comparativo", "goal": "Relacione duas ideias com the more, the better.", "words": [["rush hour", "hora do rush"], ["turnstile", "catraca"], ["traffic jam", "engarrafamento"], ["in a hurry", "com pressa"], ["swipe", "passar o cartão"], ["cab", "táxi"], ["metro card", "cartão do metrô"], ["side street", "rua lateral"]]};
englishA2Content[132]=[[["Rosa is in a hurry because the meeting starts at nine.", "Rosa está com pressa porque a reunião começa às nove."], ["It is rush hour, and a long traffic jam fills the street.", "É hora do rush, e um longo engarrafamento enche a rua."], ["Drivers honk their horns, but nobody moves.", "Os motoristas buzinam, mas ninguém se mexe."], ["Rosa leaves the cab, crosses at the crosswalk, and runs to the station.", "Rosa sai do táxi, atravessa na faixa de pedestres e corre para a estação."], ["She swipes her card at the turnstile, and the monthly fee is already paid.", "Ela passa o cartão na catraca, e a mensalidade já está paga."], ["An announcement says the train is late, so the more she waits, the angrier she feels.", "Um aviso diz que o trem está atrasado, então quanto mais ela espera, mais brava ela fica."]], [["Tom! Why are you running? The meeting starts at nine thirty.", "Tom! Por que você está correndo? A reunião começa às nove e meia."], ["I know, but the traffic jam was terrible. I left my cab on Main Street.", "Eu sei, mas o engarrafamento estava terrível. Deixei meu táxi na Main Street."], ["Come on, hurry up. The turnstile is on the left.", "Vamos, ande logo. A catraca fica à esquerda."], ["Done. Is the train late again?", "Pronto. O trem está atrasado de novo?"], ["Yes. The earlier you leave home, the easier the trip is.", "Sim. Quanto mais cedo você sai de casa, mais fácil é a viagem."], ["You're right. The more I wait, the more nervous I feel.", "Você tem razão. Quanto mais eu espero, mais nervoso eu fico."], ["Relax. We can read my itinerary and the guidebook while we wait.", "Relaxe. Podemos ler meu roteiro e o guia de viagem enquanto esperamos."], ["Sure. Let's do it, and I'll buy the coffee.", "Claro. Vamos fazer isso, e eu pago o café."]], ["/ʌ/ em rush e hurry", "O som /ʌ/ em rush e hurry é uma vogal curta e relaxada, entre o a e o é do português, com a boca meio aberta. Não diga 'rôsh': pense em um 'a' bem curto.", ["rush", "hurry"]], ["The more you wait, ___ angrier you feel.", "the", "than", "Quanto mais você espera, mais bravo você fica.", "Nas duas partes usamos the + comparativo: the more..., the angrier."], [["Yes. The earlier you leave home, the easier the trip is.", "Sim. Quanto mais cedo você sai de casa, mais fácil é a viagem."], ["You're right. The more I wait, the more nervous I feel.", "Você tem razão. Quanto mais eu espero, mais nervoso eu fico."]], [{"t": "c", "q": "The ___ I wait, the angrier I feel.", "o": ["more", "most", "much"], "pt": "Quanto mais eu espero, mais bravo eu fico.", "why": "The more + sujeito + verbo liga duas ideias: the more..., the angrier..."}, {"t": "l", "say": "The sooner we leave, the better.", "o": ["The sooner we leave, the better.", "The sooner we leave, the best.", "The sooner we left, the better."], "why": "Ouça leave e better, com the antes dos dois comparativos."}, {"t": "b", "pt": "Quanto mais cedo você sai, mais fácil é", "w": ["The", "earlier", "you", "leave", "the", "easier", "it", "is"]}, {"t": "b", "pt": "Quanto mais espero, mais bravo fico", "w": ["The", "more", "I", "wait", "the", "angrier", "I", "get"]}]];
englishA2PhotoThemes[132]="map";
englishA2ExtraWordExamples[132]={"metro card": ["The sooner you buy a metro card, the better.", "Quanto antes você comprar um cartão do metrô, melhor."], "side street": ["The earlier we leave, the quieter the side street is.", "Quanto mais cedo saímos, mais quieta é a rua lateral."]};
englishA2Plans[133]={"title": "Lotado na hora do rush", "file": "", "grammar": "Too much e too many", "goal": "Reclame de excesso usando too much e too many.", "words": [["stuffy", "abafado"], ["noise level", "nível de ruído"], ["queue", "fila"], ["packed like sardines", "lotado"], ["shove", "empurrar"], ["bump", "esbarrar"], ["sweaty", "suado"], ["chatter", "falatório"]]};
englishA2Content[133]=[[["Mia is on the subway at rush hour, and the crowd is huge.", "Mia está no metrô na hora do rush, e a multidão é enorme."], ["The train is packed like sardines, and the air is stuffy.", "O trem está lotado, e o ar está abafado."], ["There are too many people and too much noise in the car.", "Há gente demais e barulho demais no vagão."], ["A baby in a stroller cries, and a man bumps into Mia.", "Um bebê no carrinho chora, e um homem esbarra na Mia."], ["The chatter is loud, and the noise level only goes up.", "O falatório é alto, e o nível de ruído só aumenta."], ["At the turnstile, a long queue of sweaty people waits to leave.", "Na catraca, uma longa fila de pessoas suadas espera para sair."]], [["Ben, this train is packed like sardines. I can't breathe!", "Ben, este trem está lotado. Eu não consigo respirar!"], ["I know. There are too many people, and the air is stuffy.", "Eu sei. Tem gente demais, e o ar está abafado."], ["Someone just tried to shove me, and my bag hit that man.", "Alguém acabou de tentar me empurrar, e minha bolsa bateu naquele homem."], ["Sorry about that! There's too much noise, and nobody listens.", "Desculpe! Tem barulho demais, e ninguém escuta."], ["The traffic jam above ground is bad, so everyone takes the subway.", "O engarrafamento lá em cima está ruim, então todo mundo pega o metrô."], ["Really? I always leave early to avoid rush hour.", "Sério? Eu sempre saio cedo para evitar a hora do rush."], ["Good plan. Tomorrow I'll leave an hour earlier. Too much stress is bad for me.", "Bom plano. Amanhã vou sair uma hora mais cedo. Estresse demais faz mal para mim."], ["Deal. See you at the turnstile at seven.", "Combinado. Até amanhã na catraca às sete."]], ["/aʊ/ em crowd e loud", "O som /aʊ/ em crowd e loud começa com a boca bem aberta, como um 'a', e termina fechando os lábios num 'u' curto. Parece o 'au' de 'cauda', mas com a boca mais aberta no começo.", ["crowd", "loud"]], ["There are ___ people on the train.", "too many", "too much", "Há gente demais no trem.", "People é contável no plural, então usamos too many."], [["I know. There are too many people, and the air is stuffy.", "Eu sei. Tem gente demais, e o ar está abafado."], ["Sorry about that! There's too much noise, and nobody listens.", "Desculpe! Tem barulho demais, e ninguém escuta."]], [{"t": "c", "q": "I can't sleep. There is ___ noise here.", "o": ["too much", "too many", "much too"], "pt": "Não consigo dormir. Tem barulho demais aqui.", "why": "Noise é incontável, então usamos too much."}, {"t": "l", "say": "There are too many people in the queue.", "o": ["There are too many people in the queue.", "There is too much people in the queue.", "There are many people in the queue."], "why": "Ouça too many antes de people."}, {"t": "b", "pt": "Há gente demais na fila", "w": ["There", "are", "too", "many", "people", "in", "the", "queue"]}, {"t": "b", "pt": "Tem barulho demais neste trem", "w": ["There", "is", "too", "much", "noise", "on", "this", "train"]}]];
