englishA2Plans[137]={"title": "Dispensa cheia depois da compra", "file": "", "grammar": "Plenty of e lots of", "goal": "Fale de abundância usando plenty of e lots of.", "words": [["cereal box", "caixa de cereal"], ["shelf life", "prazo de validade"], ["bulk", "a granel"], ["stock up", "fazer estoque"], ["sack", "saco grande"], ["granola", "granola"], ["tortilla", "tortilha"], ["lentils", "lentilhas"]]};
englishA2Content[137]=[[["Mia and Tom went to the store and bought food in bulk.", "Mia e Tom foram ao mercado e compraram comida a granel."], ["They wanted to stock up before the rush hour on Friday.", "Eles queriam fazer estoque antes do horário de pico de sexta."], ["Now the pantry has lots of pasta, and there is plenty of rice.", "Agora a despensa tem muito macarrão, e há bastante arroz."], ["Mia puts a sack of lentils on the shelf and the granola in a jar.", "Mia põe um saco de lentilhas na prateleira e a granola em um pote."], ["The cereal box says the shelf life is six months, so they have plenty of time.", "A caixa de cereal diz que o prazo de validade é de seis meses, então eles têm bastante tempo."], ["Tom just smiles because they have lots of tortillas for the whole month.", "Tom só sorri porque eles têm muitas tortilhas para o mês todo."]], [["Look at our pantry! We have lots of pasta and rice now.", "Olhe nossa despensa! Agora temos muito macarrão e arroz."], ["Yes, we bought them in bulk. There's plenty of room on the shelf.", "Sim, compramos a granel. Tem bastante espaço na prateleira."], ["Check the date on the cereal box. What's the shelf life?", "Veja a data na caixa de cereal. Qual é o prazo de validade?"], ["It's eight months. We have plenty of time to eat it.", "São oito meses. Temos bastante tempo para comer."], ["Good. Did you wait in the queue long at the store?", "Bom. Você esperou muito na fila do mercado?"], ["No, I went before the rush hour. It took just ten minutes.", "Não, fui antes da hora do rush. Levou só dez minutos."], ["Perfect. I need a teaspoon of salt for the soup. Is there any left?", "Perfeito. Preciso de uma colher de chá de sal para a sopa. Sobrou algum?"], ["Yes, it's in the jar next to the granola.", "Sim, está no pote ao lado da granola."]], ["/dʒ/ em jar e just", "O som /dʒ/ em jar e just junta um d com o 'ch' suave, como o 'dj' de 'djavan'. Os lábios ficam um pouco arredondados e a língua toca atrás dos dentes de cima.", ["jar", "just"]], ["We have plenty ___ rice for the month.", "of", "to", "Temos bastante arroz para o mês.", "Plenty e lots são seguidos de of: plenty of, lots of."], [["Look at our pantry! We have lots of pasta and rice now.", "Olhe nossa despensa! Agora temos muito macarrão e arroz."], ["It's eight months. We have plenty of time to eat it.", "São oito meses. Temos bastante tempo para comer."]], [{"t": "c", "q": "There is ___ of milk in the fridge.", "o": ["plenty", "enough", "many"], "pt": "Tem bastante leite na geladeira.", "why": "Plenty of significa bastante; many não vem com of aqui."}, {"t": "l", "say": "We have lots of pasta.", "o": ["We have lots of pasta.", "We have lot of pasta.", "We have a lot pasta."], "why": "Ouça lots of: muito macarrão."}, {"t": "b", "pt": "Temos muito macarrão na despensa", "w": ["We", "have", "lots", "of", "pasta", "in", "the", "pantry"]}, {"t": "b", "pt": "Temos bastante tempo", "w": ["We", "have", "plenty", "of", "time"]}]];
