englishA2ExtraWordExamples[138]={"upstairs neighbor": ["He is the upstairs neighbor who plays loud music.", "Ele é o vizinho de cima que toca música alta."]};
englishA2Plans[139]={"title": "Revisão: Dia no shopping center", "file": "", "grammar": "Revisão: comparativos, would, should e quantificadores", "goal": "Compare lojas e faça pedidos no shopping center.", "words": [["mannequin", "manequim"], ["fitting room", "provador"], ["clearance", "liquidação"], ["shopping bag", "sacola de compras"], ["handbag", "bolsa"], ["loafers", "mocassins"], ["checkout", "caixa"], ["markdown", "desconto"], ["arcade", "fliperama"]]};
englishA2Content[139]=[[["Ana and Noah spend Saturday at the mall.", "Ana e Noah passam o sábado no shopping."], ["A mannequin in the window wears a handbag much nicer than Ana's old one.", "Um manequim na vitrine usa uma bolsa bem mais bonita que a velha da Ana."], ["The store has a clearance sale, and the markdown is far bigger than last month.", "A loja tem liquidação, e o desconto é bem maior que no mês passado."], ["Noah tries the loafers in the fitting room, but they are too small.", "Noah experimenta os mocassins no provador, mas são pequenos demais."], ["Ana says Noah should try a bigger size.", "Ana diz que Noah deveria experimentar um tamanho maior."], ["At the checkout, the clerk puts everything in a shopping bag.", "No caixa, a atendente põe tudo em uma sacola de compras."]], [["Noah, look at this clearance sign! Everything is far cheaper today.", "Noah, olhe esta placa de liquidação! Tudo está bem mais barato hoje."], ["Wow. Would you like to buy the handbag the mannequin is wearing?", "Uau. Você gostaria de comprar a bolsa que o manequim está usando?"], ["I'd like to, but I don't have enough money for it.", "Eu gostaria, mas não tenho dinheiro suficiente para ela."], ["Then you should wait. The markdown will get bigger next week.", "Então você deveria esperar. O desconto vai aumentar na semana que vem."], ["True. The more I wait, the less I pay. Let's try these loafers; they're a bargain.", "Verdade. Quanto mais espero, menos pago. Vamos experimentar estes mocassins; são uma pechincha."], ["Okay. I need a quiet fitting room. This store is too stuffy.", "Certo. Preciso de um provador tranquilo. Esta loja está abafada demais."], ["Hmm, they're a lot more comfortable than my old shoes.", "Hmm, eles são bem mais confortáveis que meus sapatos velhos."], ["Great! Let's pay by card at the checkout, then visit the arcade.", "Ótimo! Vamos pagar com cartão no caixa e depois visitar o fliperama."], ["Sure! There are plenty of games there, but the kids must keep it down.", "Claro! Tem muitos jogos lá, mas as crianças devem fazer menos barulho."], ["Deal. After that we can stock up on snacks in bulk.", "Combinado. Depois disso podemos fazer estoque de lanches a granel."]], ["/ɑr/ em bargain e card", "O som /ɑr/ em bargain e card tem a boca bem aberta, como o 'a' de 'pá', e depois o r americano: a ponta da língua sobe sem tocar o céu da boca. Em card, o r fica antes do d.", ["bargain", "card"]], ["I'd ___ to try the loafers, please.", "like", "likes", "Eu gostaria de experimentar os mocassins, por favor.", "Depois de I'd (I would) usamos o verbo na forma base: I'd like."], [["Noah, look at this clearance sign! Everything is far cheaper today.", "Noah, olhe esta placa de liquidação! Tudo está bem mais barato hoje."], ["I'd like to, but I don't have enough money for it.", "Eu gostaria, mas não tenho dinheiro suficiente para ela."]], [{"t": "c", "q": "There are ___ people at the checkout.", "o": ["too many", "too much", "much"], "pt": "Tem gente demais no caixa.", "why": "People é contável no plural, então usamos too many."}, {"t": "l", "say": "You should try the loafers.", "o": ["You should try the loafers.", "You should buy the loafers.", "You shouldn't try the loafers."], "why": "Ouça should try: você deveria experimentar."}, {"t": "b", "pt": "Estes mocassins são muito mais baratos", "w": ["These", "loafers", "are", "much", "cheaper"]}, {"t": "b", "pt": "Eu gostaria de um tamanho maior", "w": ["I'd", "like", "a", "bigger", "size"]}]];
englishA2PhotoThemes[139]="flag";
englishA2MiniStories[139]=["A bolsa na liquidação", "Ana loves a black handbag on a mannequin.~Ana adora uma bolsa preta em um manequim.|The price is fifty dollars, but she has only thirty.~O preço é cinquenta dólares, mas ela tem só trinta.|She feels sad and walks to the arcade with Noah.~Ela fica triste e vai ao fliperama com Noah.|Noah sees a clearance sign near the checkout.~Noah vê uma placa de liquidação perto do caixa.|He runs back and asks the clerk about the handbag.~Ele volta correndo e pergunta à atendente sobre a bolsa.|The clerk looks at the tag and smiles.~A atendente olha a etiqueta e sorri.|The markdown is big, and the handbag costs just thirty dollars.~O desconto é grande, e a bolsa custa só trinta dólares.|Noah runs to the arcade to find Ana.~Noah corre ao fliperama para encontrar Ana.|She is happy, and they go back to the store together.~Ela fica feliz, e eles voltam juntos para a loja.|Ana puts the handbag in her shopping bag and hugs Noah.~Ana põe a bolsa na sacola de compras e abraça Noah."];
englishA2Plans[140]={"title": "Ferramentas na garagem", "file": "", "grammar": "Oração relativa com which", "goal": "Identifique objetos usando which.", "words": [["drill bit", "broca"], ["toolbelt", "cinto de ferramentas"], ["toolbox", "caixa de ferramentas"], ["do it yourself", "faça você mesmo"], ["workbench", "bancada"], ["rake", "ancinho"], ["paintbrush", "pincel"], ["tighten", "apertar"]]};
englishA2Content[140]=[[["Ben's garage, which has a long workbench, is full of tools.", "A garagem do Ben, que tem uma bancada comprida, está cheia de ferramentas."], ["He opens the toolbox, which is red and very heavy.", "Ele abre a caixa de ferramentas, que é vermelha e muito pesada."], ["Inside, there is a wrench, which he needs to tighten a pipe.", "Lá dentro tem uma chave inglesa, de que ele precisa para apertar um cano."], ["The screwdriver, which has a yellow handle, is in his toolbelt.", "A chave de fenda, que tem cabo amarelo, está no cinto de ferramentas dele."], ["He finds a drill bit and a cereal box full of nails.", "Ele acha uma broca e uma caixa de cereal cheia de pregos."], ["Ben loves do it yourself projects, which save him money.", "O Ben adora projetos do tipo faça você mesmo, que fazem ele economizar dinheiro."]], [["Ben, do you have a tape measure? I can't find mine.", "Ben, você tem uma fita métrica? Não acho a minha."], ["Sure. It's in the toolbox, which is next to the door.", "Claro. Está na caixa de ferramentas, que fica do lado da porta."], ["Thanks! I also need a ladder and a paintbrush for the kitchen wall.", "Obrigada! Também preciso de uma escada e de um pincel para a parede da cozinha."], ["The ladder, which is next to the rake in the backyard, is old. Be careful.", "A escada, que está ao lado do ancinho no quintal, é velha. Cuidado."], ["I will. Is that new screwdriver in your shopping bag?", "Eu vou ter. Aquela chave de fenda nova está na sua sacola de compras?"], ["Yes, I got it today. The spare drill bit, which is in my toolbelt, is new too.", "Sim, comprei hoje. A broca reserva, que está no meu cinto de ferramentas, também é nova."], ["Great. I love do it yourself work, but I need to stock up on sandpaper.", "Ótimo. Adoro trabalho faça você mesmo, mas preciso estocar lixa."], ["Don't worry. I'll help you, and we'll finish in twenty minutes.", "Sem problema. Eu te ajudo e terminamos em vinte minutos."]], ["/r/ em wrench e screwdriver", "O r inglês não vibra: puxe a língua para trás sem encostar no céu da boca e arredonde um pouco os lábios. Em wrench, o w não é pronunciado: diga 'rench'.", ["wrench", "screwdriver"]], ["The toolbox, ___ is red, is very heavy.", "which", "who", "A caixa de ferramentas, que é vermelha, é muito pesada.", "Para coisas (objetos), usamos which; who é só para pessoas."], [["He opens the toolbox, which is red and very heavy.", "Ele abre a caixa de ferramentas, que é vermelha e muito pesada."], ["The ladder, which is next to the rake in the backyard, is old. Be careful.", "A escada, que está ao lado do ancinho no quintal, é velha. Cuidado."]], [{"t": "c", "q": "I need a drill bit, ___ is in my toolbelt.", "o": ["which", "who", "where"], "pt": "Preciso de uma broca, que está no meu cinto de ferramentas.", "why": "A broca é uma coisa, então usamos which; who é para pessoas e where para lugares."}, {"t": "l", "say": "The wrench, which is old, is on the table.", "o": ["The wrench, which is old, is on the table.", "The wrench, which is new, is on the table.", "The wrench, which is old, is on the chair."], "why": "A chave inglesa é velha (old) e está na mesa (table)."}, {"t": "b", "pt": "A caixa de ferramentas, que é vermelha, é pesada.", "w": ["The", "toolbox", "which", "is", "red", "is", "heavy"]}, {"t": "b", "pt": "Ele tem uma escada que é velha.", "w": ["He", "has", "a", "ladder", "which", "is", "old"]}]];
