englishA2Plans[148]={"title": "Museu de história natural", "file": "", "grammar": "Voz passiva no passado simples", "goal": "Conte quando algo foi feito ou descoberto.", "words": [["fossil", "fóssil"], ["skeleton", "esqueleto"], ["dinosaur", "dinossauro"], ["go back in time", "voltar no tempo"], ["bone", "osso"], ["claw", "garra"], ["footprint", "pegada"], ["ancient", "antigo"], ["extinct", "extinto"]]};
englishA2Content[148]=[[["Mia and Leo visit the natural history museum.", "A Mia e o Leo visitam o museu de história natural."], ["A giant dinosaur skeleton stands in the main hall.", "Um esqueleto gigante de dinossauro fica no salão principal."], ["It was found in Argentina many years ago.", "Ele foi encontrado na Argentina há muitos anos."], ["Its bones were cleaned and put together by scientists.", "Os ossos dele foram limpos e montados por cientistas."], ["The big exhibit was opened last spring.", "A grande exposição foi aberta na primavera passada."], ["In the gift shop, Leo buys a paperback about extinct animals.", "Na loja de presentes, o Leo compra um livro de bolso sobre animais extintos."]], [["Leo, look at this fossil! It's an ancient footprint.", "Leo, olha este fóssil! É uma pegada antiga."], ["Cool. When was it discovered?", "Legal. Quando ele foi descoberto?"], ["The sign says it was found in 1985, near a river.", "A placa diz que foi encontrado em 1985, perto de um rio."], ["And who built the skeleton? It's huge.", "E quem montou o esqueleto? É enorme."], ["Scientists did. Each bone was cleaned by hand.", "Cientistas. Cada osso foi limpo à mão."], ["Look at that claw! I read a chapter about it in that paperback. It's a real page-turner.", "Olha aquela garra! Li um capítulo sobre isso naquele livro de bolso. É envolvente de verdade."], ["I'd love to go back in time and see one.", "Eu adoraria voltar no tempo e ver um."], ["Me too! But let's see the other exhibit first.", "Eu também! Mas vamos ver a outra exposição primeiro."]], ["/ɪ/ em exhibit e skeleton", "O /ɪ/ de exhibit e skeleton é um 'i' curto e relaxado, entre 'i' e 'e', com a língua mais baixa do que em 'see'. Compare: 'sit' (curto) e 'seat' (longo).", ["exhibit", "skeleton"]], ["The skeleton ___ found in Argentina.", "was", "were", "O esqueleto foi encontrado na Argentina.", "Skeleton é singular e o fato é passado, então usamos was + particípio."], [["It was found in Argentina many years ago.", "Ele foi encontrado na Argentina há muitos anos."], ["Its bones were cleaned and put together by scientists.", "Os ossos dele foram limpos e montados por cientistas."]], [{"t": "c", "q": "The bones ___ cleaned last week.", "o": ["were", "was", "are"], "pt": "Os ossos foram limpos semana passada.", "why": "Bones é plural e last week indica passado, então usamos were + particípio."}, {"t": "l", "say": "The fossil was found near a river.", "o": ["The fossil was found near a river.", "The fossil was found near a road.", "The fossil was lost near a river."], "why": "O fóssil foi encontrado (found) perto de um rio (river)."}, {"t": "b", "pt": "O esqueleto foi encontrado em 1985.", "w": ["The", "skeleton", "was", "found", "in", "1985"]}, {"t": "b", "pt": "Os ossos foram limpos por cientistas.", "w": ["The", "bones", "were", "cleaned", "by", "scientists"]}]];
