englishA2Plans[151]={"title": "Reparos no prédio", "file": "", "grammar": "Passiva com will e can", "goal": "Fale de planos e possibilidades na passiva.", "words": [["hallway", "corredor"], ["drain", "ralo"], ["maintenance", "manutenção"], ["out of order", "fora de serviço"], ["crack", "rachadura"], ["stain", "mancha"], ["peel", "descascar"], ["unclog", "desentupir"]]};
englishA2Content[151]=[[["Rosa lives in an old building on Pine Street.", "Rosa mora em um prédio antigo na Pine Street."], ["The elevator is out of order, so everyone uses the stairs.", "O elevador está fora de serviço, então todo mundo usa a escada."], ["There is a big stain on the ceiling in the hallway.", "Há uma mancha grande no teto do corredor."], ["A small crack is in the wall, and the paint peels.", "Há uma pequena rachadura na parede, e a tinta descasca."], ["Mr. Gray from maintenance wears a safety vest and says he can repair it on Friday.", "O Sr. Gray da manutenção usa um colete de segurança e diz que pode consertar isso na sexta."], ["The kitchen drain is full of water, and the doorbell doesn't work.", "O ralo da cozinha está cheio de água, e a campainha não funciona."]], [["Hello, Mr. Gray. The drain in my kitchen is full of water again.", "Olá, Sr. Gray. O ralo da minha cozinha está cheio de água de novo."], ["I'm sorry about that. It can be unclogged this afternoon.", "Sinto muito. Ele pode ser desentupido hoje à tarde."], ["Great. And what about the ceiling in the hallway? There's a stain.", "Ótimo. E o teto do corredor? Tem uma mancha."], ["The ceiling will be painted next week. The painter is coming on Tuesday.", "O teto vai ser pintado na semana que vem. O pintor vem na terça."], ["Good. Is the elevator still out of order?", "Bom. O elevador ainda está fora de serviço?"], ["Yes, but it will be repaired tomorrow morning.", "Sim, mas ele vai ser consertado amanhã de manhã."], ["Then I'll use the stairs today. My bags aren't heavy.", "Então hoje eu uso a escada. Minhas sacolas não estão pesadas."], ["No problem. I'll fix your doorbell on Friday, too.", "Sem problema. Eu conserto sua campainha na sexta também."]], ["/ɛr/ em repair e stairs", "O som /ɛr/ de repair e stairs começa com a boca meio aberta, como o é de pé, e termina com a língua puxada para trás no r. Não pronuncie o r como o rr de carro; ele é mais suave.", ["repair", "stairs"]], ["The elevator ___ be repaired tomorrow.", "will", "did", "O elevador vai ser consertado amanhã.", "Para planos no futuro na passiva, usamos will be + particípio."], [["I'm sorry about that. It can be unclogged this afternoon.", "Sinto muito. Ele pode ser desentupido hoje à tarde."], ["The ceiling will be painted next week. The painter is coming on Tuesday.", "O teto vai ser pintado na semana que vem. O pintor vem na terça."]], [{"t": "c", "q": "The drain ___ be unclogged today.", "o": ["can", "does", "are"], "pt": "O ralo pode ser desentupido hoje.", "why": "Para possibilidade na passiva usamos can be + particípio."}, {"t": "l", "say": "The ceiling will be painted next week.", "o": ["The ceiling will be painted next week.", "The ceiling was painted next week.", "The ceiling will paint next week."], "why": "Futuro na passiva: will be + particípio, e next week indica futuro."}, {"t": "b", "pt": "O ralo pode ser consertado hoje.", "w": ["The", "drain", "can", "be", "fixed", "today"]}, {"t": "b", "pt": "O elevador vai ser reparado amanhã.", "w": ["The", "elevator", "will", "be", "repaired", "tomorrow"]}]];
