englishA2Plans[154]={"title": "Pedindo ajuda ao técnico de informática", "file": "", "grammar": "Want/ask/tell + alguém + to", "goal": "Peça que alguém faça algo com want someone to.", "words": [["technician", "técnico"], ["virus", "vírus"], ["mouse pad", "mousepad"], ["restart", "reiniciar"], ["reboot", "reinicialização"], ["backup", "cópia de segurança"], ["glitch", "falha"], ["install", "instalar"], ["update", "atualização"]]};
englishA2Content[154]=[[["Tom's laptop has a virus, and the screen keeps freezing.", "O laptop de Tom está com vírus, e a tela não para de travar."], ["His car has a flat tire, so he can't go to the office.", "O carro dele está com o pneu furado, então ele não pode ir ao escritório."], ["He calls the technician, Ms. Hill, and asks her to come today.", "Ele liga para a técnica, a Sra. Hill, e pede que ela venha hoje."], ["She wants him to restart the laptop first.", "Ela quer que ele reinicie o laptop primeiro."], ["Then she tells him to install an update and make a backup.", "Depois ela manda ele instalar uma atualização e fazer um backup."], ["After the reboot, the glitch is gone, and Tom walks down the hallway to make coffee.", "Depois da reinicialização, a falha desaparece, e Tom anda pelo corredor para fazer café."]], [["Hello, Ms. Hill? My laptop has a virus, and the maintenance office says the Wi-Fi is out of order.", "Alô, Sra. Hill? Meu laptop está com vírus, e a manutenção diz que o Wi-Fi está fora de serviço."], ["Don't panic, Tom. I want you to restart it right now.", "Calma, Tom. Quero que você reinicie agora mesmo."], ["OK, it's restarting. The mouse pad doesn't work anymore, though.", "Certo, está reiniciando. Mas o mousepad não funciona mais."], ["Then I'll ask you to plug in a regular mouse.", "Então vou pedir que você ligue um mouse comum."], ["I have one in my bag. Should I make a backup first?", "Tenho um na mochila. Devo fazer um backup antes?"], ["Yes, please. After that, I want you to install the update.", "Sim, por favor. Depois disso, quero que você instale a atualização."], ["Done! The glitch is gone, and the virus message too.", "Pronto! A falha sumiu, e a mensagem de vírus também."], ["Perfect. Your laptop is clean now, Tom.", "Perfeito. Seu laptop está limpo agora, Tom."]], ["/aɪ/ em virus e iPad", "O /aɪ/ de virus e tire começa com a boca bem aberta, como o a de pá, e termina fechando para o i, como o ai de pai. Faça os dois sons em um movimento só, sem parar.", ["virus", "tire"]], ["Tom asks her ___ come today.", "to", "for", "Tom pede que ela venha hoje.", "Depois de ask + pessoa, usamos to + verbo."], [["He calls the technician, Ms. Hill, and asks her to come today.", "Ele liga para a técnica, a Sra. Hill, e pede que ela venha hoje."], ["She wants him to restart the laptop first.", "Ela quer que ele reinicie o laptop primeiro."]], [{"t": "c", "q": "I want you ___ restart the laptop.", "o": ["to", "for", "that"], "pt": "Quero que você reinicie o laptop.", "why": "Want + pessoa + to + verbo mostra o que queremos que alguém faça."}, {"t": "l", "say": "She wants him to restart the laptop first.", "o": ["She wants him to restart the laptop first.", "She wants he to restart the laptop first.", "She wants him restart the laptop first."], "why": "Depois de want usamos him (objeto) + to + verbo."}, {"t": "b", "pt": "Eu quero que você instale a atualização.", "w": ["I", "want", "you", "to", "install", "the", "update"]}, {"t": "b", "pt": "Ela pede que ele reinicie o laptop.", "w": ["She", "asks", "him", "to", "restart", "the", "laptop"]}]];
