englishA2Plans[155]={"title": "Hábitos de saúde", "file": "", "grammar": "Stop, start e remember + -ing vs to", "goal": "Distinga stop doing e stop to do.", "words": [["jogging", "corrida leve"], ["hydrate", "hidratar"], ["vitamin", "vitamina"], ["work out", "malhar"], ["pulse", "pulso"], ["dumbbell", "haltere"], ["heartbeat", "batimento cardíaco"], ["exhausted", "exausto"]]};
englishA2Content[155]=[[["Sam stopped jogging last winter because of a virus.", "Sam parou de correr no inverno passado por causa de um vírus."], ["Now he wants to restart his habits and paddle his canoe again.", "Agora ele quer recomeçar seus hábitos e remar a canoa de novo."], ["Today he stops at the gym to work out.", "Hoje ele para na academia para malhar."], ["He remembers to bring his sneakers and a big bottle of water.", "Ele lembra de levar os tênis e uma garrafa grande de água."], ["After ten minutes with the dumbbells, his pulse is fast and his heartbeat is loud.", "Depois de dez minutos com os halteres, o pulso dele está rápido e o batimento cardíaco, forte."], ["He feels exhausted but happy, and he starts jogging again next week.", "Ele se sente exausto, mas feliz, e começa a correr de novo na semana que vem."]], [["Sam! I didn't see you here for months.", "Sam! Faz meses que não te vejo aqui."], ["I stopped working out last winter. I had a virus for two weeks.", "Parei de malhar no inverno passado. Fiquei com um vírus por duas semanas."], ["Oh no. Do you remember to hydrate during your workouts?", "Ah, não. Você lembra de se hidratar durante os treinos?"], ["Yes, I always bring a big bottle of water, and I take a vitamin every day.", "Sim, eu sempre trago uma garrafa grande de água, e tomo uma vitamina todo dia."], ["Great. Did you start jogging again, or just the dumbbells?", "Ótimo. Você voltou a correr, ou só aos halteres?"], ["Just the dumbbells so far. My pulse is high now.", "Só os halteres por enquanto. Meu pulso está alto agora."], ["Take a break, then. You look exhausted.", "Descanse um pouco, então. Você parece exausto."], ["Yes, you're right. I'll rest for five minutes.", "Sim, você tem razão. Vou descansar por cinco minutos."]], ["/dʒ/ em jogging e gym", "O /dʒ/ de jogging e gym é como o dj de djalma: a língua encosta no céu da boca e solta o ar com voz. Não use o j do português; em inglês começa com um pequeno d.", ["jogging", "gym"]], ["Sam stopped ___ because he was sick.", "jogging", "to jog", "Sam parou de correr porque estava doente.", "Stop + -ing significa parar de fazer algo."], [["Sam stopped jogging last winter because of a virus.", "Sam parou de correr no inverno passado por causa de um vírus."], ["He remembers to bring his sneakers and a big bottle of water.", "Ele lembra de levar os tênis e uma garrafa grande de água."]], [{"t": "c", "q": "Remember ___ your sneakers tomorrow!", "o": ["to bring", "bring", "brings"], "pt": "Lembre de trazer seus tênis amanhã!", "why": "Remember + to + verbo é lembrar de fazer algo no futuro."}, {"t": "l", "say": "I stopped working out in the winter.", "o": ["I stopped working out in the winter.", "I stopped to work out in the winter.", "I stop working out in the winter."], "why": "Stop + -ing é parar de fazer, e stopped marca o passado."}, {"t": "b", "pt": "Ele começou a correr de novo.", "w": ["He", "started", "jogging", "again"]}, {"t": "b", "pt": "Eu parei para tomar água.", "w": ["I", "stopped", "to", "drink", "water"]}]];
