englishA2Plans[159]={"title": "Revisão: Noite de sorteio na escola", "file": "", "grammar": "Revisão: orações relativas, quantificadores e futuro", "goal": "Descreva pessoas e prêmios no sorteio da escola.", "words": [["raffle", "sorteio"], ["ticket stub", "canhoto"], ["emcee", "mestre de cerimônias"], ["draw a name", "sortear um nome"], ["gasp", "ofegar de surpresa"], ["bleachers", "arquibancada"], ["announce", "anunciar"], ["lucky", "sortudo"]]};
englishA2Content[159]=[[["Tonight is the school raffle, and everyone who has a ticket sits in the bleachers.", "Hoje é o sorteio da escola, e todo mundo que tem ingresso senta na arquibancada."], ["The emcee is Mr. Lee, the teacher who always tells funny jokes.", "O mestre de cerimônias é o Sr. Lee, o professor que sempre conta piadas engraçadas."], ["The first prize is a ski trip, which includes a lift ticket and two ski poles.", "O primeiro prêmio é uma viagem de esqui, que inclui um passe de teleférico e dois bastões."], ["A few parents are taking photos, and a photographer from the town paper will be there.", "Alguns pais estão tirando fotos, e um fotógrafo do jornal da cidade estará lá."], ["Mr. Lee will draw a name, and the person who wins gets the prize.", "O Sr. Lee vai sortear um nome, e quem ganhar leva o prêmio."], ["Ben holds his ticket stub and feels very lucky.", "Ben segura o canhoto do ingresso e se sente muito sortudo."]], [["Ben, did you bring your ticket stub? They are drawing names soon.", "Ben, você trouxe o canhoto do ingresso? Eles vão sortear os nomes logo."], ["Yes, it's in my pocket. How many tickets did you buy?", "Sim, está no meu bolso. Quantos ingressos você comprou?"], ["Only two, but Noah bought a lot, and the girl next to us has ten.", "Só dois, mas o Noah comprou muitos, e a menina ao nosso lado tem dez."], ["Look! The principal is going to announce the first winner.", "Olhe! O diretor vai anunciar o primeiro ganhador."], ["Shh. The emcee is picking a ticket from the bowl. Listen carefully!", "Shh. O mestre de cerimônias está pegando um ingresso da tigela. Escute com atenção!"], ["Wait, that's my number! I'm the one who wins the prize!", "Espere, é o meu número! Sou eu quem ganha o prêmio!"], ["Really? That's amazing! I'm so happy for you.", "Sério? Que incrível! Estou muito feliz por você."], ["Thanks, Ana! Yes, I'm the lucky one tonight!", "Obrigado, Ana! Sim, eu sou o sortudo hoje à noite!"]], ["/z/ em prize e winner", "O /z/ de prize e wins é como o z de zebra: a língua fica atrás dos dentes de cima e a garganta vibra (coloque a mão no pescoço). Não troque por /s/, que não vibra; no final de wins soa o mesmo z.", ["prize", "wins"]], ["The man ___ draws the name is the emcee.", "who", "which", "O homem que sorteia o nome é o mestre de cerimônias.", "Para falar de uma pessoa com uma oração relativa, usamos who."], [["Tonight is the school raffle, and everyone who has a ticket sits in the bleachers.", "Hoje é o sorteio da escola, e todo mundo que tem ingresso senta na arquibancada."], ["Mr. Lee will draw a name, and the person who wins gets the prize.", "O Sr. Lee vai sortear um nome, e quem ganhar leva o prêmio."]], [{"t": "c", "q": "I don't have ___ tickets.", "o": ["many", "much", "a little"], "pt": "Eu não tenho muitos ingressos.", "why": "Tickets é contável, e com contáveis em frases negativas usamos many."}, {"t": "l", "say": "The student who wins the prize is lucky.", "o": ["The student who wins the prize is lucky.", "The student which wins the prize is lucky.", "The student who win the prize is lucky."], "why": "Para pessoas usamos who, e com who o verbo concorda: wins."}, {"t": "b", "pt": "Eu comprei muitos ingressos.", "w": ["I", "bought", "a", "lot", "of", "tickets"]}, {"t": "b", "pt": "O mestre de cerimônias vai sortear um nome.", "w": ["The", "emcee", "is", "going", "to", "draw", "a", "name"]}]];
englishA2PhotoThemes[159]="notebook";
englishA2MiniStories[159]=["A noite do sorteio", "Ana goes to the school raffle with her brother Tom.~Ana vai ao sorteio da escola com o irmão, Tom.|She bought one ticket, and Tom bought three tickets.~Ela comprou um ingresso, e Tom comprou três.|The first prize is a blue bike, and Ana really wants it.~O primeiro prêmio é uma bicicleta azul, e Ana a quer muito.|The emcee draws a name, and the whole gym gets quiet.~O mestre de cerimônias sorteia um nome, e o ginásio inteiro fica em silêncio.|\"The winner is Tom Silva!\" he says.~\"O ganhador é Tom Silva!\", ele diz.|Everyone gasps, and Tom jumps up from the bleachers.~Todos ofegam, e Tom pula da arquibancada.|Then he looks at his ticket stub and laughs.~Então ele olha o canhoto do ingresso e ri.|\"This is Ana's ticket,\" he says. \"I took the wrong one.\"~\"Este é o ingresso da Ana\", ele diz. \"Eu peguei o errado.\"|Tom walks to the stage, and the principal gives the bike to Ana.~Tom vai ao palco, e o diretor entrega a bicicleta para Ana.|That night, Ana is the happiest winner in school, and Tom is her biggest fan.~Naquela noite, Ana é a ganhadora mais feliz da escola, e Tom é seu maior fã."];
englishA2ExtraWordExamples[159]={"gasp": ["The crowd gasps when the emcee calls the number.", "A plateia ofega quando o mestre de cerimônias chama o número."]};
englishA2Plans[160]={"title": "Arrumando a mesa de trabalho", "file": "", "grammar": "Verbos frasais separáveis (pick up, turn on)", "goal": "Use verbos frasais com objeto no meio.", "words": [["paper clip", "clipe de papel"], ["binder", "fichário"], ["sticky note", "post-it"], ["throw away", "jogar fora"], ["highlighter", "marca-texto"], ["hole punch", "furador"], ["rubber band", "elástico"], ["trash can", "lata de lixo"]]};
englishA2Content[160]=[[["Ana's desk is a mess this morning.", "A mesa da Ana está uma bagunça esta manhã."], ["She picks the old papers up and throws them away.", "Ela pega os papéis velhos e joga todos fora."], ["Then she puts the paper clips and the rubber bands in a small box.", "Depois ela coloca os clipes de papel e os elásticos numa caixa pequena."], ["A yellow sticky note falls on the floor, so she picks it up.", "Um post-it amarelo cai no chão, então ela o pega."], ["The note says, \"Take your vitamin before jogging.\"", "O bilhete diz: \"Tome sua vitamina antes de correr.\""], ["Now the desk looks clean, and Ana feels happy.", "Agora a mesa está limpa, e a Ana está feliz."]], [["Ben, your desk is really messy. Where is the stapler?", "Ben, sua mesa está muito bagunçada. Cadê o grampeador?"], ["It's in the drawer, under the binder. I can't find my highlighter, though.", "Está na gaveta, embaixo do fichário. Mas não acho meu marca-texto."], ["Look, it's under the hole punch. Please pick it up.", "Olha, está embaixo do furador. Pegue, por favor."], ["Thanks! Should I throw this old paper away?", "Valeu! Devo jogar este papel velho fora?"], ["Yes, throw it away. And keep the paper clips in a box.", "Sim, jogue fora. E guarde os clipes numa caixa."], ["Sure. What about this sticky note? It says vitamin.", "Claro. E este post-it? Está escrito vitamina."], ["Keep that one. It's a reminder to take your vitamin before you work out.", "Fique com esse. É um lembrete para tomar sua vitamina antes de treinar."], ["Oh, right, I forgot! Thanks, Ana. Now my desk looks great.", "Ah, é, eu esqueci! Valeu, Ana. Agora minha mesa está ótima."]], ["/eɪ/ em stapler e paper", "Em stapler e paper, o \"a\" é um ditongo: começa parecido com o \"ê\" e termina com um \"i\" curto, como em \"lei\". Não diga \"pépa\"; diga \"PEI-per\".", ["stapler", "paper"]], ["These papers are old. Please throw ___ away.", "them", "they", "Esses papéis são velhos. Por favor, jogue-os fora.", "Com um pronome, ele vai no meio do verbo frasal: throw them away."], [["She picks the old papers up and throws them away.", "Ela pega os papéis velhos e joga todos fora."], ["A yellow sticky note falls on the floor, so she picks it up.", "Um post-it amarelo cai no chão, então ela o pega."]], [{"t": "c", "q": "The sticky note is on the floor. Please pick ___ up.", "o": ["it", "its", "them"], "pt": "O post-it está no chão. Por favor, pegue-o.", "why": "O post-it é uma coisa só, então usamos it no meio de pick up."}, {"t": "l", "say": "She throws them away.", "o": ["She throws them away.", "She throws him away.", "She threw them away."], "why": "Ouça: throws (presente) e them (as coisas), não him nem threw."}, {"t": "b", "pt": "Pegue isso, por favor.", "w": ["Please", "pick", "it", "up"]}, {"t": "b", "pt": "Eu joguei eles fora.", "w": ["I", "threw", "them", "away"]}]];
