englishA2Plans[162]={"title": "Procurando informação em uma biblioteca de bairro", "file": "", "grammar": "Look for, look after, look up", "goal": "Use look for, look after e look up.", "words": [["encyclopedia", "enciclopédia"], ["thesaurus", "dicionário de sinônimos"], ["bookmark", "marcador de página"], ["look it up", "procurar (uma palavra)"], ["library card", "carteirinha da biblioteca"], ["fiction", "ficção"], ["biography", "biografia"], ["return", "devolver"]]};
englishA2Content[162]=[[["Rosa goes to the neighborhood library on Saturday.", "A Rosa vai à biblioteca do bairro no sábado."], ["She is looking for an encyclopedia about birds.", "Ela está procurando uma enciclopédia sobre pássaros."], ["A librarian shows her the right shelf.", "Uma bibliotecária mostra a ela a prateleira certa."], ["Rosa wants a different word for \"big\", so she looks it up in the thesaurus.", "A Rosa quer outra palavra para \"big\", então ela procura no dicionário de sinônimos."], ["She uses an old ticket stub as a bookmark.", "Ela usa um velho canhoto de ingresso como marcador de página."], ["At home she looks after her little brother and reads to him.", "Em casa ela cuida do irmãozinho e lê para ele."]], [["Excuse me, I'm looking for an encyclopedia about birds.", "Com licença, estou procurando uma enciclopédia sobre pássaros."], ["Sure. It's on the second shelf, near the biographies and the dictionaries.", "Claro. Está na segunda prateleira, perto das biografias e dos dicionários."], ["Found it! Do you also have a thesaurus? I need a better word for \"nice\".", "Achei! Vocês também têm um dicionário de sinônimos? Preciso de uma palavra melhor para \"nice\"."], ["Yes, we do. If you don't know a word, you can look it up here.", "Temos, sim. Se você não conhece uma palavra, pode procurá-la aqui."], ["Great. Can I borrow this book with my library card? I'll use this old ticket stub as a bookmark.", "Ótimo. Posso pegar este livro emprestado com minha carteirinha? Vou usar este canhoto velho como marcador de página."], ["Of course. By the way, we have a raffle on Friday. They draw a name at five, and the prize is a box of fiction books.", "Claro. Aliás, temos um sorteio na sexta. Eles sorteiam um nome às cinco, e o prêmio é uma caixa de livros de ficção."], ["Nice! I'll come, and I'll bring my brother. I look after him on Fridays.", "Legal! Eu venho e trago meu irmão. Eu cuido dele nas sextas."], ["Perfect. Then I'll see you both on Friday, Rosa.", "Perfeito. Então eu vejo vocês dois na sexta, Rosa."]], ["/k/ em bookmark e look", "Em bookmark e look, o \"k\" é seco e forte: encoste o fundo da língua no céu da boca e solte um pequeno sopro de ar. No fim de look, não acrescente \"i\" (nada de \"lúki\").", ["bookmark", "look"]], ["Rosa is ___ an encyclopedia about birds.", "looking for", "looking after", "A Rosa está procurando uma enciclopédia sobre pássaros.", "Look for significa procurar; look after significa cuidar de."], [["She is looking for an encyclopedia about birds.", "Ela está procurando uma enciclopédia sobre pássaros."], ["At home she looks after her little brother and reads to him.", "Em casa ela cuida do irmãozinho e lê para ele."]], [{"t": "c", "q": "If you don't know the word, ___ it up.", "o": ["look", "see", "watch"], "pt": "Se você não sabe a palavra, procure-a.", "why": "Look it up é a expressão para procurar uma palavra num livro ou site."}, {"t": "l", "say": "She looks after her brother.", "o": ["She looks after her brother.", "She looks for her brother.", "She looks at her brother."], "why": "Looks after significa cuidar de alguém."}, {"t": "b", "pt": "Procure essa palavra no dicionário.", "w": ["Look", "it", "up", "in", "the", "dictionary"]}, {"t": "b", "pt": "Eu cuido do meu irmão.", "w": ["I", "look", "after", "my", "brother"]}]];
