englishA2Plans[171]={"title": "Gostos de série e filme", "file": "", "grammar": "Advérbios de grau: quite, pretty, extremely, absolutely", "goal": "Dê sua opinião usando quite e extremely.", "words": [["episode", "episódio"], ["plot", "enredo"], ["subtitle", "legenda"], ["binge-watch", "maratonar"], ["season", "temporada"], ["character", "personagem"], ["trailer", "trailer"], ["great ending", "final ótimo"]]};
englishA2Content[171]=[[["Ben and Lia watch a new series at night.", "Ben e Lia assistem a uma série nova à noite."], ["The plot is quite simple, but the characters are funny.", "O enredo é bem simples, mas os personagens são engraçados."], ["Episode one is pretty short.", "O episódio um é bem curto."], ["Ben says the ending is extremely good.", "Ben diz que o final é extremamente bom."], ["Lia turns on the subtitles because the actor talks fast.", "Lia liga as legendas porque o ator fala rápido."], ["They decide to binge-watch the whole season.", "Eles decidem maratonar a temporada inteira."]], [["Did you see the new series everyone talks about?", "Você viu a série nova de que todo mundo fala?"], ["Yes! I watched the first episode on Friday. It's pretty good.", "Sim! Assisti ao primeiro episódio na sexta. É bem bom."], ["Is the plot easy to follow? I'm tired after my lecture, and I have little time this semester.", "O enredo é fácil de acompanhar? Estou cansada depois da aula e tenho pouco tempo neste semestre."], ["Yes, it's quite simple. The characters are absolutely hilarious.", "Sim, é bem simples. Os personagens são absolutamente hilários."], ["Really? Do you read the subtitles, or do you listen in English?", "Sério? Você lê as legendas ou escuta em inglês?"], ["Both. The actors speak extremely fast, so I need the subtitles.", "Os dois. Os atores falam muito rápido, então preciso das legendas."], ["Good idea. My editor wants a review for the magazine anyway.", "Boa ideia. Meu editor quer uma resenha para a revista de qualquer jeito."], ["Great! Then let's binge-watch the first three episodes tonight.", "Ótimo! Então vamos maratonar os três primeiros episódios hoje à noite."]], ["/ɪ/ em episode e subtitle", "O som /ɪ/ de episode e subtitle: é um 'i' curto e relaxado, entre o 'i' e o 'e' do português. Não estique como em 'sheep'.", ["episode", "subtitle"]], ["The plot is ___ interesting.", "quite", "quiet", "O enredo é bem interessante.", "Quite dá grau ao adjetivo; quiet significa silencioso."], [["The plot is quite simple, but the characters are funny.", "O enredo é bem simples, mas os personagens são engraçados."], ["Ben says the ending is extremely good.", "Ben diz que o final é extremamente bom."]], [{"t": "c", "q": "The actors speak ___ fast.", "o": ["extremely", "extreme", "extremity"], "pt": "Os atores falam extremamente rápido.", "why": "O advérbio extremely vem antes do adjetivo fast."}, {"t": "l", "say": "The first episode is pretty short.", "o": ["The first episode is pretty short.", "The first episode is pretty long.", "The first episode was pretty short."], "why": "Pretty short quer dizer bem curto."}, {"t": "b", "pt": "O final é extremamente bom.", "w": ["The", "ending", "is", "extremely", "good"]}, {"t": "b", "pt": "A trama é bastante simples.", "w": ["The", "plot", "is", "quite", "simple"]}]];
