englishA2Plans[173]={"title": "Mudanças recentes no bairro", "file": "", "grammar": "Advérbios de tempo: recently, lately, nowadays", "goal": "Fale de mudanças recentes usando recently e lately.", "words": [["billboard", "outdoor"], ["cobblestone", "paralelepípedo"], ["mural", "mural"], ["pothole", "buraco na rua"], ["streetlamp", "poste de luz"], ["storefront", "fachada de loja"], ["awning", "toldo"], ["new shop", "loja nova"]]};
englishA2Content[173]=[[["Ana has lived in this neighborhood for ten years.", "Ana mora neste bairro há dez anos."], ["Recently, the city built a cycle path on the main street.", "Recentemente, a prefeitura fez uma ciclovia na rua principal."], ["Workers painted a colorful mural on an old wall.", "Operários pintaram um mural colorido num muro velho."], ["Lately, a big billboard stands next to the newsstand.", "Ultimamente, um outdoor grande fica ao lado da banca de jornal."], ["Nowadays the sidewalk is wider, but the cobblestone road still has a pothole.", "Hoje em dia a calçada é mais larga, mas a rua de paralelepípedo ainda tem um buraco."], ["New streetlamps stand at the crosswalk, and a green awning covers the storefront.", "Postes novos ficam na faixa de pedestres, e um toldo verde cobre a fachada da loja."]], [["Ben, have you seen the new mural on Pine Street?", "Ben, você viu o mural novo da Rua Pine?"], ["Yes! I've walked past it every morning lately.", "Vi! Tenho passado por ele toda manhã ultimamente."], ["It's beautiful. Last year, there was only a gray wall.", "É lindo. Ano passado, só havia um muro cinza."], ["True. And the city recently built a cycle path near the newsstand.", "Verdade. E a prefeitura fez uma ciclovia perto da banca de jornal há pouco tempo."], ["Nowadays I ride my bike to work instead of taking the bus.", "Hoje em dia vou de bicicleta para o trabalho em vez de pegar o ônibus."], ["Nice! Did they fix the pothole on the corner?", "Legal! Eles consertaram o buraco da esquina?"], ["Not yet. The cobblestones are pretty, but they're bad for bikes.", "Ainda não. Os paralelepípedos são bonitos, mas ruins para bicicletas."], ["I agree. Let's call the city about the pothole and the underpass tomorrow.", "Concordo. Vamos ligar para a prefeitura amanhã sobre o buraco e a passagem subterrânea."]], ["/ɔ/ em mural e sidewalk", "O som /ɔ/ de mural e sidewalk: abra bem a boca e arredonde um pouco os lábios, parecido com o 'ó' de 'pó', mas mais curto.", ["mural", "sidewalk"]], ["___, many people work from home.", "Nowadays", "Yesterday", "Hoje em dia, muita gente trabalha de casa.", "Nowadays fala do presente em geral; yesterday pede passado."], [["Yes! I've walked past it every morning lately.", "Vi! Tenho passado por ele toda manhã ultimamente."], ["Nowadays I ride my bike to work instead of taking the bus.", "Hoje em dia vou de bicicleta para o trabalho em vez de pegar o ônibus."]], [{"t": "c", "q": "They ___ painted the old wall.", "o": ["recently", "nowadays", "tomorrow"], "pt": "Eles pintaram o muro velho recentemente.", "why": "Recently combina com o passado já concluído."}, {"t": "l", "say": "Lately, I walk to work.", "o": ["Lately, I walk to work.", "Lately, I work at home.", "Lately, I talk to work."], "why": "Lately fala de um período recente até agora."}, {"t": "b", "pt": "Recentemente, a cidade construiu uma ciclovia.", "w": ["Recently", "the", "city", "built", "a", "cycle", "path"]}, {"t": "b", "pt": "Hoje em dia eu uso a ciclovia.", "w": ["Nowadays", "I", "use", "the", "cycle", "path"]}]];
