englishA2Plans[175]={"title": "Perguntando ao concierge do hotel", "file": "", "grammar": "Do you know what time...?", "goal": "Pergunte com Do you know usando ordem afirmativa.", "words": [["concierge", "concierge"], ["bellboy", "carregador de malas"], ["minibar", "frigobar"], ["room key", "chave do quarto"], ["doorman", "porteiro"], ["bathrobe", "roupão"], ["room service", "serviço de quarto"], ["extra towel", "toalha extra"]]};
englishA2Content[175]=[[["Lia arrives at a hotel in Chicago late in the evening.", "Lia chega a um hotel em Chicago no fim da noite."], ["A doorman opens the door, and a bellboy takes her suitcase.", "Um porteiro abre a porta, e um carregador pega a mala dela."], ["In the lobby, there is a big mural of the city.", "No saguão, há um mural grande da cidade."], ["At the front desk, she gets her room key.", "Na recepção, ela pega a chave do quarto."], ["The concierge smiles and says, \"Welcome! Your room has a balcony.\"", "O concierge sorri e diz: \"Bem-vinda! Seu quarto tem sacada.\""], ["Lia is tired, so she goes to her room.", "Lia está cansada, então vai para o quarto."]], [["Good evening. Do you know what time breakfast starts?", "Boa noite. Você sabe a que horas começa o café da manhã?"], ["Yes, it starts at seven in the lobby restaurant.", "Sim, começa às sete no restaurante do saguão."], ["Great. And do you know where I can buy a map of the city?", "Ótimo. E você sabe onde posso comprar um mapa da cidade?"], ["There's a small shop across the street. It's open until nine.", "Há uma lojinha do outro lado da rua. Fica aberta até as nove."], ["Thank you. Do you know how far the museum is from here?", "Obrigada. Você sabe a que distância fica o museu daqui?"], ["It's about ten minutes on foot. Pay attention to the signs near the mural.", "São cerca de dez minutos a pé. Preste atenção nas placas perto do mural."], ["I will. Is there a luggage locker for my big bag?", "Vou prestar. Tem um armário de bagagem para minha mala grande?"], ["Yes. The bellboy will keep it safe for you.", "Tem, sim. O carregador vai guardar com segurança para você."]], ["/ɔ/ em lobby e concierge", "O som /ɔ/ de lobby e concierge: abra bem a boca, parecido com o 'ó' do português, mas curto. Em lobby o 'o' é esse som; em concierge ele aparece na primeira sílaba, 'con'.", ["lobby", "concierge"]], ["Do you know what time the pool ___?", "opens", "does open", "Você sabe a que horas a piscina abre?", "Na pergunta com Do you know, o verbo vem sem does: the pool opens."], [["Good evening. Do you know what time breakfast starts?", "Boa noite. Você sabe a que horas começa o café da manhã?"], ["Yes, it starts at seven in the lobby restaurant.", "Sim, começa às sete no restaurante do saguão."]], [{"t": "c", "q": "Do you know where the elevator ___?", "o": ["is", "does", "are"], "pt": "Você sabe onde fica o elevador?", "why": "Depois de where vem o sujeito e depois is."}, {"t": "l", "say": "Do you know what time it closes?", "o": ["Do you know what time it closes?", "Do you know what time does it close?", "Do you know what it time closes?"], "why": "A ordem é what time + sujeito + verbo."}, {"t": "b", "pt": "Você sabe onde fica o saguão?", "w": ["Do", "you", "know", "where", "the", "lobby", "is"]}, {"t": "b", "pt": "Você sabe que horas ele abre?", "w": ["Do", "you", "know", "what", "time", "it", "opens"]}]];
