englishA2ExtraWordExamples[175]={"minibar": ["The minibar in my room has cold water.", "O frigobar do meu quarto tem água gelada."], "bathrobe": ["There is a white bathrobe in the bathroom.", "Há um roupão branco no banheiro."], "checkout": ["Checkout is at eleven o'clock.", "A saída do hotel é às onze horas."], "room service": ["Do you know what time room service starts?", "Você sabe a que horas começa o serviço de quarto?"], "extra towel": ["Can I get an extra towel, please?", "Posso pegar uma toalha extra, por favor?"]};
englishA2Plans[176]={"title": "Dúvidas na fila do cinema", "file": "", "grammar": "I wonder if / Can you tell me if", "goal": "Pergunte se algo é verdade usando if.", "words": [["usher", "lanterninha"], ["showtime", "horário da sessão"], ["seat row", "fileira"], ["sold out", "esgotado"], ["projector", "projetor"], ["thriller", "filme de suspense"], ["spoiler", "spoiler"], ["big screen", "tela grande"]]};
englishA2Content[176]=[[["Noah and Mia stand in line at the movie theater.", "Noah e Mia estão na fila do cinema."], ["The line is long, and Mia is worried.", "A fila é longa, e Mia está preocupada."], ["\"I wonder if the thriller is sold out,\" she says.", "\"Será que o filme de suspense está esgotado?\", ela diz."], ["An usher checks the tickets at the door.", "Um lanterninha confere os ingressos na porta."], ["Noah hates spoilers, so he doesn't read about the sequel.", "Noah odeia spoilers, então não lê nada sobre a continuação."], ["The usher smiles and says the showtime is in ten minutes.", "O lanterninha sorri e diz que a sessão é daqui a dez minutos."]], [["Excuse me. Can you tell me if the eight o'clock showtime is sold out?", "Com licença. Pode me dizer se a sessão das oito está esgotada?"], ["No, it isn't. But the front seat rows are almost full.", "Não, não está. Mas as primeiras fileiras estão quase cheias."], ["I wonder if there are two seats in the back row?", "Será que há dois lugares na última fileira?"], ["Let me check... Yes, seats five and six are free.", "Deixe-me ver... Sim, os lugares cinco e seis estão livres."], ["Perfect. Can you tell me if the movie has English subtitles?", "Perfeito. Pode me dizer se o filme tem legendas em inglês?"], ["Yes, it does. And the plot is easy to follow. The projector in room three is brand new, too.", "Tem, sim. E o enredo é fácil de acompanhar. O projetor da sala três também é novinho."], ["Great. I usually binge-watch series at home, but I love the big screen.", "Ótimo. Normalmente maratono séries em casa, mas adoro a telona."], ["Yes, you'll love it. The shop by the door sells popcorn. Enjoy the show!", "Com certeza vai adorar. A lojinha da porta vende pipoca. Aproveitem a sessão!"]], ["/ʃ/ em showtime e shop", "O som /ʃ/ de showtime e shop: coloque os lábios como para pedir silêncio ('shhh') e deixe o ar passar. É o 'ch' do português, de 'chá'.", ["showtime", "shop"]], ["Can you tell me ___ the movie is sold out?", "if", "what", "Pode me dizer se o filme está esgotado?", "If quer dizer 'se' numa pergunta de sim ou não."], [["I wonder if there are two seats in the back row?", "Será que há dois lugares na última fileira?"], ["Perfect. Can you tell me if the movie has English subtitles?", "Perfeito. Pode me dizer se o filme tem legendas em inglês?"]], [{"t": "c", "q": "I wonder ___ they have popcorn.", "o": ["if", "do", "what"], "pt": "Será que eles têm pipoca?", "why": "If introduz uma pergunta de sim ou não."}, {"t": "l", "say": "Can you tell me if the show is sold out?", "o": ["Can you tell me if the show is sold out?", "Can you tell me if is the show sold out?", "Can you tell me if the show sold is out?"], "why": "Depois de if, o sujeito vem antes do verbo."}, {"t": "b", "pt": "Será que o filme está esgotado?", "w": ["I", "wonder", "if", "the", "movie", "is", "sold", "out"]}, {"t": "b", "pt": "Pode me dizer se há lugares?", "w": ["Can", "you", "tell", "me", "if", "there", "are", "seats"]}]];
