englishA2Plans[177]={"title": "Conferindo detalhes de um evento", "file": "", "grammar": "Question tags com verbo auxiliar", "goal": "Confirme informações usando question tags.", "words": [["guest list", "lista de convidados"], ["venue", "local do evento"], ["RSVP", "confirmação de presença"], ["dress code", "traje exigido"], ["banquet", "banquete"], ["catering", "serviço de buffet"], ["decoration", "decoração"], ["buffet", "bufê"]]};
englishA2Content[177]=[[["Rosa plans a birthday party at a small theater venue.", "Rosa planeja uma festa de aniversário num pequeno teatro."], ["A catering company brings a buffet, and friends help with the decorations.", "Uma empresa de bufê traz comida, e amigos ajudam na decoração."], ["The show is sold out, so the party starts after the showtime.", "O espetáculo está esgotado, então a festa começa depois da sessão."], ["The invitation says the RSVP is due on Friday.", "O convite diz que a confirmação de presença vai até sexta."], ["Tom reads the guest list and asks, \"Ana is coming, isn't she?\"", "Tom lê a lista de convidados e pergunta: \"A Ana vem, não vem?\""], ["\"Yes, she is,\" says Rosa. \"The dress code is casual.\"", "\"Vem, sim\", diz Rosa. \"O traje é casual.\""]], [["Rosa, the party is on Saturday, isn't it?", "Rosa, a festa é no sábado, não é?"], ["Yes, it is. It starts after the showtime, around ten o'clock.", "É, sim. Começa depois da sessão, por volta das dez."], ["The venue has a big stage, doesn't it?", "O local tem um palco grande, não tem?"], ["Yes, it does. An usher will help the guests find their seats.", "Tem, sim. Um lanterninha vai ajudar os convidados a achar os lugares."], ["I sent my RSVP yesterday. You got it, didn't you?", "Mandei minha confirmação ontem. Você recebeu, não recebeu?"], ["Yes, I did. You're on the guest list with your sister.", "Recebi, sim. Você está na lista com sua irmã."], ["Great. What should I wear? Is there a dress code?", "Ótimo. O que devo vestir? Tem algum traje exigido?"], ["Yes, casual is fine. See you on Saturday!", "Sim, casual está bom. Até sábado!"]], ["/v/ em venue e invitation", "O som /v/ de venue e invitation: encoste os dentes de cima no lábio de baixo e faça vibrar a voz, como o 'v' de 'vaca'. Não troque por 'b'.", ["venue", "invitation"]], ["She is coming, ___ she?", "isn't", "is", "Ela vem, não vem?", "Frase afirmativa pede tag negativa: isn't she?"], [["Rosa, the party is on Saturday, isn't it?", "Rosa, a festa é no sábado, não é?"], ["The venue has a big stage, doesn't it?", "O local tem um palco grande, não tem?"]], [{"t": "c", "q": "They have the invitation, ___ they?", "o": ["don't", "do", "aren't"], "pt": "Eles têm o convite, não têm?", "why": "Have no presente simples pede don't na tag."}, {"t": "l", "say": "You didn't forget, did you?", "o": ["You didn't forget, did you?", "You didn't forget, didn't you?", "You didn't forget, do you?"], "why": "Frase negativa pede tag afirmativa com did."}, {"t": "b", "pt": "A festa é no sábado, não é?", "w": ["The", "party", "is", "on", "Saturday,", "isn't", "it"]}, {"t": "b", "pt": "Você enviou o RSVP, não enviou?", "w": ["You", "sent", "the", "RSVP,", "didn't", "you"]}]];
