englishA2ExtraWordExamples[177]={"banquet": ["The banquet is in a big hall.", "O banquete é num salão grande."]};
englishA2Plans[178]={"title": "Dúvidas sobre uma viagem em grupo", "file": "", "grammar": "Question tags e respostas curtas", "goal": "Confirme combinados usando tags e respostas curtas.", "words": [["tour guide", "guia turístico"], ["meeting point", "ponto de encontro"], ["head count", "contagem de pessoas"], ["sign in", "registrar presença"], ["canteen", "cantil"], ["ruins", "ruínas"], ["group photo", "foto em grupo"], ["bus ride", "viagem de ônibus"]]};
englishA2Content[178]=[[["Mia joins a group tour of the old ruins.", "Mia entra num passeio em grupo pelas ruínas antigas."], ["The concierge at her hotel booked it for her.", "O concierge do hotel reservou o passeio para ela."], ["At the meeting point, she has to sign in with the tour guide.", "No ponto de encontro, ela precisa se registrar com o guia turístico."], ["The guide does a head count and smiles.", "O guia faz a contagem de pessoas e sorri."], ["\"You brought a raincoat, didn't you?\" asks the guide.", "\"Você trouxe capa de chuva, não trouxe?\", pergunta o guia."], ["\"Yes, I did,\" says Mia, and she shows her canteen and binoculars.", "\"Trouxe, sim\", diz Mia, e mostra o cantil e o binóculo."]], [["Ben, you're coming on the tour tomorrow, aren't you?", "Ben, você vem ao passeio amanhã, não vem?"], ["Yes, I am. Where is the meeting point?", "Vou, sim. Onde é o ponto de encontro?"], ["It's at the hotel entrance. The concierge has the guest list.", "É na entrada do hotel. O concierge está com a lista de convidados."], ["Okay. The guide takes the group by bus, doesn't she?", "Certo. A guia leva o grupo de ônibus, não leva?"], ["Yes, she does. First we sign in, and then she does a head count.", "Leva, sim. Primeiro registramos presença, e depois ela conta todo mundo."], ["Got it. You didn't forget your raincoat, did you?", "Entendi. Você não esqueceu a capa de chuva, esqueceu?"], ["No, I didn't. It's already in my backpack, next to my map.", "Não esqueci. Já está na minha mochila, ao lado do meu mapa."], ["Good. I have my room key, so I'm ready. See you at nine!", "Bom. Estou com a chave do quarto, então estou pronto. Até as nove!"]], ["/ɡ/ em guide e group", "O som /ɡ/ de guide e group: é o 'g' de 'gato', feito com a parte de trás da língua tocando o céu da boca. Em guide o 'u' é mudo: fale 'gáid'.", ["guide", "group"]], ["You aren't late, ___ you?", "are", "aren't", "Você não está atrasado, está?", "Frase negativa pede tag afirmativa: are you?"], [["Ben, you're coming on the tour tomorrow, aren't you?", "Ben, você vem ao passeio amanhã, não vem?"], ["Yes, she does. First we sign in, and then she does a head count.", "Leva, sim. Primeiro registramos presença, e depois ela conta todo mundo."]], [{"t": "c", "q": "Ben is in the group, isn't he? Yes, he ___.", "o": ["is", "does", "isn't"], "pt": "Ben está no grupo, não está? Sim, está.", "why": "A resposta curta repete o auxiliar da tag: is."}, {"t": "l", "say": "You are on the list, aren't you?", "o": ["You are on the list, aren't you?", "You are on the list, are you?", "You are on the list, don't you?"], "why": "Frase afirmativa com are pede aren't you na tag."}, {"t": "b", "pt": "Você trouxe o protetor solar, não trouxe?", "w": ["You", "brought", "the", "sunscreen,", "didn't", "you"]}, {"t": "b", "pt": "O guia faz a contagem, não faz?", "w": ["The", "guide", "does", "a", "head", "count,", "doesn't", "he"]}]];
