englishA2Plans[184]={"title": "Procurando um lugar para estacionar", "file": "", "grammar": "Somewhere, anywhere, nowhere, everywhere", "goal": "Use pronomes indefinidos para lugares.", "words": [["parking lot", "estacionamento"], ["curbside", "beira da calçada"], ["permit", "autorização"], ["valet", "manobrista"], ["pavement", "pavimento"], ["parking spot", "vaga de estacionamento"], ["full lot", "estacionamento lotado"], ["street parking", "vaga na rua"]]};
englishA2Content[184]=[[["Tom and Mia drive to a concert, but they can't find somewhere to park.", "Tom e Mia vão de carro a um show, mas não acham onde estacionar."], ["The parking lot is full, and there is nowhere on the curbside.", "O estacionamento está lotado, e não há lugar na beira da calçada."], ["A sign says: you need a permit here, or they tow your car.", "Uma placa diz: é preciso autorização aqui, ou seu carro é rebocado."], ["Cars honk everywhere, and the street is crazy.", "Carros buzinam por toda parte, e a rua está uma loucura."], ["Then they see a garage with a valet at the door.", "Então eles veem uma garagem com um manobrista na porta."], ["The valet takes the car, and Tom is happy.", "O manobrista leva o carro, e o Tom fica feliz."]], [["Is there anywhere to park? I don't see a spot.", "Tem algum lugar para estacionar? Não vejo vaga."], ["Not here. Everyone is looking for somewhere nearby.", "Aqui não. Todo mundo procura um lugar por perto."], ["Don't drive on the pavement! Just reverse a little.", "Não suba na calçada! É só dar ré um pouco."], ["Okay. Why are those cars honking at us?", "Ok. Por que aqueles carros estão buzinando para nós?"], ["Because we block the street. There's a garage near the wristband booth.", "Porque bloqueamos a rua. Tem uma garagem perto do posto de pulseiras."], ["Good. Does it have a valet? I don't want them to tow the car.", "Bom. Tem manobrista? Não quero que rebocem o carro."], ["Yes! He'll take the car, and we can see the lineup.", "Tem! Ele leva o carro, e a gente pode ver a programação."], ["Perfect. I'll pay him now, and you can put on makeup inside.", "Perfeito. Pago a ele agora, e você pode se maquiar lá dentro."]], ["/ɡ/ em garage e valet", "O /ɡ/ é como o 'g' de 'gato': língua alta no fundo da boca e vibração na garganta. Em garage, o final é um 'j' suave (/ʒ/); em valet, o t final é mudo: 'va-LEI'.", ["garage", "valet"]], ["I can't find a parking spot ___.", "anywhere", "somewhere", "Não consigo achar vaga em lugar nenhum.", "Com can't (negativa), usamos anywhere, não somewhere."], [["Tom and Mia drive to a concert, but they can't find somewhere to park.", "Tom e Mia vão de carro a um show, mas não acham onde estacionar."], ["Not here. Everyone is looking for somewhere nearby.", "Aqui não. Todo mundo procura um lugar por perto."]], [{"t": "c", "q": "There is ___ to park. All the lots are full.", "o": ["nowhere", "anywhere", "somewhere"], "pt": "Não há lugar para estacionar. Todos os estacionamentos estão cheios.", "why": "Nowhere significa 'lugar nenhum' e combina com 'todos cheios'."}, {"t": "l", "say": "Cars honk everywhere in the city.", "o": ["Cars honk everywhere in the city.", "Cars honk anywhere in the city.", "Cars honk somewhere in the city."], "why": "Everywhere significa 'por toda parte'."}, {"t": "b", "pt": "Não há lugar para estacionar.", "w": ["There", "is", "nowhere", "to", "park"]}, {"t": "b", "pt": "Ele procura uma vaga em todo lugar.", "w": ["He", "looks", "for", "a", "spot", "everywhere"]}]];
