englishA2ExtraWordExamples[184]={"parking spot": ["There's no parking spot anywhere.", "Não tem vaga de estacionamento em lugar nenhum."], "full lot": ["Everywhere I look, I see a full lot.", "Para onde olho, vejo um estacionamento lotado."], "street parking": ["Is there street parking somewhere near here?", "Tem vaga na rua em algum lugar por aqui?"]};
englishA2Plans[185]={"title": "Conectando ideias: apesar de", "file": "", "grammar": "Although e even though", "goal": "Una ideias contrárias com although.", "words": [["rainstorm", "temporal"], ["stubborn", "teimoso"], ["disappointed", "decepcionado"], ["carry on", "seguir em frente"], ["damp", "úmido"], ["heavy rain", "chuva forte"], ["wet clothes", "roupa molhada"], ["bad weather", "mau tempo"]]};
englishA2Content[185]=[[["Noah is stubborn, so he wants to hike in a rainstorm.", "Noah é teimoso, então quer fazer trilha num temporal."], ["Lia is disappointed, but she goes with him.", "Lia está decepcionada, mas vai com ele."], ["Although the trail is slippery, they walk up slowly.", "Embora a trilha esteja escorregadia, eles sobem devagar."], ["Their jackets are soaked, and their socks are damp.", "As jaquetas estão encharcadas, e as meias estão úmidas."], ["Even though Lia starts to shiver, she keeps walking.", "Mesmo começando a tremer de frio, a Lia continua andando."], ["There is mud on their shoes, but they smile.", "Tem lama nos sapatos deles, mas eles sorriem."]], [["It's raining hard, Noah. Are you sure about the hike?", "Está chovendo forte, Noah. Tem certeza da trilha?"], ["Yes! Although it's raining, the forest is beautiful today.", "Tenho! Embora esteja chovendo, a floresta está linda hoje."], ["You're so stubborn. We always argue about this!", "Você é tão teimoso. A gente sempre discute por isso!"], ["I know, but even though it's wet, it's going to be fun.", "Eu sei, mas mesmo molhado, vai ser divertido."], ["Okay. I'm going to be soaked, so you must apologize.", "Tá. Vou ficar encharcada, então você tem que pedir desculpas."], ["Deal. I'll carry your duffel bag, and I apologize for the weather.", "Fechado. Eu levo sua bolsa, e peço desculpas pelo tempo."], ["I almost fell in the mud. The trail is really slippery.", "Quase caí na lama. A trilha está muito escorregadia."], ["Let's keep going. The top is close, and the view is great.", "Vamos em frente. O topo está perto, e a vista é ótima."], ["Fine, although my feet are damp.", "Tudo bem, embora meus pés estejam úmidos."], ["I promise! Let's carry on, and we'll rest at the top.", "Prometo! Vamos seguir em frente e descansar no topo."]], ["/s/ em stubborn e disappointed", "No stubborn, o 's' vem colado ao 't': diga 'stubborn', sem 'i' antes (nada de 'istubborn'). Em disappointed, o 's' é sibilante, /s/, sem vibração, como em 'sapo'.", ["stubborn", "disappointed"]], ["___ it's raining, we're going to the park.", "Although", "Because", "Embora esteja chovendo, vamos ao parque.", "Although liga duas ideias contrárias: chove, mas vamos mesmo assim."], [["Although the trail is slippery, they walk up slowly.", "Embora a trilha esteja escorregadia, eles sobem devagar."], ["Fine, although my feet are damp.", "Tudo bem, embora meus pés estejam úmidos."]], [{"t": "c", "q": "I'm not tired ___ it's very late.", "o": ["even though", "because", "so"], "pt": "Não estou cansado, mesmo sendo muito tarde.", "why": "Even though liga ideias contrárias: tarde, mas sem cansaço."}, {"t": "l", "say": "Although it's raining, we go outside.", "o": ["Although it's raining, we go outside.", "Because it's raining, we go outside.", "So it's raining, we go outside."], "why": "Although indica contraste: chove, mas saímos."}, {"t": "b", "pt": "Embora esteja chovendo, nós saímos.", "w": ["Although", "it's", "raining", "we", "go", "out"]}, {"t": "b", "pt": "Mesmo cansado, eu sigo em frente.", "w": ["Even", "though", "I'm", "tired", "I", "carry", "on"]}]];
