englishA2ExtraWordExamples[185]={"heavy rain": ["Although there was heavy rain, we carried on.", "Embora houvesse chuva forte, seguimos em frente."], "wet clothes": ["Even though I wore wet clothes, I smiled.", "Mesmo com roupa molhada, eu sorri."], "bad weather": ["Even though we had bad weather, we had fun.", "Mesmo com mau tempo, nos divertimos."]};
englishA2Plans[186]={"title": "Resposta de um cliente insatisfeito", "file": "", "grammar": "However e on the other hand", "goal": "Contraste duas ideias usando however.", "words": [["shopper", "comprador"], ["feedback", "opinião de cliente"], ["survey", "pesquisa"], ["in conclusion", "em conclusão"], ["review", "avaliação"], ["quality", "qualidade"], ["complain", "reclamar"], ["gift card", "vale-presente"]]};
englishA2Content[186]=[[["Rosa answers a survey about the new store.", "A Rosa responde a uma pesquisa sobre a loja nova."], ["The jackets on the hangers are good quality; however, they are expensive.", "As jaquetas nos cabides são de boa qualidade; porém, são caras."], ["The staff is nice. On the other hand, one cashier was rude.", "A equipe é simpática. Por outro lado, um caixa foi mal-educado."], ["She wants to complain, but she writes her feedback in a calm way.", "Ela quer reclamar, mas escreve a opinião de forma calma."], ["She gives the store four stars.", "Ela dá quatro estrelas para a loja."], ["In conclusion, she is a happy shopper, and she will come back.", "Em conclusão, ela é uma cliente feliz e vai voltar."]], [["Did you fill out the survey about the store?", "Você preencheu a pesquisa sobre a loja?"], ["Yes. I wrote a long review. I liked the staff; however, the parking lot was always full.", "Preenchi. Escrevi uma avaliação longa. Gostei da equipe; porém, o estacionamento estava sempre lotado."], ["Really? I thought the quality was great.", "Sério? Achei a qualidade ótima."], ["The quality is great. On the other hand, the prices are high.", "A qualidade é ótima. Por outro lado, os preços são altos."], ["True. Did you complain to the manager?", "Verdade. Você reclamou com o gerente?"], ["No, I wrote my feedback online instead. It's easier.", "Não, escrevi minha opinião online. É mais fácil."], ["Last week one worker was rude to me. However, he apologized later.", "Semana passada um funcionário foi mal-educado comigo. Porém, depois ele pediu desculpas."], ["Good. I hope they read it. In conclusion, we'll shop there again.", "Que bom. Espero que leiam. Em conclusão, vamos comprar lá de novo."]], ["/b/ em feedback e survey", "O /b/ fecha os dois lábios e solta o ar de uma vez, com vibração. Em feedback, o k final é seco, sem 'i' depois. Em survey, o som inicial é /s/, não /b/.", ["feedback", "survey"]], ["The phone is cheap. ___, the quality is bad.", "However", "Because", "O celular é barato. No entanto, a qualidade é ruim.", "However introduz uma ideia que contrasta com a anterior."], [["The jackets on the hangers are good quality; however, they are expensive.", "As jaquetas nos cabides são de boa qualidade; porém, são caras."], ["The quality is great. On the other hand, the prices are high.", "A qualidade é ótima. Por outro lado, os preços são altos."]], [{"t": "c", "q": "The room is small. On the other ___, it is very cheap.", "o": ["hand", "side", "one"], "pt": "O quarto é pequeno. Por outro lado, é muito barato.", "why": "A expressão fixa é 'on the other hand'."}, {"t": "l", "say": "The quality is good; however, it's expensive.", "o": ["The quality is good; however, it's expensive.", "The quality is good; because it's expensive.", "The quality is good, so it's expensive."], "why": "However mostra contraste: bom, mas caro."}, {"t": "b", "pt": "Eu gosto dela; no entanto, é cara.", "w": ["I", "like", "it", "however", "it's", "expensive"]}, {"t": "b", "pt": "Em conclusão, eu vou voltar.", "w": ["In", "conclusion", "I", "will", "come", "back"]}]];
