englishA2Plans[189]={"title": "Revisão: Roteiro a pé pela cidade", "file": "", "grammar": "Revisão: preposições, passiva e verbos frasais", "goal": "Guie alguém por um roteiro a pé.", "words": [["monument", "monumento"], ["archway", "arco"], ["lamppost", "poste de luz"], ["street corner", "esquina"], ["carving", "entalhe"], ["courtyard", "pátio"], ["street map", "mapa de ruas"], ["old town", "cidade antiga"]]};
englishA2Content[189]=[[["Today Mia shows Noah around the old city.", "Hoje a Mia mostra a cidade velha para o Noah."], ["They start at a big monument in the main square.", "Eles começam num grande monumento na praça principal."], ["It was built in 1900, and it is visited by many tourists.", "Foi construído em 1900 e é visitado por muitos turistas."], ["Then they walk through an archway into a quiet courtyard.", "Depois eles passam por um arco até um pátio tranquilo."], ["At the street corner, they wait at the crosswalk and cross the bridge.", "Na esquina, esperam na faixa de pedestres e atravessam a ponte."], ["From the rooftop, they see the whole city and a park like a jungle.", "Do terraço, veem a cidade toda e um parque que parece uma selva."]], [["Where do we start our walk, Mia?", "Onde começamos nosso passeio, Mia?"], ["At the monument. It's in the main square, next to a big fountain.", "No monumento. Fica na praça principal, ao lado de uma grande fonte."], ["Nice. What is that carving on the wall?", "Legal. O que é aquele entalhe na parede?"], ["It's an old carving of a ship. It was made by a local artist.", "É um entalhe antigo de um navio. Foi feito por um artista local."], ["And how do we get to the courtyard?", "E como chegamos ao pátio?"], ["Go through the archway, then turn left at the street corner.", "Passe pelo arco e vire à esquerda na esquina."], ["I see a lamppost and a balcony with flowers. Is that the place?", "Vejo um poste de luz e uma sacada com flores. É esse lugar?"], ["Yes! Then we'll go up to the rooftop for the view.", "É! Depois subimos ao terraço para ver a vista."], ["Perfect. Do we need a permit to park at the curbside?", "Perfeito. Precisamos de autorização para estacionar na calçada?"], ["Yes, but the parking lot is free. Let's leave the car there.", "Sim, mas o estacionamento é grátis. Vamos deixar o carro lá."]], ["/dʒ/ em bridge e jungle", "O /dʒ/ começa com a língua no céu da boca e solta o ar com vibração, como o 'dj' de 'djembê'. Diga 'BRIDJ' e 'DJÂNGUEL', sem terminar bridge com 'i'.", ["bridge", "jungle"]], ["The old bridge ___ built in 1950.", "was", "were", "A ponte velha foi construída em 1950.", "The old bridge é singular, então usamos was na voz passiva."], [["It was built in 1900, and it is visited by many tourists.", "Foi construído em 1900 e é visitado por muitos turistas."], ["Go through the archway, then turn left at the street corner.", "Passe pelo arco e vire à esquerda na esquina."]], [{"t": "c", "q": "Walk ___ the archway to reach the courtyard.", "o": ["through", "at", "on"], "pt": "Passe pelo arco para chegar ao pátio.", "why": "Through significa 'através de', como passar por uma abertura."}, {"t": "l", "say": "We cross the street at the crosswalk.", "o": ["We cross the street at the crosswalk.", "We cross the street at the courtyard.", "We cross the street at the rooftop."], "why": "Atravessamos a rua na faixa de pedestres (crosswalk)."}, {"t": "b", "pt": "Vire à esquerda na esquina.", "w": ["Turn", "left", "at", "the", "street", "corner"]}, {"t": "b", "pt": "Este monumento foi construído em 1900.", "w": ["This", "monument", "was", "built", "in", "1900"]}]];
englishA2PhotoThemes[189]="city";
englishA2MiniStories[189]=["O passeio inesperado", "Last Sunday, Mia took Noah on a walk around the old city.~No domingo passado, a Mia levou o Noah para um passeio pela cidade velha.|They started at the monument, but Noah lost his map.~Eles começaram no monumento, mas o Noah perdeu o mapa.|He looked in his bag, and Mia laughed.~Ele procurou na bolsa, e a Mia riu.|\"Don't worry. I know the way,\" she said.~\"Relaxa. Eu conheço o caminho\", disse ela.|They walked through an archway and past a lamppost.~Eles passaram por um arco e por um poste de luz.|At the street corner, they got lost anyway.~Na esquina, eles se perderam do mesmo jeito.|A kind old man helped them find the crosswalk.~Um senhor simpático os ajudou a achar a faixa de pedestres.|They crossed the bridge and found a small cafe in a courtyard.~Eles atravessaram a ponte e acharam um café pequeno num pátio.|Then Noah found the map in his pocket, and they laughed together.~Então o Noah achou o mapa no bolso, e eles riram juntos.|The wrong way was the best part of the day.~O caminho errado foi a melhor parte do dia."];
englishA2ExtraWordExamples[189]={"street map": ["We checked the street map before the walk.", "Olhamos o mapa de ruas antes da caminhada."], "old town": ["The old town was built by the river.", "A cidade antiga foi construída perto do rio."]};
englishA2Plans[190]={"title": "Dia de limpeza da praia", "file": "", "grammar": "So e such para intensidade", "goal": "Intensifique com so e such.", "words": [["jellyfish", "água-viva"], ["seashell", "concha"], ["tide", "maré"], ["pick up litter", "recolher lixo"], ["starfish", "estrela-do-mar"], ["pebble", "seixo"], ["dune", "duna"], ["bonfire", "fogueira"]]};
englishA2Content[190]=[[["Ana and Ben pick up litter on the beach today.", "Ana e Ben recolhem lixo na praia hoje."], ["The sea is so calm after the rainstorm.", "O mar está tão calmo depois do temporal."], ["It is such a bright morning!", "É uma manhã tão clara!"], ["Ben finds a pretty seashell and a pink starfish.", "Ben encontra uma concha bonita e uma estrela-do-mar rosa."], ["The tide is so low that they can walk to the dune.", "A maré está tão baixa que eles podem ir andando até a duna."], ["A jellyfish lies on the sand, so Ana stays away.", "Uma água-viva está na areia, então Ana fica longe."]], [["Look at this seashell, Ben! It is so shiny.", "Olhe esta concha, Ben! Ela é tão brilhante."], ["Wow, it's beautiful. I only found a gray pebble.", "Uau, é linda. Eu só achei um seixo cinza."], ["Careful, there's a jellyfish near the water. It's such a big one!", "Cuidado, tem uma água-viva perto da água. É uma enorme!"], ["Really? Don't touch it. The tide is coming in, so let's go up to the dune.", "Sério? Não toque nela. A maré está subindo, então vamos subir para a duna."], ["Good idea. We can carry on there. I don't want to lose track of time again.", "Boa ideia. Podemos seguir em frente lá. Não quero perder a noção do tempo de novo."], ["Sure. Last night's rainstorm left so much trash here, and I'm so tired already!", "Claro. O temporal de ontem à noite deixou muito lixo aqui, e eu já estou tão cansado!"], ["Me too, but the bags are almost full. We did a good job today.", "Eu também, mas os sacos estão quase cheios. Fizemos um bom trabalho hoje."], ["Yes! Let's get lunch from the cooler and plan the bonfire for tonight.", "Sim! Vamos pegar o almoço na caixa térmica e planejar a fogueira de hoje à noite."]], ["/ʃ/ em seashell e sea", "Em seashell o 'sh' é /ʃ/: arredonde os lábios e deixe o ar sair suave, como o 'ch' de 'chave'. Compare com sea, que começa com /s/, um 's' limpo, sem arredondar os lábios.", ["seashell", "sea"]], ["It was ___ a sunny day at the beach.", "such", "so", "Foi um dia tão ensolarado na praia.", "Antes de a + adjetivo + substantivo usamos such; so vem direto antes do adjetivo."], [["Look at this seashell, Ben! It is so shiny.", "Olhe esta concha, Ben! Ela é tão brilhante."], ["Careful, there's a jellyfish near the water. It's such a big one!", "Cuidado, tem uma água-viva perto da água. É uma enorme!"]], [{"t": "c", "q": "Careful! That is ___ a big jellyfish.", "o": ["such", "so", "too"], "pt": "Cuidado! Essa é uma água-viva enorme.", "why": "Such vem antes de a + adjetivo + substantivo (such a big jellyfish)."}, {"t": "l", "say": "The water is so cold today.", "o": ["The water is so cold today.", "The water is such cold today.", "The water was so cold today."], "why": "So vai direto com o adjetivo (so cold); such cold não existe aqui, e a frase fala do presente."}, {"t": "b", "pt": "A maré está tão baixa hoje.", "w": ["The", "tide", "is", "so", "low", "today"]}, {"t": "b", "pt": "Foi um dia tão bonito.", "w": ["It", "was", "such", "a", "beautiful", "day"]}]];
englishA2PhotoThemes[190]="map";
englishA2Plans[191]={"title": "Gostos em comum no encontro de amigos", "file": "", "grammar": "So do I e neither do I", "goal": "Concorde com so do I e neither do I.", "words": [["playlist", "lista de músicas"], ["encore", "bis"], ["chorus", "refrão"], ["same here", "eu também"], ["drummer", "baterista"], ["vinyl", "disco de vinil"], ["hum", "cantarolar"], ["live music", "música ao vivo"]]};
englishA2Content[191]=[[["Lia and Tom are at a small concert tonight.", "Lia e Tom estão em um show pequeno hoje à noite."], ["The drummer plays a fast beat, and the crowd sings the chorus.", "O baterista toca um ritmo rápido, e a plateia canta o refrão."], ["Tom hums along because he loves this playlist.", "Tom cantarola junto porque adora essa lista de músicas."], ["Lia likes old vinyl records, and Tom does too.", "Lia gosta de discos de vinil antigos, e Tom também."], ["The singer picks up the mic and plays an encore.", "A cantora pega o microfone e toca um bis."], ["After the show, they talk about the songs and the long delay at the door.", "Depois do show, eles falam das músicas e do longo atraso na porta."]], [["I love this chorus. I always hum the lyrics in the shower.", "Adoro esse refrão. Eu sempre cantarolo a letra no chuveiro."], ["So do I! I put it on my playlist last week.", "Eu também! Coloquei na minha lista de músicas semana passada."], ["Really? I don't like loud music at home, though.", "Sério? Mas eu não gosto de música alta em casa."], ["Neither do I. I prefer quiet songs on vinyl.", "Eu também não. Eu prefiro músicas calmas em vinil."], ["Same here. My dad has a lot of old records in the garage.", "Eu também. Meu pai tem muitos discos antigos na garagem."], ["Cool! Did you fill out the survey at the door? They want feedback.", "Legal! Você preencheu a pesquisa na porta? Eles querem opiniões."], ["Not yet. I don't want to wait in line again after that delay.", "Ainda não. Não quero esperar na fila de novo depois daquele atraso."], ["Okay, deal. And I hope they play an encore next time!", "Certo, combinado. E espero que eles toquem um bis da próxima vez!"]], ["/s/ em playlist e lyrics", "O /s/ de playlist e lyrics é um chiado limpo, com a língua perto dos dentes de cima e sem vibrar a garganta. Cuidado para não dizer 'z' no fim de lyrics: lá o som é /z/, mas em playlist termina em /st/.", ["playlist", "lyrics"]], ["I don't like waiting in line. — ___ do I.", "Neither", "So", "Eu não gosto de esperar na fila. — Nem eu.", "A frase é negativa, então a resposta concordando usa Neither do I; So do I é para frases afirmativas."], [["So do I! I put it on my playlist last week.", "Eu também! Coloquei na minha lista de músicas semana passada."], ["Neither do I. I prefer quiet songs on vinyl.", "Eu também não. Eu prefiro músicas calmas em vinil."]], [{"t": "c", "q": "I love old vinyl records. — So ___ I.", "o": ["do", "does", "am"], "pt": "Eu adoro discos de vinil antigos. — Eu também.", "why": "Com love (presente simples) a resposta é So do I."}, {"t": "l", "say": "So do I. I love this playlist.", "o": ["So do I. I love this playlist.", "So am I. I love this playlist.", "So do I. I loved this playlist."], "why": "Com o verbo love no presente, concordamos com So do I."}, {"t": "b", "pt": "Eu também! Eu adoro esse refrão.", "w": ["So", "do", "I!", "I", "love", "this", "chorus"]}, {"t": "b", "pt": "Nem eu. Eu prefiro vinil.", "w": ["Neither", "do", "I.", "I", "prefer", "vinyl"]}]];
