englishA2Plans[192]={"title": "Escolhendo entre dois restaurantes", "file": "", "grammar": "Both, either e neither", "goal": "Fale de duas opções usando both, either e neither.", "words": [["entree", "prato principal"], ["maître", "maître"], ["gratuity", "gorjeta"], ["split the bill", "dividir a conta"], ["vegetarian", "vegetariano"], ["patio", "pátio"], ["tasty", "gostoso"], ["fancy", "chique"]]};
englishA2Content[192]=[[["Rosa and Noah choose a restaurant for dinner.", "Rosa e Noah escolhem um restaurante para o jantar."], ["Both places are near the street corner.", "Os dois lugares ficam perto da esquina."], ["Neither restaurant is too fancy for them.", "Nenhum dos restaurantes é chique demais para eles."], ["One has a cozy patio, and the other has a tasty vegetarian entree.", "Um tem um pátio aconchegante, e o outro tem um prato principal vegetariano gostoso."], ["The waiter says they can sit at either table.", "O garçom diz que eles podem sentar em qualquer mesa."], ["Then the maître smiles and shows them the way.", "Então o maître sorri e mostra o caminho a eles."]], [["Both restaurants look nice. Which one do you want?", "Os dois restaurantes parecem bons. Qual você quer?"], ["Either one is fine with me, but I want something tasty and cheap.", "Qualquer um serve para mim, mas quero algo gostoso e barato."], ["Okay. The cozy one plays a nice playlist of soft jazz.", "Certo. O aconchegante toca uma boa lista de músicas de jazz suave."], ["Great. Neither place has a long menu, so I can choose fast.", "Ótimo. Nenhum dos lugares tem um cardápio longo, então posso escolher rápido."], ["Don't worry. The waiter can help us, and we can wait for him at the door.", "Não se preocupe. O garçom pode nos ajudar, e podemos esperar por ele na porta."], ["Sure. Should we split the bill at the end? I'll pay the gratuity.", "Claro. Devemos dividir a conta no final? Eu pago a gorjeta."], ["Yes, let's split the bill. I lose track of time when we eat, so let's order fast.", "Sim, vamos dividir a conta. Eu perco a noção do tempo quando comemos, então vamos pedir rápido."], ["Good idea. Look, the maître is calling us now. I'm so hungry!", "Boa ideia. Olhe, o maître está nos chamando agora. Estou com tanta fome!"]], ["/w/ em waiter e wait", "O /w/ de waiter e wait se faz com os lábios bem arredondados, como um 'u' rápido, sem encostar os dentes no lábio. Não troque por /v/ nem por 'u-ê' separado: é um som só.", ["waiter", "wait"]], ["I don't want pizza or pasta. ___ one is good for me.", "Neither", "Both", "Eu não quero pizza nem macarrão. Nenhum dos dois serve para mim.", "Neither significa nenhum dos dois e combina com a ideia negativa; both significa os dois."], [["Both restaurants look nice. Which one do you want?", "Os dois restaurantes parecem bons. Qual você quer?"], ["Great. Neither place has a long menu, so I can choose fast.", "Ótimo. Nenhum dos lugares tem um cardápio longo, então posso escolher rápido."]], [{"t": "c", "q": "You can sit at ___ table, the left or the right.", "o": ["either", "neither", "both"], "pt": "Você pode sentar em qualquer mesa, a da esquerda ou a da direita.", "why": "Either quer dizer um ou outro, à sua escolha, e leva substantivo no singular."}, {"t": "l", "say": "Both places are cozy.", "o": ["Both places are cozy.", "Both place are cozy.", "Both places is cozy."], "why": "Both pede plural: both places are."}, {"t": "b", "pt": "Nenhum prato principal é vegetariano.", "w": ["Neither", "entree", "is", "vegetarian"]}, {"t": "b", "pt": "Os dois restaurantes são chiques.", "w": ["Both", "restaurants", "are", "fancy"]}]];
