englishA2ExtraWordExamples[193]={"bus tour": ["Why don't we take a bus tour today?", "Por que não fazemos um passeio de ônibus hoje?"]};
englishA2Plans[194]={"title": "Fofoca no escritório", "file": "", "grammar": "Discurso indireto: said that", "goal": "Conte o que alguém disse usando said that.", "words": [["gossip", "fofoca"], ["promotion", "promoção"], ["scandal", "escândalo"], ["spill the beans", "contar o segredo"], ["bonus", "bônus"], ["raise", "aumento de salário"], ["water cooler", "bebedouro"], ["big news", "grande novidade"]]};
englishA2Content[194]=[[["Lia works in a busy office, and today it is full of gossip.", "Lia trabalha em um escritório movimentado, e hoje ele está cheio de fofoca."], ["Ben said that the company wants to hire an intern.", "Ben disse que a empresa quer contratar um estagiário."], ["Rosa said that Tom is going to get a promotion.", "Rosa disse que Tom vai ganhar uma promoção."], ["Tom said that he wants a raise.", "Tom disse que quer um aumento."], ["Mia said that she can't spill the beans.", "Mia disse que não pode contar o segredo."], ["After that, Lia goes to the snack bar for coffee.", "Depois disso, Lia vai à lanchonete tomar um café."]], [["Did you hear the new gossip? Ben said that the manager wants to quit.", "Você ouviu a nova fofoca? Ben disse que o gerente quer pedir demissão."], ["No way! That is a big scandal. Is it true?", "Não acredito! Isso é um grande escândalo. É verdade?"], ["I'm not sure. Mia said that she heard it at the snack bar.", "Não tenho certeza. Mia disse que ouviu isso na lanchonete."], ["Hmm. Tom said that he is going to get a promotion and a bonus.", "Hmm. Tom disse que vai ganhar uma promoção e um bônus."], ["Maybe the new intern knows more. We can ask her at lunch.", "Talvez a nova estagiária saiba mais. Podemos perguntar a ela no almoço."], ["Good idea. I want a good entree anyway. But please don't spill the beans in front of everyone.", "Boa ideia. Quero um bom prato principal de qualquer jeito. Mas, por favor, não conte o segredo na frente de todos."], ["Of course not. I only want to know the truth.", "Claro que não. Só quero saber a verdade."], ["Same here. Let's find out at lunch.", "Eu também. Vamos descobrir no almoço."]], ["/ɑ/ em gossip e promotion", "O /ɑ/ de gossip e promotion é uma vogal aberta e relaxada: abra bem a boca, como no 'a' de 'pá', e não feche para 'ó' nem para 'ou'. Em inglês americano, gossip soa como 'gáa-sip'.", ["gossip", "promotion"]], ["Rosa ___ that Tom is going to get a promotion.", "said", "say", "Rosa disse que Tom vai ganhar uma promoção.", "Para contar o que alguém falou no passado usamos said that."], [["Ben said that the company wants to hire an intern.", "Ben disse que a empresa quer contratar um estagiário."], ["I'm not sure. Mia said that she heard it at the snack bar.", "Não tenho certeza. Mia disse que ouviu isso na lanchonete."]], [{"t": "c", "q": "Yesterday, Mia ___ that she was tired.", "o": ["said", "says", "say"], "pt": "Ontem, Mia disse que estava cansada.", "why": "Com yesterday usamos o passado: said that."}, {"t": "l", "say": "Ben said that he wants a raise.", "o": ["Ben said that he wants a raise.", "Ben said that she wants a raise.", "Ben said that he wants a rice."], "why": "Ben é homem (he), e raise significa aumento de salário."}, {"t": "b", "pt": "Ben disse que quer um aumento.", "w": ["Ben", "said", "that", "he", "wants", "a", "raise"]}, {"t": "b", "pt": "Mia disse que está cansada.", "w": ["Mia", "said", "that", "she", "is", "tired"]}]];
