englishA2Plans[197]={"title": "Desejos de quem queria ter mais tempo", "file": "", "grammar": "Wish + passado simples", "goal": "Expresse desejos usando I wish.", "words": [["hobby", "passatempo"], ["spare time", "tempo livre"], ["sticky tab", "marcador adesivo"], ["wish upon a star", "fazer um pedido a uma estrela"], ["sewing", "costura"], ["knitting", "tricô"], ["journal", "diário"], ["more time", "mais tempo"]]};
englishA2Content[197]=[[["Rosa has a busy job, and she has little spare time.", "Rosa tem um trabalho cheio, e ela tem pouco tempo livre."], ["Her hobby is baking, but she bakes only on Sundays.", "O passatempo dela é fazer bolos, mas ela só assa aos domingos."], ["She puts a sticky tab on her favorite recipes.", "Ela coloca um marcador adesivo nas receitas favoritas."], ["At night, she writes in her journal.", "À noite, ela escreve no diário."], ["Rosa wishes she had more time, so she looks at the stars.", "Rosa gostaria de ter mais tempo, então ela olha para as estrelas."], ["She makes a wish upon a star and smiles.", "Ela faz um pedido a uma estrela e sorri."]], [["You look tired, Rosa. Was it a long day?", "Você parece cansada, Rosa. Foi um dia longo?"], ["Yes. I wish I had more time for baking.", "Foi. Eu queria ter mais tempo para fazer bolos."], ["I understand. I wish I weren't so busy, too. I have no time for knitting or sewing.", "Eu entendo. Eu também queria não estar tão ocupado. Não tenho tempo para tricô nem costura."], ["Wow, you do both? I wish I could sew a button!", "Uau, você faz os dois? Eu queria saber costurar um botão!"], ["It's easy. I can teach you. Call me, and leave a voicemail.", "É fácil. Posso ensinar você. Me ligue e deixe um recado."], ["Thanks! If I won the lottery, I would quit my job and buy a mansion.", "Obrigada! Se eu ganhasse na loteria, largaria meu emprego e compraria uma mansão."], ["Ha! Don't think about pie in the sky. Just save one hour a week, and I'll cook fish for dinner.", "Ha! Não pense em sonho impossível. Só guarde uma hora por semana, e eu faço peixe para o jantar."], ["Good idea. I'll put a sticky tab on my calendar for it.", "Boa ideia. Vou colocar um marcador adesivo no meu calendário para isso."]], ["/ʃ/ em wish e fish", "O /ʃ/ de wish e fish aparece no fim da palavra: arredonde os lábios e solte o ar contínuo, como o 'ch' de 'chuva' prolongado. Não acrescente um 'i' depois (wishi): termine só com o chiado.", ["wish", "fish"]], ["I wish I ___ more spare time.", "had", "have", "Eu queria ter mais tempo livre.", "Depois de I wish usamos o passado simples (had) para falar de algo que não é verdade agora."], [["Yes. I wish I had more time for baking.", "Foi. Eu queria ter mais tempo para fazer bolos."], ["Wow, you do both? I wish I could sew a button!", "Uau, você faz os dois? Eu queria saber costurar um botão!"]], [{"t": "c", "q": "She wishes she ___ a bigger kitchen.", "o": ["had", "has", "have"], "pt": "Ela queria ter uma cozinha maior.", "why": "Depois de wish usamos o passado: had."}, {"t": "l", "say": "I wish I had more spare time.", "o": ["I wish I had more spare time.", "I wish I have more spare time.", "I wish I had less spare time."], "why": "Wish + passado (had), e more significa mais, não menos."}, {"t": "b", "pt": "Eu queria ter mais tempo livre.", "w": ["I", "wish", "I", "had", "more", "spare", "time"]}, {"t": "b", "pt": "Eu queria saber costurar.", "w": ["I", "wish", "I", "could", "sew"]}]];
