englishA2Plans[202]={"title": "Mudança de humor ao longo do dia", "file": "", "grammar": "Get + adjetivo (get tired, get cold)", "goal": "Fale de mudanças com get.", "words": [["mood", "humor"], ["stress", "estresse"], ["yawn", "bocejar"], ["cheer up", "animar-se"], ["cheerful", "alegre"], ["grumpy", "mal-humorado"], ["gloomy", "sombrio"], ["cranky", "ranzinza"]]};
englishA2Content[202]=[[["Lia gets tired around three o'clock every day.", "Lia fica cansada por volta das três horas todos os dias."], ["Her mood changes: she is cheerful in the morning, but later she gets grumpy.", "O humor dela muda: de manhã ela é alegre, mas depois fica mal-humorada."], ["She yawns a lot, and her stress gets worse.", "Ela boceja muito, e o estresse dela piora."], ["Yesterday, Noah stood by her desk with a cup of tea.", "Ontem, Noah ficou em pé ao lado da mesa dela com uma xícara de chá."], ["He told a joke, and she began to cheer up.", "Ele contou uma piada, e ela começou a se animar."], ["She got happy again, and the gloomy afternoon felt short.", "Ela ficou feliz de novo, e a tarde sombria pareceu curta."]], [["You look cranky, Lia. Did something happen at work?", "Você parece ranzinza, Lia. Aconteceu alguma coisa no trabalho?"], ["Not really. I get tired every afternoon, and the conference deadline is today.", "Na verdade não. Eu fico cansada toda tarde, e o prazo da conferência é hoje."], ["I know that feeling. I get nervous when a deadline gets close.", "Conheço esse sentimento. Eu fico nervoso quando um prazo chega perto."], ["My head hurts, too. I think I have a headache.", "Minha cabeça dói também. Acho que estou com dor de cabeça."], ["Maybe a short nap would help. Last week I took one and felt better.", "Talvez um cochilo curto ajude. Semana passada eu fiz um e me senti melhor."], ["At work? My boss gets angry when people sleep at the office.", "No trabalho? Meu chefe fica bravo quando as pessoas dormem no escritório."], ["Then put a sticky tab on your screen to remind you to take a walk. I walk in my spare time, too.", "Então cole um lembrete na tela para você se lembrar de dar uma caminhada. Eu também caminho no meu tempo livre."], ["A walk sounds perfect. Let's go outside now, and thanks, Noah!", "Uma caminhada parece perfeita. Vamos lá fora agora, e obrigada, Noah!"]], ["/u/ em mood e stood", "Em stood o /ʊ/ é curto e relaxado, com os lábios só um pouco arredondados; em mood o /uː/ é longo e tenso. Compare os dois: 'stood' é rápido, 'mood' é esticado.", ["mood", "stood"]], ["I get ___ after a long day.", "tired", "tiredly", "Eu fico cansado depois de um longo dia.", "Depois de get usamos um adjetivo (tired), não um advérbio."], [["Lia gets tired around three o'clock every day.", "Lia fica cansada por volta das três horas todos os dias."], ["She yawns a lot, and her stress gets worse.", "Ela boceja muito, e o estresse dela piora."]], [{"t": "c", "q": "When the room gets ___, I put on a sweater.", "o": ["cold", "coldly", "coldness"], "pt": "Quando o quarto fica frio, eu coloco um suéter.", "why": "Get + adjetivo: gets cold."}, {"t": "l", "say": "Her mood gets better after a nap.", "o": ["Her mood gets better after a nap.", "Her mood gets worse after a nap.", "Her mood gets better after a walk."], "why": "A frase ouvida diz gets better after a nap."}, {"t": "b", "pt": "Eu fico cansado à tarde.", "w": ["I", "get", "tired", "in", "the", "afternoon"]}, {"t": "b", "pt": "Ela fica nervosa antes do prazo.", "w": ["She", "gets", "nervous", "before", "the", "deadline"]}]];
