englishA2Plans[203]={"title": "Opinião sobre dependência de tecnologia", "file": "", "grammar": "Verbo + preposição (depend on, listen to)", "goal": "Use verbos com preposições fixas.", "words": [["screen time", "tempo de tela"], ["notification", "notificação"], ["addiction", "vício"], ["unplug", "desligar da tomada"], ["scroll", "rolar a tela"], ["spam", "spam"], ["phone battery", "bateria do celular"], ["social media", "redes sociais"]]};
englishA2Content[203]=[[["Rosa looks at her phone as soon as she wakes up.", "Rosa olha para o celular assim que acorda."], ["She scrolls through her feed and waits for new notifications.", "Ela rola o feed e espera por novas notificações."], ["Her screen time depends on her mood and on the weather.", "O tempo de tela dela depende do humor e do clima."], ["Last night, she listened to music instead of scrolling.", "Ontem à noite, ela ouviu música em vez de rolar a tela."], ["Her brother laughs at her addiction, but he loves his games, too.", "O irmão ri do vício dela, mas ele também adora os jogos dele."], ["Tonight she will unplug her charger and talk to him about the habit.", "Hoje à noite ela vai tirar o carregador da tomada e conversar com ele sobre o hábito."]], [["Rosa, you're always on your phone. How many hours of screen time do you have?", "Rosa, você está sempre no celular. Quantas horas de tempo de tela você tem?"], ["About six hours a day. I know, it's a bad habit, and it gives me stress.", "Umas seis horas por dia. Eu sei, é um mau hábito, e me dá estresse."], ["Yesterday you didn't hear me when I called you from the kitchen.", "Ontem você não me ouviu quando eu chamei da cozinha."], ["Sorry! I depend on my phone for work, but I also check my inbox and spam all day.", "Desculpa! Eu dependo do celular para trabalhar, mas também olho a caixa de entrada e o spam o dia todo."], ["Let's try something. Tonight, unplug the charger and turn off the wifi.", "Vamos tentar uma coisa. Hoje à noite, tire o carregador da tomada e desligue o wi-fi."], ["Hmm. I worry about missing a message from my boss.", "Hmm. Eu me preocupo em perder uma mensagem do meu chefe."], ["You can wait for the morning. Nobody calls at midnight, and you'll sleep better in your pajamas.", "Você pode esperar até de manhã. Ninguém liga à meia-noite, e você vai dormir melhor de pijama."], ["Okay, you win. I'll try it tonight, I promise.", "Tá bom, você venceu. Vou tentar hoje à noite, prometo."]], ["/n/ em notification e unplug", "O /n/ de notification e unplug: encoste a ponta da língua atrás dos dentes de cima e deixe o ar sair pelo nariz. Em unplug, o n fica no meio da palavra, como em 'banco', mas sem abrir a boca para o 'u'.", ["notification", "unplug"]], ["Rosa waits ___ new notifications.", "for", "to", "Rosa espera por novas notificações.", "O verbo wait pede a preposição for."], [["She scrolls through her feed and waits for new notifications.", "Ela rola o feed e espera por novas notificações."], ["Her screen time depends on her mood and on the weather.", "O tempo de tela dela depende do humor e do clima."]], [{"t": "c", "q": "My screen time depends ___ my mood.", "o": ["on", "at", "of"], "pt": "Meu tempo de tela depende do meu humor.", "why": "O verbo depend pede a preposição on."}, {"t": "l", "say": "She waits for new notifications.", "o": ["She waits for new notifications.", "She waits to new notifications.", "She looks at new notifications."], "why": "A frase ouvida diz waits for, e wait pede for."}, {"t": "b", "pt": "Eu sempre espero por mensagens.", "w": ["I", "always", "wait", "for", "messages"]}, {"t": "b", "pt": "Ela olha para o celular.", "w": ["She", "looks", "at", "her", "phone"]}]];
