englishA2ExtraWordExamples[210]={"put through": ["The receptionist can put through your call to the lab.", "A recepcionista pode transferir a sua ligação para o laboratório."]};
englishA2Plans[211]={"title": "Recado para o contador que está fora", "file": "", "grammar": "Deixar e anotar recados: Can I take a message? / Tell him that…", "goal": "Deixe um recado com Tell him that… e ofereça anotar um com Can I take a message?", "words": [["voice mail", "caixa postal de voz"], ["ring back", "ligar de volta"], ["get through", "conseguir completar a ligação"], ["take down", "anotar"], ["missed call", "chamada perdida"], ["busy signal", "sinal de ocupado"], ["fax", "fax"], ["cut off", "cortar, cair a ligação"]]};
englishA2Content[211]=[[["Omar calls the accounting office, but he hears a busy signal.", "Omar liga para o escritório de contabilidade, mas ouve o sinal de ocupado."], ["He tries three times, and finally he gets through.", "Ele tenta três vezes e, por fim, consegue completar a ligação."], ["\"Mr. Hill is out,\" says the assistant. \"Can I take a message?\"", "\"O Sr. Hill saiu\", diz a assistente. \"Posso anotar um recado?\""], ["\"Tell him that I sent the papers by fax,\" Omar says.", "\"Diga a ele que eu mandei os papéis por fax\", diz Omar."], ["She says she will take down the message and give it to him.", "Ela diz que vai anotar o recado e entregá-lo a ele."], ["At two o'clock, Mr. Hill reads the note and calls Omar.", "Às duas horas, o Sr. Hill lê o bilhete e liga para o Omar."]], [["Hi Omar, I saw your missed call. Sorry I couldn't answer.", "Oi, Omar, vi a sua chamada perdida. Desculpe por não ter atendido."], ["Hi, Mr. Hill. I left a voice mail, but it cut off after ten seconds.", "Oi, Sr. Hill. Deixei uma mensagem de voz, mas ela cortou depois de dez segundos."], ["Then I missed half of it. What did you say?", "Então perdi metade. O que você disse?"], ["I said the contract is ready. Please tell Sara that I need her signature by Friday.", "Eu disse que o contrato está pronto. Por favor, diga à Sara que preciso da assinatura dela até sexta."], ["Got it. Sara is at lunch, so I'll tell her at one o'clock.", "Entendi. A Sara está almoçando, então vou avisá-la à uma hora."], ["Perfect. Could you ring back if she has any questions? I'm in the office until six.", "Perfeito. Você poderia ligar de volta se ela tiver dúvidas? Fico no escritório até as seis."], ["Sure. I'll ring back around four, after my meeting.", "Claro. Ligo de volta por volta das quatro, depois da minha reunião."], ["Great. Four o'clock is fine. Thanks, Mr. Hill.", "Ótimo. Quatro horas está bom. Obrigado, Sr. Hill."]], ["/θ/ em three e thanks", "Coloque a ponta da língua entre os dentes e sopre, sem vibrar a voz. Não troque por 's' nem por 't': three não é 'tree'.", ["three", "thanks"]], ["Can I ___ a message?", "take", "make", "Posso anotar um recado?", "Em inglês, a gente 'toma' (take) um recado, não 'faz' (make) um recado."], [["\"Mr. Hill is out,\" says the assistant. \"Can I take a message?\"", "\"O Sr. Hill saiu\", diz a assistente. \"Posso anotar um recado?\""], ["\"Tell him that I sent the papers by fax,\" Omar says.", "\"Diga a ele que eu mandei os papéis por fax\", diz Omar."]], [{"t": "c", "q": "Tell Sara ___ I need her signature.", "o": ["that", "to", "for"], "pt": "Diga à Sara que eu preciso da assinatura dela.", "why": "Depois de tell + pessoa, o recado vem introduzido por that."}, {"t": "l", "say": "Can I take a message?", "o": ["Can I take a message?", "Can I make a message?", "Can I take a massage?"], "why": "A expressão certa é take a message, e message não é massage."}, {"t": "b", "pt": "Diga a ele que eu mandei um fax.", "w": ["Tell", "him", "that", "I", "sent", "a", "fax"]}, {"t": "b", "pt": "Posso anotar um recado?", "w": ["Can", "I", "take", "a", "message"]}]];
