englishA2ExtraWordExamples[211]={"get through": ["I called ten times, but I couldn't get through.", "Liguei dez vezes, mas não consegui completar a ligação."]};
englishA2Plans[212]={"title": "Comprando ingressos de show e soletrando o nome", "file": "", "grammar": "Soletrar nomes e repetir números: Could you spell…? / Do you mean…?", "goal": "Peça e dê o soletrado de nomes e números com Could you spell…? e Do you mean…?", "words": [["initial", "inicial"], ["digit", "dígito"], ["area code", "código de área"], ["capital letter", "letra maiúscula"], ["hyphen", "hífen"], ["at sign", "arroba"], ["zip code", "CEP"], ["mix up", "confundir, trocar"], ["dialled", "discou"]]};
englishA2Content[212]=[[["Mia dialled the number of a theater to buy two tickets.", "Mia discou o número de um teatro para comprar dois ingressos."], ["The agent asks, \"Could you spell your last name, please?\"", "A atendente pergunta: \"Você poderia soletrar o seu sobrenome, por favor?\""], ["\"It's Moreira, M-O-R-E-I-R-A, with a capital letter at the start,\" Mia says.", "\"É Moreira, M-O-R-E-I-R-A, com letra maiúscula no começo\", diz Mia."], ["Then she gives her zip code, and the agent asks, \"Do you mean 90210?\"", "Depois ela dá o CEP, e a atendente pergunta: \"Você quer dizer 90210?\""], ["Her email has a hyphen and an at sign, so she says each one slowly.", "O e-mail dela tem um hífen e uma arroba, então ela fala cada um devagar."], ["At the end, the agent reads everything back, and it's all correct.", "No fim, a atendente lê tudo de volta, e está tudo certo."]], [["Box office, good evening. How can I help you?", "Bilheteria, boa noite. Como posso ajudar?"], ["Hi, I'd like two tickets for Saturday night, please.", "Oi, eu gostaria de dois ingressos para sábado à noite, por favor."], ["Sure. Could you spell your first name and give me your middle initial?", "Claro. Você poderia soletrar o seu primeiro nome e me dar a inicial do nome do meio?"], ["It's Mia, M-I-A, and my middle initial is L.", "É Mia, M-I-A, e a inicial do meio é L."], ["Thanks. And your phone number? Do you mean 415 or 450 for the area code?", "Obrigada. E o seu telefone? Você quer dizer 415 ou 450 para o código de área?"], ["It's 415, like San Francisco. The number is 555-0187.", "É 415, como San Francisco. O número é 555-0187."], ["So that's 555-0817. Or did I mix up two digits?", "Então é 555-0817. Ou será que eu troquei dois dígitos?"], ["You did mix up two digits. It's 0187: zero, one, eight, seven.", "Você trocou dois dígitos, sim. É 0187: zero, um, oito, sete."]], ["/ɪ/ curto em digit e initial", "O 'i' de digit e initial é curto e relaxado, bem diferente do 'i' longo de see. Não estique a vogal.", ["digit", "initial"]], ["Could you ___ your last name?", "spell", "speak", "Você poderia soletrar o seu sobrenome?", "Soletrar é spell; speak significa falar, e isso muda o pedido."], [["The agent asks, \"Could you spell your last name, please?\"", "A atendente pergunta: \"Você poderia soletrar o seu sobrenome, por favor?\""], ["Thanks. And your phone number? Do you mean 415 or 450 for the area code?", "Obrigada. E o seu telefone? Você quer dizer 415 ou 450 para o código de área?"]], [{"t": "c", "q": "Do you ___ 415 or 450?", "o": ["mean", "means", "meaning"], "pt": "Você quer dizer 415 ou 450?", "why": "Depois de Do you, o verbo fica na forma simples: mean."}, {"t": "l", "say": "Could you spell your last name?", "o": ["Could you spell your last name?", "Could you sell your last name?", "Could you tell your last name?"], "why": "Você ouviu spell (soletrar), não sell nem tell."}, {"t": "b", "pt": "Você poderia soletrar o seu sobrenome?", "w": ["Could", "you", "spell", "your", "last", "name"]}, {"t": "b", "pt": "Você quer dizer o código de área?", "w": ["Do", "you", "mean", "the", "area", "code"]}]];
