englishA2Plans[213]={"title": "Ligação ruim do metrô para o achados e perdidos", "file": "", "grammar": "Pedir para repetir ou falar mais devagar com perguntas indiretas", "goal": "Peça para repetir ou falar mais devagar usando Could you tell me…? e Do you know…?", "words": [["speak up", "falar mais alto"], ["slow down", "falar mais devagar"], ["say again", "repetir"], ["come again", "como? (pedir repetição)"], ["bad connection", "ligação ruim"], ["static", "chiado"], ["echo", "eco"], ["mumble", "murmurar"], ["break up", "falhar, picotar (sinal)"]]};
englishA2Content[213]=[[["Kenji calls the airport from the subway, but it's a bad connection.", "Kenji liga para o aeroporto do metrô, mas a ligação está ruim."], ["There is static on the line, and he hears an echo of his own voice.", "Há chiado na linha, e ele ouve o eco da própria voz."], ["\"Could you speak up, please?\" he says. \"I can't hear you.\"", "\"Você poderia falar mais alto, por favor?\", ele diz. \"Não consigo ouvir você.\""], ["The agent asks, \"Can you tell me what color your suitcase is?\"", "O atendente pergunta: \"Você pode me dizer de que cor é a sua mala?\""], ["The voice starts to break up, so Kenji walks up to the street.", "A voz começa a falhar, então Kenji sobe até a rua."], ["Outside, the line is clear, and he can finally talk.", "Do lado de fora, a linha está limpa, e ele finalmente consegue falar."]], [["Lost Luggage Office. Can you hear me now?", "Achados e Perdidos de Bagagem. Está me ouvindo agora?"], ["Yes, much better. I was in the subway a minute ago.", "Sim, muito melhor. Eu estava no metrô há um minuto."], ["No problem. Could you tell me where you last saw your suitcase?", "Sem problema. Você poderia me dizer onde viu a sua mala pela última vez?"], ["At gate 12. It's a big blue bag with a yellow tag.", "No portão 12. É uma mala azul grande com uma etiqueta amarela."], ["Come again? I didn't catch the gate number.", "Como? Não entendi o número do portão."], ["Gate twelve. Sorry, I tend to mumble when I'm tired.", "Portão doze. Desculpe, eu costumo murmurar quando estou cansado."], ["That's fine. Could you slow down and tell me the flight number?", "Tudo bem. Você poderia falar mais devagar e me dizer o número do voo?"], ["Sure. It's flight UA 482. Do you know if the bag is there?", "Claro. É o voo UA 482. Você sabe se a mala está aí?"], ["Got it, UA 482. Yes, we found it, and you can pick it up today.", "Entendi, UA 482. Sim, nós a encontramos, e você pode buscá-la hoje."], ["Great news! I'll be there in an hour.", "Ótima notícia! Chego aí em uma hora."]], ["/ʌ/ em mumble e come", "O /ʌ/ é um 'a' curto e relaxado, com a boca quase parada. Não diga 'mumbôl' nem 'cômi': pense num 'â' bem rápido.", ["mumble", "come"]], ["Can you tell me where ___?", "it is", "is it", "Você pode me dizer onde está?", "Em pergunta indireta a ordem volta a ser a da afirmação: where it is, não where is it."], [["The agent asks, \"Can you tell me what color your suitcase is?\"", "O atendente pergunta: \"Você pode me dizer de que cor é a sua mala?\""], ["That's fine. Could you slow down and tell me the flight number?", "Tudo bem. Você poderia falar mais devagar e me dizer o número do voo?"]], [{"t": "c", "q": "Do you know what time the office ___?", "o": ["opens", "does it open", "is open"], "pt": "Você sabe a que horas o escritório abre?", "why": "Na pergunta indireta, o verbo vem depois do sujeito, sem do: the office opens."}, {"t": "l", "say": "Could you tell me where the bag is?", "o": ["Could you tell me where the bag is?", "Could you tell me where is the bag?", "Could you tell me where the bag was?"], "why": "A pergunta indireta mantém a ordem normal: where the bag is."}, {"t": "b", "pt": "Você pode falar mais devagar, por favor?", "w": ["Could", "you", "slow", "down", "please"]}, {"t": "b", "pt": "Você sabe onde fica o portão?", "w": ["Do", "you", "know", "where", "the", "gate", "is"]}]];
