englishA2Plans[214]={"title": "Remarcando o corte de cabelo no salão", "file": "", "grammar": "Marcar e remarcar horários: How about…? / I'm afraid I can't…", "goal": "Remarque um horário usando How about…? e recuse com educação com I'm afraid I can't…", "words": [["reschedule", "remarcar"], ["booked up", "lotado, sem vagas"], ["fully booked", "totalmente reservado"], ["slot", "horário disponível"], ["cancelled", "cancelado"], ["inconvenient", "inconveniente, incômodo"], ["convenience", "comodidade"], ["I'm afraid", "infelizmente, receio que"]]};
englishA2Content[214]=[[["Lia has a haircut on Friday at three, but her train is cancelled.", "Lia tem um corte de cabelo na sexta às três, mas o trem dela foi cancelado."], ["She calls the salon to reschedule.", "Ela liga para o salão para remarcar."], ["\"I'm afraid Friday is fully booked,\" says the receptionist.", "\"Infelizmente a sexta está totalmente reservada\", diz a recepcionista."], ["\"How about Saturday morning? There's a slot at ten.\"", "\"Que tal sábado de manhã? Tem um horário às dez.\""], ["Lia says, \"I'm afraid I can't. I work until noon on Saturday.\"", "Lia diz: \"Infelizmente não posso. Trabalho até o meio-dia no sábado.\""], ["In the end, they choose Monday at six, and Lia thanks her.", "No fim, elas escolhem segunda às seis, e Lia agradece."]], [["Bella Salon, good morning. How can I help you?", "Bella Salon, bom dia. Como posso ajudar?"], ["Hi, I have an appointment on Friday at three, but I need to reschedule.", "Oi, tenho um horário na sexta às três, mas preciso remarcar."], ["I see. I'm afraid the rest of the week is booked up.", "Entendo. Receio que o resto da semana esteja lotado."], ["Oh no. Do you have anything on Monday?", "Ah, não. Vocês têm algo na segunda?"], ["How about Monday at 4:30?", "Que tal segunda às 16h30?"], ["I'm afraid I can't. I don't finish work until six.", "Infelizmente não posso. Só saio do trabalho às seis."], ["No problem. Our last slot is at 6:30. Would that work?", "Sem problema. Nosso último horário é às 18h30. Serve?"], ["Yes, that's perfect. I hope it's not inconvenient to change it so late.", "Sim, perfeito. Espero que não seja incômodo mudar tão em cima da hora."], ["Not at all. For your convenience, we'll send you a text reminder on Sunday.", "De jeito nenhum. Para sua comodidade, vamos mandar um lembrete por mensagem no domingo."], ["Great. So it's Monday at 6:30. Thanks a lot!", "Ótimo. Então é segunda às 18h30. Muito obrigada!"]], ["/sl/ em slot e salon", "Comece com um 's' limpo e emende o 'l', sem 'i' na frente: slot, não 'islot'. Em salon, a ênfase vai na primeira sílaba.", ["slot", "salon"]], ["I'm afraid I ___ come on Friday.", "can't", "don't can", "Infelizmente não posso ir na sexta.", "Can é um verbo modal e não usa don't: a forma negativa é can't."], [["Lia says, \"I'm afraid I can't. I work until noon on Saturday.\"", "Lia diz: \"Infelizmente não posso. Trabalho até o meio-dia no sábado.\""], ["I'm afraid I can't. I don't finish work until six.", "Infelizmente não posso. Só saio do trabalho às seis."]], [{"t": "c", "q": "How ___ Monday at six?", "o": ["about", "for", "like"], "pt": "Que tal segunda às seis?", "why": "A sugestão se faz com How about + horário ou dia."}, {"t": "l", "say": "I'm afraid I can't come on Friday.", "o": ["I'm afraid I can't come on Friday.", "I'm afraid I can come on Friday.", "I'm afraid I can't come on Sunday."], "why": "Você ouviu can't (não posso) e Friday (sexta)."}, {"t": "b", "pt": "Infelizmente não posso na sexta.", "w": ["I'm", "afraid", "I", "can't", "on", "Friday"]}, {"t": "b", "pt": "Que tal segunda às seis?", "w": ["How", "about", "Monday", "at", "six"]}]];
