englishA2Plans[215]={"title": "Reclamando de uma cobrança na conta do celular", "file": "", "grammar": "Reclamar de uma cobrança: I'm calling about… / There's a problem with…", "goal": "Explique o motivo da ligação com I'm calling about… e aponte o erro com There's a problem with…", "words": [["double-charged", "cobrado em dobro"], ["overcharge", "cobrança a mais"], ["dispute", "contestar"], ["reference number", "número de referência"], ["case number", "número do protocolo"], ["apologies", "pedido de desculpas"], ["look into", "investigar"], ["phone bill", "conta de telefone"], ["adding up", "fazendo sentido (contas)"]]};
englishA2Content[215]=[[["Rosa opens her phone bill and sees a problem.", "Rosa abre a conta de telefone e vê um problema."], ["She was double-charged for the same plan in March.", "Ela foi cobrada em dobro pelo mesmo plano em março."], ["She calls the company and says, \"I'm calling about my bill.\"", "Ela liga para a empresa e diz: \"Estou ligando sobre a minha conta.\""], ["\"There's a problem with the amount,\" she says. \"It's not adding up.\"", "\"Há um problema com o valor\", ela diz. \"A conta não bate.\""], ["The agent says, \"Apologies for the mistake. I'll look into it.\"", "O atendente diz: \"Desculpe pelo erro. Vou investigar.\""], ["She gets a case number and waits for an answer.", "Ela recebe um número de protocolo e espera uma resposta."]], [["Thank you for calling Nova Mobile. This is Dan. How can I help?", "Obrigado por ligar para a Nova Mobile. Aqui é o Dan. Como posso ajudar?"], ["Hi, I'm calling about my bill. There's a problem with the charge for March.", "Oi, estou ligando sobre a minha conta. Há um problema com a cobrança de março."], ["I'm sorry to hear that. Could I have your reference number, please?", "Sinto muito. Pode me dar o seu número de referência, por favor?"], ["Sure. It's 48-2291. I think it's an overcharge of thirty dollars.", "Claro. É 48-2291. Acho que é uma cobrança a mais de trinta dólares."], ["Let me take a look. You're right, the plan appears twice. I apologize.", "Deixe-me dar uma olhada. Você tem razão, o plano aparece duas vezes. Peço desculpas."], ["So can I dispute the extra charge? I don't want to pay it.", "Então posso contestar a cobrança extra? Não quero pagá-la."], ["Of course. I've opened a case, and your case number is 7714.", "Claro. Abri um chamado, e o seu número de protocolo é 7714."], ["Great. Will the thirty dollars come off my next bill?", "Ótimo. Os trinta dólares vão sair da minha próxima conta?"], ["Yes. You'll see the new total on the fifth of April.", "Sim. Você verá o novo total no dia cinco de abril."], ["Perfect. I'll keep the number 7714. Thanks, Dan.", "Perfeito. Vou guardar o número 7714. Obrigada, Dan."]], ["/tʃ/ em March e charge", "O 'ch' inglês é como o 'tch' de 'tchau', mas com os lábios um pouco projetados. March termina com esse som: não diga 'Márqui'.", ["March", "charge"]], ["I'm calling ___ my bill.", "about", "for", "Estou ligando sobre a minha conta.", "Para dizer o assunto da ligação usamos about, não for."], [["She calls the company and says, \"I'm calling about my bill.\"", "Ela liga para a empresa e diz: \"Estou ligando sobre a minha conta.\""], ["Hi, I'm calling about my bill. There's a problem with the charge for March.", "Oi, estou ligando sobre a minha conta. Há um problema com a cobrança de março."]], [{"t": "c", "q": "There's a problem ___ the bill.", "o": ["with", "of", "in"], "pt": "Há um problema com a conta.", "why": "A expressão fixa é a problem with something."}, {"t": "l", "say": "I'm calling about my phone bill.", "o": ["I'm calling about my phone bill.", "I'm calling about my phone bell.", "I'm calling about my phone ball."], "why": "Você ouviu bill (conta), não bell nem ball."}, {"t": "b", "pt": "Estou ligando sobre a minha conta.", "w": ["I'm", "calling", "about", "my", "bill"]}, {"t": "b", "pt": "Há um problema com a cobrança.", "w": ["There's", "a", "problem", "with", "the", "charge"]}]];
