englishA2Plans[216]={"title": "Confirmando a entrega de um sofá", "file": "", "grammar": "Confirmar dados: Let me check / So that's… / Let me read back", "goal": "Confirme dados ao telefone com Let me check, So that's… e Let me read back…", "words": [["read back", "reler em voz alta para confirmar"], ["let me check", "deixe-me conferir"], ["double-check", "conferir de novo"], ["correct", "correto"], ["exactly", "exatamente"], ["jot down", "anotar rápido"], ["ID number", "número de documento"], ["gate code", "código do portão"], ["contact", "contato"]]};
englishA2Content[216]=[[["Priya buys a sofa online, and the store calls to confirm the delivery.", "Priya compra um sofá on-line, e a loja liga para confirmar a entrega."], ["\"Let me check the address,\" says the agent.", "\"Deixe-me conferir o endereço\", diz o atendente."], ["He asks for her ID number and a contact phone.", "Ele pede o número do documento dela e um telefone de contato."], ["\"Let me read back your address,\" he says. \"Sixteen Oak Street, apartment 5.\"", "\"Deixe-me reler o seu endereço\", ele diz. \"Oak Street, 16, apartamento 5.\""], ["Priya says, \"That's correct, but the building has a gate code.\"", "Priya diz: \"Está correto, mas o prédio tem um código no portão.\""], ["She asks him to jot down the code: 4-4-1-9.", "Ela pede que ele anote o código: 4-4-1-9."]], [["Hi, this is Sam from Home Mart. I'm calling to confirm your delivery.", "Oi, aqui é o Sam, da Home Mart. Estou ligando para confirmar a sua entrega."], ["Oh, good. It's for Thursday, right?", "Ah, que bom. É para quinta, certo?"], ["Let me check. Yes, Thursday between two and four. So that's 16 Oak Street, apartment 5?", "Deixe-me ver. Sim, quinta entre duas e quatro. Então é Oak Street, 16, apartamento 5?"], ["Exactly. But I'll be at work, so my brother will receive it.", "Exatamente. Mas estarei no trabalho, então meu irmão vai receber."], ["No problem. Could you give me his phone number, please?", "Sem problema. Pode me dar o telefone dele, por favor?"], ["It's 555-0142. His name is Leo, and he'll show his ID.", "É 555-0142. O nome dele é Leo, e ele vai mostrar o documento."], ["Thanks. Let me double-check: Leo, 555-0142, gate code 4419. Is that right?", "Obrigado. Deixe-me conferir de novo: Leo, 555-0142, código do portão 4419. Está certo?"], ["Yes, all correct. Thank you for calling, Sam.", "Sim, tudo correto. Obrigada por ligar, Sam."]], ["/r/ em correct e read", "Para o 'r' inglês, a língua fica puxada para trás sem encostar em nada. Não use o 'h' do 'r' de 'rato' em read.", ["correct", "read"]], ["Let me ___ the date.", "check", "to check", "Deixe-me conferir a data.", "Depois de let me usamos o verbo simples, sem to."], [["\"Let me check the address,\" says the agent.", "\"Deixe-me conferir o endereço\", diz o atendente."], ["\"Let me read back your address,\" he says. \"Sixteen Oak Street, apartment 5.\"", "\"Deixe-me reler o seu endereço\", ele diz. \"Oak Street, 16, apartamento 5.\""]], [{"t": "c", "q": "Let me ___ the time.", "o": ["check", "to check", "checking"], "pt": "Deixe-me conferir a hora.", "why": "Let me é seguido do verbo simples: check."}, {"t": "l", "say": "Let me read it back.", "o": ["Let me read it back.", "Let me read it black.", "Let me lead it back."], "why": "Você ouviu read it back (reler para confirmar)."}, {"t": "b", "pt": "Deixe-me conferir o endereço.", "w": ["Let", "me", "check", "the", "address"]}, {"t": "b", "pt": "Então são duas da tarde?", "w": ["So", "that's", "two", "in", "the", "afternoon"]}]];
