englishA2Plans[217]={"title": "Pedindo ajuda para um vizinho que passou mal", "file": "", "grammar": "Descrever um problema de saúde e o lugar numa ligação de emergência", "goal": "Descreva o problema e o endereço numa ligação de emergência com He has… e We're at…", "words": [["dispatcher", "atendente de emergência"], ["paramedic", "paramédico"], ["chest pain", "dor no peito"], ["conscious", "consciente"], ["cross street", "rua transversal"], ["stay calm", "manter a calma"], ["on the way", "a caminho"], ["unconscious", "inconsciente"], ["speaker phone", "viva-voz"]]};
englishA2Content[217]=[[["Elena finds her neighbor, Mr. Reed, on the floor of the laundry room.", "Elena encontra o vizinho, o Sr. Reed, no chão da lavanderia."], ["She calls 911, and a dispatcher answers.", "Ela liga para o 911, e uma atendente responde."], ["\"My neighbor has chest pain, and he's very pale,\" she says.", "\"Meu vizinho está com dor no peito e está muito pálido\", ela diz."], ["\"Stay calm and tell me your location,\" says the dispatcher.", "\"Mantenha a calma e me diga onde vocês estão\", diz a atendente."], ["Elena says, \"We're at 20 Pine Street. The nearest cross street is Main.\"", "Elena diz: \"Estamos na Pine Street, 20. A transversal mais próxima é a Main.\""], ["Soon she hears a siren, and a paramedic runs in.", "Logo ela ouve uma sirene, e um paramédico entra correndo."]], [["911, what's your emergency?", "911, qual é a sua emergência?"], ["My neighbor fell, and he isn't answering. I think he's unconscious.", "Meu vizinho caiu e não responde. Acho que está inconsciente."], ["Is he breathing? Is he conscious? Can he talk to you?", "Ele está respirando? Está consciente? Consegue falar com você?"], ["His eyes are open, but he can't talk. He has pain in his chest.", "Os olhos dele estão abertos, mas ele não consegue falar. Ele está com dor no peito."], ["Okay, help is on the way. What's your address and the nearest cross street?", "Certo, a ajuda está a caminho. Qual é o seu endereço e a transversal mais próxima?"], ["It's 20 Pine Street, apartment 1. The cross street is Main Avenue.", "É Pine Street, 20, apartamento 1. A transversal é a Main Avenue."], ["Good. Please stay calm and put me on speaker phone, so you can help him.", "Bom. Por favor, mantenha a calma e me ponha no viva-voz, para poder ajudá-lo."], ["You're on speaker phone now. I can see the ambulance outside!", "Você está no viva-voz agora. Estou vendo a ambulância lá fora!"]], ["/eɪ/ em stay e Main", "O /eɪ/ é um ditongo: comece em 'e' e deslize para 'i'. Em stay, o 's' vem limpo, sem 'e' na frente.", ["stay", "Main"]], ["He ___ chest pain.", "has", "is", "Ele está com dor no peito.", "Para dizer que alguém sente uma dor, usamos have/has, não be."], [["\"My neighbor has chest pain, and he's very pale,\" she says.", "\"Meu vizinho está com dor no peito e está muito pálido\", ela diz."], ["It's 20 Pine Street, apartment 1. The cross street is Main Avenue.", "É Pine Street, 20, apartamento 1. A transversal é a Main Avenue."]], [{"t": "c", "q": "My mother ___ a bad headache.", "o": ["has", "is", "have"], "pt": "Minha mãe está com uma forte dor de cabeça.", "why": "Com dor se diz has + dor; com she/he/mother usamos has."}, {"t": "l", "say": "Help is on the way.", "o": ["Help is on the way.", "Hope is on the way.", "Help is on the bay."], "why": "Você ouviu Help is on the way (a ajuda está a caminho)."}, {"t": "b", "pt": "Ele está com dor no peito.", "w": ["He", "has", "chest", "pain"]}, {"t": "b", "pt": "Fique calmo e me diga o endereço.", "w": ["Stay", "calm", "and", "tell", "me", "the", "address"]}]];
