englishA2Plans[218]={"title": "Encerrando a ligação com uma amiga depois de um favor", "file": "", "grammar": "Encerrar a ligação com educação: Is there anything else? / Thanks for calling", "goal": "Encerre ligações com educação usando Is there anything else…? e Thanks for calling.", "words": [["thanks for calling", "obrigado por ligar"], ["anything else", "mais alguma coisa"], ["have a nice day", "tenha um bom dia"], ["take care", "se cuide"], ["you're welcome", "de nada"], ["no worries", "sem problema"], ["talk soon", "falamos em breve"], ["have a good one", "tudo de bom"], ["catch you later", "até mais"]]};
englishA2Content[218]=[[["Noah calls the city library to renew two books.", "Noah liga para a biblioteca da cidade para renovar dois livros."], ["The librarian renews them for three more weeks.", "A bibliotecária renova os livros por mais três semanas."], ["\"Is there anything else I can help you with?\" she asks.", "\"Posso ajudar com mais alguma coisa?\", ela pergunta."], ["\"No, that's all. Thank you!\" Noah answers.", "\"Não, é só isso. Obrigado!\", responde Noah."], ["She says, \"Thanks for calling, and have a nice day.\"", "Ela diz: \"Obrigada por ligar, e tenha um bom dia.\""], ["Noah says goodbye and puts his phone in his pocket.", "Noah se despede e guarda o celular no bolso."]], [["Mia, thanks for lending me your library card yesterday.", "Mia, obrigado por me emprestar a sua carteirinha da biblioteca ontem."], ["You're welcome! Did you find all the books?", "De nada! Você achou todos os livros?"], ["Yes, all three. Sorry I called so late last night.", "Sim, os três. Desculpe ter ligado tão tarde ontem à noite."], ["No worries. I was still awake. Is there anything else you need?", "Sem problema. Eu ainda estava acordada. Precisa de mais alguma coisa?"], ["Just one thing. Are you free on Sunday for lunch?", "Só uma coisa. Você está livre no domingo para almoçar?"], ["Sunday works. Let's meet at noon at the Green Café.", "Domingo dá certo. Vamos nos encontrar ao meio-dia no Green Café."], ["Perfect. I have to go now, my bus is here. Take care, and have a good one!", "Perfeito. Tenho que ir agora, meu ônibus chegou. Se cuide, e tudo de bom!"], ["You too! See you Sunday at noon. Talk soon, and catch you later!", "Você também! Até domingo ao meio-dia. Falamos em breve, e até mais!"]], ["/ŋ/ em calling e anything", "O 'ng' final é um som nasal feito no fundo da boca, sem um 'g' forte depois. Diga calling, não 'callingue'.", ["calling", "anything"]], ["Is there ___ else I can help you with?", "anything", "something", "Posso ajudar com mais alguma coisa?", "Em perguntas usamos anything; something é mais comum em frases afirmativas."], [["\"Is there anything else I can help you with?\" she asks.", "\"Posso ajudar com mais alguma coisa?\", ela pergunta."], ["She says, \"Thanks for calling, and have a nice day.\"", "Ela diz: \"Obrigada por ligar, e tenha um bom dia.\""]], [{"t": "c", "q": "Thanks for ___.", "o": ["calling", "call", "to call"], "pt": "Obrigado por ligar.", "why": "Depois de thanks for usamos o verbo com -ing."}, {"t": "l", "say": "Is there anything else?", "o": ["Is there anything else?", "Is there anyone else?", "Is there anywhere else?"], "why": "Você ouviu anything (alguma coisa), não anyone nem anywhere."}, {"t": "b", "pt": "Obrigado por ligar para a biblioteca.", "w": ["Thanks", "for", "calling", "the", "library"]}, {"t": "b", "pt": "Tenha um bom dia.", "w": ["Have", "a", "nice", "day"]}]];
