englishA2Plans[219]={"title": "Revisão: um dia de ligações na loja de bicicletas", "file": "", "grammar": "Revisão: um dia de ligações (mini-história)", "goal": "Revise pedidos, recados, confirmações e despedidas ao telefone num dia de trabalho.", "words": [["wrap up", "terminar, encerrar"], ["touch base", "falar rapidamente com alguém"], ["follow up", "dar seguimento"], ["heads up", "aviso prévio"], ["keep in touch", "manter contato"], ["dead battery", "bateria descarregada"], ["directory", "lista telefônica"], ["speak soon", "falamos em breve"], ["sign off", "encerrar a ligação"]]};
englishA2Content[219]=[[["Tom wants to wrap up his phone calls before lunch.", "Tom quer terminar as ligações antes do almoço."], ["First, he looks for a number in the directory.", "Primeiro, ele procura um número na lista telefônica."], ["Then he calls a supplier to touch base about a late order.", "Depois liga para um fornecedor para falar sobre um pedido atrasado."], ["\"Just a heads up,\" the supplier says, \"the tires will arrive on Friday.\"", "\"Só um aviso\", diz o fornecedor, \"os pneus chegam na sexta.\""], ["At noon, Tom's phone has a dead battery, so he plugs it in.", "Ao meio-dia, o celular do Tom está com a bateria descarregada, então ele o carrega."], ["After lunch, he finishes the last call and feels happy.", "Depois do almoço, ele termina a última ligação e fica feliz."]], [["Good afternoon, this is Tom from Speedy Bikes. Could I speak to Rosa Diaz?", "Boa tarde, aqui é o Tom, da Speedy Bikes. Eu poderia falar com a Rosa Diaz?"], ["Speaking. Hi, Tom. Is my bike ready?", "Sou eu. Oi, Tom. A minha bicicleta está pronta?"], ["Almost. I'm calling to follow up on the new brakes. They arrive Friday.", "Quase. Estou ligando para dar seguimento aos freios novos. Eles chegam na sexta."], ["Friday is fine. Can I pick it up at five?", "Sexta está bom. Posso buscar às cinco?"], ["I'm afraid we close at five. How about four thirty?", "Infelizmente fechamos às cinco. Que tal às quatro e meia?"], ["Four thirty is perfect. Sorry, my phone died earlier, so I missed your call.", "Quatro e meia é perfeito. Desculpe, meu celular descarregou antes e perdi a sua ligação."], ["No problem. Let's keep in touch, and I have to sign off now. Another customer is calling.", "Sem problema. Vamos manter contato, e preciso encerrar agora. Outro cliente está ligando."], ["Sure. See you Friday at four thirty. Speak soon!", "Claro. Até sexta às quatro e meia. Falamos em breve!"]], ["/ɛ/ em dead e heads", "O /ɛ/ é um 'é' aberto e curto, como em 'pé'. Não troque por 'i': dead não é 'did'.", ["dead", "heads"]], ["Could I ___ to Rosa, please?", "speak", "say", "Eu poderia falar com a Rosa, por favor?", "Com Could I ... to, o verbo certo para falar com alguém é speak."], [["Good afternoon, this is Tom from Speedy Bikes. Could I speak to Rosa Diaz?", "Boa tarde, aqui é o Tom, da Speedy Bikes. Eu poderia falar com a Rosa Diaz?"], ["I'm afraid we close at five. How about four thirty?", "Infelizmente fechamos às cinco. Que tal às quatro e meia?"]], [{"t": "c", "q": "Could I ___ to Dr. Lopez?", "o": ["speak", "say", "tell"], "pt": "Eu poderia falar com a Dra. Lopez?", "why": "Para falar com alguém ao telefone usamos speak to."}, {"t": "l", "say": "I'm afraid we close at five.", "o": ["I'm afraid we close at five.", "I'm afraid we close at nine.", "I'm afraid we closed at five."], "why": "Você ouviu close at five (fechamos às cinco), no presente."}, {"t": "b", "pt": "Posso falar com a Rosa?", "w": ["Could", "I", "speak", "to", "Rosa"]}, {"t": "b", "pt": "Que tal às quatro e meia?", "w": ["How", "about", "four", "thirty"]}]];
