englishA2MiniStories[219]=["Um dia de ligações do Sam", "Sam has a busy Monday and many calls to make.~Sam tem uma segunda-feira cheia e muitas ligações para fazer.|First, he calls the clinic, and the switchboard puts him on hold.~Primeiro, ele liga para a clínica, e a central o deixa em espera.|Nobody answers at the next number, so he leaves a voice mail.~Ninguém atende no número seguinte, então ele deixa uma mensagem de voz.|On the third call, the connection is bad, and he asks the man to speak up.~Na terceira ligação, a conexão está ruim, e ele pede que o homem fale mais alto.|The man can't hear the name, so Sam spells it letter by letter.~O homem não ouve o nome, então Sam o soletra letra por letra.|At noon, he sees a double-charged bill and calls his phone company.~Ao meio-dia, ele vê uma conta cobrada em dobro e liga para a operadora.|The agent says, \"I'll look into it. Let me read back your account number.\"~O atendente diz: \"Vou investigar. Deixe-me reler o número da sua conta.\"|In the afternoon, Sam needs to reschedule his dentist appointment.~À tarde, Sam precisa remarcar a consulta no dentista.|The receptionist says, \"I'm afraid we're booked up, but how about Friday?\"~A recepcionista diz: \"Infelizmente estamos lotados, mas que tal sexta?\"|Sam says, \"Friday is perfect. Thank you, and have a nice day!\"~Sam diz: \"Sexta é perfeito. Obrigado, e tenha um bom dia!\""];
englishA2Plans[220]={"title": "Meu trabalho no atendimento ao cliente", "file": "", "grammar": "Descrever o trabalho: I'm responsible for… / my job involves + -ing", "goal": "Descreva seu trabalho com I'm responsible for… e My job involves + verbo com -ing.", "words": [["responsible", "responsável"], ["in charge of", "encarregado de"], ["client", "cliente"], ["customer service", "atendimento ao cliente"], ["full-time", "período integral"], ["junior", "júnior, de nível inicial"], ["employee", "funcionário"], ["expert", "especialista"]]};
englishA2Content[220]=[[["I work full-time in customer service at a phone company.", "Eu trabalho em período integral no atendimento ao cliente de uma empresa de telefone."], ["I'm responsible for answering calls from angry clients.", "Sou responsável por atender ligações de clientes zangados."], ["My job involves listening, typing notes, and solving problems.", "Meu trabalho envolve ouvir, digitar anotações e resolver problemas."], ["My brother Sam is a junior employee at a bank, and he works part-time.", "Meu irmão Sam é um funcionário júnior de um banco e trabalha meio período."], ["He's in charge of the new accounts on Fridays.", "Ele é encarregado das contas novas às sextas."], ["Last Monday a client thanked me, and now I feel like an expert.", "Na segunda passada um cliente me agradeceu, e agora me sinto um especialista."]], [["Omar, what do you do at the phone company?", "Omar, o que você faz na empresa de telefone?"], ["I work in customer service. I'm responsible for the calls about internet problems.", "Eu trabalho no atendimento ao cliente. Sou responsável pelas ligações sobre problemas de internet."], ["That sounds hard. What does your job involve every day?", "Parece difícil. O que seu trabalho envolve todo dia?"], ["It involves talking to about forty clients and writing a short report.", "Envolve falar com uns quarenta clientes e escrever um relatório curto."], ["Forty? Are you a full-time employee?", "Quarenta? Você é funcionário de período integral?"], ["Yes, I am. My sister works part-time in the same office, and she's still junior.", "Sou, sim. Minha irmã trabalha meio período no mesmo escritório e ainda é júnior."], ["Who is in charge of your team?", "Quem é o responsável pela sua equipe?"], ["A woman named Rosa. She's an expert, so I'm learning a lot of things.", "Uma mulher chamada Rosa. Ela é especialista, então estou aprendendo muitas coisas."]], ["/θ/ em thanked e things", "Ponha a ponta da língua entre os dentes e solte o ar, sem trocar por 't' ou 'f'. Em thanked e things o som vem no começo.", ["thanked", "things"]], ["I'm responsible ___ answering the phone.", "for", "of", "Sou responsável por atender o telefone.", "Depois de responsible, a preposição certa é for."], [["I'm responsible for answering calls from angry clients.", "Sou responsável por atender ligações de clientes zangados."], ["It involves talking to about forty clients and writing a short report.", "Envolve falar com uns quarenta clientes e escrever um relatório curto."]], [{"t": "c", "q": "My job involves ___ emails all day.", "o": ["answering", "answer", "to answer"], "pt": "Meu trabalho envolve responder e-mails o dia todo.", "why": "Depois de involves usamos o verbo com -ing."}, {"t": "l", "say": "I'm in charge of the new clients.", "o": ["I'm in charge of the new clients.", "I'm in charge of the new classes.", "I'm in charge for the new clients."], "why": "A expressão certa é in charge of, e você ouviu clients."}, {"t": "b", "pt": "Eu sou responsável pelos clientes novos.", "w": ["I'm", "responsible", "for", "the", "new", "clients"]}, {"t": "b", "pt": "Meu trabalho envolve atender o telefone.", "w": ["My", "job", "involves", "answering", "the", "phone"]}]];
