englishA2Plans[221]={"title": "A copiadora travada antes da reunião", "file": "", "grammar": "Pedir ajuda a um colega: Could you give me a hand with…?", "goal": "Peça ajuda a um colega com Could you give me a hand with…?", "words": [["give me a hand", "me dar uma mão"], ["paper jam", "papel preso"], ["photocopy", "fotocópia, copiar"], ["out of order", "fora de serviço"], ["show me how", "me mostrar como"], ["figure out", "descobrir, entender"], ["equipment", "equipamento"], ["assist", "ajudar, auxiliar"], ["lend a hand", "dar uma mãozinha"]]};
englishA2Content[221]=[[["The photocopy machine in our office has a paper jam again.", "A copiadora do nosso escritório está com papel preso de novo."], ["Ben needs fifty copies before the meeting at ten.", "Ben precisa de cinquenta cópias antes da reunião das dez."], ["He can't figure out how to open the back door of the machine.", "Ele não consegue descobrir como abrir a porta de trás da máquina."], ["He asks Lia, \"Could you give me a hand with this machine?\"", "Ele pergunta à Lia: \"Você poderia me dar uma mão com esta máquina?\""], ["She shows him the green button, and together they pull out the paper.", "Ela mostra o botão verde, e juntos eles puxam o papel."], ["Then the machine stops again, so Ben runs to the second floor.", "Aí a máquina para de novo, e Ben corre para o segundo andar."]], [["Lia, could you give me a hand with the photocopy machine?", "Lia, você poderia me dar uma mão com a copiadora?"], ["Sure, Ben. What's the problem?", "Claro, Ben. Qual é o problema?"], ["There's a paper jam, and I can't figure out how to open the back.", "Tem papel preso, e não consigo descobrir como abrir a parte de trás."], ["Press the green button first, then pull the paper out slowly.", "Aperte o botão verde primeiro, depois puxe o papel devagar."], ["Could you show me how? I need fifty copies before the meeting at ten.", "Você pode me mostrar como? Preciso de cinquenta cópias antes da reunião das dez."], ["Okay, watch my hands. There. Now you try.", "Certo, olhe minhas mãos. Pronto. Agora tente você."], ["It works! Wait, the screen says out of order now.", "Funcionou! Espere, a tela diz fora de serviço agora."], ["Use the equipment on the second floor. I can lend a hand with the boxes, too.", "Use o equipamento do segundo andar. Posso dar uma mãozinha com as caixas também."]], ["/æ/ em jam e hand", "Abra bem a boca, entre o 'é' e o 'a' do português. Não diga 'jem' nem 'jam' com 'a' fechado.", ["jam", "hand"]], ["Could you give me a hand ___ these boxes?", "with", "for", "Você poderia me dar uma mão com estas caixas?", "Depois de a hand, a ajuda com algo usa with."], [["He asks Lia, \"Could you give me a hand with this machine?\"", "Ele pergunta à Lia: \"Você poderia me dar uma mão com esta máquina?\""], ["Lia, could you give me a hand with the photocopy machine?", "Lia, você poderia me dar uma mão com a copiadora?"]], [{"t": "c", "q": "Could you ___ me a hand with this report?", "o": ["give", "make", "do"], "pt": "Você poderia me dar uma mão com este relatório?", "why": "A expressão fixa é give me a hand."}, {"t": "l", "say": "I can't figure out how to open it.", "o": ["I can't figure out how to open it.", "I can't figure out how to close it.", "I can't find out how to open it."], "why": "Você ouviu figure out e open."}, {"t": "b", "pt": "Você poderia me dar uma mão?", "w": ["Could", "you", "give", "me", "a", "hand"]}, {"t": "b", "pt": "A máquina está fora de serviço.", "w": ["The", "machine", "is", "out", "of", "order"]}]];
