englishA2Plans[222]={"title": "Ensinando a enviar uma encomenda", "file": "", "grammar": "Dar instruções em sequência: first, next, make sure you…", "goal": "Explique um passo a passo com first, next e make sure you…", "words": [["instruction", "instrução"], ["procedure", "procedimento"], ["step by step", "passo a passo"], ["make sure", "certificar-se"], ["carry on", "continuar"], ["go over", "revisar, repassar"], ["efficient", "eficiente"], ["assign", "designar, atribuir"]]};
englishA2Content[222]=[[["Rosa has a new job: she trains Tom to send packages.", "Rosa tem uma tarefa nova: ela treina o Tom para enviar encomendas."], ["First, she gives him the written instructions.", "Primeiro, ela entrega a ele as instruções escritas."], ["Next, they go over the procedure step by step.", "Depois, eles repassam o procedimento passo a passo."], ["Make sure you check the address twice, she says.", "Certifique-se de conferir o endereço duas vezes, ela diz."], ["The boss gives Tom ten boxes, and he has to carry on alone.", "O chefe dá dez caixas ao Tom, e ele tem de continuar sozinho."], ["He is slow at first, but by noon he's very efficient.", "Ele é lento no começo, mas ao meio-dia já é muito eficiente."]], [["Tom, first, scan the label on the box.", "Tom, primeiro, escaneie a etiqueta da caixa."], ["Like this? The light is red.", "Assim? A luz está vermelha."], ["Hold it closer. Good. Next, type the weight, and make sure it's correct.", "Segure mais perto. Bom. Depois, digite o peso e certifique-se de que está certo."], ["It's four kilos. What do I do after that?", "São quatro quilos. O que eu faço depois disso?"], ["Then print the receipt and put it in the plastic bag. Don't forget the tape.", "Aí imprima o recibo e ponha na sacola plástica. Não esqueça a fita."], ["Got it. Could you go over the steps once more? I'm a little nervous.", "Entendi. Você pode repassar os passos mais uma vez? Estou um pouco nervoso."], ["Of course. Scan, type the weight, print, and then carry on with the next box.", "Claro. Escaneie, digite o peso, imprima e continue com a próxima caixa."], ["Okay. The boss assigns me ten boxes today, so I'll call you if there's a problem.", "Certo. O chefe me atribui dez caixas hoje, então vou te chamar se houver problema."]], ["/ʃ/ em sure e she", "Arredonde os lábios e solte um 'ch' suave, como quando pedimos silêncio. Em sure o som vem no começo; não diga 'sur' com s.", ["sure", "she"]], ["___ sure you check the address twice.", "Make", "Do", "Certifique-se de conferir o endereço duas vezes.", "A expressão fixa é make sure, nunca do sure."], [["Next, they go over the procedure step by step.", "Depois, eles repassam o procedimento passo a passo."], ["Hold it closer. Good. Next, type the weight, and make sure it's correct.", "Segure mais perto. Bom. Depois, digite o peso e certifique-se de que está certo."]], [{"t": "c", "q": "___, open the box. Next, check the label.", "o": ["First", "Last", "After"], "pt": "Primeiro, abra a caixa. Depois, confira a etiqueta.", "why": "First abre a sequência e combina com next."}, {"t": "l", "say": "Make sure you check the address.", "o": ["Make sure you check the address.", "Make sure you change the address.", "Make sure you checked the address."], "why": "Depois de make sure you usamos o verbo simples: check."}, {"t": "b", "pt": "Primeiro, escaneie a etiqueta.", "w": ["First", "scan", "the", "label"]}, {"t": "b", "pt": "Certifique-se de que o peso está certo.", "w": ["Make", "sure", "the", "weight", "is", "correct"]}]];
