englishA2Plans[223]={"title": "Reunião para planejar a festa de fim de ano", "file": "", "grammar": "Opinar em reunião: I think we should… / I agree / I'm not sure", "goal": "Dê sua opinião em uma reunião com I think we should…, I agree e I'm not sure.", "words": [["point of view", "ponto de vista"], ["proposal", "proposta"], ["committee", "comitê"], ["conclude", "concluir"], ["negotiate", "negociar"], ["come up with", "ter uma ideia, bolar"], ["option", "opção"], ["disagree", "discordar"]]};
englishA2Content[223]=[[["The office committee meets on Tuesday to plan the year-end party.", "O comitê do escritório se reúne na terça para planejar a festa de fim de ano."], ["Elena has a proposal: a picnic in the park instead of a dinner.", "Elena tem uma proposta: um piquenique no parque em vez de um jantar."], ["Kenji disagrees because the weather in December is cold.", "Kenji discorda porque o clima em dezembro é frio."], ["\"I think we should ask everyone,\" Priya says.", "\"Acho que devemos perguntar a todos\", diz Priya."], ["From her point of view, the second option is cheaper, and nobody can come up with a better idea.", "Do ponto de vista dela, a segunda opção é mais barata, e ninguém consegue bolar uma ideia melhor."], ["In the end, they conclude the picnic is best, and Elena will negotiate the price with the park.", "No fim, eles concluem que o piquenique é o melhor, e Elena vai negociar o preço com o parque."]], [["Okay, so what do you think about my proposal for the party?", "Então, o que você acha da minha proposta para a festa?"], ["Honestly, I'm not sure. A picnic in December could be very cold.", "Sinceramente, não tenho certeza. Um piquenique em dezembro pode ser muito frio."], ["True, but the restaurant option costs forty dollars per person.", "Verdade, mas a opção do restaurante custa quarenta dólares por pessoa."], ["Really? That's expensive. I think we should check the budget first.", "Sério? É caro. Acho que devemos conferir o orçamento primeiro."], ["Good idea. Can you come up with a third option by Friday?", "Boa ideia. Você consegue bolar uma terceira opção até sexta?"], ["Maybe an office lunch. From my point of view, it's simple and cheap.", "Talvez um almoço no escritório. Na minha opinião, é simples e barato."], ["I agree! Let's conclude the meeting now, and I'll negotiate with the caterer tomorrow.", "Concordo! Vamos encerrar a reunião agora, e amanhã eu negocio com o buffet."], ["Perfect. I'll write the notes and send them to the committee.", "Perfeito. Vou escrever as anotações e enviar ao comitê."]], ["/ɪ/ curto em think e picnic", "Faça um 'i' curto e relaxado, bem diferente do 'i' longo de feet. Em think e picnic a boca quase não se mexe.", ["think", "picnic"]], ["I think we ___ ask the manager.", "should", "should to", "Acho que devemos perguntar ao gerente.", "Depois de should vem o verbo direto, sem to."], [["Honestly, I'm not sure. A picnic in December could be very cold.", "Sinceramente, não tenho certeza. Um piquenique em dezembro pode ser muito frio."], ["Really? That's expensive. I think we should check the budget first.", "Sério? É caro. Acho que devemos conferir o orçamento primeiro."]], [{"t": "c", "q": "I think we ___ start earlier.", "o": ["should", "must to", "can to"], "pt": "Acho que devemos começar mais cedo.", "why": "Should é seguido do verbo sem to."}, {"t": "l", "say": "I'm not sure about the date.", "o": ["I'm not sure about the date.", "I'm not sure about the data.", "I'm not sure about that day."], "why": "Você ouviu date, a data, e não data, os dados."}, {"t": "b", "pt": "Eu concordo com você.", "w": ["I", "agree", "with", "you"]}, {"t": "b", "pt": "Acho que devemos perguntar a todos.", "w": ["I", "think", "we", "should", "ask", "everyone"]}]];
