englishA2Plans[224]={"title": "O relatório de vendas atrasado", "file": "", "grammar": "Prazos e atrasos: haven't finished yet / be late with", "goal": "Fale de prazos com haven't finished yet e be late with.", "words": [["behind schedule", "atrasado no cronograma"], ["be late with", "estar atrasado com"], ["extend", "prorrogar"], ["overtime", "hora extra"], ["ASAP", "o mais rápido possível"], ["turn in", "entregar"], ["submit", "enviar, submeter"], ["get back to", "retornar para alguém"]]};
englishA2Content[224]=[[["Mia is late with the sales report again.", "Mia está atrasada de novo com o relatório de vendas."], ["She hasn't finished it yet, and the boss wants it ASAP.", "Ela ainda não terminou, e o chefe quer o mais rápido possível."], ["The team is behind schedule because two people are sick.", "A equipe está atrasada no cronograma porque duas pessoas estão doentes."], ["Mia works overtime on Wednesday, and she hasn't eaten dinner yet.", "Mia faz hora extra na quarta e ainda não jantou."], ["On Thursday morning she asks the boss to extend the deadline until Friday.", "Na quinta de manhã ela pede ao chefe para prorrogar o prazo até sexta."], ["He says yes, so she can submit the report on Friday.", "Ele diz sim, então ela pode enviar o relatório na sexta."]], [["Mia, have you finished the sales report yet?", "Mia, você já terminou o relatório de vendas?"], ["Not yet. I'm sorry, I'm late with it again.", "Ainda não. Desculpe, estou atrasada com ele de novo."], ["The boss needs it ASAP. The client calls at four.", "O chefe precisa dele o mais rápido possível. O cliente liga às quatro."], ["I know. I haven't finished the last page yet because my computer froze.", "Eu sei. Ainda não terminei a última página porque meu computador travou."], ["Can you turn in the first part now? Then you can send the rest later.", "Você pode entregar a primeira parte agora? Aí manda o resto depois."], ["Good idea. I'll submit the charts in twenty minutes.", "Boa ideia. Vou enviar os gráficos em vinte minutos."], ["And ask the boss to extend the deadline if you need more time.", "E peça ao chefe para prorrogar o prazo se precisar de mais tempo."], ["I will. I'll get back to you before four, I promise.", "Vou pedir. Eu retorno para você antes das quatro, prometo."]], ["/h/ em hasn't e haven't", "Solte o ar da garganta, como quando você embaça um vidro, sem o 'r' do português. Em has e have o 'h' soa de leve.", ["hasn't", "haven't"]], ["I haven't finished the report ___.", "yet", "already", "Eu ainda não terminei o relatório.", "Em frases negativas, o 'ainda' do português vira yet."], [["She hasn't finished it yet, and the boss wants it ASAP.", "Ela ainda não terminou, e o chefe quer o mais rápido possível."], ["Not yet. I'm sorry, I'm late with it again.", "Ainda não. Desculpe, estou atrasada com ele de novo."]], [{"t": "c", "q": "She hasn't sent the e-mail ___.", "o": ["yet", "already", "ago"], "pt": "Ela ainda não enviou o e-mail.", "why": "Em frases negativas com have/has, usamos yet."}, {"t": "l", "say": "I'm late with the report again.", "o": ["I'm late with the report again.", "I was late with the report again.", "I'm late with the reports again."], "why": "Você ouviu o presente, I'm, e report no singular."}, {"t": "b", "pt": "Ainda não terminei o relatório.", "w": ["I", "haven't", "finished", "the", "report", "yet"]}, {"t": "b", "pt": "Estamos atrasados com o projeto.", "w": ["We're", "late", "with", "the", "project"]}]];
