englishA2Plans[225]={"title": "Um e-mail para um cliente novo", "file": "", "grammar": "E-mails simples: I'm writing to… / I attach… / formal e informal", "goal": "Escreva um e-mail curto com I'm writing to…, I attach… e um fecho adequado.", "words": [["attach", "anexar"], ["regards", "cumprimentos"], ["sincerely", "atenciosamente"], ["dear sir", "prezado senhor"], ["best wishes", "os melhores votos"], ["look forward to", "aguardar com expectativa"], ["subject", "assunto"], ["enclose", "incluir, enviar junto"], ["formal", "formal"]]};
englishA2Content[225]=[[["Priya writes an e-mail to a new client named Mr. Brown.", "Priya escreve um e-mail para um cliente novo, o Sr. Brown."], ["The subject is short: Price list for March.", "O assunto é curto: Lista de preços de março."], ["She starts with a formal line: Dear Sir, I'm writing to ask about your order.", "Ela começa com uma linha formal: Prezado senhor, escrevo para perguntar sobre o seu pedido."], ["Then she writes: I attach the price list, and I look forward to your answer.", "Depois escreve: Anexo a lista de preços e aguardo sua resposta."], ["She ends with Sincerely, and Kind regards would be okay, too.", "Ela termina com Atenciosamente, e Cordialmente também seria bom."], ["To her friend Lia, she writes a short note: Best wishes for the trip!", "Para a amiga Lia, ela escreve um bilhete curto: Os melhores votos para a viagem!"]], [["Priya, are you still writing that e-mail to Mr. Brown?", "Priya, você ainda está escrevendo aquele e-mail para o Sr. Brown?"], ["Yes. I'm writing to ask about his order, but I don't know how to start.", "Sim. Estou escrevendo para perguntar sobre o pedido dele, mas não sei como começar."], ["Use a formal opening. Write Dear Mr. Brown, not Hi.", "Use uma abertura formal. Escreva Prezado Sr. Brown, e não Oi."], ["Okay. Should I enclose the price list in the e-mail?", "Certo. Devo enviar a lista de preços junto no e-mail?"], ["In an e-mail you attach it. You enclose papers in a letter.", "No e-mail você anexa. Papéis você inclui numa carta."], ["Good to know. How do I end it? With Sincerely or Best wishes?", "Bom saber. Como termino? Com Atenciosamente ou Os melhores votos?"], ["Use Sincerely for Mr. Brown. Best wishes is for friends.", "Use Atenciosamente para o Sr. Brown. Os melhores votos é para amigos."], ["Perfect. Now I attach the list, and I'll write: I look forward to hearing from you.", "Perfeito. Agora anexo a lista e vou escrever: Aguardo seu retorno."]], ["/aɪ/ em writing e price", "Comece com 'a' aberto e termine num 'i' rápido, como em 'pai'. Em writing e price o som é o mesmo.", ["writing", "price"]], ["I'm writing ___ ask about the price.", "to", "for", "Estou escrevendo para perguntar sobre o preço.", "Para dar o motivo, usamos to + verbo, não for."], [["She starts with a formal line: Dear Sir, I'm writing to ask about your order.", "Ela começa com uma linha formal: Prezado senhor, escrevo para perguntar sobre o seu pedido."], ["Yes. I'm writing to ask about his order, but I don't know how to start.", "Sim. Estou escrevendo para perguntar sobre o pedido dele, mas não sei como começar."]], [{"t": "c", "q": "I look forward ___ your answer.", "o": ["to", "for", "at"], "pt": "Aguardo sua resposta.", "why": "A expressão fixa é look forward to."}, {"t": "l", "say": "I attach the price list.", "o": ["I attach the price list.", "I attached the price list.", "I attach the prize list."], "why": "Você ouviu o presente, attach, e price, o preço."}, {"t": "b", "pt": "Escrevo para perguntar sobre o pedido.", "w": ["I'm", "writing", "to", "ask", "about", "the", "order"]}, {"t": "b", "pt": "Anexo a lista de preços.", "w": ["I", "attach", "the", "price", "list"]}]];
