englishA2Plans[226]={"title": "Entrevista para barista na cafeteria", "file": "", "grammar": "Entrevista de emprego: experiência com present perfect e passado simples", "goal": "Fale de sua experiência com I've worked… para algo geral e I worked… para algo com data.", "words": [["hiring", "contratando"], ["applicant", "candidato"], ["qualified", "qualificado"], ["strengths", "pontos fortes"], ["weakness", "ponto fraco"], ["work experience", "experiência profissional"], ["team player", "pessoa que trabalha bem em equipe"], ["trainee", "estagiário, aprendiz"]]};
englishA2Content[226]=[[["The Blue Cup café is hiring a new barista, and ten applicants come on Saturday.", "A cafeteria Blue Cup está contratando um novo barista, e dez candidatos vêm no sábado."], ["Sam is nervous, but he's qualified for the job.", "Sam está nervoso, mas é qualificado para a vaga."], ["Sam tells the manager: I worked at a bakery from 2022 to 2024.", "Sam diz à gerente: Trabalhei numa padaria de 2022 a 2024."], ["He says he has made hundreds of sandwiches and has never been late.", "Ele diz que já fez centenas de sanduíches e nunca se atrasou."], ["His strengths are speed and a big smile, and his weakness is that he talks too much.", "Os pontos fortes dele são rapidez e um grande sorriso, e o ponto fraco é que fala demais."], ["The manager likes him because he's a team player, and she offers him a trainee position.", "A gerente gosta dele porque ele trabalha bem em equipe, e oferece a ele uma vaga de aprendiz."]], [["Thanks for coming, Sam. Tell me about your work experience.", "Obrigada por vir, Sam. Fale da sua experiência profissional."], ["I worked at a bakery for two years, and I've also worked as a waiter.", "Trabalhei numa padaria por dois anos e também já trabalhei como garçom."], ["Have you ever used an espresso machine?", "Você já usou uma máquina de espresso?"], ["Yes, I have. I've used one every day since last March.", "Já, sim. Uso uma todo dia desde março passado."], ["What are your strengths?", "Quais são seus pontos fortes?"], ["I'm fast, and I'm a team player. I've never missed a shift.", "Sou rápido e trabalho bem em equipe. Nunca faltei a um turno."], ["And what's your biggest weakness?", "E qual é seu maior ponto fraco?"], ["I sometimes talk too much with customers, but they usually enjoy it.", "Às vezes falo demais com os clientes, mas eles geralmente gostam."], ["Good. We're hiring one trainee, and the job starts Monday. Can you come at seven?", "Bom. Vamos contratar um aprendiz, e o trabalho começa na segunda. Você pode vir às sete?"], ["Yes, I can. Thank you so much!", "Posso, sim. Muito obrigado!"]], ["/w/ em worked e work", "Arredonde os lábios como para dizer 'u' e abra rápido, sem trocar por 'v'. Em work, o 'or' soa como um 'ér' curto.", ["worked", "work"]], ["I ___ at a bakery in 2023.", "worked", "have worked", "Eu trabalhei numa padaria em 2023.", "Com uma data no passado, como in 2023, usamos o passado simples."], [["I worked at a bakery for two years, and I've also worked as a waiter.", "Trabalhei numa padaria por dois anos e também já trabalhei como garçom."], ["Yes, I have. I've used one every day since last March.", "Já, sim. Uso uma todo dia desde março passado."]], [{"t": "c", "q": "I ___ never been late for work.", "o": ["have", "did", "was"], "pt": "Eu nunca me atrasei para o trabalho.", "why": "Com never e experiência até hoje usamos have + particípio."}, {"t": "l", "say": "I've used an espresso machine every day.", "o": ["I've used an espresso machine every day.", "I used an espresso machine every day.", "I've used an espresso machine yesterday."], "why": "Você ouviu I've used, present perfect."}, {"t": "b", "pt": "Eu trabalhei numa padaria por dois anos.", "w": ["I", "worked", "at", "a", "bakery", "for", "two", "years"]}, {"t": "b", "pt": "Eu já trabalhei como garçom.", "w": ["I've", "worked", "as", "a", "waiter"]}]];
