englishA2Plans[227]={"title": "Pedindo folga para o casamento da irmã", "file": "", "grammar": "Pedir folga: Can I take… off? / I'd like to…", "goal": "Peça uma folga com Can I take… off? e I'd like to…", "words": [["day off", "dia de folga"], ["sick leave", "licença médica"], ["take off", "tirar folga"], ["request", "pedido, solicitação"], ["approve", "aprovar"], ["substitute", "substituto"], ["swap shifts", "trocar de turno"], ["ask for", "pedir"]]};
englishA2Content[227]=[[["Omar's sister is getting married on Friday, May 9th.", "A irmã do Omar vai se casar na sexta, 9 de maio."], ["He wants a day off, so he writes a request for his boss.", "Ele quer um dia de folga, então escreve um pedido para a chefe."], ["It's hard because Rosa is on sick leave this month.", "É difícil porque a Rosa está de licença médica este mês."], ["Who will cover his work? Omar asks his friend Ben to be his substitute.", "Quem vai cobrir o trabalho dele? Omar pede ao amigo Ben para ser seu substituto."], ["Ben agrees if they swap shifts: Omar works Saturday instead.", "Ben aceita se trocarem de turno: Omar trabalha no sábado."], ["The boss approves the request, and Omar says thank you three times.", "A chefe aprova o pedido, e Omar agradece três vezes."]], [["Ms. Park, can I take Friday off? My sister's wedding is that day.", "Sra. Park, posso tirar sexta de folga? O casamento da minha irmã é nesse dia."], ["Friday the ninth? We're busy, and Rosa is on sick leave.", "Sexta, dia nove? Estamos ocupados, e a Rosa está de licença médica."], ["I know. I'd like to ask for just one day, and I'll find a substitute.", "Eu sei. Gostaria de pedir só um dia, e vou arrumar um substituto."], ["Do you have someone in mind?", "Você já tem alguém em mente?"], ["Yes, Ben. We can swap shifts: I'll work next Saturday for him.", "Tenho, o Ben. Podemos trocar de turno: eu trabalho no próximo sábado por ele."], ["That sounds fair. Please send me a written request today.", "Parece justo. Por favor, me envie um pedido por escrito hoje."], ["Of course. I'll write it right now.", "Claro. Vou escrever agora mesmo."], ["Okay, I approve it. Congratulations to your sister!", "Certo, eu aprovo. Parabéns à sua irmã!"]], ["/ʌ/ em substitute e just", "Faça um 'a' curto e relaxado, com a boca quase parada e sem arredondar os lábios. Em just e substitute é o mesmo som.", ["substitute", "just"]], ["Can I ___ Friday off?", "take", "make", "Posso tirar sexta de folga?", "Para folga usamos o verbo take: take a day off."], [["Ms. Park, can I take Friday off? My sister's wedding is that day.", "Sra. Park, posso tirar sexta de folga? O casamento da minha irmã é nesse dia."], ["I know. I'd like to ask for just one day, and I'll find a substitute.", "Eu sei. Gostaria de pedir só um dia, e vou arrumar um substituto."]], [{"t": "c", "q": "I'd like ___ take Monday off.", "o": ["to", "for", "that"], "pt": "Eu gostaria de tirar a segunda de folga.", "why": "I'd like é seguido de to + verbo."}, {"t": "l", "say": "Can I take Friday off?", "o": ["Can I take Friday off?", "Can I make Friday off?", "Can I take Sunday off?"], "why": "Você ouviu take e Friday."}, {"t": "b", "pt": "Posso tirar sexta de folga?", "w": ["Can", "I", "take", "Friday", "off"]}, {"t": "b", "pt": "Eu gostaria de pedir um dia de folga.", "w": ["I'd", "like", "to", "ask", "for", "a", "day", "off"]}]];
