englishA2Plans[228]={"title": "Falta de entregadores na pizzaria", "file": "", "grammar": "Resolver problemas em equipe: Why don't we…? / Let us…", "goal": "Proponha soluções com Why don't we…? e Let us…", "words": [["solution", "solução"], ["alternative", "alternativa"], ["brainstorm", "chuva de ideias"], ["deal with", "lidar com"], ["compromise", "acordo, meio-termo"], ["conflict", "conflito"], ["cooperate", "cooperar"], ["work together", "trabalhar juntos"], ["split up", "dividir"]]};
englishA2Content[228]=[[["At Rosa's Pizza, two drivers are sick, and twenty orders are waiting.", "Na Rosa's Pizza, dois entregadores estão doentes, e vinte pedidos estão esperando."], ["The team needs a solution fast, so Rosa calls a short brainstorm.", "A equipe precisa de uma solução rápida, então a Rosa chama uma breve chuva de ideias."], ["Tom says: \"Why don't we split up the orders by neighborhood?\"", "Tom diz: \"Por que não dividimos os pedidos por bairro?\""], ["Mia has a conflict: she can't deliver before six, so they find a compromise.", "Mia tem um conflito: não pode entregar antes das seis, então eles chegam a um acordo."], ["Everybody agrees to cooperate, and the whole team can work together until nine.", "Todos concordam em cooperar, e a equipe toda pode trabalhar junta até as nove."], ["The alternative is to close the kitchen, but now every pizza arrives hot.", "A alternativa seria fechar a cozinha, mas agora toda pizza chega quente."]], [["Tom, we have twenty orders and only two drivers. What can we do?", "Tom, temos vinte pedidos e só dois entregadores. O que podemos fazer?"], ["Why don't we ask the kitchen staff to help with the nearby orders?", "Por que não pedimos à equipe da cozinha para ajudar com os pedidos próximos?"], ["Good idea. I'll call everybody here and make a plan.", "Boa ideia. Vou chamar todo mundo aqui e fazer um plano."], ["Let us start with the orders for the north side. They're the farthest.", "Vamos começar pelos pedidos da zona norte. São os mais distantes."], ["Okay. Who can deal with the phone calls while we're out?", "Certo. Quem pode lidar com as ligações enquanto estamos fora?"], ["Mia can. Why don't we give her the new tablet?", "A Mia pode. Por que não damos a ela o tablet novo?"], ["Perfect. We'll meet at nine to count the money.", "Perfeito. Nos encontramos às nove para contar o dinheiro."], ["Sounds good. The customers won't wait long, so I'm leaving now.", "Combinado. Os clientes não vão esperar muito, então estou saindo agora."]], ["/ð/ em together e they", "Ponha a língua entre os dentes e faça vibrar, com som de voz. Não troque por 'd' ou 'z'.", ["together", "they"]], ["Why ___ we ask the team for help?", "don't", "not", "Por que não pedimos ajuda à equipe?", "Para sugerir, usamos Why don't we, nunca Why not we."], [["Tom says: \"Why don't we split up the orders by neighborhood?\"", "Tom diz: \"Por que não dividimos os pedidos por bairro?\""], ["Let us start with the orders for the north side. They're the farthest.", "Vamos começar pelos pedidos da zona norte. São os mais distantes."]], [{"t": "c", "q": "Why ___ we call the manager?", "o": ["don't", "aren't", "not"], "pt": "Por que não ligamos para o gerente?", "why": "A sugestão é Why don't we + verbo."}, {"t": "l", "say": "Let us start with the north side.", "o": ["Let us start with the north side.", "Let us start with the south side.", "Let us stop with the north side."], "why": "Você ouviu start e north."}, {"t": "b", "pt": "Por que não dividimos os pedidos?", "w": ["Why", "don't", "we", "split", "up", "the", "orders"]}, {"t": "b", "pt": "Vamos trabalhar juntos hoje.", "w": ["Let's", "work", "together", "today"]}]];
