englishA2Plans[229]={"title": "Primeira semana na loja de bicicletas", "file": "", "grammar": "Revisão: primeira semana no novo emprego (mini-história)", "goal": "Revise o vocabulário do trabalho contando como você se adapta a um emprego novo.", "words": [["break room", "sala de descanso"], ["name tag", "crachá"], ["lunch break", "intervalo de almoço"], ["settle in", "se adaptar"], ["fit in", "se enturmar"], ["get used to", "se acostumar com"], ["mentor", "mentor, mentora"], ["probation", "período de experiência"], ["benefit", "benefício"]]};
englishA2Content[229]=[[["On Monday, Kenji gets a name tag at the bike shop.", "Na segunda, Kenji recebe um crachá na loja de bicicletas."], ["The break room is small, but the coffee is good.", "A sala de descanso é pequena, mas o café é bom."], ["His mentor, Elena, shows him how to repair a flat tire.", "A mentora dele, Elena, mostra como consertar um pneu furado."], ["He needs time to get used to the noise.", "Ele precisa de tempo para se acostumar com o barulho."], ["At the lunch break, the other workers invite him to their table, and he starts to fit in.", "No intervalo de almoço, os outros funcionários o convidam para a mesa, e ele começa a se enturmar."], ["By Friday, he can settle in, and the boss says the probation period is going well.", "Na sexta, ele já se adapta, e o chefe diz que o período de experiência vai bem."]], [["Kenji, how is your first week going?", "Kenji, como está indo sua primeira semana?"], ["Pretty good. I'm still getting used to the noise, but everybody is nice.", "Bem. Ainda estou me acostumando com o barulho, mas todo mundo é legal."], ["Great. Have you talked to the boss about the probation period?", "Ótimo. Você já falou com o chefe sobre o período de experiência?"], ["Yes. He said it's three months, and then I'll get health benefits.", "Já. Ele disse que são três meses, e depois eu tenho benefícios de saúde."], ["That's right. And if you have a problem, you can always ask me. I'm your mentor, remember?", "Isso mesmo. E se tiver um problema, pode sempre me perguntar. Sou sua mentora, lembra?"], ["I will. Actually, I broke a tool on Wednesday, and I was afraid to tell you.", "Vou perguntar. Na verdade, quebrei uma ferramenta na quarta e tive medo de contar."], ["Don't worry. Everybody breaks something in the first week. Last year I broke three!", "Não se preocupe. Todo mundo quebra algo na primeira semana. Ano passado eu quebrei três!"], ["Really? Thanks, Elena. I feel better now, and I think I'm going to like this job.", "Sério? Obrigado, Elena. Me sinto melhor agora, e acho que vou gostar deste trabalho."]], ["/æ/ em tag e flat", "Abra a boca como para dizer 'a' e leve a língua um pouco para a frente, entre 'é' e 'a'. Em tag e flat o som é o mesmo.", ["tag", "flat"]], ["I'm not used ___ the noise yet.", "to", "for", "Eu ainda não estou acostumado com o barulho.", "Depois de used, a preposição certa é to."], [["He needs time to get used to the noise.", "Ele precisa de tempo para se acostumar com o barulho."], ["Pretty good. I'm still getting used to the noise, but everybody is nice.", "Bem. Ainda estou me acostumando com o barulho, mas todo mundo é legal."]], [{"t": "c", "q": "By Friday, I started to ___ in.", "o": ["settle", "sit", "stay"], "pt": "Na sexta, eu comecei a me adaptar.", "why": "A expressão fixa é settle in."}, {"t": "l", "say": "I'm still getting used to the noise.", "o": ["I'm still getting used to the noise.", "I'm still getting used to the news.", "I was still getting used to the noise."], "why": "Você ouviu noise, o barulho, e o presente I'm."}, {"t": "b", "pt": "Ele precisa de tempo para se acostumar.", "w": ["He", "needs", "time", "to", "get", "used", "to", "it"]}, {"t": "b", "pt": "Minha mentora me ajuda todo dia.", "w": ["My", "mentor", "helps", "me", "every", "day"]}]];
