englishA2MiniStories[229]=["A primeira semana da Lia", "Lia starts a full-time job at a small bike shop.~Lia começa um emprego de período integral numa pequena loja de bicicletas.|She is responsible for the customers, and her mentor is Tom.~Ela é responsável pelos clientes, e o mentor dela é o Tom.|On Monday the photocopy machine has a paper jam, so she asks, \"Could you give me a hand?\"~Na segunda a copiadora está com papel preso, então ela pergunta: \"Você poderia me dar uma mão?\"|Tom explains step by step: first open the door, next pull the paper, and make sure the page is clean.~Tom explica passo a passo: primeiro abra a porta, depois puxe o papel e certifique-se de que a página está limpa.|On Wednesday she is late with the weekly report because she hasn't finished the numbers yet.~Na quarta ela está atrasada com o relatório semanal porque ainda não terminou os números.|She writes to the boss: \"I'm writing to ask for more time, and I attach the first part.\"~Ela escreve ao chefe: \"Escrevo para pedir mais tempo e anexo a primeira parte.\"|At the meeting, she says, \"I think we should hire a second person,\" and everyone agrees.~Na reunião, ela diz: \"Acho que devemos contratar mais uma pessoa\", e todos concordam.|On Thursday she asks for Friday off to visit her family, and the boss approves it.~Na quinta ela pede folga na sexta para visitar a família, e o chefe aprova.|On Friday morning the shop is full, so the team works together and finds a compromise.~Na sexta de manhã a loja está cheia, então a equipe trabalha junta e chega a um acordo.|By the end of the week, Lia has settled in, and Tom says she fits in well.~No fim da semana, Lia já se adaptou, e o Tom diz que ela se enturmou bem."];
englishA2Plans[230]={"title": "Acordei com um resfriado", "file": "", "grammar": "Descrever sintomas: have, feel, hurt e how long", "goal": "Descreva seus sintomas e diga há quanto tempo você os sente.", "words": [["sore throat", "dor de garganta"], ["runny nose", "nariz escorrendo"], ["have a cold", "estar resfriado"], ["symptom", "sintoma"], ["sneezing", "espirrando"], ["aching", "doendo, dolorido"], ["feel sick", "sentir enjoo"], ["throw up", "vomitar"], ["earache", "dor de ouvido"]]};
englishA2Content[230]=[[["Ana woke up with a sore throat and a runny nose.", "Ana acordou com dor de garganta e nariz escorrendo."], ["She kept sneezing, and her whole body was aching.", "Ela não parava de espirrar, e o corpo todo estava doendo."], ["\"I have a cold,\" she said, and she stayed home.", "\"Estou resfriada\", disse ela, e ficou em casa."], ["She also has an earache in her left ear.", "Ela também está com dor de ouvido no ouvido esquerdo."], ["At noon she began to feel sick, but she didn't throw up.", "Ao meio-dia ela começou a sentir enjoo, mas não vomitou."], ["By night her only symptom was a runny nose, so she slept well.", "À noite, o único sintoma era o nariz escorrendo, então ela dormiu bem."]], [["Ben, you look terrible this morning. What's wrong?", "Ben, você está com uma cara péssima hoje. O que houve?"], ["I think I have a cold. I have a sore throat and a runny nose.", "Acho que estou resfriado. Estou com dor de garganta e nariz escorrendo."], ["Oh no. How long has your throat hurt?", "Poxa. Há quanto tempo sua garganta dói?"], ["Since Sunday night. I keep sneezing, and my body is aching.", "Desde domingo à noite. Não paro de espirrar, e meu corpo está doendo."], ["Do you have a fever, or any other symptom?", "Você está com febre ou tem algum outro sintoma?"], ["No fever, but I have an earache, and I feel sick when I eat.", "Sem febre, mas estou com dor de ouvido e sinto enjoo quando como."], ["Please don't throw up on my desk! Really, go home and rest.", "Por favor, não vomite na minha mesa! Sério, vá para casa descansar."], ["Ha! Don't worry. I'm going home at ten, and I'll call the doctor tomorrow.", "Ha! Não se preocupe. Vou para casa às dez e ligo para o médico amanhã."]], ["/θ/ em throat e think", "Coloque a ponta da língua entre os dentes e solte o ar, sem vibrar a voz. Não diga tróut nem fróut.", ["throat", "think"]], ["My throat has hurt ___ Sunday night.", "since", "for", "Minha garganta dói desde domingo à noite.", "Sunday night é um ponto no tempo, então usamos since; for é para períodos como two days."], [["Oh no. How long has your throat hurt?", "Poxa. Há quanto tempo sua garganta dói?"], ["Since Sunday night. I keep sneezing, and my body is aching.", "Desde domingo à noite. Não paro de espirrar, e meu corpo está doendo."]], [{"t": "c", "q": "How long ___ you felt sick?", "o": ["have", "do", "are"], "pt": "Há quanto tempo você está se sentindo mal?", "why": "Para perguntar há quanto tempo algo dura, usamos How long have you + particípio."}, {"t": "l", "say": "I have a runny nose and a sore throat.", "o": ["I have a runny nose and a sore throat.", "I had a runny nose and a sore throat.", "I have a runny nose and an earache."], "why": "A frase diz que agora você tem nariz escorrendo e dor de garganta."}, {"t": "b", "pt": "Minha garganta dói desde domingo.", "w": ["My", "throat", "has", "hurt", "since", "Sunday"]}, {"t": "b", "pt": "Estou com dor de ouvido desde ontem.", "w": ["I", "have", "had", "an", "earache", "since", "yesterday"]}]];
