englishA2Plans[231]={"title": "Torci o joelho no futebol", "file": "", "grammar": "Perguntas do médico e respostas com present perfect e for/since", "goal": "Responda às perguntas do médico sobre uma lesão usando for e since.", "words": [["injury", "lesão"], ["sprain", "torção"], ["limp", "mancar"], ["bandaged", "enfaixado"], ["allergic", "alérgico"], ["infection", "infecção"], ["recover", "se recuperar"], ["stiff", "rígido, duro"], ["pull a muscle", "distender um músculo"]]};
englishA2Content[231]=[[["Tom plays soccer every Saturday, but last week he got an injury.", "Tom joga futebol todo sábado, mas na semana passada ele se machucou."], ["He has had a limp since the game, and his knee has been stiff for four days.", "Ele manca desde o jogo, e o joelho está rígido há quatro dias."], ["The doctor says it's a sprain, not a broken bone.", "A médica diz que é uma torção, não um osso quebrado."], ["She has bandaged the knee and checked for infection.", "Ela enfaixou o joelho e verificou se havia infecção."], ["Tom has never been allergic to any medicine.", "Tom nunca foi alérgico a nenhum remédio."], ["He needs two weeks to recover, and he hasn't played since Saturday.", "Ele precisa de duas semanas para se recuperar e não joga desde sábado."]], [["Good morning, Tom. What happened? Did you pull a muscle?", "Bom dia, Tom. O que aconteceu? Você distendeu um músculo?"], ["I'm not sure. I fell during a game last Saturday, and I have had a limp since then.", "Não tenho certeza. Eu caí durante um jogo no sábado passado e manco desde então."], ["How long has your knee been stiff?", "Há quanto tempo seu joelho está rígido?"], ["For about four days. It hurts when I go down the stairs.", "Há uns quatro dias. Dói quando eu desço a escada."], ["Let me see. It's a sprain, and there's no infection. Are you allergic to any medicine?", "Deixe-me ver. É uma torção, e não há infecção. Você é alérgico a algum remédio?"], ["No, I've never been allergic to anything. How long will I need to recover?", "Não, nunca fui alérgico a nada. Quanto tempo vou levar para me recuperar?"], ["Probably two weeks. Keep it bandaged, and please don't play soccer yet.", "Provavelmente duas semanas. Mantenha enfaixado e, por favor, não jogue futebol ainda."], ["Okay, I'll stay home. I've already told my coach about the injury.", "Certo, vou ficar em casa. Já avisei meu treinador sobre a lesão."]], ["/ɪ/ curto em limp e infection", "Faça o i bem curto, com a boca relaxada, entre o i e o e do português. Limp não rima com o i longo de leap.", ["limp", "infection"]], ["How long ___ your knee been stiff?", "has", "is", "Há quanto tempo seu joelho está rígido?", "Para perguntar a duração até agora, usamos How long has + sujeito + particípio (been)."], [["How long has your knee been stiff?", "Há quanto tempo seu joelho está rígido?"], ["For about four days. It hurts when I go down the stairs.", "Há uns quatro dias. Dói quando eu desço a escada."]], [{"t": "c", "q": "I haven't played soccer ___ Saturday.", "o": ["since", "for", "ago"], "pt": "Não jogo futebol desde sábado.", "why": "Saturday é um ponto no tempo, então usamos since."}, {"t": "l", "say": "Tom has had a limp since Saturday.", "o": ["Tom has had a limp since Saturday.", "Tom has had a sprain since Saturday.", "Tom has had a limp since Sunday."], "why": "A frase diz que o limp (mancar) começou no sábado."}, {"t": "b", "pt": "Eu não sou alérgico a nenhum remédio.", "w": ["I'm", "not", "allergic", "to", "any", "medicine"]}, {"t": "b", "pt": "Há quanto tempo seu joelho está rígido?", "w": ["How", "long", "has", "your", "knee", "been", "stiff"]}]];
