englishA2Plans[233]={"title": "Os conselhos do Sr. Park", "file": "", "grammar": "Hábitos saudáveis: should / shouldn't e advérbios de frequência", "goal": "Dê conselhos de saúde com should e shouldn't e fale da frequência.", "words": [["unhealthy", "pouco saudável"], ["health", "saúde"], ["get enough sleep", "dormir o suficiente"], ["cut down on", "reduzir o consumo de"], ["smoking", "fumar, tabagismo"], ["stay in shape", "manter a forma"], ["energetic", "cheio de energia"], ["go for a walk", "dar uma caminhada"], ["lung", "pulmão"]]};
englishA2Content[233]=[[["Mr. Park is seventy, and he is very energetic.", "O Sr. Park tem setenta anos e é muito cheio de energia."], ["He stopped smoking ten years ago, and now his lungs are healthy.", "Ele parou de fumar há dez anos, e agora seus pulmões estão saudáveis."], ["Every morning he likes to go for a walk with his dog.", "Toda manhã ele gosta de dar uma caminhada com o cachorro."], ["He says, \"You should get enough sleep and never skip breakfast.\"", "Ele diz: \"Você deve dormir o suficiente e nunca pular o café da manhã.\""], ["\"You shouldn't eat unhealthy food every day,\" he tells young Omar.", "\"Você não deve comer comida pouco saudável todo dia\", ele diz ao jovem Omar."], ["Omar decides to cut down on soda to stay in shape.", "Omar decide reduzir o refrigerante para manter a forma."]], [["Mr. Park, you look so energetic. What's your secret?", "Sr. Park, o senhor parece tão cheio de energia. Qual é o segredo?"], ["No secret, Omar. I never miss my walk, and I sleep eight hours.", "Nenhum segredo, Omar. Nunca perco minha caminhada e durmo oito horas."], ["Really? I'm only twenty-five, and I'm always tired after work.", "Sério? Tenho só vinte e cinco anos e vivo cansado depois do trabalho."], ["You should go to bed earlier. And you shouldn't drink coffee after five.", "Você deveria dormir mais cedo. E não deveria tomar café depois das cinco."], ["I usually drink three cups a day. Is that unhealthy?", "Eu geralmente tomo três xícaras por dia. Isso é pouco saudável?"], ["A little. Your health will thank you if you drink less.", "Um pouco. Sua saúde vai agradecer se você tomar menos."], ["Okay. I also sit all day. How can I stay in shape?", "Certo. Eu também fico sentado o dia todo. Como posso manter a forma?"], ["Walk to work twice a week, and take the stairs. You can start today.", "Vá a pé para o trabalho duas vezes por semana e use a escada. Pode começar hoje."], ["Okay, I'll try. I'll walk on Tuesday and Thursday.", "Certo, vou tentar. Vou a pé na terça e na quinta."], ["Great. Come and tell me on Friday, and I'll make tea.", "Ótimo. Venha me contar na sexta, e eu faço chá."]], ["/ʃ/ em should e shape", "Arredonde os lábios e solte o ar com a língua afastada do céu da boca, como no chiado de quem pede silêncio. Em should, o L é mudo.", ["should", "shape"]], ["You ___ eat unhealthy food every day.", "shouldn't", "don't should", "Você não deve comer comida pouco saudável todo dia.", "Para dizer o que não é bom fazer, usamos shouldn't + verbo; don't should não existe."], [["You should go to bed earlier. And you shouldn't drink coffee after five.", "Você deveria dormir mais cedo. E não deveria tomar café depois das cinco."], ["\"You shouldn't eat unhealthy food every day,\" he tells young Omar.", "\"Você não deve comer comida pouco saudável todo dia\", ele diz ao jovem Omar."]], [{"t": "c", "q": "Mr. Park ___ misses his walk.", "o": ["never", "not", "no"], "pt": "O Sr. Park nunca perde sua caminhada.", "why": "Never é advérbio de frequência e vem antes do verbo; not e no não servem aqui."}, {"t": "l", "say": "You shouldn't drink coffee after five.", "o": ["You shouldn't drink coffee after five.", "You should drink coffee after five.", "You shouldn't drink tea after five."], "why": "A frase é um conselho negativo sobre café depois das cinco."}, {"t": "b", "pt": "Você deveria dormir mais cedo.", "w": ["You", "should", "go", "to", "bed", "earlier"]}, {"t": "b", "pt": "Eu geralmente tomo três xícaras por dia.", "w": ["I", "usually", "drink", "three", "cups", "a", "day"]}]];
