englishA2Plans[234]={"title": "Final do campeonato de vôlei", "file": "", "grammar": "Esportes e treino: comparativos e superlativos no esporte", "goal": "Compare jogadores e times usando -er than, more… than e the -est.", "words": [["league", "liga, campeonato"], ["champion", "campeão"], ["athletic", "atlético"], ["work out", "malhar, treinar"], ["warm up", "aquecer"], ["cool down", "desacelerar"], ["out of breath", "sem fôlego"], ["exercising", "se exercitando"], ["in a row", "seguidos"]]};
englishA2Content[234]=[[["Kenji's team plays in a local volleyball league.", "O time de Kenji joga em uma liga local de vôlei."], ["They work out three times a week, and they always warm up before a game.", "Eles treinam três vezes por semana e sempre se aquecem antes do jogo."], ["This year they are the champions, and they won five games in a row.", "Este ano eles são os campeões e ganharam cinco jogos seguidos."], ["Their rivals are taller, but Kenji's team is more athletic and faster.", "Os rivais são mais altos, mas o time de Kenji é mais atlético e mais rápido."], ["After the final game, everyone was out of breath.", "Depois do jogo final, todos estavam sem fôlego."], ["They sat down to cool down, and the coach said it was the best season ever.", "Eles se sentaram para desacelerar, e o treinador disse que foi a melhor temporada de todas."]], [["Congratulations, Kenji! You're the champions of the league!", "Parabéns, Kenji! Vocês são os campeões da liga!"], ["Thanks, Elena! I'm so tired. I'm still out of breath.", "Obrigado, Elena! Estou muito cansado. Ainda estou sem fôlego."], ["That was the longest game of the season. Your team looked more athletic than the other team.", "Foi o jogo mais longo da temporada. Seu time parecia mais atlético que o outro."], ["We've been exercising four days a week since March. It's much harder than last year.", "Estamos treinando quatro dias por semana desde março. É muito mais difícil que no ano passado."], ["Is that why you won five games in a row?", "É por isso que vocês ganharam cinco jogos seguidos?"], ["Yes. We always warm up for twenty minutes, and we cool down after each practice.", "Sim. Sempre nos aquecemos por vinte minutos e desaceleramos depois de cada treino."], ["Wow, I work out only once a week. Who is the fastest player on your team?", "Nossa, eu malho só uma vez por semana. Quem é o jogador mais rápido do seu time?"], ["Mia is the fastest, but Sam is the strongest. I'm the slowest!", "A Mia é a mais rápida, mas o Sam é o mais forte. Eu sou o mais lento!"], ["Maybe I should join your team. Can I come to practice on Tuesday?", "Talvez eu deva entrar no seu time. Posso ir ao treino na terça?"], ["Sure! We start at six. Bring water and good shoes.", "Claro! Começamos às seis. Traga água e um bom tênis."]], ["/w/ em work e won", "Arredonde os lábios como para dizer u curto e abra rápido para a vogal. Não troque por v: work não é vork.", ["work", "won"]], ["Mia is ___ player on our team.", "the fastest", "the most fast", "A Mia é a jogadora mais rápida do nosso time.", "Fast é curto, então o superlativo é the fastest; the most fast não existe."], [["Their rivals are taller, but Kenji's team is more athletic and faster.", "Os rivais são mais altos, mas o time de Kenji é mais atlético e mais rápido."], ["They sat down to cool down, and the coach said it was the best season ever.", "Eles se sentaram para desacelerar, e o treinador disse que foi a melhor temporada de todas."]], [{"t": "c", "q": "This game was ___ than the last one.", "o": ["harder", "more hard", "hardest"], "pt": "Este jogo foi mais difícil que o último.", "why": "Hard é curto, então o comparativo é harder + than."}, {"t": "l", "say": "We won five games in a row.", "o": ["We won five games in a row.", "We lost five games in a row.", "We won four games in a row."], "why": "A frase diz que o time ganhou cinco jogos seguidos."}, {"t": "b", "pt": "Eu sou o mais lento do time.", "w": ["I'm", "the", "slowest", "on", "the", "team"]}, {"t": "b", "pt": "Ela é mais atlética que eu.", "w": ["She", "is", "more", "athletic", "than", "me"]}]];
