englishA2Plans[235]={"title": "Trocando os lanches do escritório", "file": "", "grammar": "Dieta: much, many, a little, a few com comida", "goal": "Fale da sua dieta com much, many, a little e a few.", "words": [["lose weight", "emagrecer"], ["overweight", "acima do peso"], ["nutritious", "nutritivo"], ["hunger", "fome"], ["calories", "calorias"], ["sugary", "açucarado"], ["burn calories", "queimar calorias"], ["fewer", "menos (contáveis)"]]};
englishA2Content[235]=[[["Noah wants to lose weight because his doctor says he's a little overweight.", "Noah quer emagrecer porque o médico diz que ele está um pouco acima do peso."], ["He eats a lot of sugary snacks, and he doesn't drink much water.", "Ele come muitos lanches açucarados e não bebe muita água."], ["Now he eats fewer cookies, only a few a week.", "Agora ele come menos biscoitos, só alguns por semana."], ["His lunch is nutritious: some chicken, a little rice, and many vegetables.", "O almoço dele é nutritivo: um pouco de frango, um pouco de arroz e muitos legumes."], ["He counts calories, and he eats a small snack when hunger comes.", "Ele conta calorias e come um lanche pequeno quando a fome aparece."], ["After work he walks to burn calories, and he has lost two kilos.", "Depois do trabalho ele caminha para queimar calorias e já perdeu dois quilos."]], [["Ms. Cruz, I want to lose weight, but I get hungry all the time.", "Dra. Cruz, quero emagrecer, mas fico com fome o tempo todo."], ["Tell me what you eat. How many meals do you have a day?", "Conte o que você come. Quantas refeições você faz por dia?"], ["Three meals, but I eat many sugary snacks between them.", "Três refeições, mas como muitos lanches açucarados entre elas."], ["That's the problem. How much soda do you drink?", "Esse é o problema. Quanto refrigerante você bebe?"], ["Not much, just a little at lunch. About one can.", "Não muito, só um pouco no almoço. Cerca de uma lata."], ["Try water instead. And eat fewer cookies. Only a few a week.", "Experimente água. E coma menos biscoitos. Só alguns por semana."], ["Okay. Is it true that a nutritious breakfast helps with hunger?", "Certo. É verdade que um café da manhã nutritivo ajuda com a fome?"], ["Yes. Eat eggs and fruit. A little exercise helps too, so you can burn calories.", "Sim. Coma ovos e frutas. Um pouco de exercício também ajuda, e você queima calorias."], ["Great. I walk twice a week after work, and I'll walk three times now.", "Ótimo. Eu caminho duas vezes por semana depois do trabalho e vou caminhar três vezes agora."], ["Good. See you in a month, Noah, and we'll count the kilos.", "Bom. Nos vemos em um mês, Noah, e vamos contar os quilos."]], ["/ʌ/ em much e lunch", "Abra pouco a boca e deixe a língua relaxada, num som curto entre o a e o é do português. Não diga muche nem lonche com o fechado.", ["much", "lunch"]], ["How ___ cookies do you eat a week?", "many", "much", "Quantos biscoitos você come por semana?", "Cookies é contável, então usamos How many; much é para incontáveis."], [["Tell me what you eat. How many meals do you have a day?", "Conte o que você come. Quantas refeições você faz por dia?"], ["Try water instead. And eat fewer cookies. Only a few a week.", "Experimente água. E coma menos biscoitos. Só alguns por semana."]], [{"t": "c", "q": "I drink ___ water, only one glass.", "o": ["a little", "a few", "many"], "pt": "Eu bebo um pouco de água, só um copo.", "why": "Water é incontável, então usamos a little; a few é para contáveis."}, {"t": "l", "say": "I eat a few cookies a week.", "o": ["I eat a few cookies a week.", "I ate a few cookies a week.", "I eat a few cookies a day."], "why": "A frase está no presente e diz que são poucos biscoitos por semana."}, {"t": "b", "pt": "Quantos biscoitos você come por semana?", "w": ["How", "many", "cookies", "do", "you", "eat", "a", "week"]}, {"t": "b", "pt": "Eu não bebo muita água.", "w": ["I", "don't", "drink", "much", "water"]}]];
