englishA2Plans[236]={"title": "Noites sem sono antes do trabalho novo", "file": "", "grammar": "Dormir bem: used to, because e so", "goal": "Fale do sono e dos hábitos de antes com used to, because e so.", "words": [["fall asleep", "pegar no sono"], ["wake up", "acordar"], ["alarm clock", "despertador"], ["night owl", "coruja, pessoa noturna"], ["sleep in", "dormir até tarde"], ["toss and turn", "rolar na cama sem dormir"], ["lie down", "deitar"], ["stressed", "estressado"]]};
englishA2Content[236]=[[["Priya used to be a night owl, but now she has an early job.", "Priya era uma pessoa noturna, mas agora tem um trabalho cedo."], ["She is stressed, so she can't fall asleep before midnight.", "Ela está estressada, então não consegue pegar no sono antes da meia-noite."], ["When she tries to lie down, she can only toss and turn.", "Quando tenta se deitar, ela só rola na cama."], ["Her alarm clock rings at six, so she must wake up very early.", "O despertador toca às seis, então ela precisa acordar bem cedo."], ["She used to sleep in on weekends because she had no work.", "Ela costumava dormir até tarde nos fins de semana porque não trabalhava."], ["Now she puts her phone away at nine, and she sleeps better.", "Agora ela guarda o celular às nove e dorme melhor."]], [["I'm so tired. I didn't sleep well because I was stressed.", "Estou tão cansada. Não dormi bem porque estava estressada."], ["What happened? You used to fall asleep in five minutes.", "O que houve? Você costumava pegar no sono em cinco minutos."], ["Yes, but now I toss and turn all night, so I can't wake up in the morning.", "Sim, mas agora rolo na cama a noite toda, então não consigo acordar de manhã."], ["Is your alarm clock loud? You used to be a night owl, so early mornings are hard.", "Seu despertador é alto? Você era uma pessoa noturna, então manhãs cedo são difíceis."], ["I know. On weekends I used to sleep in until noon, but now I work on Saturdays.", "Eu sei. Nos fins de semana eu dormia até o meio-dia, mas agora trabalho aos sábados."], ["Poor you. Try this: put your phone away at nine, and lie down at ten.", "Coitada. Tente isto: guarde o celular às nove e deite às dez."], ["Okay. I always check my phone in bed because I like the news.", "Certo. Eu sempre olho o celular na cama porque gosto de ler as notícias."], ["That's why you can't sleep. Read a book instead. Do you want to try tonight?", "É por isso que você não dorme. Leia um livro. Quer tentar hoje à noite?"], ["Yes, I'll leave the phone in the kitchen tonight. Thanks, Elena!", "Sim, vou deixar o celular na cozinha hoje à noite. Obrigada, Elena!"], ["Deal. Call me tomorrow and tell me how you slept.", "Combinado. Me ligue amanhã e conte como dormiu."]], ["/aɪ/ em night e tired", "Comece com o a aberto e deslize para o i, num único movimento. Não pronuncie o gh de night, e não diga nigit.", ["night", "tired"]], ["Priya ___ sleep in on weekends.", "used to", "use to", "Priya costumava dormir até tarde nos fins de semana.", "Para hábitos do passado, usamos used to com d: used to + verbo."], [["Priya used to be a night owl, but now she has an early job.", "Priya era uma pessoa noturna, mas agora tem um trabalho cedo."], ["She used to sleep in on weekends because she had no work.", "Ela costumava dormir até tarde nos fins de semana porque não trabalhava."]], [{"t": "c", "q": "I was tired ___ I didn't sleep well.", "o": ["because", "so", "or"], "pt": "Eu estava cansada porque não dormi bem.", "why": "Because dá a razão (por que estava cansada); so dá o resultado."}, {"t": "l", "say": "I used to fall asleep in five minutes.", "o": ["I used to fall asleep in five minutes.", "I used to fall asleep in fifteen minutes.", "I used to wake up in five minutes."], "why": "A frase diz que antes você pegava no sono em cinco minutos."}, {"t": "b", "pt": "Eu costumava dormir até tarde aos sábados.", "w": ["I", "used", "to", "sleep", "in", "on", "Saturdays"]}, {"t": "b", "pt": "Estou cansada, então vou dormir cedo.", "w": ["I'm", "tired", "so", "I'm", "going", "to", "bed", "early"]}]];
