englishA2Plans[237]={"title": "Uma pausa na segunda-feira caótica", "file": "", "grammar": "Estresse e relaxamento: conselhos com you could / why not", "goal": "Dê ideias para relaxar com You could… e Why not…?", "words": [["tension", "tensão"], ["calm down", "se acalmar"], ["take a deep breath", "respirar fundo"], ["take a break", "fazer uma pausa"], ["meditate", "meditar"], ["meditation", "meditação"], ["let go", "deixar para lá"], ["heart rate", "batimento cardíaco"]]};
englishA2Content[237]=[[["Sam had a terrible Monday, and his shoulders were full of tension.", "Sam teve uma segunda-feira terrível, e os ombros estavam cheios de tensão."], ["His heart rate was fast because of the big deadline.", "Os batimentos estavam acelerados por causa do prazo importante."], ["His coworker Rosa told him to take a break and calm down.", "A colega Rosa disse a ele para fazer uma pausa e se acalmar."], ["Why not take a deep breath and count to ten?", "Por que não respirar fundo e contar até dez?"], ["Rosa likes to meditate, and she says meditation helps her let go of stress.", "Rosa gosta de meditar e diz que a meditação ajuda a deixar o estresse para lá."], ["Sam tried it for five minutes, and his heart rate slowed down.", "Sam tentou por cinco minutos, e os batimentos desaceleraram."]], [["Sam, you look stressed. Your shoulders are full of tension.", "Sam, você parece estressado. Seus ombros estão cheios de tensão."], ["I know. This deadline is killing me, and my heart rate feels so fast.", "Eu sei. Esse prazo está me matando, e meu coração parece muito acelerado."], ["You could take a break for ten minutes. Why not walk outside?", "Você poderia fazer uma pausa de dez minutos. Por que não caminhar lá fora?"], ["I can't. My boss needs the report by five o'clock.", "Não posso. Meu chefe precisa do relatório até as cinco."], ["Then why not take a deep breath and count to ten first? You need to calm down.", "Então por que não respirar fundo e contar até dez primeiro? Você precisa se acalmar."], ["Does that really work? I've never tried it.", "Isso funciona mesmo? Nunca tentei."], ["Yes! I meditate every morning for ten minutes. Meditation helps me let go of the stress.", "Sim! Eu medito toda manhã por dez minutos. A meditação me ajuda a deixar o estresse para lá."], ["Interesting. You could show me how after lunch.", "Interessante. Você poderia me mostrar como depois do almoço."], ["Sure. Meet me in the garden at one o'clock.", "Claro. Encontre-me no jardim à uma hora."], ["Okay, I'll be there. Thanks, Rosa!", "Certo, estarei lá. Obrigado, Rosa!"]], ["/iː/ longo em deep e meet", "Estique os lábios como num sorriso e alongue o som do i. Deep não é dip: o i longo muda a palavra.", ["deep", "meet"]], ["Why not ___ a break?", "take", "to take", "Por que não fazer uma pausa?", "Depois de Why not usamos o verbo no infinitivo sem to."], [["You could take a break for ten minutes. Why not walk outside?", "Você poderia fazer uma pausa de dez minutos. Por que não caminhar lá fora?"], ["Then why not take a deep breath and count to ten first? You need to calm down.", "Então por que não respirar fundo e contar até dez primeiro? Você precisa se acalmar."]], [{"t": "c", "q": "You ___ talk to your boss about the deadline.", "o": ["could", "could to", "coulds"], "pt": "Você poderia falar com seu chefe sobre o prazo.", "why": "Depois de could usamos o verbo sem to."}, {"t": "l", "say": "Why not take a deep breath?", "o": ["Why not take a deep breath?", "Why not take a deep bath?", "Why not take a long breath?"], "why": "A sugestão é respirar fundo (deep breath)."}, {"t": "b", "pt": "Por que não fazer uma pausa?", "w": ["Why", "not", "take", "a", "break"]}, {"t": "b", "pt": "Você poderia meditar dez minutos.", "w": ["You", "could", "meditate", "for", "ten", "minutes"]}]];
