englishA2Plans[238]={"title": "Primeiros socorros no piquenique", "file": "", "grammar": "Primeiros socorros: imperativos em sequência", "goal": "Dê instruções em ordem com First…, Then… e imperativos.", "words": [["first aid", "primeiros socorros"], ["bleeding", "sangramento"], ["wound", "ferimento"], ["apply pressure", "pressionar o local"], ["ice pack", "bolsa de gelo"], ["faint", "desmaiar"], ["bee sting", "picada de abelha"], ["painful", "doloroso"]]};
englishA2Content[238]=[[["At the picnic, Omar fell and cut his hand on a rock.", "No piquenique, Omar caiu e cortou a mão numa pedra."], ["The wound was bleeding a lot, and he felt like he could faint.", "O ferimento sangrava muito, e ele sentiu que podia desmaiar."], ["Lia knew first aid, so she stayed calm.", "Lia sabia primeiros socorros, então manteve a calma."], ["She washed the wound, and then she began to apply pressure with a clean towel.", "Ela lavou o ferimento e depois começou a pressionar com uma toalha limpa."], ["Lia also had a bee sting on her arm, and it was painful, so she used an ice pack.", "Lia também levou uma picada de abelha no braço, e era dolorosa, então usou uma bolsa de gelo."], ["After ten minutes the bleeding stopped, and they went to the clinic.", "Depois de dez minutos o sangramento parou, e eles foram à clínica."]], [["Omar, sit down! Your hand is bleeding a lot.", "Omar, sente-se! Sua mão está sangrando muito."], ["It's a deep wound, and it hurts. I feel like I'm going to faint.", "É um ferimento fundo, e dói. Sinto que vou desmaiar."], ["Lie down and put your feet up. Don't look at it. I know first aid.", "Deite e levante os pés. Não olhe para ele. Eu sei primeiros socorros."], ["Okay. Should I wash it first, or press on it?", "Certo. Devo lavar primeiro ou pressionar?"], ["First, wash the wound with clean water. Then apply pressure with this towel.", "Primeiro, lave o ferimento com água limpa. Depois pressione com esta toalha."], ["Like this? It's painful when I press.", "Assim? Dói quando eu aperto."], ["Yes, keep pressing for ten minutes. Don't take the towel off.", "Sim, continue apertando por dez minutos. Não tire a toalha."], ["Lia, you have a bee sting on your arm! Does it hurt?", "Lia, você tem uma picada de abelha no braço! Dói?"], ["A little, but I'm okay. Hold the towel, and I'll get the ice pack from my bag.", "Um pouco, mas estou bem. Segure a toalha, e eu pego a bolsa de gelo na minha bolsa."], ["Thanks, Lia. You really know first aid. I feel better already.", "Obrigado, Lia. Você sabe mesmo primeiros socorros. Já me sinto melhor."]], ["/eɪ/ em faint e painful", "Comece num e aberto e deslize para o i. Em faint, o som é de duas vogais seguidas, não fent.", ["faint", "painful"]], ["First, wash the wound. ___, apply pressure.", "Then", "Than", "Primeiro, lave o ferimento. Depois, pressione.", "Then marca o passo seguinte da sequência; than é só para comparar."], [["First, wash the wound with clean water. Then apply pressure with this towel.", "Primeiro, lave o ferimento com água limpa. Depois pressione com esta toalha."], ["Yes, keep pressing for ten minutes. Don't take the towel off.", "Sim, continue apertando por dez minutos. Não tire a toalha."]], [{"t": "c", "q": "Sit down and ___ look at the wound.", "o": ["don't", "doesn't", "not"], "pt": "Sente-se e não olhe para o ferimento.", "why": "O imperativo negativo usa don't + verbo."}, {"t": "l", "say": "Put the ice pack on your arm.", "o": ["Put the ice pack on your arm.", "Put the ice pack in your bag.", "Put the ice cream on your arm."], "why": "A instrução é pôr a bolsa de gelo no braço."}, {"t": "b", "pt": "Primeiro lave o ferimento com água.", "w": ["First", "wash", "the", "wound", "with", "water"]}, {"t": "b", "pt": "Aperte a toalha por dez minutos.", "w": ["Press", "the", "towel", "for", "ten", "minutes"]}]];
