englishA2Plans[239]={"title": "Preparando a corrida de domingo", "file": "", "grammar": "Revisão: uma semana de corrida e descanso", "goal": "Fale de treino, descanso e metas usando a revisão do bloco.", "words": [["rest day", "dia de descanso"], ["stay hydrated", "se manter hidratado"], ["keep an eye on", "ficar de olho em"], ["injure", "machucar"], ["recovery", "recuperação"], ["take it easy", "pegar leve"], ["personal best", "recorde pessoal"], ["finish line", "linha de chegada"], ["give up", "desistir"]]};
englishA2Content[239]=[[["Kenji has a 10K race on Sunday, so this week is important.", "Kenji tem uma corrida de 10 km no domingo, então esta semana é importante."], ["On Monday he ran five kilometers, and on Tuesday he took a rest day.", "Na segunda ele correu cinco quilômetros e, na terça, tirou um dia de descanso."], ["He drinks more water now because he wants to stay hydrated.", "Ele bebe mais água agora porque quer se manter hidratado."], ["His friend Lia tells him to keep an eye on his knee and take it easy on Friday.", "A amiga Lia diz para ele ficar de olho no joelho e pegar leve na sexta."], ["He doesn't want to injure himself before the race.", "Ele não quer se machucar antes da corrida."], ["His goal is a personal best, and he will not give up before the finish line.", "A meta dele é um recorde pessoal, e ele não vai desistir antes da linha de chegada."]], [["Kenji, how's your training going? Have you run every day this week?", "Kenji, como vai o treino? Você correu todo dia esta semana?"], ["No, I've only run three times. Yesterday was my rest day.", "Não, só corri três vezes. Ontem foi meu dia de descanso."], ["Good. You should keep an eye on your knee. You don't want to injure it again.", "Bom. Você deve ficar de olho no joelho. Não quer machucar de novo."], ["I know. It hasn't hurt since last month. Will my recovery be fast after the race?", "Eu sei. Não dói desde o mês passado. Minha recuperação será rápida depois da corrida?"], ["Probably. Drink a lot of water and stay hydrated, and don't run on Monday.", "Provavelmente. Beba muita água, fique hidratado e não corra na segunda."], ["I will. Tomorrow I'm going to take it easy and run just three kilometers.", "Vou beber. Amanhã vou pegar leve e correr só três quilômetros."], ["Good plan. What's your goal for Sunday? Do you want a personal best?", "Bom plano. Qual é sua meta para domingo? Quer um recorde pessoal?"], ["Yes! My best time is fifty-eight minutes. If I feel tired, I won't give up.", "Sim! Meu melhor tempo é cinquenta e oito minutos. Se eu me sentir cansado, não vou desistir."], ["I'll be at the finish line with a big sign!", "Vou estar na linha de chegada com um cartaz enorme!"], ["Great, see you there! Bring my water bottle, please.", "Ótimo, até lá! Leve minha garrafa de água, por favor."]], ["/f/ em finish e friend", "Encoste os dentes de cima no lábio de baixo e sopre. Não troque por p nem por h.", ["finish", "friend"]], ["Kenji hasn't run ___ Monday.", "since", "for", "Kenji não corre desde segunda.", "Monday é um ponto no tempo, então usamos since."], [["He drinks more water now because he wants to stay hydrated.", "Ele bebe mais água agora porque quer se manter hidratado."], ["He doesn't want to injure himself before the race.", "Ele não quer se machucar antes da corrida."]], [{"t": "c", "q": "I've been tired ___ Tuesday.", "o": ["since", "for", "ago"], "pt": "Estou cansado desde terça.", "why": "Tuesday é um ponto no tempo, então usamos since."}, {"t": "l", "say": "Don't give up before the finish line.", "o": ["Don't give up before the finish line.", "Don't give up after the finish line.", "Don't get up before the finish line."], "why": "A frase manda não desistir antes da linha de chegada."}, {"t": "b", "pt": "Eu quero um recorde pessoal.", "w": ["I", "want", "a", "personal", "best"]}, {"t": "b", "pt": "Hoje vou pegar leve.", "w": ["Today", "I'm", "going", "to", "take", "it", "easy"]}]];
englishA2PhotoThemes[239]="map";
englishA2MiniStories[239]=["A semana da corrida do Kenji", "Kenji wanted to run his first 10K, but on Monday he woke up with a sore throat.~Kenji queria correr seus primeiros 10 km, mas na segunda acordou com dor de garganta.|He took cough syrup twice a day, with food, and he got better in three days.~Ele tomou xarope duas vezes ao dia, com comida, e melhorou em três dias.|His doctor said, \"You should get enough sleep and cut down on sugary drinks.\"~O médico disse: \"Você deve dormir o suficiente e reduzir as bebidas açucaradas.\"|So he went to bed earlier, because he used to be a night owl.~Então ele foi dormir mais cedo, porque costumava ser uma pessoa noturna.|On Wednesday he worked out with his team, and he did not forget to warm up.~Na quarta ele treinou com o time e não esqueceu de se aquecer.|On Friday he felt stressed, so he took a deep breath and went for a walk.~Na sexta ele se sentiu estressado, então respirou fundo e foi caminhar.|On Saturday Lia cut her hand, and Kenji used first aid to stop the bleeding.~No sábado Lia cortou a mão, e Kenji usou primeiros socorros para parar o sangramento.|On Sunday it was hot, so he drank a lot of water and stayed hydrated.~No domingo estava quente, então ele bebeu muita água e se manteve hidratado.|The race was hard, and he was out of breath, but he didn't give up.~A corrida foi difícil, e ele ficou sem fôlego, mas não desistiu.|He crossed the finish line with a personal best, and Lia was there with a big sign.~Ele cruzou a linha de chegada com um recorde pessoal, e Lia estava lá com um cartaz enorme."];
englishA2Plans[240]={"title": "Tudo quebrou no apartamento da Ana", "file": "", "grammar": "Descrever problemas: it doesn’t work / it’s broken", "goal": "Diga o que está quebrado em casa usando doesn’t work e it’s broken.", "words": [["light bulb", "lâmpada"], ["burn out", "queimar (lâmpada)"], ["stop working", "parar de funcionar"], ["water heater", "aquecedor de água"], ["dripping", "pingando"], ["kitchen sink", "pia da cozinha"], ["fuse box", "caixa de fusíveis"], ["circuit breaker", "disjuntor"], ["wall socket", "tomada de parede"], ["make a noise", "fazer barulho"]]};
englishA2Content[240]=[[["Ana’s apartment has three problems this week.", "O apartamento da Ana tem três problemas esta semana."], ["The light bulb in the hall doesn’t work, and the water heater doesn’t make hot water.", "A lâmpada do corredor não funciona, e o aquecedor de água não esquenta a água."], ["The kitchen sink is dripping all night, and the old fridge likes to make a noise at two a.m.", "A pia da cozinha pinga a noite toda, e a geladeira velha gosta de fazer barulho às duas da manhã."], ["The wall socket by the window is dead, so her phone charger is useless there.", "A tomada de parede perto da janela está morta, então o carregador do celular é inútil ali."], ["She opens the fuse box and checks the circuit breaker, but everything looks fine.", "Ela abre a caixa de fusíveis e confere o disjuntor, mas tudo parece normal."], ["Now she’s afraid the oven will stop working too, so she’s calling the landlord.", "Agora ela tem medo de que o forno também pare de funcionar, então vai ligar para o proprietário."]], [["Ana, why is it so dark in the hall? Is the light bulb broken?", "Ana, por que está tão escuro no corredor? A lâmpada está queimada?"], ["Yes, it’s broken. The one in the kitchen is going to burn out soon, too.", "Sim, está queimada. A da cozinha também vai queimar logo."], ["Wow. What else is wrong in this place?", "Nossa. O que mais está errado neste lugar?"], ["The water heater doesn’t work. I took a cold shower this morning, and I almost cried.", "O aquecedor de água não funciona. Tomei banho frio hoje de manhã e quase chorei."], ["Oh no! Did you check the fuse box?", "Ai, não! Você olhou a caixa de fusíveis?"], ["Yes, I did. I turned the circuit breaker off and on, but nothing happened.", "Olhei sim. Desliguei e liguei o disjuntor, mas nada aconteceu."], ["And the sink? I can hear it dripping from here.", "E a pia? Dá para ouvir pingando daqui."], ["Yes, the kitchen sink. And the wall socket by my bed doesn’t work either.", "É, a pia da cozinha. E a tomada de parede perto da minha cama também não funciona."], ["OK. Tomorrow we’re calling the landlord together, right?", "Certo. Amanhã a gente liga para o proprietário junto, né?"], ["Yes, first thing in the morning. I’m tired of cold showers.", "Sim, logo de manhã. Estou cansada de banho frio."]], ["/w/ em water e wall", "Arredonde os lábios como para dizer 'u' antes de começar: 'uóter', 'uól'. Não troque o w por v.", ["water", "wall"]], ["The water heater ___ work.", "doesn’t", "don’t", "O aquecedor de água não funciona.", "Com he/she/it (the water heater), a negativa do presente é doesn’t."], [["The light bulb in the hall doesn’t work, and the water heater doesn’t make hot water.", "A lâmpada do corredor não funciona, e o aquecedor de água não esquenta a água."], ["The water heater doesn’t work. I took a cold shower this morning, and I almost cried.", "O aquecedor de água não funciona. Tomei banho frio hoje de manhã e quase chorei."]], [{"t": "c", "q": "The light bulb is ___, so the room is dark.", "o": ["broken", "break", "breaking"], "pt": "A lâmpada está quebrada, então o quarto está escuro.", "why": "Depois de is usamos o adjetivo broken (quebrado)."}, {"t": "l", "say": "The wall socket doesn’t work.", "o": ["The wall socket doesn’t work.", "The water socket doesn’t work.", "The wall socket does work."], "why": "Você ouviu wall socket e a negativa doesn’t work."}, {"t": "b", "pt": "A pia da cozinha está pingando.", "w": ["The", "kitchen", "sink", "is", "dripping"]}, {"t": "b", "pt": "O aquecedor de água não funciona.", "w": ["The", "water", "heater", "doesn’t", "work"]}]];
englishA2PhotoThemes[240]="city";
englishA2Plans[241]={"title": "Ligando para o zelador do prédio", "file": "", "grammar": "Pedir um conserto: Could you come and look at…?", "goal": "Peça a alguém para vir ver um problema usando Could you come and look at…?", "words": [["look at", "dar uma olhada em"], ["work order", "ordem de serviço"], ["maintenance man", "zelador, técnico de manutenção"], ["come over", "passar aqui, vir até aqui"], ["as soon as possible", "o mais rápido possível"], ["emergency repair", "reparo de emergência"], ["boiler", "caldeira, aquecedor"], ["front door", "porta da frente"], ["power outage", "queda de energia"]]};
englishA2Content[241]=[[["Priya lives on the fourth floor, and her boiler is making a strange sound.", "A Priya mora no quarto andar, e o aquecedor dela está fazendo um som estranho."], ["She calls the maintenance man and asks, “Could you come and look at it today?”", "Ela liga para o zelador e pergunta: “O senhor poderia vir dar uma olhada hoje?”"], ["He says he can come over after lunch if she fills out a work order online.", "Ele diz que pode passar lá depois do almoço se ela preencher uma ordem de serviço on-line."], ["Priya fills out the work order and writes, “Please come as soon as possible.”", "A Priya preenche a ordem de serviço e escreve: “Venha o mais rápido possível, por favor.”"], ["At three o’clock, someone knocks on the front door.", "Às três horas, alguém bate na porta da frente."], ["It’s Mr. Cole, and he finishes the emergency repair in twenty minutes.", "É o Sr. Cole, e ele termina o reparo de emergência em vinte minutos."]], [["Hello, Mr. Cole? This is Priya in apartment 4B. Could you come and look at my boiler?", "Alô, Sr. Cole? Aqui é a Priya do apartamento 4B. O senhor poderia vir dar uma olhada no meu aquecedor?"], ["Sure. What’s the problem, exactly?", "Claro. Qual é o problema, exatamente?"], ["It makes a loud noise, and the water is cold. After the power outage last night, nothing is the same.", "Faz um barulho alto, e a água está fria. Depois da queda de energia de ontem à noite, nada é igual."], ["I see. That sounds like an emergency repair. Did you send a work order?", "Entendi. Parece um reparo de emergência. Você mandou uma ordem de serviço?"], ["Not yet. Could I send it now, or should I call the office?", "Ainda não. Posso mandar agora ou devo ligar para o escritório?"], ["Send it online, and I’ll come over as soon as possible. Could you wait for me at the front door? The buzzer doesn’t work.", "Mande on-line, e eu passo aí o mais rápido possível. Poderia me esperar na porta da frente? A campainha não funciona."], ["Of course. Could you come before five? I have to leave for work at six.", "Claro. O senhor poderia vir antes das cinco? Preciso sair para o trabalho às seis."], ["No problem. I’ll be there at four-thirty.", "Sem problema. Estarei aí às quatro e meia."]], ["/k/ em could e come", "O k inicial leva um sopro de ar, como se você soprasse uma vela pequena. Em could, o l é mudo: diga 'cud'.", ["could", "come"]], ["___ you come and look at the heater?", "Could", "Do", "Você poderia vir dar uma olhada no aquecedor?", "Para pedir com educação usamos Could you + verbo; Do you come… muda o sentido."], [["She calls the maintenance man and asks, “Could you come and look at it today?”", "Ela liga para o zelador e pergunta: “O senhor poderia vir dar uma olhada hoje?”"], ["Hello, Mr. Cole? This is Priya in apartment 4B. Could you come and look at my boiler?", "Alô, Sr. Cole? Aqui é a Priya do apartamento 4B. O senhor poderia vir dar uma olhada no meu aquecedor?"]], [{"t": "c", "q": "Could you ___ over this afternoon?", "o": ["come", "to come", "coming"], "pt": "Você poderia passar aqui esta tarde?", "why": "Depois de Could you usamos o verbo simples: come."}, {"t": "l", "say": "Could you come and look at it today?", "o": ["Could you come and look at it today?", "Could you come and look at it Monday?", "Could you come and look at it tonight?"], "why": "A palavra final da frase é today."}, {"t": "b", "pt": "Você poderia vir dar uma olhada?", "w": ["Could", "you", "come", "and", "look", "at", "it"]}, {"t": "b", "pt": "Eu passo aí o mais rápido possível.", "w": ["I’ll", "come", "over", "as", "soon", "as", "possible"]}]];
englishA2PhotoThemes[241]="health";
englishA2Plans[242]={"title": "Usando a máquina de lavar do primo", "file": "", "grammar": "Instruções de uso: press, turn, plug in", "goal": "Explique como usar um aparelho com press, turn on / turn off e plug in.", "words": [["plug in", "ligar na tomada"], ["turn on", "ligar"], ["turn off", "desligar"], ["press the button", "apertar o botão"], ["remote control", "controle remoto"], ["washing machine", "máquina de lavar"], ["microwave oven", "forno de micro-ondas"], ["set the timer", "ajustar o timer"], ["hold down", "manter pressionado"], ["extension cord", "extensão elétrica"]]};
englishA2Content[242]=[[["Lia is staying at her cousin Omar’s apartment this weekend.", "A Lia está passando o fim de semana no apartamento do primo Omar."], ["Omar leaves a note: “Plug in the extension cord first, then turn on the washing machine.”", "O Omar deixa um bilhete: “Primeiro ligue a extensão na tomada, depois ligue a máquina de lavar.”"], ["The note also says: “Press the button twice and set the timer to forty minutes.”", "O bilhete também diz: “Aperte o botão duas vezes e ajuste o timer para quarenta minutos.”"], ["For the microwave oven, hold down the start key for two seconds.", "Para o micro-ondas, mantenha a tecla de início pressionada por dois segundos."], ["The TV remote control is on the sofa, and Lia must turn off the lights at night.", "O controle remoto da TV está no sofá, e a Lia precisa apagar as luzes à noite."], ["When she finishes, she writes, “Everything works, and the clothes are clean!”", "Quando termina, ela escreve: “Tudo funciona, e as roupas estão limpas!”"]], [["Hi, Lia. Did you find my note about the washing machine?", "Oi, Lia. Você achou meu bilhete sobre a máquina de lavar?"], ["Yes, but I’m confused. Do I plug in the cord first, or turn on the machine?", "Achei, mas estou confusa. Ligo o cabo na tomada primeiro ou ligo a máquina?"], ["Plug in the extension cord first. Then press the button with the little sun on it.", "Ligue a extensão primeiro. Depois aperte o botão com o solzinho."], ["OK, it’s on! Now what? There are twelve programs here.", "Pronto, ligou! E agora? Tem doze programas aqui."], ["Choose the third one, and set the timer to forty minutes.", "Escolha o terceiro e ajuste o timer para quarenta minutos."], ["Done. And how do I use your microwave oven? I want to heat some soup.", "Pronto. E como uso seu micro-ondas? Quero esquentar uma sopa."], ["Close the door, then hold down the start key for two seconds. Don’t press it quickly.", "Feche a porta e mantenha a tecla de início pressionada por dois segundos. Não aperte rápido."], ["It works! One more thing: where is the TV remote control? I can’t find it.", "Funcionou! Mais uma coisa: onde está o controle remoto da TV? Não consigo achar."], ["It’s always under the sofa pillow. You’ll find it there.", "Está sempre embaixo da almofada do sofá. Você vai achar lá."], ["Found it! Thanks, Omar. I’ll turn off the lights before bed.", "Achei! Obrigada, Omar. Vou apagar as luzes antes de dormir."]], ["/p/ em press e plug", "O p inicial pede um sopro de ar: ponha a mão na frente da boca e sinta o ar sair em press e plug.", ["press", "plug"]], ["First, ___ in the cord. Then press the button.", "plug", "plugs", "Primeiro, ligue o cabo na tomada. Depois aperte o botão.", "No imperativo usamos o verbo simples, sem -s: plug in."], [["The note also says: “Press the button twice and set the timer to forty minutes.”", "O bilhete também diz: “Aperte o botão duas vezes e ajuste o timer para quarenta minutos.”"], ["Plug in the extension cord first. Then press the button with the little sun on it.", "Ligue a extensão primeiro. Depois aperte o botão com o solzinho."]], [{"t": "c", "q": "Don’t ___ the button too hard.", "o": ["press", "pressing", "pressed"], "pt": "Não aperte o botão com muita força.", "why": "Depois de Don’t usamos o verbo simples: press."}, {"t": "l", "say": "Hold down the start key for two seconds.", "o": ["Hold down the start key for two seconds.", "Hold down the start key for two minutes.", "Hold on the start key for two seconds."], "why": "Você ouviu hold down e two seconds."}, {"t": "b", "pt": "Aperte o botão e ajuste o timer.", "w": ["Press", "the", "button", "and", "set", "the", "timer"]}, {"t": "b", "pt": "Desligue a luz quando sair.", "w": ["Turn", "off", "the", "lights", "when", "you", "leave"]}]];
englishA2PhotoThemes[242]="map";
englishA2Plans[243]={"title": "Pedindo um favor ao vizinho do lado", "file": "", "grammar": "Combinar com vizinhos: Could you…? / Would you mind…?", "goal": "Peça um favor a um vizinho com Could you…? e Would you mind + -ing?", "words": [["next door", "ao lado, na casa vizinha"], ["keep it down", "fazer menos barulho"], ["loud music", "música alta"], ["turn the music down", "abaixar a música"], ["knock on the door", "bater na porta"], ["quiet hours", "horário de silêncio"], ["water the plants", "regar as plantas"], ["while I’m away", "enquanto estou fora"], ["parking space", "vaga de estacionamento"], ["spare key", "chave reserva"]]};
englishA2Content[243]=[[["Sam lives next door to Elena, and they get along well.", "O Sam mora ao lado da Elena, e eles se dão bem."], ["On Friday night, there is loud music coming from Elena’s party.", "Na sexta à noite, há música alta vindo da festa da Elena."], ["At eleven, Sam decides to knock on the door and ask nicely.", "Às onze, o Sam resolve bater na porta e pedir com educação."], ["He asks her to keep it down because quiet hours start at ten.", "Ele pede que ela faça menos barulho porque o horário de silêncio começa às dez."], ["Elena is sorry, and she turns the music off at once.", "A Elena pede desculpas e desliga a música na hora."], ["A week later, Sam gives Elena his spare key so she can water the plants.", "Uma semana depois, o Sam dá a chave reserva à Elena para ela regar as plantas."]], [["Elena, would you mind if I borrowed your parking space tomorrow? My sister is visiting.", "Elena, você se importaria se eu usasse sua vaga amanhã? Minha irmã vem me visitar."], ["Not at all. Just move your car by six, please. I need it for work.", "Imagina. Só tire seu carro até as seis, por favor. Preciso dele para o trabalho."], ["Thanks! Also, please turn the music down tonight after ten. I have an early flight.", "Obrigado! E, por favor, abaixe a música hoje depois das dez. Tenho um voo cedo."], ["Sorry about last Friday! Next time, please knock on the door. I didn’t hear my phone.", "Desculpe pela sexta passada! Da próxima vez, bata na porta, por favor. Eu não ouvi o celular."], ["No problem. Actually, could you water the plants while I’m away? I’ll be in Denver for a week.", "Sem problema. Aliás, você poderia regar as plantas enquanto eu estiver fora? Vou ficar uma semana em Denver."], ["Sure. Would you mind leaving your spare key with me?", "Claro. Você se importaria de deixar sua chave reserva comigo?"], ["I’ll bring it tonight. Thanks so much, Elena!", "Trago hoje à noite. Muito obrigado, Elena!"], ["Anytime. And I promise, no more loud music after quiet hours!", "Quando precisar. E prometo, nada de música alta depois do horário de silêncio!"]], ["/aɪ/ em mind e quiet", "Mind rima com find: o ditongo 'ai' é longo. Em quiet, diga 'cuái-et', com duas sílabas.", ["mind", "quiet"]], ["Would you mind ___ the music down?", "turning", "turn", "Você se importaria de abaixar a música?", "Depois de Would you mind usamos o verbo com -ing: turning."], [["Elena, would you mind if I borrowed your parking space tomorrow? My sister is visiting.", "Elena, você se importaria se eu usasse sua vaga amanhã? Minha irmã vem me visitar."], ["No problem. Actually, could you water the plants while I’m away? I’ll be in Denver for a week.", "Sem problema. Aliás, você poderia regar as plantas enquanto eu estiver fora? Vou ficar uma semana em Denver."]], [{"t": "c", "q": "Could you ___ the plants while I’m away?", "o": ["water", "watering", "to water"], "pt": "Você poderia regar as plantas enquanto estou fora?", "why": "Depois de Could you usamos o verbo simples: water."}, {"t": "l", "say": "Would you mind keeping it down?", "o": ["Would you mind keeping it down?", "Would you mind keeping it up?", "Would you mind turning it up?"], "why": "O pedido é keeping it down, fazer menos barulho."}, {"t": "b", "pt": "Você se importaria de abaixar a música?", "w": ["Would", "you", "mind", "turning", "the", "music", "down"]}, {"t": "b", "pt": "Você poderia regar as plantas?", "w": ["Could", "you", "water", "the", "plants"]}]];
englishA2PhotoThemes[243]="map";
englishA2ExtraWordExamples[243]={"while I’m away": ["Please water the plants while I’m away.", "Por favor, regue as plantas enquanto eu estiver fora."]};
englishA2Plans[244]={"title": "Mudando os móveis da sala de lugar", "file": "", "grammar": "Posição dos móveis: next to / in front of / behind", "goal": "Diga onde colocar os móveis com next to, in front of, behind e against.", "words": [["move the sofa", "mover o sofá"], ["coffee table", "mesa de centro"], ["push aside", "empurrar para o lado"], ["against the wall", "encostado na parede"], ["rearrange", "reorganizar"], ["power strip", "régua de tomadas"], ["trash can", "lixeira"], ["dining table", "mesa de jantar"], ["TV stand", "rack da TV"], ["bed frame", "estrutura da cama"]]};
englishA2Content[244]=[[["Mia wants to rearrange her small living room this weekend.", "A Mia quer reorganizar a sala pequena dela neste fim de semana."], ["Tom helps her move the sofa against the wall, next to the window.", "O Tom ajuda a mover o sofá, encostado na parede, ao lado da janela."], ["They push aside the coffee table and put it in front of the sofa.", "Eles empurram a mesa de centro para o lado e a colocam na frente do sofá."], ["The TV stand goes in the corner, and the power strip goes behind it.", "O rack da TV vai para o canto, e a régua de tomadas fica atrás dele."], ["They put the trash can next to the dining table, and Mia laughs.", "Eles põem a lixeira ao lado da mesa de jantar, e a Mia ri."], ["Finally, they carry the bed frame to the other room, and the living room looks bigger.", "Por fim, levam a estrutura da cama para o outro quarto, e a sala parece maior."]], [["Tom, can you help me rearrange the living room? Nothing fits here.", "Tom, você pode me ajudar a reorganizar a sala? Nada cabe aqui."], ["Sure. Where do you want the sofa?", "Claro. Onde você quer o sofá?"], ["Put it against the wall, next to the window. Then the light is better.", "Coloque encostado na parede, ao lado da janela. Assim a luz fica melhor."], ["OK. Should I push aside the coffee table first?", "Certo. Devo empurrar a mesa de centro para o lado primeiro?"], ["Yes, please. Then it goes back in front of the sofa.", "Sim, por favor. Depois ela volta para a frente do sofá."], ["Done. And the TV stand? It’s too heavy for one person.", "Pronto. E o rack da TV? É pesado demais para uma pessoa."], ["Leave it in the corner. The power strip goes behind it, so nobody sees the cords.", "Deixe no canto. A régua de tomadas vai atrás, assim ninguém vê os fios."], ["Good idea. Where does the trash can go? Under the sink?", "Boa ideia. Onde vai a lixeira? Embaixo da pia?"], ["No, it’s too small there. Keep it in the kitchen.", "Não, lá é pequeno demais. Deixe na cozinha."], ["Great. Now the bed frame in the hall is blocking the door. Should we move it?", "Ótimo. Agora a estrutura da cama no corredor está bloqueando a porta. Vamos mover?"]], ["/b/ em behind e bed", "Feche os lábios e solte o b com voz. Em behind, o som final é 'ai': 'bi-RAINd', sem vogal extra depois do d.", ["behind", "bed"]], ["Put the coffee table ___ the sofa.", "in front of", "in front", "Ponha a mesa de centro na frente do sofá.", "Em português dizemos “na frente do”; em inglês precisamos de in front of, com of."], [["They push aside the coffee table and put it in front of the sofa.", "Eles empurram a mesa de centro para o lado e a colocam na frente do sofá."], ["Yes, please. Then it goes back in front of the sofa.", "Sim, por favor. Depois ela volta para a frente do sofá."]], [{"t": "c", "q": "The power strip is ___ the TV stand, so nobody sees it.", "o": ["behind", "in behind", "on behind"], "pt": "A régua de tomadas está atrás do rack da TV, então ninguém a vê.", "why": "Behind já significa “atrás de”, sem preposição extra."}, {"t": "l", "say": "Put it next to the window.", "o": ["Put it next to the window.", "Put it in front of the window.", "Put it behind the window."], "why": "Você ouviu next to, que é “ao lado de”."}, {"t": "b", "pt": "Coloque o sofá encostado na parede.", "w": ["Put", "the", "sofa", "against", "the", "wall"]}, {"t": "b", "pt": "A lixeira fica atrás da porta.", "w": ["The", "trash", "can", "goes", "behind", "the", "door"]}]];
englishA2PhotoThemes[244]="map";
englishA2Plans[245]={"title": "Dividindo a faxina com o colega de apartamento", "file": "", "grammar": "Rotina da casa: have to e don’t have to", "goal": "Fale das tarefas da casa com have to / has to e don’t have to.", "words": [["do the laundry", "lavar a roupa"], ["wash the dishes", "lavar a louça"], ["sweep the floor", "varrer o chão"], ["mop the floor", "passar pano no chão"], ["vacuum the carpet", "passar aspirador no tapete"], ["clean the bathroom", "limpar o banheiro"], ["cleaning supplies", "produtos de limpeza"], ["laundry basket", "cesto de roupa suja"], ["dust the shelves", "tirar o pó das prateleiras"], ["take out the trash", "levar o lixo para fora"]]};
englishA2Content[245]=[[["Rosa and Kenji share an apartment, and they have a chore chart on the fridge.", "A Rosa e o Kenji dividem um apartamento e têm uma tabela de tarefas na geladeira."], ["On Mondays, Rosa has to do the laundry and wash the dishes.", "Às segundas, a Rosa tem que lavar a roupa e a louça."], ["Kenji doesn’t have to cook, but he has to sweep the floor and mop the floor.", "O Kenji não precisa cozinhar, mas tem que varrer e passar pano no chão."], ["Every Saturday, someone has to vacuum the carpet and clean the bathroom.", "Todo sábado, alguém tem que passar aspirador no tapete e limpar o banheiro."], ["The cleaning supplies are under the sink, and the laundry basket is in the hall.", "Os produtos de limpeza ficam embaixo da pia, e o cesto de roupa suja fica no corredor."], ["Today Kenji has to dust the shelves and take out the trash, so he starts early.", "Hoje o Kenji tem que tirar o pó das prateleiras e levar o lixo para fora, então começa cedo."]], [["Kenji, do you remember the chart? It’s your week to clean the bathroom.", "Kenji, você lembra da tabela? Esta semana é sua vez de limpar o banheiro."], ["I know. Do I have to clean the shower too, or just the toilet?", "Eu sei. Eu tenho que limpar o chuveiro também ou só o vaso?"], ["You have to do everything. But you don’t have to dust the shelves today.", "Tem que fazer tudo. Mas você não precisa tirar o pó das prateleiras hoje."], ["Great. Where are the cleaning supplies? I can’t find them.", "Ótimo. Onde estão os produtos de limpeza? Não consigo achar."], ["They’re under the sink. The laundry basket is full, so I’ll do the laundry tonight.", "Estão embaixo da pia. O cesto de roupa suja está cheio, então vou lavar a roupa hoje à noite."], ["Thanks. I don’t work until noon tomorrow, so I can wash the dishes too.", "Obrigado. Só trabalho ao meio-dia amanhã, então posso lavar a louça também."], ["Really? Then I’ll sweep the floor, and you mop the floor.", "Sério? Então eu varro o chão, e você passa o pano."], ["Deal. We’ll even vacuum the carpet before the guests come.", "Combinado. Vamos até passar aspirador no tapete antes de os convidados chegarem."]], ["/ʃ/ em shelves e dishes", "O sh é como o 'ch' de 'chuva' dito com a boca arredondada, sem o t antes. Em dishes, o final é 'ish-iz'.", ["shelves", "dishes"]], ["Kenji ___ have to cook.", "doesn’t", "don’t", "O Kenji não precisa cozinhar.", "Com he/she/it, a negativa é doesn’t have to."], [["Kenji doesn’t have to cook, but he has to sweep the floor and mop the floor.", "O Kenji não precisa cozinhar, mas tem que varrer e passar pano no chão."], ["You have to do everything. But you don’t have to dust the shelves today.", "Tem que fazer tudo. Mas você não precisa tirar o pó das prateleiras hoje."]], [{"t": "c", "q": "Rosa ___ do the laundry on Mondays.", "o": ["has to", "have to", "having to"], "pt": "A Rosa tem que lavar a roupa às segundas.", "why": "Com Rosa (she) usamos has to."}, {"t": "l", "say": "You don’t have to take out the trash.", "o": ["You don’t have to take out the trash.", "You have to take out the trash.", "You didn’t have to take out the trash."], "why": "Você ouviu don’t have to, que quer dizer “não precisa”."}, {"t": "b", "pt": "Eu tenho que lavar a louça.", "w": ["I", "have", "to", "wash", "the", "dishes"]}, {"t": "b", "pt": "Você não precisa varrer o chão.", "w": ["You", "don’t", "have", "to", "sweep", "the", "floor"]}]];
englishA2PhotoThemes[245]="city";
englishA2Plans[246]={"title": "Dividindo as contas de casa", "file": "", "grammar": "Contas e serviços: pay, bill, due, included", "goal": "Fale de contas com bill, due, included e pay.", "words": [["electricity bill", "conta de luz"], ["water bill", "conta de água"], ["internet bill", "conta de internet"], ["due date", "data de vencimento"], ["pay online", "pagar pela internet"], ["bank transfer", "transferência bancária"], ["monthly rent", "aluguel mensal"], ["per month", "por mês"], ["included", "incluído"], ["pay the bill", "pagar a conta"]]};
englishA2Content[246]=[[["Noah and Lia split the monthly rent, which is nine hundred dollars.", "O Noah e a Lia dividem o aluguel mensal, que é de novecentos dólares."], ["Water is included in the rent, so they don’t get a water bill.", "A água está incluída no aluguel, então eles não recebem conta de água."], ["The electricity bill is about sixty dollars per month.", "A conta de luz é de cerca de sessenta dólares por mês."], ["The internet bill is due on the fifth, and they put the due date on the fridge.", "A conta de internet vence no dia cinco, e eles colocam a data de vencimento na geladeira."], ["Noah likes to pay online, but Lia prefers a bank transfer.", "O Noah gosta de pagar pela internet, mas a Lia prefere transferência bancária."], ["This month Lia forgets to pay the bill, and the internet stops on the sixth.", "Este mês a Lia esquece de pagar a conta, e a internet para no dia seis."]], [["Lia, the electricity bill came today. It’s seventy-two dollars this month.", "Lia, a conta de luz chegou hoje. São setenta e dois dólares este mês."], ["Seventy-two? That’s a lot! What’s the due date?", "Setenta e dois? É muito! Qual é o vencimento?"], ["The twelfth. I can pay online tonight if you send me your half.", "Dia doze. Posso pagar pela internet hoje à noite se você me mandar sua metade."], ["I’ll make a bank transfer right now. Is the water included in the rent?", "Vou fazer uma transferência agora mesmo. A água está incluída no aluguel?"], ["Yes, it is. But the internet isn’t included, and it’s forty dollars per month.", "Está sim. Mas a internet não está incluída, e custa quarenta dólares por mês."], ["OK. When is that one due? I don’t want to forget again.", "Certo. Quando vence essa? Não quero esquecer de novo."], ["On the fifth. Last time you forgot to pay the bill, and we had no wifi for two days.", "Dia cinco. Da última vez você esqueceu de pagar a conta, e ficamos dois dias sem wifi."], ["I know, I know! This time I’ll put a reminder on my phone. Promise.", "Eu sei, eu sei! Desta vez vou colocar um lembrete no celular. Prometo."]], ["/θ/ em month e monthly", "Ponha a ponta da língua entre os dentes e sopre, sem virar o som em 's' ou 'f'. Month termina com th: 'mânth'.", ["month", "monthly"]], ["Water is ___ in the rent.", "included", "include", "A água está incluída no aluguel.", "Depois de is usamos o particípio included, que significa “incluído”."], [["Water is included in the rent, so they don’t get a water bill.", "A água está incluída no aluguel, então eles não recebem conta de água."], ["Yes, it is. But the internet isn’t included, and it’s forty dollars per month.", "Está sim. Mas a internet não está incluída, e custa quarenta dólares por mês."]], [{"t": "c", "q": "When is the internet bill ___?", "o": ["due", "do", "dues"], "pt": "Quando vence a conta de internet?", "why": "Be due é “vencer, estar com vencimento”."}, {"t": "l", "say": "I will pay the bill online tonight.", "o": ["I will pay the bill online tonight.", "I will pay the bill online tomorrow.", "I will pay the bell online tonight."], "why": "Você ouviu tonight e bill."}, {"t": "b", "pt": "A conta de luz vence no dia doze.", "w": ["The", "electricity", "bill", "is", "due", "on", "the", "twelfth"]}, {"t": "b", "pt": "O aluguel mensal inclui a água.", "w": ["The", "monthly", "rent", "includes", "the", "water"]}]];
