englishA2Plans[247]={"title": "Regras do prédio para o novo morador", "file": "", "grammar": "Regras de convivência: must / mustn’t", "goal": "Fale de regras do prédio com must e mustn’t.", "words": [["house rules", "regras da casa"], ["no smoking", "proibido fumar"], ["no pets", "animais não permitidos"], ["recycling bin", "lixeira de reciclagem"], ["garbage day", "dia da coleta de lixo"], ["common area", "área comum"], ["fire exit", "saída de emergência"], ["lock the door", "trancar a porta"], ["fire alarm", "alarme de incêndio"], ["move out", "mudar-se, sair do imóvel"]]};
englishA2Content[247]=[[["Priya gets a paper with the house rules when she moves in.", "A Priya recebe um papel com as regras da casa quando se muda."], ["There is a no smoking sign in the common area, and the lease says no pets.", "Há uma placa de proibido fumar na área comum, e o contrato diz que não pode ter animais."], ["Residents must put glass and paper in the recycling bin on garbage day, which is Tuesday.", "Os moradores devem pôr vidro e papel na lixeira de reciclagem no dia da coleta, que é terça."], ["Everyone must lock the door at night, and you mustn’t block the fire exit with boxes.", "Todos devem trancar a porta à noite, e você não deve bloquear a saída de emergência com caixas."], ["If the fire alarm rings, everyone must leave the building at once.", "Se o alarme de incêndio tocar, todos devem sair do prédio imediatamente."], ["The last rule says you must tell the manager a month before you move out.", "A última regra diz que você deve avisar o síndico um mês antes de se mudar."]], [["Mr. Park, I read the house rules. Can I keep my sister’s cat for a week?", "Sr. Park, li as regras da casa. Posso ficar com o gato da minha irmã por uma semana?"], ["I’m sorry, but pets aren’t allowed. You mustn’t keep any animals here.", "Sinto muito, mas animais não são permitidos. Você não deve ter nenhum bicho aqui."], ["I understand. And where do I put the glass? The recycling bin is full.", "Entendi. E onde ponho o vidro? A lixeira de reciclagem está cheia."], ["Use the big one behind the building. Tuesday is garbage day.", "Use a grande atrás do prédio. A terça é o dia da coleta."], ["Got it. Also, my friend wants to smoke on the balcony. Is that OK?", "Entendi. Outra coisa: meu amigo quer fumar na varanda. Pode?"], ["No, you mustn’t smoke on the balcony. He can smoke on the street.", "Não, você não deve fumar na varanda. Ele pode fumar na rua."], ["Fine. And the front door? Should I lock it every time?", "Tudo bem. E a porta da frente? Devo trancar toda vez?"], ["Yes, every night. And remember, never leave boxes at the fire exit.", "Sim, toda noite. E lembre-se, nunca deixe caixas na saída de emergência."]], ["/ʌ/ em must e mustn’t", "O u de must soa como um 'â' curto, parecido com 'mas'. Em mustn’t, o t quase some: diga 'mâ-sent'.", ["must", "mustn’t"]], ["You ___ block the fire exit.", "mustn’t", "don’t have to", "Você não deve bloquear a saída de emergência.", "Mustn’t expressa proibição; don’t have to só diz que não é obrigatório."], [["Everyone must lock the door at night, and you mustn’t block the fire exit with boxes.", "Todos devem trancar a porta à noite, e você não deve bloquear a saída de emergência com caixas."], ["I’m sorry, but pets aren’t allowed. You mustn’t keep any animals here.", "Sinto muito, mas animais não são permitidos. Você não deve ter nenhum bicho aqui."]], [{"t": "c", "q": "Pets are not allowed. You ___ keep a cat here.", "o": ["mustn’t", "don’t have to", "doesn’t must"], "pt": "Animais não são permitidos. Você não deve ter um gato aqui.", "why": "Para proibição usamos mustn’t."}, {"t": "l", "say": "Everyone must leave when the fire alarm rings.", "o": ["Everyone must leave when the fire alarm rings.", "Everyone mustn’t leave when the fire alarm rings.", "Everyone can leave when the fire alarm rings."], "why": "Você ouviu must leave, uma obrigação."}, {"t": "b", "pt": "Você deve trancar a porta à noite.", "w": ["You", "must", "lock", "the", "door", "at", "night"]}, {"t": "b", "pt": "Você não deve fumar na área comum.", "w": ["You", "mustn’t", "smoke", "in", "the", "common", "area"]}]];
