englishA2Plans[248]={"title": "Pedindo orçamento para reformar a cozinha", "file": "", "grammar": "Orçamento de reforma: How much…? / How long…?", "goal": "Pergunte preço e prazo de uma obra com How much…? e How long…?", "words": [["renovation", "reforma"], ["repaint", "pintar de novo"], ["new tiles", "azulejos novos"], ["labor", "mão de obra"], ["materials", "materiais"], ["total cost", "custo total"], ["estimate", "estimativa de preço"], ["quote", "orçamento"], ["contractor", "empreiteiro"], ["free estimate", "orçamento grátis"]]};
englishA2Content[248]=[[["Ben wants a small renovation in his kitchen, so he calls a contractor.", "O Ben quer uma pequena reforma na cozinha, então liga para um empreiteiro."], ["The contractor gives him a free estimate and visits the apartment on Saturday.", "O empreiteiro faz um orçamento grátis e visita o apartamento no sábado."], ["The plan is to repaint the walls and put in new tiles near the stove.", "O plano é pintar as paredes de novo e colocar azulejos novos perto do fogão."], ["The estimate has two parts: materials cost six hundred dollars, and labor costs nine hundred.", "A estimativa tem duas partes: os materiais custam seiscentos dólares, e a mão de obra custa novecentos."], ["Ben asks for a second quote from another company to compare the total cost.", "O Ben pede um segundo orçamento a outra empresa para comparar o custo total."], ["The second quote is cheaper, but the work takes three weeks instead of two.", "O segundo orçamento é mais barato, mas a obra leva três semanas em vez de duas."]], [["Thanks for coming, Mr. Hale. How much does it cost to repaint the kitchen?", "Obrigado por vir, Sr. Hale. Quanto custa pintar a cozinha de novo?"], ["It depends. Do you want new tiles too, or only paint?", "Depende. Você quer azulejos novos também, ou só tinta?"], ["Both, I think. What do the tiles cost?", "Os dois, acho. Quanto custam os azulejos?"], ["About five dollars per square foot. You need around eighty feet, so that’s four hundred.", "Cerca de cinco dólares por pé quadrado. Você precisa de uns oitenta pés, então são quatrocentos."], ["OK. And how long does the whole job take?", "Certo. E quanto tempo leva o serviço todo?"], ["Two weeks, if the materials arrive on time. I only work with a small team.", "Duas semanas, se os materiais chegarem no prazo. Trabalho só com uma equipe pequena."], ["Two weeks is fine. Can I have the total price in writing?", "Duas semanas está bom. Posso ter o preço total por escrito?"], ["Sure. I’ll send a quote tonight. The labor is nine hundred dollars.", "Claro. Mando um orçamento hoje à noite. A mão de obra são novecentos dólares."], ["Great. And how much is the deposit before you start?", "Ótimo. E quanto é o sinal antes de você começar?"], ["Twenty percent. Then we have a deal, and we start on June third.", "Vinte por cento. Então temos um acordo, e começamos no dia três de junho."]], ["/r/ em renovation e repaint", "O r inglês é suave: a língua se enrola para trás sem tocar o céu da boca e sem vibrar. Não diga 'rr' como em 'rato'.", ["renovation", "repaint"]], ["How ___ does the whole renovation take?", "long", "much", "Quanto tempo leva a reforma toda?", "How long pergunta pela duração; how much pergunta pelo preço."], [["OK. And how long does the whole job take?", "Certo. E quanto tempo leva o serviço todo?"], ["Great. And how much is the deposit before you start?", "Ótimo. E quanto é o sinal antes de você começar?"]], [{"t": "c", "q": "How ___ is the total cost?", "o": ["much", "long", "many"], "pt": "Quanto é o custo total?", "why": "Para preço usamos How much."}, {"t": "l", "say": "How long does the work take?", "o": ["How long does the work take?", "How much does the work cost?", "How far does the work take?"], "why": "Você ouviu How long, que pergunta pela duração."}, {"t": "b", "pt": "Quanto é o custo total?", "w": ["How", "much", "is", "the", "total", "cost"]}, {"t": "b", "pt": "Quanto tempo leva o serviço?", "w": ["How", "long", "does", "the", "job", "take"]}]];
