englishA2Plans[249]={"title": "A casa nova depois do conserto", "file": "", "grammar": "Revisão: a casa nova depois do conserto", "goal": "Revise problemas, pedidos, regras e prazos de uma casa em reforma.", "words": [["remodel", "reformar"], ["start date", "data de início"], ["finish by", "terminar até"], ["rough price", "preço aproximado"], ["smoke detector", "detector de fumaça"], ["trash bag", "saco de lixo"], ["fresh paint", "tinta fresca"], ["new curtains", "cortinas novas"], ["welcome mat", "capacho"], ["housewarming party", "festa de inauguração da casa"]]};
englishA2Content[249]=[[["Rosa and Sam decide to remodel the little house they bought in March.", "A Rosa e o Sam decidem reformar a casinha que compraram em março."], ["The contractor gives a rough price and a start date of April first.", "O empreiteiro dá um preço aproximado e uma data de início de primeiro de abril."], ["He promises to finish by the end of May, and he does.", "Ele promete terminar até o fim de maio, e termina."], ["The house smells like fresh paint, and the new curtains look great.", "A casa cheira a tinta fresca, e as cortinas novas ficam ótimas."], ["Sam installs a smoke detector in the hall and fills one more trash bag with old boxes.", "O Sam instala um detector de fumaça no corredor e enche mais um saco de lixo com caixas velhas."], ["On Saturday, they put a welcome mat at the door and plan a housewarming party.", "No sábado, eles põem um capacho na porta e planejam uma festa de inauguração."]], [["Sam, the whole house smells like fresh paint! I love it.", "Sam, a casa inteira cheira a tinta fresca! Adorei."], ["Me too. Mr. Hale finished two days before the date we agreed.", "Eu também. O Sr. Hale terminou dois dias antes da data combinada."], ["Remember the rough price he gave us in March? We paid almost exactly that.", "Lembra do preço aproximado que ele deu em março? Pagamos quase exatamente isso."], ["Yes! And did you see the new curtains? They’re in the kitchen now.", "Sim! E você viu as cortinas novas? Já estão na cozinha."], ["They look great. Could you put this trash bag outside, please? It’s full of old paper.", "Ficaram ótimas. Você poderia pôr este saco de lixo lá fora, por favor? Está cheio de papel velho."], ["Sure. I’ll also test the smoke detector in the hall. It beeped twice yesterday.", "Claro. Também vou testar o detector de fumaça do corredor. Ele apitou duas vezes ontem."], ["Good idea. Where’s the welcome mat? Our guests come at six.", "Boa ideia. Onde está o capacho? Os convidados chegam às seis."], ["It’s in front of the door, and everything is ready. Let’s enjoy it!", "Está na frente da porta, e tudo está pronto. Vamos aproveitar!"]], ["/h/ em house e housewarming", "O h inglês é um sopro leve, como se você embaçasse um vidro. Não o engula nem faça um 'rr' forte.", ["house", "housewarming"]], ["The welcome mat is ___ the front door.", "in front of", "in front", "O capacho está na frente da porta da frente.", "Em inglês, “na frente de” é in front of, com of."], [["The house smells like fresh paint, and the new curtains look great.", "A casa cheira a tinta fresca, e as cortinas novas ficam ótimas."], ["Yes! And did you see the new curtains? They’re in the kitchen now.", "Sim! E você viu as cortinas novas? Já estão na cozinha."]], [{"t": "c", "q": "Rosa ___ have to cook; they ordered pizza.", "o": ["doesn’t", "don’t", "hasn’t"], "pt": "A Rosa não precisa cozinhar; eles pediram pizza.", "why": "Com Rosa (she), a negativa de have to é doesn’t have to."}, {"t": "l", "say": "The smoke detector doesn’t work.", "o": ["The smoke detector doesn’t work.", "The smoke detector does work.", "The smoke detector doesn’t ring."], "why": "Você ouviu doesn’t work, ou seja, não funciona."}, {"t": "b", "pt": "Eles vão fazer uma festa de inauguração.", "w": ["They", "are", "having", "a", "housewarming", "party"]}, {"t": "b", "pt": "Você não deve fumar dentro da casa.", "w": ["You", "mustn’t", "smoke", "in", "the", "house"]}]];
englishA2PhotoThemes[249]="map";
englishA2MiniStories[249]=["A casa nova da Rosa", "Rosa and Sam bought an old house, but the water heater didn’t work.~A Rosa e o Sam compraram uma casa velha, mas o aquecedor de água não funcionava.|Rosa asked a contractor, “Could you come and look at the house today?”~A Rosa perguntou a um empreiteiro: “O senhor poderia vir dar uma olhada na casa hoje?”|Sam asked, “How much is the renovation, and how long does it take?”~O Sam perguntou: “Quanto custa a reforma, e quanto tempo leva?”|The contractor said, “Four thousand dollars, and the work takes six weeks.”~O empreiteiro disse: “Quatro mil dólares, e a obra leva seis semanas.”|The neighbors next door said, “Would you mind keeping the noise down after six?”~Os vizinhos do lado disseram: “Vocês se importariam de fazer menos barulho depois das seis?”|Rosa and Sam had to move the sofa and put the boxes behind the door every night.~A Rosa e o Sam tinham que mover o sofá e pôr as caixas atrás da porta toda noite.|They paid the electricity bill on the due date, and nothing was broken anymore.~Eles pagaram a conta de luz no vencimento, e nada mais estava quebrado.|At the end, the walls had fresh paint, and the new rule was: you mustn’t wear shoes inside.~No fim, as paredes tinham tinta fresca, e a nova regra era: não se deve usar sapatos dentro de casa.|Sam put a welcome mat at the front door, and Rosa hung new curtains.~O Sam pôs um capacho na porta da frente, e a Rosa pendurou cortinas novas.|Everyone came to the housewarming party, and the little house finally felt like home.~Todos vieram à festa de inauguração, e a casinha finalmente parecia um lar."];
englishA2Plans[250]={"title": "Perguntando o preço dos tênis na loja", "file": "", "grammar": "Pedir preço e desconto: How much is/are…? / Is there a discount?", "goal": "Pergunte o preço com How much is…? e peça desconto com Is there a discount?", "words": [["price tag", "etiqueta de preço"], ["pricey", "caro (informal)"], ["affordable", "acessível"], ["cash register", "caixa registradora"], ["bargain hunter", "caçador de pechinchas"], ["overpriced", "caro demais"], ["spare change", "trocado"], ["store credit", "crédito na loja"], ["gift card", "vale-presente"]]};
englishA2Content[250]=[[["Ana sees a pair of red sneakers in the window.", "Ana vê um par de tênis vermelhos na vitrine."], ["The price tag says $89, and that is pricey for her.", "A etiqueta diz US$ 89, e isso é caro para ela."], ["She is a bargain hunter, so she asks, \"Is there a discount?\"", "Ela é caçadora de pechinchas, então pergunta: \"Tem desconto?\""], ["The clerk says the sneakers are 20 percent off today.", "O vendedor diz que os tênis estão com 20 por cento de desconto hoje."], ["At the cash register, she pays $71.20 and smiles.", "No caixa, ela paga US$ 71,20 e sorri."], ["Now the shoes are affordable, and she wears them home.", "Agora os tênis estão acessíveis, e ela volta para casa com eles."]], [["Excuse me, how much are these boots? I can't find the price tag.", "Com licença, quanto custam estas botas? Não acho a etiqueta de preço."], ["They're $120. Do you have a gift card or store credit?", "Custam US$ 120. Você tem um vale-presente ou crédito na loja?"], ["I have a gift card for $50. Is there a discount on boots today?", "Tenho um vale-presente de US$ 50. Tem desconto em botas hoje?"], ["Yes! Everything in this aisle is 15 percent off until six.", "Tem! Tudo neste corredor está com 15 por cento de desconto até as seis."], ["Really? That's good, because $120 is overpriced for boots.", "Sério? Que bom, porque US$ 120 é caro demais para botas."], ["These are leather, so they aren't cheap. This other pair is cheaper.", "Estas são de couro, então não são baratas. Este outro par é mais barato."], ["How much is the other pair with the discount?", "Quanto custa o outro par com o desconto?"], ["It's $68. After your gift card, you only pay $18.", "Custa US$ 68. Depois do vale-presente, você paga só US$ 18."], ["Great! I even have spare change in my pocket.", "Ótimo! Eu até tenho trocado no bolso."], ["Perfect. Please come to the register, and I'll wrap them.", "Perfeito. Venha ao caixa, e eu embrulho."]], ["/p/ em price e pricey", "O /p/ inglês sai com um sopro de ar: segure um papel na frente da boca e ele deve mexer. Não troque por /b/.", ["price", "pricey"]], ["___ there a discount on this lamp?", "Is", "Are", "Tem desconto nesta luminária?", "Com um item no singular (a discount), a pergunta usa Is there."], [["She is a bargain hunter, so she asks, \"Is there a discount?\"", "Ela é caçadora de pechinchas, então pergunta: \"Tem desconto?\""], ["I have a gift card for $50. Is there a discount on boots today?", "Tenho um vale-presente de US$ 50. Tem desconto em botas hoje?"]], [{"t": "c", "q": "___ are these boots? They're $120.", "o": ["How much", "How many", "How far"], "pt": "Quanto custam estas botas? Custam US$ 120.", "why": "Para perguntar o preço, usamos How much."}, {"t": "l", "say": "Is there a discount on boots today?", "o": ["Is there a discount on boots today?", "Is there a discount on boots tomorrow?", "Are there discounts on shoes today?"], "why": "Você ouviu discount, boots e today."}, {"t": "b", "pt": "Quanto custa este casaco?", "w": ["How", "much", "is", "this", "coat"]}, {"t": "b", "pt": "Tem desconto hoje?", "w": ["Is", "there", "a", "discount", "today"]}]];
