englishA2Plans[252]={"title": "Comprando uma luminária pela internet", "file": "", "grammar": "Comprar online: add to cart, checkout page, delivery, tracking number", "goal": "Siga os passos de uma compra online e fale de código de desconto e entrega.", "words": [["shopping cart", "carrinho de compras"], ["add to cart", "adicionar ao carrinho"], ["checkout page", "página de pagamento"], ["discount code", "código de desconto"], ["promo code", "código promocional"], ["tracking number", "código de rastreio"], ["wish list", "lista de desejos"], ["browse", "navegar, dar uma olhada"], ["expire", "vencer, expirar"]]};
englishA2Content[252]=[[["Lia browses an online store on Sunday night.", "Lia dá uma olhada numa loja virtual no domingo à noite."], ["She adds a blue lamp to her wish list.", "Ela coloca uma luminária azul na lista de desejos."], ["Then she clicks \"add to cart\" and opens her shopping cart.", "Depois ela clica em \"adicionar ao carrinho\" e abre o carrinho de compras."], ["On the checkout page, she types a discount code.", "Na página de pagamento, ela digita um código de desconto."], ["The delivery takes five days, and she gets a tracking number by email.", "A entrega leva cinco dias, e ela recebe um código de rastreio por e-mail."], ["Now she can follow her package on her phone.", "Agora ela pode acompanhar o pacote pelo celular."]], [["Sam, I want to buy a lamp online. Can you help me?", "Sam, quero comprar uma luminária na internet. Você pode me ajudar?"], ["Sure. First, browse the store and pick one. Then click add to cart.", "Claro. Primeiro, dê uma olhada na loja e escolha uma. Depois clique em adicionar ao carrinho."], ["Okay, it's in my shopping cart now. Where do I put my address?", "Certo, está no meu carrinho agora. Onde coloco meu endereço?"], ["On the checkout page. Wait, do you have a promo code?", "Na página de pagamento. Espere, você tem um código promocional?"], ["I have one from a newsletter, but I think it expires tonight.", "Tenho um de um boletim, mas acho que vence hoje à noite."], ["Type it in now. Codes expire fast, and this one saves ten dollars.", "Digite agora. Códigos vencem rápido, e este economiza dez dólares."], ["It works! The delivery is free, and I got a tracking number.", "Funcionou! A entrega é grátis, e recebi um código de rastreio."], ["Great. Now you can watch your lamp travel on your phone.", "Ótimo. Agora você pode ver sua luminária viajando pelo celular."]], ["/k/ em cart e click", "O /k/ inglês tem um sopro leve no final. Em click, termine no /k/ sem acrescentar um 'i' (não diga 'clíqui').", ["cart", "click"]], ["Please click \"add to cart\" ___ you choose the lamp.", "after", "before", "Por favor, clique em \"adicionar ao carrinho\" depois de escolher a luminária.", "Primeiro você escolhe o produto; só depois clica em adicionar, então usamos after."], [["On the checkout page, she types a discount code.", "Na página de pagamento, ela digita um código de desconto."], ["On the checkout page. Wait, do you have a promo code?", "Na página de pagamento. Espere, você tem um código promocional?"]], [{"t": "c", "q": "Type your discount code on the ___ page.", "o": ["checkout", "browse", "expire"], "pt": "Digite seu código de desconto na página de pagamento.", "why": "A página onde você paga se chama checkout page."}, {"t": "l", "say": "I got a tracking number by email.", "o": ["I got a tracking number by email.", "I got a tracking number by phone.", "I got a shopping number by email."], "why": "Você ouviu tracking number e email."}, {"t": "b", "pt": "Coloque a luminária no carrinho.", "w": ["Add", "the", "lamp", "to", "your", "cart"]}, {"t": "b", "pt": "O código vence hoje à noite.", "w": ["The", "code", "expires", "tonight"]}]];
