englishA2Plans[253]={"title": "Trocando uma jaqueta que não serviu", "file": "", "grammar": "Devolver um produto: I'd like to return… / It doesn't fit / too + adjetivo", "goal": "Peça para devolver um produto com I'd like to return… e explique o problema com too small ou too tight.", "words": [["return policy", "política de devolução"], ["money back", "dinheiro de volta"], ["wrong size", "tamanho errado"], ["too small", "pequeno demais"], ["too tight", "apertado demais"], ["too loose", "largo demais"], ["try on", "experimentar (roupa)"], ["defective", "com defeito"], ["refundable", "reembolsável"]]};
englishA2Content[253]=[[["Noah bought a jacket online, but it was the wrong size.", "Noah comprou uma jaqueta pela internet, mas era o tamanho errado."], ["It doesn't fit, and the sleeves are too tight.", "Não serve, e as mangas estão apertadas demais."], ["He goes back to the store with the jacket and the bag.", "Ele volta à loja com a jaqueta e a sacola."], ["The return policy says he has thirty days to bring it back.", "A política de devolução diz que ele tem trinta dias para trazê-la de volta."], ["The jacket is refundable, because it still has the tag.", "A jaqueta é reembolsável, porque ainda está com a etiqueta."], ["The clerk gives Noah his money back, and he leaves happy.", "A vendedora devolve o dinheiro a Noah, e ele sai feliz."]], [["Hi, I'd like to return this jacket. It doesn't fit.", "Oi, eu gostaria de devolver esta jaqueta. Ela não serve."], ["Sorry to hear that. What's the problem? Is it too small?", "Sinto muito. Qual é o problema? É pequena demais?"], ["Yes, it's too small. Can I try on a large first?", "Sim, é pequena demais. Posso experimentar uma grande primeiro?"], ["Of course. The fitting rooms are on the left.", "Claro. Os provadores ficam à esquerda."], ["The large is too loose, so I'd like my money back, please.", "A grande é larga demais, então eu gostaria do meu dinheiro de volta, por favor."], ["Okay. Do you have the receipt? I need to check the return policy.", "Certo. Você tem o recibo? Preciso conferir a política de devolução."], ["Here it is. I bought the jacket twelve days ago.", "Aqui está. Comprei a jaqueta há doze dias."], ["Good. It isn't defective, but it's refundable for thirty days.", "Ótimo. Não tem defeito, mas é reembolsável por trinta dias."], ["Then I can give you your money back. Cash or card?", "Então posso devolver seu dinheiro. Em dinheiro ou no cartão?"], ["Card, please. Thank you for your help.", "No cartão, por favor. Obrigado pela ajuda."]], ["/θ/ em thirty e thank", "Em thirty e thank, ponha a ponta da língua entre os dentes e solte o ar. Não troque por /s/ nem por /f/.", ["thirty", "thank"]], ["The shoes don't fit. They are ___ small.", "too", "very", "Os sapatos não servem. São pequenos demais.", "Too indica excesso, algo além do que serve; very só reforça."], [["It doesn't fit, and the sleeves are too tight.", "Não serve, e as mangas estão apertadas demais."], ["Hi, I'd like to return this jacket. It doesn't fit.", "Oi, eu gostaria de devolver esta jaqueta. Ela não serve."]], [{"t": "c", "q": "I'd like to ___ this shirt. It doesn't fit.", "o": ["return", "browse", "expire"], "pt": "Eu gostaria de devolver esta camisa. Ela não serve.", "why": "Para devolver um produto, usamos return."}, {"t": "l", "say": "The sleeves are too tight.", "o": ["The sleeves are too tight.", "The sleeves are too loose.", "The sleeves are very light."], "why": "Você ouviu too tight: apertado demais."}, {"t": "b", "pt": "Eu gostaria do meu dinheiro de volta.", "w": ["I'd", "like", "my", "money", "back"]}, {"t": "b", "pt": "Posso experimentar um tamanho maior?", "w": ["Can", "I", "try", "on", "a", "bigger", "size"]}]];
