englishA2Plans[254]={"title": "Dividindo a conta do jantar", "file": "", "grammar": "Pagar e dividir contas: Let's split… / I'll pay for…", "goal": "Divida a conta com Let's split the bill e ofereça-se para pagar com I'll pay for…", "words": [["split the bill", "dividir a conta"], ["pay cash", "pagar em dinheiro"], ["pay by card", "pagar com cartão"], ["in cash", "em dinheiro"], ["credit card", "cartão de crédito"], ["pay for", "pagar por"], ["pay back", "devolver o dinheiro"], ["owe", "dever"], ["tipping", "dar gorjeta"]]};
englishA2Content[254]=[[["Kenji and Elena have dinner at a small Italian restaurant.", "Kenji e Elena jantam num pequeno restaurante italiano."], ["The bill is $64, and the waiter brings it to the table.", "A conta é de US$ 64, e o garçom a traz para a mesa."], ["Kenji says, \"Let's split the bill.\"", "Kenji diz: \"Vamos dividir a conta.\""], ["Elena only has a credit card, but Kenji wants to pay cash.", "Elena só tem cartão de crédito, mas Kenji quer pagar em dinheiro."], ["Elena says she can pay by card, and Kenji gives her his half in cash.", "Elena diz que pode pagar com cartão, e Kenji lhe dá a metade dele em dinheiro."], ["They both leave a tip and walk home.", "Os dois deixam gorjeta e vão para casa a pé."]], [["The bill is $64. Let's split the bill, okay?", "A conta é de US$ 64. Vamos dividir a conta, certo?"], ["Sure. But I only have a credit card. Does the waiter take cards?", "Claro. Mas eu só tenho cartão de crédito. O garçom aceita cartão?"], ["Yes, but the machine is slow tonight. I'll pay for the tip in cash.", "Aceita, mas a maquininha está lenta hoje. Eu pago a gorjeta em dinheiro."], ["Thanks. Tipping is normal here, right? About eighteen percent?", "Obrigada. Dar gorjeta é normal aqui, né? Uns dezoito por cento?"], ["Right, that's about $11. We can split that too.", "Isso, dá uns US$ 11. Podemos dividir isso também."], ["Then I owe you $5.50 for my half of the tip.", "Então eu te devo US$ 5,50 pela minha metade da gorjeta."], ["Forget it. Just pay me back with a coffee tomorrow.", "Esqueça. Me pague com um café amanhã."], ["Deal. I'll bring you the biggest coffee in town.", "Combinado. Vou te trazer o maior café da cidade."]], ["/ɪ/ em split e bill", "O /ɪ/ de split e bill é curto e relaxado, entre 'i' e 'e'. Em split, comece com /sp/ junto, sem um 'e' antes (não diga 'esplit').", ["split", "bill"]], ["It's my birthday, so I'll ___ dinner.", "pay for", "pay", "É meu aniversário, então eu pago o jantar.", "Pagar uma coisa é pay for; sem for, o verbo fica incompleto."], [["Kenji says, \"Let's split the bill.\"", "Kenji diz: \"Vamos dividir a conta.\""], ["Yes, but the machine is slow tonight. I'll pay for the tip in cash.", "Aceita, mas a maquininha está lenta hoje. Eu pago a gorjeta em dinheiro."]], [{"t": "c", "q": "Let's ___ the bill. It's $40 for two people.", "o": ["split", "owe", "expire"], "pt": "Vamos dividir a conta. São US$ 40 para duas pessoas.", "why": "Dividir a conta é split the bill."}, {"t": "l", "say": "I'll pay for the tip in cash.", "o": ["I'll pay for the tip in cash.", "I'll pay for the trip in cash.", "I'll pay for the tip by card."], "why": "Você ouviu tip e in cash."}, {"t": "b", "pt": "Eu pago o jantar hoje.", "w": ["I'll", "pay", "for", "dinner", "today"]}, {"t": "b", "pt": "Vamos dividir a conta.", "w": ["Let's", "split", "the", "bill"]}]];
