englishA2Plans[255]={"title": "Juntando dinheiro para uma viagem", "file": "", "grammar": "Economizar dinheiro: saving for, I'm going to save…", "goal": "Fale de uma meta com I'm saving for… e I'm going to save… por mês.", "words": [["piggy bank", "cofrinho"], ["emergency fund", "reserva de emergência"], ["save up", "juntar dinheiro"], ["cut back", "cortar gastos"], ["tight budget", "orçamento apertado"], ["pocket money", "mesada"], ["pay raise", "aumento de salário"], ["make money", "ganhar dinheiro"]]};
englishA2Content[255]=[[["Mia is saving for a trip to Mexico next summer.", "Mia está juntando dinheiro para uma viagem ao México no próximo verão."], ["She keeps coins in a piggy bank on her desk.", "Ela guarda moedas num cofrinho na mesa."], ["Every month, she puts $100 in her bank.", "Todo mês, ela coloca US$ 100 no banco."], ["She wants to cut back on coffee and taxis.", "Ela quer cortar gastos com café e táxi."], ["Her boss may give her a pay raise in June.", "A chefe pode dar um aumento de salário a ela em junho."], ["Mia is going to save up $1,500 by July.", "Mia vai juntar US$ 1.500 até julho."]], [["Tom, what are you saving for this year?", "Tom, para que você está juntando dinheiro este ano?"], ["I'm saving for a car, but I also want an emergency fund.", "Estou juntando para um carro, mas também quero uma reserva de emergência."], ["Smart. How much are you going to save each month?", "Esperto. Quanto você vai guardar por mês?"], ["About $200. I have a tight budget, so I'm going to cut back on takeout.", "Uns US$ 200. Tenho um orçamento apertado, então vou cortar a comida de delivery."], ["My little sister gets pocket money, and she's saving for a bike.", "Minha irmãzinha recebe mesada e está juntando para uma bicicleta."], ["Really? Does she have a piggy bank?", "Sério? Ela tem um cofrinho?"], ["Yes, a pink one. She also wants to make money by washing cars.", "Tem, um rosa. Ela também quer ganhar dinheiro lavando carros."], ["Good for her! I'm going to ask my boss about a pay raise.", "Bom para ela! Vou perguntar à minha chefe sobre um aumento."]], ["/v/ em save e every", "No /v/ de save e every, os dentes de cima tocam o lábio de baixo e a voz vibra. Não troque por /b/.", ["save", "every"]], ["I'm ___ a new phone, so I don't buy snacks.", "saving for", "saving", "Estou juntando dinheiro para um celular novo, então não compro lanches.", "Para dizer o objetivo da economia, usamos saving for + o que você quer."], [["Mia is saving for a trip to Mexico next summer.", "Mia está juntando dinheiro para uma viagem ao México no próximo verão."], ["Mia is going to save up $1,500 by July.", "Mia vai juntar US$ 1.500 até julho."]], [{"t": "c", "q": "I'm going to ___ $50 every month.", "o": ["save", "saves", "saving"], "pt": "Vou guardar US$ 50 todo mês.", "why": "Depois de going to, o verbo fica na forma simples: save."}, {"t": "l", "say": "She is saving for a bike.", "o": ["She is saving for a bike.", "She is saving for a bag.", "He is saving for a bike."], "why": "Você ouviu she e a bike."}, {"t": "b", "pt": "Estou juntando dinheiro para um carro.", "w": ["I'm", "saving", "for", "a", "car"]}, {"t": "b", "pt": "Vou cortar gastos com café.", "w": ["I'm", "going", "to", "cut", "back", "on", "coffee"]}]];
englishA2PhotoThemes[255]="ticket";
englishA2Plans[256]={"title": "Pedindo US$ 40 emprestados a uma amiga", "file": "", "grammar": "Emprestar e pagar de volta: lend / borrow", "goal": "Peça dinheiro com Can I borrow…? e ofereça com I can lend you…", "words": [["debt", "dívida"], ["broke", "sem dinheiro"], ["short of", "faltando"], ["pay off", "quitar"], ["pay in full", "pagar tudo"], ["rent money", "dinheiro do aluguel"], ["lose money", "perder dinheiro"], ["poor", "pobre"]]};
englishA2Content[256]=[[["Sam is broke at the end of the month.", "Sam está sem dinheiro no fim do mês."], ["He is $40 short of the rent money.", "Faltam US$ 40 para ele completar o dinheiro do aluguel."], ["His friend Ana says she can lend him the money.", "A amiga Ana diz que pode emprestar o dinheiro a ele."], ["Sam promises to pay in full on Friday.", "Sam promete pagar tudo na sexta."], ["Ana hates debt, so she writes the date on a note.", "Ana odeia dívidas, então escreve a data num bilhete."], ["On Friday, Sam gives her the money, and they both smile.", "Na sexta, Sam lhe dá o dinheiro, e os dois sorriem."]], [["Ana, can I borrow $40? I'm broke until Friday.", "Ana, posso pegar US$ 40 emprestados? Estou sem dinheiro até sexta."], ["Sure, I can lend you $40. What happened? Did you lose money?", "Claro, posso te emprestar US$ 40. O que aconteceu? Você perdeu dinheiro?"], ["No, but my phone broke, and the repair cost $90.", "Não, mas meu celular quebrou, e o conserto custou US$ 90."], ["Ouch. Here, take it. Pay me back when you can.", "Nossa. Tome. Me pague quando puder."], ["I will. I never want to be in debt, so I'm going to pay off every dollar.", "Vou pagar. Não quero ficar em dívida, então vou quitar cada dólar."], ["Remember when we were poor students? We counted every penny.", "Lembra quando éramos estudantes pobres? Contávamos cada centavo."], ["Yes! You lent me $5 for lunch twice, and I never forgot.", "Sim! Você me emprestou US$ 5 para o almoço duas vezes, e eu nunca esqueci."], ["Just bring the money on Friday, and lunch is on me.", "Só traga o dinheiro na sexta, e o almoço é por minha conta."], ["Deal. Friday at noon, and I'm paying for the drinks.", "Combinado. Sexta ao meio-dia, e eu pago as bebidas."], ["Perfect. I'll write it on my calendar.", "Perfeito. Vou anotar no calendário."]], ["/b/ em borrow e broke", "O /b/ é vozeado: os lábios se abrem e a voz já está ligada. Em broke, junte /br/ sem vogal no meio (não diga 'biroke').", ["borrow", "broke"]], ["Can I ___ your pen? I forgot mine.", "borrow", "lend", "Posso pegar sua caneta emprestada? Esqueci a minha.", "Borrow é pegar emprestado; lend é emprestar a alguém."], [["His friend Ana says she can lend him the money.", "A amiga Ana diz que pode emprestar o dinheiro a ele."], ["Ana, can I borrow $40? I'm broke until Friday.", "Ana, posso pegar US$ 40 emprestados? Estou sem dinheiro até sexta."]], [{"t": "c", "q": "I can ___ you $20 until Monday.", "o": ["lend", "borrow", "owe"], "pt": "Posso te emprestar US$ 20 até segunda.", "why": "Quem dá o dinheiro emprestado usa lend."}, {"t": "l", "say": "Can I borrow forty dollars?", "o": ["Can I borrow forty dollars?", "Can I borrow fourteen dollars?", "Can I lend forty dollars?"], "why": "Você ouviu borrow e forty."}, {"t": "b", "pt": "Posso pegar emprestado seu carregador?", "w": ["Can", "I", "borrow", "your", "charger"]}, {"t": "b", "pt": "Vou te pagar na sexta.", "w": ["I'm", "going", "to", "pay", "you", "back", "on", "Friday"]}]];
englishA2PhotoThemes[256]="map";
englishA2Plans[257]={"title": "Entendendo cobranças no extrato do banco", "file": "", "grammar": "Ler extrato e fatura: balance, charge, fee", "goal": "Leia um extrato e pergunte sobre uma cobrança com What is this charge?", "words": [["bank statement", "extrato bancário"], ["account balance", "saldo da conta"], ["monthly fee", "taxa mensal"], ["late fee", "multa por atraso"], ["bank fee", "tarifa bancária"], ["utilities", "contas de luz, água etc."], ["groceries", "compras de mercado"], ["subscription", "assinatura"], ["total", "total"]]};
englishA2Content[257]=[[["Priya opens her bank statement on Sunday morning.", "Priya abre o extrato bancário no domingo de manhã."], ["Her account balance is $412, lower than last month.", "O saldo da conta dela é de US$ 412, menor que o do mês passado."], ["She sees a $9.99 subscription that she forgot to cancel.", "Ela vê uma assinatura de US$ 9,99 que esqueceu de cancelar."], ["There is also a $3 bank fee for using another bank's ATM.", "Há também uma tarifa bancária de US$ 3 por usar o caixa eletrônico de outro banco."], ["The total for utilities and groceries is $290.", "O total de contas e mercado é de US$ 290."], ["Priya cancels the subscription and feels better.", "Priya cancela a assinatura e se sente melhor."]], [["Omar, can you look at this bank statement with me?", "Omar, você pode ver este extrato bancário comigo?"], ["Sure. What's the problem? Your balance looks normal.", "Claro. Qual é o problema? Seu saldo parece normal."], ["There's a $15 late fee here. I paid my phone bill on time!", "Tem uma multa por atraso de US$ 15 aqui. Paguei minha conta de telefone em dia!"], ["Maybe the payment arrived late. Look, there's also a monthly fee of $5.", "Talvez o pagamento tenha chegado atrasado. Olhe, também tem uma taxa mensal de US$ 5."], ["A monthly fee? My account was free when I opened it.", "Uma taxa mensal? Minha conta era grátis quando abri."], ["Call the bank. Ask them to remove the charge and explain the fees.", "Ligue para o banco. Peça para tirarem a cobrança e explicarem as taxas."], ["I'll call tomorrow morning. Thank you for your help.", "Vou ligar amanhã de manhã. Obrigada pela ajuda."], ["No problem. Tell me what they say.", "Sem problema. Me conte o que eles disserem."], ["Okay, I'll text you right after the call.", "Certo, mando uma mensagem logo depois da ligação."], ["Great. Then we can check the next statement together.", "Ótimo. Aí conferimos o próximo extrato juntos."]], ["/æ/ em balance e bank", "O /æ/ pede a boca bem aberta, entre 'a' e 'é'. Em bank, não deixe o 'a' ficar nasal como em 'bãnco'.", ["balance", "bank"]], ["What is this $15 ___ on my statement?", "charge", "change", "O que é esta cobrança de US$ 15 no meu extrato?", "Charge é cobrança; change é troco ou mudança, e não combina com extrato."], [["Her account balance is $412, lower than last month.", "O saldo da conta dela é de US$ 412, menor que o do mês passado."], ["Call the bank. Ask them to remove the charge and explain the fees.", "Ligue para o banco. Peça para tirarem a cobrança e explicarem as taxas."]], [{"t": "c", "q": "My account ___ is $412 today.", "o": ["balance", "fee", "charge"], "pt": "O saldo da minha conta é de US$ 412 hoje.", "why": "O dinheiro que sobra na conta é o balance."}, {"t": "l", "say": "There is a late fee on my statement.", "o": ["There is a late fee on my statement.", "There is a late fee on my payment.", "There is a lot of fees on my statement."], "why": "Você ouviu late fee e statement."}, {"t": "b", "pt": "O que é esta cobrança?", "w": ["What", "is", "this", "charge"]}, {"t": "b", "pt": "Meu saldo é menor que o do mês passado.", "w": ["My", "balance", "is", "lower", "than", "last", "month"]}]];
englishA2PhotoThemes[257]="city";
englishA2Plans[258]={"title": "Mensagem suspeita de um número desconhecido", "file": "", "grammar": "Evitar golpes: Be careful / Never share… (imperativo)", "goal": "Alerte alguém com Be careful e Never share… para evitar golpes.", "words": [["scam", "golpe"], ["scammer", "golpista"], ["suspicious", "suspeito"], ["unknown number", "número desconhecido"], ["verify", "confirmar, verificar"], ["identity", "identidade"], ["fake", "falso"], ["rip off", "enganar, cobrar caro demais"], ["secure", "seguro"]]};
englishA2Content[258]=[[["Rosa gets a text from an unknown number.", "Rosa recebe uma mensagem de um número desconhecido."], ["The message says her card is blocked and asks for her password.", "A mensagem diz que o cartão dela está bloqueado e pede a senha."], ["It looks suspicious, because the grammar is bad.", "Parece suspeita, porque a gramática é ruim."], ["A real bank never asks you to verify your password by text.", "Um banco de verdade nunca pede para você confirmar a senha por mensagem."], ["Rosa knows it is a scam, so she doesn't click the link.", "Rosa sabe que é um golpe, então não clica no link."], ["She deletes the message and blocks the scammer.", "Ela apaga a mensagem e bloqueia o golpista."]], [["Rosa, you look worried. What's wrong?", "Rosa, você parece preocupada. O que houve?"], ["Ben, I got a weird text from an unknown number. Look!", "Ben, recebi uma mensagem estranha de um número desconhecido. Olhe!"], ["Be careful, Rosa. Don't click that link. It looks fake.", "Cuidado, Rosa. Não clique nesse link. Parece falso."], ["I know. It says I won a free phone, but I have to pay $5 first.", "Eu sei. Diz que ganhei um celular grátis, mas preciso pagar US$ 5 antes."], ["That's a classic trick. They want to rip off people like us.", "Esse é um truque clássico. Eles querem enganar gente como nós."], ["What if they call me? They might ask for my identity number.", "E se eles me ligarem? Podem pedir o número da minha identidade."], ["Never share your password or your identity number, even if they sound polite.", "Nunca compartilhe sua senha ou o número da identidade, mesmo que pareçam educados."], ["Good idea. I'll only shop on secure websites with the lock icon.", "Boa ideia. Só vou comprar em sites seguros com o ícone de cadeado."], ["Exactly. And block that number right now, before you forget.", "Exatamente. E bloqueie esse número agora mesmo, antes que esqueça."], ["Done! It's blocked, and I feel much safer.", "Pronto! Está bloqueado, e me sinto muito mais segura."]], ["/s/ antes de consoante em scam e secure", "Em scam, comece direto no /s/, sem um 'i' antes (não diga 'iscam'). Em secure, o /s/ é limpo e o final soa como 'kiur'.", ["scam", "secure"]], ["___ share your password with anyone.", "Never", "Don't never", "Nunca compartilhe sua senha com ninguém.", "Em inglês não se usa duplo negativo; Never já carrega a ideia de negação."], [["Ben, I got a weird text from an unknown number. Look!", "Ben, recebi uma mensagem estranha de um número desconhecido. Olhe!"], ["What if they call me? They might ask for my identity number.", "E se eles me ligarem? Podem pedir o número da minha identidade."]], [{"t": "c", "q": "___ careful with messages from strangers.", "o": ["Be", "Are", "Do"], "pt": "Tenha cuidado com mensagens de estranhos.", "why": "Na ordem, usamos Be + adjetivo: Be careful."}, {"t": "l", "say": "Never share your password.", "o": ["Never share your password.", "Never change your password.", "Ever share your password."], "why": "Você ouviu never share e password."}, {"t": "b", "pt": "Não clique nesse link.", "w": ["Don't", "click", "that", "link"]}, {"t": "b", "pt": "Nunca compartilhe sua senha.", "w": ["Never", "share", "your", "password"]}]];
