englishA2Plans[259]={"title": "Contando moedas antes do dia do pagamento", "file": "", "grammar": "Revisão: dinheiro, compras e cuidado (be careful, going to)", "goal": "Revise o vocabulário do mês do orçamento apertado e fale de planos com going to.", "words": [["sold out", "esgotado"], ["credit card", "cartão de crédito"], ["free shipping", "frete grátis"], ["worth", "valer a pena"], ["bank account", "conta bancária"], ["be careful", "ter cuidado"], ["for free", "de graça"], ["payday", "dia de pagamento"], ["dime", "moeda de dez centavos"]]};
englishA2Content[259]=[[["Payday is next week, and Lia's wallet is almost empty.", "O dia de pagamento é na semana que vem, e a carteira de Lia está quase vazia."], ["She finds three dimes under the sofa and laughs.", "Ela acha três moedas de dez centavos embaixo do sofá e ri."], ["Her bank account has only $38 left.", "A conta bancária dela tem só US$ 38."], ["The book she wants is sold out at the local store.", "O livro que ela quer está esgotado na loja do bairro."], ["The online store has it, and free shipping starts at $35.", "A loja virtual tem o livro, e o frete grátis começa em US$ 35."], ["She decides to be careful and wait, because the book is worth it.", "Ela decide ter cuidado e esperar, porque o livro vale a pena."]], [["Tom, is it a good idea to use my credit card this week?", "Tom, é boa ideia usar meu cartão de crédito esta semana?"], ["Be careful. Credit cards charge high fees if you pay late.", "Cuidado. Cartões de crédito cobram taxas altas se você paga atrasado."], ["I know. But the author gives the first chapter for free.", "Eu sei. Mas a autora dá o primeiro capítulo de graça."], ["Then read it for free, and decide on payday.", "Então leia de graça e decida no dia do pagamento."], ["Good idea. If I like it, I'm going to buy the whole book.", "Boa ideia. Se eu gostar, vou comprar o livro inteiro."], ["And wait for the sale. It's cheaper than last month.", "E espere a promoção. Está mais barato que no mês passado."], ["Right. I'll have $200 after payday, so I'm going to buy two books.", "Certo. Vou ter US$ 200 depois do pagamento, então vou comprar dois livros."], ["Perfect. And I'll lend you my old book for the weekend.", "Perfeito. E eu te empresto meu livro velho no fim de semana."]], ["/w/ em wallet e worth", "No /w/, arredonde os lábios como para dizer 'u' e abra rápido na vogal. Não comece com /v/.", ["wallet", "worth"]], ["She is going to ___ careful with her money.", "be", "is", "Ela vai tomar cuidado com o dinheiro dela.", "Depois de going to, o verbo fica na forma simples: be."], [["Be careful. Credit cards charge high fees if you pay late.", "Cuidado. Cartões de crédito cobram taxas altas se você paga atrasado."], ["Good idea. If I like it, I'm going to buy the whole book.", "Boa ideia. Se eu gostar, vou comprar o livro inteiro."]], [{"t": "c", "q": "The jacket is ___ out, so I can't buy it.", "o": ["sold", "sell", "selling"], "pt": "A jaqueta está esgotada, então não posso comprá-la.", "why": "Sold out é a expressão para esgotado."}, {"t": "l", "say": "Payday is next week.", "o": ["Payday is next week.", "Payday is next weekend.", "Today is next week."], "why": "Você ouviu payday e next week."}, {"t": "b", "pt": "Vou tomar cuidado com meu dinheiro.", "w": ["I'm", "going", "to", "be", "careful", "with", "money"]}, {"t": "b", "pt": "O livro vale a pena.", "w": ["The", "book", "is", "worth", "it"]}]];
englishA2PhotoThemes[259]="map";
englishA2MiniStories[259]=["O mês apertado da Lia", "Lia has only $200 left, and payday is ten days away.~Lia tem só US$ 200 e faltam dez dias para o pagamento.|She wants a coat, but the price tag says $120.~Ela quer um casaco, mas a etiqueta diz US$ 120.|She asks, \"Is there a discount?\" and the clerk says it's 30 percent off.~Ela pergunta: \"Tem desconto?\" e o vendedor diz que são 30 por cento.|At home, she puts boots in her cart, but they are sold out.~Em casa, ela põe botas no carrinho, mas elas estão esgotadas.|At dinner, she and Tom split the bill, and she pays him back the next day.~No jantar, ela e Tom dividem a conta, e ela o paga no dia seguinte.|Her bank statement shows a $3 fee, and the account is almost empty.~O extrato mostra uma tarifa de US$ 3, e a conta está quase vazia.|A text from an unknown number says she can win a phone for free.~Uma mensagem de um número desconhecido diz que ela pode ganhar um celular de graça.|Lia remembers to be careful, so she deletes the message.~Lia lembra de ter cuidado, então apaga a mensagem.|Ana lends her $20, and Lia promises to pay it back on payday.~Ana lhe empresta US$ 20, e Lia promete devolver no dia do pagamento.|On payday, she orders a cheaper coat with free shipping, and it's worth every dollar.~No dia do pagamento, ela pede um casaco mais barato com frete grátis, e vale cada dólar."];
englishA2Plans[260]={"title": "Criando conta no app de ônibus", "file": "", "grammar": "Sequência no passado: download, sign up, log in", "goal": "Conte os passos para usar um app novo: baixar, criar conta e entrar.", "words": [["log in", "entrar (na conta)"], ["log out", "sair (da conta)"], ["profile", "perfil"], ["pop up", "aparecer de repente"], ["storage", "armazenamento"], ["delete", "apagar"], ["icon", "ícone"], ["setting", "configuração"]]};
englishA2Content[260]=[[["Rosa downloaded the bus app on Monday morning.", "Rosa baixou o aplicativo de ônibus na segunda de manhã."], ["First she tapped the green icon, and a window popped up.", "Primeiro ela tocou no ícone verde, e uma janela apareceu."], ["She signed up with her email and chose a password.", "Ela criou a conta com o e-mail e escolheu uma senha."], ["Then she opened her profile and added her photo.", "Depois ela abriu o perfil e colocou a foto."], ["The app needed a lot of storage, so she deleted two old games.", "O app precisava de muito espaço, então ela apagou dois jogos velhos."], ["Now she can log in fast, and she can log out when she's done.", "Agora ela entra rápido e pode sair da conta quando terminar."]], [["Tom, did you download the new bus app yet?", "Tom, você já baixou o novo app de ônibus?"], ["Yes, I did. First I tapped the icon, and then I signed up.", "Baixei. Primeiro toquei no ícone e depois criei a conta."], ["Did the app ask for a lot of information?", "O app pediu muitas informações?"], ["Just my email and a password. Then a code popped up.", "Só o e-mail e uma senha. Depois apareceu um código."], ["My phone says there isn't enough storage. I need to delete some photos.", "Meu celular diz que não tem espaço. Preciso apagar umas fotos."], ["Open the settings, and you'll see which apps use the most storage.", "Abra as configurações, e você vai ver quais apps usam mais espaço."], ["Good idea. Okay, I'm in. How do I change my profile picture?", "Boa ideia. Pronto, entrei. Como mudo minha foto de perfil?"], ["Tap your profile, and then tap the little camera.", "Toque no seu perfil e depois na câmera pequena."], ["Done! Should I log out now?", "Pronto! Devo sair da conta agora?"], ["No, stay logged in. Next time it'll open in two seconds.", "Não, fique conectada. Da próxima vez abre em dois segundos."]], ["/aɪ/ em icon e profile", "O som /aɪ/ é como o 'ai' de 'pai', mas termine com um 'i' curto. Diga ICON com força no primeiro pedaço e profile com 'ai' no meio.", ["icon", "profile"]], ["First I downloaded the app, and then I ___ up.", "signed", "sign", "Primeiro baixei o app, e depois criei a conta.", "Na sequência de ações passadas, o segundo verbo também fica no passado: signed."], [["Rosa downloaded the bus app on Monday morning.", "Rosa baixou o aplicativo de ônibus na segunda de manhã."], ["She signed up with her email and chose a password.", "Ela criou a conta com o e-mail e escolheu uma senha."]], [{"t": "c", "q": "She downloaded the app and then she ___ up.", "o": ["signed", "sign", "signing"], "pt": "Ela baixou o app e depois criou a conta.", "why": "Sequência no passado: downloaded, depois signed."}, {"t": "l", "say": "First I tapped the icon, and then I logged in.", "o": ["First I tapped the icon, and then I logged in.", "First I tapped the icon, and then I logged out.", "First I deleted the icon, and then I logged in."], "why": "Você ouviu tapped the icon e logged in."}, {"t": "b", "pt": "Eu baixei o app ontem.", "w": ["I", "downloaded", "the", "app", "yesterday"]}, {"t": "b", "pt": "Preciso apagar fotos velhas.", "w": ["I", "need", "to", "delete", "old", "photos"]}]];
