englishA2ExtraWordExamples[260]={"pop up": ["A new window pops up on my screen.", "Uma janela nova aparece na minha tela."]};
englishA2Plans[261]={"title": "O celular que trava e esquenta", "file": "", "grammar": "Problemas do celular: it won't… / it keeps + -ing", "goal": "Descreva o que o celular faz de errado usando keeps + -ing e won't.", "words": [["overheat", "superaquecer"], ["freeze up", "travar"], ["shut down", "desligar sozinho"], ["run out", "acabar"], ["screenshot", "captura de tela"], ["airplane mode", "modo avião"], ["back up", "fazer backup"], ["sync", "sincronizar"], ["vibrate", "vibrar"]]};
englishA2Content[261]=[[["Omar's phone keeps freezing up when he opens the camera.", "O celular do Omar fica travando quando ele abre a câmera."], ["The battery will run out by lunch, even after a full charge.", "A bateria vai acabar até o almoço, mesmo depois de carga completa."], ["Yesterday it started to overheat in his pocket, and it won't turn on now.", "Ontem ele começou a esquentar demais no bolso, e agora não liga."], ["He tried airplane mode, but the screen still won't respond.", "Ele tentou o modo avião, mas a tela ainda não responde."], ["Mia told him to back up his photos before the phone shuts down for good.", "A Mia disse para ele fazer backup das fotos antes que o celular desligue de vez."], ["At the store, a technician fixed it, and Omar sent Mia a screenshot of the receipt.", "Na loja, um técnico consertou, e o Omar mandou para a Mia uma captura do recibo."]], [["Omar, why didn't you answer my text this morning?", "Omar, por que você não respondeu minha mensagem hoje cedo?"], ["My phone keeps freezing up, and it won't even vibrate when someone calls.", "Meu celular fica travando e nem vibra quando alguém liga."], ["Did you try airplane mode? Sometimes that fixes it for a minute.", "Você tentou o modo avião? Às vezes isso resolve por um minuto."], ["I did, but the battery will run out in two hours anyway.", "Tentei, mas a bateria acaba em duas horas de qualquer jeito."], ["That's bad. Did you back up your photos last week?", "Que ruim. Você fez backup das fotos na semana passada?"], ["No, I didn't. The cloud won't sync, and it keeps saying Error 42.", "Não. A nuvem não sincroniza e fica dizendo Erro 42."], ["Take a screenshot of that error. The store can read it.", "Tire uma captura desse erro. A loja consegue ler."], ["Good idea. Yesterday it started to overheat, and then it shut down.", "Boa ideia. Ontem começou a esquentar demais e depois desligou."], ["Go to the store at five. They close at seven, so you have time.", "Vá à loja às cinco. Eles fecham às sete, então dá tempo."], ["Okay, I'll go right after work. Thanks, Mia!", "Certo, vou logo depois do trabalho. Obrigado, Mia!"]], ["/ʃ/ em shut e screenshot", "Para o /ʃ/, estique os lábios para a frente e solte o ar como quando você pede silêncio: shhh. Não troque por 's' nem por 'tch'.", ["shut", "screenshot"]], ["My phone ___ shutting down, and I'm tired of it.", "keeps", "keep", "Meu celular fica desligando, e estou cansado disso.", "Com 'my phone' (ele), o verbo leva -s: keeps + -ing."], [["My phone keeps freezing up, and it won't even vibrate when someone calls.", "Meu celular fica travando e nem vibra quando alguém liga."], ["I did, but the battery will run out in two hours anyway.", "Tentei, mas a bateria acaba em duas horas de qualquer jeito."]], [{"t": "c", "q": "The screen ___ respond. I pressed it ten times.", "o": ["won't", "doesn't can", "isn't"], "pt": "A tela não responde. Apertei dez vezes.", "why": "Won't mostra que o aparelho se recusa a funcionar."}, {"t": "l", "say": "My phone keeps freezing up.", "o": ["My phone keeps freezing up.", "My phone keeps freezing down.", "My phone keep freezing up."], "why": "Freeze up é travar, e keeps leva -s com 'phone'."}, {"t": "b", "pt": "Meu celular fica desligando", "w": ["My", "phone", "keeps", "shutting", "down"]}, {"t": "b", "pt": "A bateria vai acabar até o almoço", "w": ["The", "battery", "will", "run", "out", "by", "lunch"]}]];
