englishA2Plans[262]={"title": "Ligar de volta e entrar no grupo", "file": "", "grammar": "Mensagens e chamadas: send, receive, call back", "goal": "Fale de mensagens e chamadas de vídeo e combine de ligar de volta.", "words": [["call back", "ligar de volta"], ["hang up", "desligar a chamada"], ["video call", "chamada de vídeo"], ["group chat", "conversa em grupo"], ["voice message", "mensagem de voz"], ["text back", "responder por mensagem"], ["ping", "mandar um aviso"], ["emoji", "emoji"]]};
englishA2Content[262]=[[["Priya received a voice message from her brother Sam at eight.", "A Priya recebeu uma mensagem de voz do irmão Sam às oito."], ["He wanted a video call, but her Wi-Fi was slow.", "Ele queria uma chamada de vídeo, mas o Wi-Fi dela estava lento."], ["She sent him a smiling emoji and said, “I'll call back in ten minutes.”", "Ela mandou um emoji sorrindo e disse: “Eu ligo de volta em dez minutos.”"], ["Then her friends pinged her in the group chat about the picnic.", "Aí os amigos avisaram ela no grupo sobre o piquenique."], ["She typed a long answer, but her phone died before she could send it.", "Ela digitou uma resposta longa, mas o celular morreu antes de enviar."], ["When she charged it, Sam was waiting, and she texted back right away.", "Quando ela carregou, o Sam estava esperando, e ela respondeu na hora."]], [["Priya, I tried to call you twice, but you didn't pick up.", "Priya, tentei ligar duas vezes, mas você não atendeu."], ["Sorry! I was in a meeting. I couldn't hang up on my boss.", "Desculpe! Eu estava em reunião. Não podia desligar na cara do chefe."], ["No problem. I sent a voice message about Saturday. Did you get it?", "Sem problema. Mandei uma mensagem de voz sobre sábado. Você recebeu?"], ["Wait, my phone just pinged. Yes, I received it.", "Espere, meu celular acabou de apitar. Sim, recebi."], ["Great. Can we do a video call at six? Lia and Omar want to join.", "Ótimo. Podemos fazer uma chamada de vídeo às seis? A Lia e o Omar querem entrar."], ["Sure. I'll send everyone the link in the group chat.", "Claro. Vou mandar o link para todo mundo no grupo."], ["Last time I forgot my camera, and nobody saw me. I only sent an emoji.", "Da última vez esqueci a câmera, e ninguém me viu. Só mandei um emoji."], ["I remember! If you can't talk, text back, and I'll call back later.", "Eu lembro! Se você não puder falar, responda por mensagem, e eu ligo de volta depois."], ["Perfect. See you at six.", "Perfeito. Até as seis."], ["Deal. I'll send the link at five thirty.", "Combinado. Mando o link às cinco e meia."]], ["/v/ em voice e video", "No /v/, os dentes de cima tocam levemente o lábio de baixo e a garganta vibra. Não troque por 'b': diga voice, não boice.", ["voice", "video"]], ["I missed your call. I'll ___ you back in ten minutes.", "call", "make", "Perdi sua ligação. Eu ligo de volta em dez minutos.", "Em português é 'ligar de volta'; em inglês, call you back, não make."], [["Priya received a voice message from her brother Sam at eight.", "A Priya recebeu uma mensagem de voz do irmão Sam às oito."], ["I remember! If you can't talk, text back, and I'll call back later.", "Eu lembro! Se você não puder falar, responda por mensagem, e eu ligo de volta depois."]], [{"t": "c", "q": "I'm busy now. I'll ___ you back at six.", "o": ["call", "make", "do"], "pt": "Estou ocupado agora. Eu ligo de volta às seis.", "why": "Call someone back é ligar de volta."}, {"t": "l", "say": "She sent him a smiling emoji.", "o": ["She sent him a smiling emoji.", "She sent him a smiling email.", "She sent her a smiling emoji."], "why": "Emoji é o rostinho; email é outra coisa."}, {"t": "b", "pt": "Você recebeu minha mensagem de voz?", "w": ["Did", "you", "receive", "my", "voice", "message"]}, {"t": "b", "pt": "Podemos fazer uma chamada de vídeo às seis?", "w": ["Can", "we", "do", "a", "video", "call", "at", "six"]}]];
