englishA2Plans[263]={"title": "Proteger a conta depois de um golpe", "file": "", "grammar": "Senhas e segurança: should, shouldn't e must em conselhos", "goal": "Dê conselhos de segurança digital com should, shouldn't e must.", "words": [["hacker", "hacker, invasor"], ["phishing", "golpe de e-mail falso"], ["two-step", "em duas etapas"], ["antivirus", "antivírus"], ["password manager", "gerenciador de senhas"], ["hack", "invadir (um sistema)"], ["private", "privado"], ["sign out", "sair (da conta)"]]};
englishA2Content[263]=[[["Elena's friend Kenji lost his account to a hacker last week.", "O amigo da Elena, Kenji, perdeu a conta para um hacker na semana passada."], ["A fake email, called phishing, asked him for his password.", "Um e-mail falso, chamado phishing, pediu a senha dele."], ["Now he must use a different password for every site.", "Agora ele precisa usar uma senha diferente para cada site."], ["He should install an antivirus app and use two-step login.", "Ele deveria instalar um antivírus e usar login em duas etapas."], ["Elena uses a password manager, so she doesn't need to remember them all.", "A Elena usa um gerenciador de senhas, então não precisa lembrar de todas."], ["She never shares private information, and she always signs out on public computers.", "Ela nunca divulga informações privadas e sempre sai da conta em computadores públicos."]], [["Elena, somebody tried to hack my email last night.", "Elena, alguém tentou invadir meu e-mail ontem à noite."], ["Really? What happened? Did you get a strange message?", "Sério? O que aconteceu? Você recebeu alguma mensagem estranha?"], ["Yes, a text said, “Click here or you'll lose your account.”", "Sim, um texto dizia: “Clique aqui ou você perde sua conta.”"], ["That's phishing! You mustn't click on it. You should delete it.", "Isso é phishing! Você não pode clicar. Deveria apagar."], ["I know now. But what should I do about my password?", "Agora eu sei. Mas o que devo fazer com minha senha?"], ["You must change it today. Use twelve letters, numbers, and symbols.", "Você precisa trocar hoje. Use doze letras, números e símbolos."], ["That's hard to remember. Can I write it on a note?", "É difícil de lembrar. Posso anotar num papel?"], ["No, don't. Try a password manager. I've used one for two years.", "Não. Use um gerenciador de senhas. Eu uso um há dois anos."], ["Okay. And I'll turn on two-step login too.", "Certo. E também vou ligar o login em duas etapas."], ["Good. And sign out when you use the library computer.", "Bom. E saia da conta quando usar o computador da biblioteca."]], ["/h/ em hacker e hack", "O /h/ do inglês é um sopro de ar saindo da garganta, mais suave que o 'r' forte do português. Diga HACK, não 'rack'.", ["hacker", "hack"]], ["You ___ share your password with anyone. It's private.", "mustn't", "don't must", "Você não pode contar sua senha a ninguém. É privada.", "A proibição forte usa mustn't; 'don't must' não existe."], [["That's phishing! You mustn't click on it. You should delete it.", "Isso é phishing! Você não pode clicar. Deveria apagar."], ["You must change it today. Use twelve letters, numbers, and symbols.", "Você precisa trocar hoje. Use doze letras, números e símbolos."]], [{"t": "c", "q": "You ___ change your password today. It isn't safe.", "o": ["must", "mustn't", "are must"], "pt": "Você precisa trocar sua senha hoje. Ela não é segura.", "why": "Must expressa obrigação forte."}, {"t": "l", "say": "You should use a password manager.", "o": ["You should use a password manager.", "You shouldn't use a password manager.", "You should use a password message."], "why": "Should dá conselho; shouldn't seria o contrário."}, {"t": "b", "pt": "Você não deve clicar nesse link", "w": ["You", "shouldn't", "click", "on", "that", "link"]}, {"t": "b", "pt": "Eu sempre saio da conta no computador público", "w": ["I", "always", "sign", "out", "on", "public", "computers"]}]];
