englishA2Plans[266]={"title": "Pesquisando como cozinhar ovos", "file": "", "grammar": "Pesquisar na internet: look up, find out, search for", "goal": "Fale de buscar informação online com look up, find out e search for.", "words": [["search for", "procurar (na internet)"], ["find out", "descobrir"], ["browser", "navegador"], ["reliable", "confiável"], ["trend", "tendência"], ["subscribe", "se inscrever"], ["unsubscribe", "cancelar a inscrição"], ["livestream", "transmissão ao vivo"]]};
englishA2Content[266]=[[["Noah wanted to learn to cook, so he opened his browser.", "O Noah queria aprender a cozinhar, então abriu o navegador."], ["He searched for easy pasta recipes and found 5,000 results.", "Ele procurou receitas fáceis de macarrão e achou 5 mil resultados."], ["First he looked up the word simmer in an online dictionary.", "Primeiro ele procurou a palavra simmer num dicionário online."], ["Then he wanted to find out which videos are reliable.", "Depois ele quis descobrir quais vídeos são confiáveis."], ["One trend said you can cook pasta in cold water, but it didn't work.", "Uma tendência dizia que dá para cozinhar macarrão em água fria, mas não funcionou."], ["He subscribed to a cooking channel and watched the livestream on Sunday.", "Ele se inscreveu num canal de culinária e viu a transmissão ao vivo no domingo."]], [["Noah, what are you doing on your laptop? You look serious.", "Noah, o que você está fazendo no notebook? Você parece sério."], ["I'm trying to find out how long to boil eggs.", "Estou tentando descobrir quanto tempo ferver ovos."], ["Just search for boiled eggs in your browser. It's easy.", "É só procurar boiled eggs no navegador. É fácil."], ["I did, but every site says something different. Which one is reliable?", "Já fiz isso, mas cada site diz uma coisa. Qual é confiável?"], ["Look at the website name. A cooking school is better than a random blog.", "Veja o nome do site. Uma escola de culinária é melhor que um blog qualquer."], ["Good point. I also looked up soft yolk, and one video has two million views.", "Boa. Também procurei gema mole, e um vídeo tem dois milhões de visualizações."], ["Careful with that. Some trends are silly. Did you subscribe to the channel?", "Cuidado com isso. Algumas tendências são bobas. Você se inscreveu no canal?"], ["Yes, but I'll unsubscribe if the videos are bad. There's a livestream at seven.", "Sim, mas cancelo se os vídeos forem ruins. Tem uma transmissão ao vivo às sete."], ["Great! You can ask questions there and get an answer in real time.", "Ótimo! Você pode perguntar lá e receber resposta na hora."], ["Perfect. I'll find out tonight, and I'll text you.", "Perfeito. Eu descubro hoje à noite e te mando mensagem."]], ["/r/ em browser e reliable", "O 'r' inglês não vibra: enrole a língua para trás sem encostar no céu da boca. Em browser e reliable, não pronuncie como o 'h' brasileiro de 'rato'.", ["browser", "reliable"]], ["I want to ___ out what time the store closes.", "find", "look", "Quero descobrir a que horas a loja fecha.", "Find out significa descobrir; look out significa tomar cuidado."], [["I'm trying to find out how long to boil eggs.", "Estou tentando descobrir quanto tempo ferver ovos."], ["Just search for boiled eggs in your browser. It's easy.", "É só procurar boiled eggs no navegador. É fácil."]], [{"t": "c", "q": "I don't know this word. I'll ___ it up.", "o": ["look", "see", "watch"], "pt": "Não conheço essa palavra. Vou procurar.", "why": "Look up é procurar uma palavra num dicionário."}, {"t": "l", "say": "Search for easy pasta recipes.", "o": ["Search for easy pasta recipes.", "Search of easy pasta recipes.", "Search easy pasta recipe for."], "why": "Search for + o que você procura."}, {"t": "b", "pt": "Preciso descobrir o horário do trem", "w": ["I", "need", "to", "find", "out", "the", "train", "time"]}, {"t": "b", "pt": "Esse site é confiável", "w": ["This", "website", "is", "reliable"]}]];
