englishA2Plans[267]={"title": "Reunião online com a conexão ruim", "file": "", "grammar": "Trabalho remoto: connection, screen share, mute", "goal": "Resolva problemas numa reunião online: mute, unmute, screen share e conexão.", "words": [["screen share", "compartilhar a tela"], ["unmute", "ativar o microfone"], ["offline", "desconectado"], ["go offline", "ficar sem conexão"], ["log on", "entrar no sistema"], ["interrupt", "interromper"], ["coverage", "sinal (de rede)"], ["log off", "sair do sistema"]]};
englishA2Content[267]=[[["Ben works from home on Tuesdays and Thursdays.", "O Ben trabalha de casa às terças e quintas."], ["At nine, he logs on and joins the team meeting.", "Às nove, ele entra no sistema e participa da reunião da equipe."], ["His connection is weak today, so his voice keeps breaking up.", "A conexão dele está fraca hoje, então a voz fica cortando."], ["Rosa asked him to unmute, but the sound was still bad.", "A Rosa pediu que ele ativasse o microfone, mas o som continuou ruim."], ["He tried a screen share, and the slides loaded very slowly.", "Ele tentou compartilhar a tela, e os slides carregaram bem devagar."], ["He didn't want to interrupt the boss, so he decided to go offline and call from his phone.", "Ele não quis interromper a chefe, então decidiu ficar offline e ligar pelo celular."]], [["Ben, I can't hear you. Are you on mute?", "Ben, não consigo ouvir você. Está no mudo?"], ["Let me check... Yes! Sorry. I'll unmute now. Can you hear me?", "Deixe eu ver... Sim! Desculpe. Vou ativar o microfone. Você me ouve?"], ["Better. But your video keeps freezing. Is your connection okay?", "Melhor. Mas seu vídeo fica travando. Sua conexão está boa?"], ["No, it's terrible today. The Wi-Fi is weak, and I have almost no coverage on my phone.", "Não, está péssima hoje. O Wi-Fi está fraco, e quase não tenho sinal no celular."], ["That's a problem. Can you do a screen share of the report?", "Que problema. Você consegue compartilhar a tela com o relatório?"], ["I'll try. Please don't interrupt me if the slides move slowly.", "Vou tentar. Por favor, não me interrompa se os slides andarem devagar."], ["Of course. Wait, you're offline now! I can't see anything.", "Claro. Espere, você está offline agora! Não vejo nada."], ["I'm sorry! I'll log off and log on again. Give me two minutes.", "Desculpe! Vou sair e entrar de novo. Me dê dois minutos."], ["No problem. We'll wait. Maybe use your phone as a backup.", "Sem problema. Esperamos. Talvez use o celular como reserva."], ["Good idea. I'm back, and the report is on the screen.", "Boa ideia. Voltei, e o relatório está na tela."]], ["/mj/ em mute e unmute", "Em mute, comece com um 'iu' rápido, como em 'miúdo' sem o 'd': /mjut/. Em unmute, o acento fica na segunda sílaba: un-MUTE.", ["mute", "unmute"]], ["We can't hear you. Please ___ yourself.", "unmute", "mute", "Não ouvimos você. Por favor, ative seu microfone.", "Para voltar a falar, você precisa tirar do mudo: unmute."], [["Ben, I can't hear you. Are you on mute?", "Ben, não consigo ouvir você. Está no mudo?"], ["Let me check... Yes! Sorry. I'll unmute now. Can you hear me?", "Deixe eu ver... Sim! Desculpe. Vou ativar o microfone. Você me ouve?"]], [{"t": "c", "q": "Sorry, I was on mute. I'll ___ now.", "o": ["unmute", "unmuted", "muting"], "pt": "Desculpe, eu estava no mudo. Vou ativar o microfone agora.", "why": "Depois de I'll vem o verbo simples: unmute."}, {"t": "l", "say": "My connection is very weak today.", "o": ["My connection is very weak today.", "My connection is very week today.", "My collection is very weak today."], "why": "Connection é conexão; collection é coleção."}, {"t": "b", "pt": "Você pode compartilhar sua tela", "w": ["Can", "you", "share", "your", "screen"]}, {"t": "b", "pt": "Por favor, não me interrompa", "w": ["Please", "don't", "interrupt", "me"]}]];
