englishA2Plans[268]={"title": "Um boato sobre o parque da cidade", "file": "", "grammar": "Notícias e boatos: it says that… / I heard that…", "goal": "Fale de notícias e boatos com It says that… e I heard that…", "words": [["fact-check", "checar os fatos"], ["mislead", "enganar"], ["believe", "acreditar"], ["evidence", "evidência"], ["false", "falso"], ["proof", "prova"], ["doubt", "dúvida, duvidar"], ["obvious", "óbvio"], ["exaggerate", "exagerar"], ["spread", "espalhar"]]};
englishA2Content[268]=[[["Tom read a post that said the city park will close next week.", "O Tom leu um post que dizia que o parque da cidade fecha na semana que vem."], ["The post says that all the trees are sick.", "O post diz que todas as árvores estão doentes."], ["Elena had her doubts, and she wanted proof.", "A Elena tinha dúvidas e queria prova."], ["She did a quick fact-check on the city's website.", "Ela fez uma checagem rápida no site da prefeitura."], ["The news was false, and there was no evidence.", "A notícia era falsa, e não havia nenhuma evidência."], ["Someone wanted to mislead people, and the rumor spread fast.", "Alguém quis enganar as pessoas, e o boato se espalhou rápido."]], [["Elena, I heard that the city park is closing next week.", "Elena, ouvi dizer que o parque da cidade vai fechar na semana que vem."], ["Really? Where did you hear that?", "Sério? Onde você ouviu isso?"], ["A post says that the trees are sick and dangerous.", "Um post diz que as árvores estão doentes e perigosas."], ["I doubt it. I was there on Sunday, and everything looked fine.", "Duvido. Estive lá no domingo, e estava tudo bem."], ["But the post has 3,000 shares. So many people believe it.", "Mas o post tem 3 mil compartilhamentos. Muita gente acredita."], ["That doesn't mean it's true. People exaggerate online. Is there any proof?", "Isso não quer dizer que é verdade. As pessoas exageram na internet. Tem alguma prova?"], ["No, only a blurry photo. I guess it's obvious now.", "Não, só uma foto borrada. Acho que agora é óbvio."], ["Let's do a fact-check. The city website says that the park is open every day.", "Vamos checar os fatos. O site da prefeitura diz que o parque abre todos os dias."], ["You're right. It's false. Let's stop it before it spreads.", "Você tem razão. É falso. Vamos parar isso antes que se espalhe."], ["Good idea. Someone wanted to mislead us. I'll tell my friends.", "Boa ideia. Alguém quis nos enganar. Vou contar para meus amigos."]], ["/f/ em false e proof", "No /f/, os dentes de cima tocam o lábio de baixo e o ar passa sem vibrar a garganta. Cuidado com proof: termina em /f/, não em 'v'.", ["false", "proof"]], ["The website ___ that the park is open all week.", "says", "say", "O site diz que o parque abre a semana toda.", "Com 'the website' (ele), o verbo no presente leva -s: says."], [["A post says that the trees are sick and dangerous.", "Um post diz que as árvores estão doentes e perigosas."], ["Elena, I heard that the city park is closing next week.", "Elena, ouvi dizer que o parque da cidade vai fechar na semana que vem."]], [{"t": "c", "q": "The article ___ that the bus is free on Sundays.", "o": ["says", "say", "tells"], "pt": "O artigo diz que o ônibus é grátis aos domingos.", "why": "It/article says that… introduz a informação lida."}, {"t": "l", "say": "I heard that the news is false.", "o": ["I heard that the news is false.", "I heard that the news is fast.", "I hear that the news was false."], "why": "False é falso; fast é rápido."}, {"t": "b", "pt": "Eu duvido que seja verdade", "w": ["I", "doubt", "it's", "true"]}, {"t": "b", "pt": "Ouvi dizer que o parque vai fechar", "w": ["I", "heard", "that", "the", "park", "is", "closing"]}]];
