englishA2Plans[269]={"title": "Revisão: uma tarde sem internet", "file": "", "grammar": "Revisão: passado simples, present perfect e conselhos no mundo digital", "goal": "Revise o vocabulário de tecnologia contando uma tarde sem internet.", "words": [["power cut", "queda de energia"], ["paper map", "mapa de papel"], ["rely on", "depender de"], ["boredom", "tédio"], ["disconnect", "desconectar-se"], ["addicted", "viciado"], ["cope", "lidar, dar conta"], ["back online", "de volta à internet"], ["restore", "restabelecer"]]};
englishA2Content[269]=[[["A power cut stopped the internet in Priya's building on Saturday.", "Uma queda de energia parou a internet no prédio da Priya no sábado."], ["Her phone had no signal, so she used a paper map to find the bakery.", "O celular dela estava sem sinal, então ela usou um mapa de papel para achar a padaria."], ["She realized how much she relies on her phone.", "Ela percebeu o quanto depende do celular."], ["Her brother said he was addicted to videos, and he felt boredom after ten minutes.", "O irmão dela disse que era viciado em vídeos e sentiu tédio depois de dez minutos."], ["They decided to disconnect and play a board game.", "Eles decidiram se desconectar e jogar um jogo de tabuleiro."], ["By evening, they could cope without screens, and the lights came back.", "À noite, eles davam conta sem telas, e a luz voltou."]], [["Sam, did the Wi-Fi come back yet?", "Sam, o Wi-Fi já voltou?"], ["No. The company says they'll restore it by seven.", "Não. A empresa diz que vai restabelecer até as sete."], ["Seven? That's three hours! What are we going to do?", "Sete? São três horas! O que vamos fazer?"], ["I don't know. I'm addicted to my videos, and I'm already bored.", "Não sei. Sou viciado nos meus vídeos e já estou entediado."], ["Let's disconnect for once. We can play cards, or I'll cook dinner.", "Vamos nos desconectar por uma vez. Podemos jogar cartas, ou eu faço o jantar."], ["Okay. Honestly, I can cope for one evening. Do we have a flashlight?", "Certo. Sinceramente, aguento uma noite. Temos lanterna?"], ["Yes, in the kitchen drawer. The paper map is there too, if we go out.", "Temos, na gaveta da cozinha. O mapa de papel também está lá, se sairmos."], ["Great. Wait, my phone just buzzed. We're back online!", "Ótimo. Espere, meu celular acabou de vibrar. Voltamos à internet!"], ["Already? Let's keep the cards on the table. We can check the news later.", "Já? Vamos deixar as cartas na mesa. Dá para ver as notícias depois."], ["Deal. Cards first, phone later.", "Combinado. Cartas primeiro, celular depois."]], ["/b/ em back e boredom", "No /b/, os lábios se fecham e soltam o ar com a garganta vibrando. Em boredom, o acento cai na primeira sílaba: BOR-dom.", ["back", "boredom"]], ["I ___ a paper map because my phone had no signal.", "used", "use", "Usei um mapa de papel porque o celular estava sem sinal.", "A história aconteceu no passado, então o verbo é used."], [["Her phone had no signal, so she used a paper map to find the bakery.", "O celular dela estava sem sinal, então ela usou um mapa de papel para achar a padaria."], ["She realized how much she relies on her phone.", "Ela percebeu o quanto depende do celular."]], [{"t": "c", "q": "The power was off, so we ___ cards.", "o": ["played", "play", "playing"], "pt": "A luz estava apagada, então jogamos cartas.", "why": "Ação terminada no passado: played."}, {"t": "l", "say": "We're back online!", "o": ["We're back online!", "We're back on line up!", "We're black online!"], "why": "Back online é de volta à internet."}, {"t": "b", "pt": "Eu dependo muito do meu celular", "w": ["I", "rely", "on", "my", "phone", "a", "lot"]}, {"t": "b", "pt": "Vamos nos desconectar só por esta noite", "w": ["Let's", "disconnect", "for", "tonight"]}]];
englishA2PhotoThemes[269]="flag";
englishA2MiniStories[269]=["Um dia sem internet", "On Saturday, Rosa tried to log in to her bus app, but her phone kept freezing up.~No sábado, a Rosa tentou entrar no app de ônibus, mas o celular ficava travando.|She wanted to find out the route, so she searched for it in her browser.~Ela queria descobrir o trajeto, então procurou no navegador.|Nothing loaded because a power cut had stopped the Wi-Fi in the whole street.~Nada carregou porque uma queda de energia parou o Wi-Fi na rua inteira.|Her friend Tom sent a voice message, but she couldn't receive it.~O amigo Tom mandou uma mensagem de voz, mas ela não conseguiu receber.|She thought, I must buy a paper map for days like this.~Ela pensou: preciso comprar um mapa de papel para dias assim.|Later Tom texted, “Don't believe the rumors about the bus. I'll call back soon.”~Mais tarde o Tom escreveu: “Não acredite nos boatos sobre o ônibus. Eu ligo de volta logo.”|Rosa decided to disconnect, and she walked to the bakery.~A Rosa decidiu se desconectar e foi a pé até a padaria.|She has never felt such boredom, but she has never seen her street so quiet.~Ela nunca sentiu tanto tédio, mas também nunca viu a rua tão silenciosa.|At six, the network was back online, and she saw Tom's reaction to her photo.~Às seis, a rede voltou, e ela viu a reação do Tom à foto dela.|She wrote a caption and posted, “I can cope without the internet!”~Ela escreveu uma legenda e postou: “Eu dou conta sem internet!”"];
englishA2ExtraWordExamples[269]={"rely on": ["We rely on the Wi-Fi for everything.", "Dependemos do Wi-Fi para tudo."]};
englishA2Plans[270]={"title": "Planejando um passeio a pé pelo centro histórico", "file": "", "grammar": "Planejar um passeio: places to visit e how to get there (on foot, by bus)", "goal": "Planeje o dia e pergunte How do we get there? usando on foot e by bus.", "words": [["city tour", "passeio pela cidade"], ["walking tour", "passeio a pé guiado"], ["tourist attraction", "atração turística"], ["on foot", "a pé"], ["day trip", "bate-volta de um dia"], ["opening hours", "horário de funcionamento"], ["worth visiting", "que vale a visita"], ["scenic", "de paisagem bonita"], ["travel guide", "guia de viagem"]]};
englishA2Content[270]=[[["Ana and Ben have one free day, so they plan a city tour.", "Ana e Ben têm um dia livre, então planejam um passeio pela cidade."], ["The travel guide says the old town is worth visiting.", "O guia de viagem diz que a cidade velha vale a visita."], ["It isn't far, so they can get there on foot.", "Não é longe, então eles podem chegar lá a pé."], ["The museum has short opening hours, so they go there first.", "O museu tem horário curto, então eles vão lá primeiro."], ["After lunch, they join a walking tour with a funny guide.", "Depois do almoço, eles entram num passeio a pé com um guia engraçado."], ["In the evening, they take a scenic road to the river and watch the sunset.", "À noite, eles pegam uma estrada de paisagem bonita até o rio e veem o pôr do sol."]], [["Which tourist attraction should we see first, Ben?", "Qual atração turística devemos ver primeiro, Ben?"], ["The castle is the biggest one, but it closes at four.", "O castelo é a maior, mas fecha às quatro."], ["Then let's go now. How do we get there from the hotel?", "Então vamos agora. Como chegamos lá a partir do hotel?"], ["We can take bus 12, or we can walk. It's only twenty minutes.", "Podemos pegar o ônibus 12 ou ir andando. São só vinte minutos."], ["I'd rather go on foot. I want to take photos of the old streets.", "Prefiro ir a pé. Quero tirar fotos das ruas antigas."], ["Good idea. Tomorrow we can do a day trip to the coast, if it's sunny.", "Boa ideia. Amanhã podemos fazer um bate-volta até a costa, se estiver sol."], ["Great! Is it easy to get there?", "Ótimo! É fácil chegar lá?"], ["Yes, I checked. There's a train every hour, so let's buy the tickets after dinner.", "Sim, eu conferi. Tem um trem a cada hora, então vamos comprar as passagens depois do jantar."]], ["/ɪ/ curto em visit e city", "O 'i' é curto e relaxado, bem diferente do 'i' longo de 'vi'. Diga 'VIZ-it' e 'SIT-i', sem alongar a vogal.", ["visit", "city"]], ["We can get to the castle ___ foot.", "on", "by", "Nós podemos chegar ao castelo a pé.", "Em português dizemos 'a pé', mas em inglês a expressão fixa é on foot."], [["It isn't far, so they can get there on foot.", "Não é longe, então eles podem chegar lá a pé."], ["Then let's go now. How do we get there from the hotel?", "Então vamos agora. Como chegamos lá a partir do hotel?"]], [{"t": "c", "q": "The old market is close. We can go ___ foot.", "o": ["on", "by", "with"], "pt": "O mercado antigo é perto. Podemos ir a pé.", "why": "A expressão fixa é on foot; by é para veículos, como by bus."}, {"t": "l", "say": "We can get there on foot.", "o": ["We can get there on foot.", "We can't get there on foot.", "We can see there on foot."], "why": "Você ouviu can (não can't) e o verbo get there, que quer dizer chegar lá."}, {"t": "b", "pt": "Como chegamos ao castelo?", "w": ["How", "do", "we", "get", "to", "the", "castle"]}, {"t": "b", "pt": "Esse museu vale a visita.", "w": ["This", "museum", "is", "worth", "visiting"]}]];
