englishA2Plans[271]={"title": "Visita ao museu de arte com audioguia", "file": "", "grammar": "Passado simples (regular e irregular) para contar uma visita ao museu", "goal": "Conte o que você fez no museu: I took, I paid, I left, I bought.", "words": [["audio guide", "audioguia"], ["guided tour", "visita guiada"], ["admission", "entrada, ingresso"], ["gift shop", "lojinha de lembranças"], ["cloakroom", "guarda-volumes"], ["ticket office", "bilheteria"], ["student discount", "desconto de estudante"], ["line up", "entrar na fila"], ["on display", "em exposição"], ["curator", "curador"]]};
englishA2Content[271]=[[["Omar visited the art museum on Sunday morning.", "Omar visitou o museu de arte no domingo de manhã."], ["He had to line up at the ticket office for ten minutes.", "Ele teve de entrar na fila da bilheteria por dez minutos."], ["The admission was twelve dollars, but he got a student discount.", "A entrada custou doze dólares, mas ele ganhou desconto de estudante."], ["He left his coat in the cloakroom and took an audio guide.", "Ele deixou o casaco no guarda-volumes e pegou um audioguia."], ["Then he joined a guided tour, and the curator showed the paintings on display in room four.", "Depois ele entrou numa visita guiada, e o curador mostrou as pinturas em exposição na sala quatro."], ["At the end, he bought a small book in the gift shop.", "No final, ele comprou um livrinho na lojinha."]], [["How was the museum yesterday, Omar?", "Como foi o museu ontem, Omar?"], ["It was great! I stayed there for three hours.", "Foi ótimo! Fiquei lá por três horas."], ["Really? Did you pay the full price?", "Sério? Você pagou o preço inteiro?"], ["No, I showed my student card, so I paid only six dollars.", "Não, mostrei minha carteirinha de estudante, então paguei só seis dólares."], ["Nice! Did you take the audio guide or a guided tour?", "Legal! Você pegou o audioguia ou fez a visita guiada?"], ["I took the tour. The curator told funny stories about every painting.", "Fiz a visita. O curador contou histórias engraçadas sobre cada pintura."], ["I want to go next Saturday. Did they change the hours?", "Quero ir no próximo sábado. Eles mudaram o horário?"], ["No, they didn't. It still opens at nine, and you can leave your bag in the cloakroom.", "Não, não mudaram. Ainda abre às nove, e você pode deixar a bolsa no guarda-volumes."]], ["/k/ aspirado em curator e cloakroom", "O 'c' inicial leva um sopro de ar, como um 'quê' leve. Diga 'KYUR-ei-ter', com a força no começo, e 'KLOK-room'.", ["curator", "cloakroom"]], ["I ___ my coat in the cloakroom an hour ago.", "left", "leaved", "Eu deixei meu casaco no guarda-volumes há uma hora.", "Leave é irregular: o passado é left, não leaved."], [["The admission was twelve dollars, but he got a student discount.", "A entrada custou doze dólares, mas ele ganhou desconto de estudante."], ["No, I showed my student card, so I paid only six dollars.", "Não, mostrei minha carteirinha de estudante, então paguei só seis dólares."]], [{"t": "c", "q": "Yesterday, Priya ___ the audio guide.", "o": ["took", "taked", "take"], "pt": "Ontem, Priya pegou o audioguia.", "why": "Take é irregular e ontem pede passado: took."}, {"t": "l", "say": "I paid only six dollars.", "o": ["I paid only six dollars.", "I pay only six dollars.", "I paid only sixty dollars."], "why": "Você ouviu o passado paid e o número six, não sixty."}, {"t": "b", "pt": "Eu visitei o museu ontem.", "w": ["I", "visited", "the", "museum", "yesterday"]}, {"t": "b", "pt": "Nós compramos os ingressos na bilheteria.", "w": ["We", "bought", "the", "tickets", "at", "the", "ticket", "office"]}]];
