englishA2Plans[274]={"title": "Comprando passagem de trem numa estação desconhecida", "file": "", "grammar": "Single e return, qual plataforma e atraso: Which platform? / There's a delay", "goal": "Compre uma passagem de ida ou de ida e volta e pergunte Which platform?", "words": [["single ticket", "passagem só de ida"], ["return ticket", "passagem de ida e volta"], ["round trip", "viagem de ida e volta"], ["ticket machine", "máquina de bilhetes"], ["peak hour", "horário de pico"], ["aboard", "a bordo"], ["railroad", "ferrovia"], ["overnight", "durante a noite"]]};
englishA2Content[274]=[[["Noah arrives at the railroad station in Chicago at eight.", "Noah chega à estação ferroviária de Chicago às oito."], ["It's peak hour, so he uses the ticket machine.", "É horário de pico, então ele usa a máquina de bilhetes."], ["The machine asks, \"Single ticket or return ticket?\"", "A máquina pergunta: \"Só ida ou ida e volta?\""], ["Noah chooses a round trip because he'll come back on Sunday.", "Noah escolhe ida e volta porque vai voltar no domingo."], ["The board shows a delay, so he waits on platform four.", "O painel mostra um atraso, então ele espera na plataforma quatro."], ["Finally, he gets aboard and finds a window seat.", "Por fim, ele embarca e acha um lugar na janela."]], [["Excuse me, the ticket machine doesn't take my card.", "Com licença, a máquina de bilhetes não aceita meu cartão."], ["Sorry about that. Where are you going?", "Sinto muito. Para onde você vai?"], ["To Boston. I need a return ticket for Sunday evening.", "Para Boston. Preciso de uma passagem de ida e volta para domingo à noite."], ["A return ticket is sixty dollars. It's cheaper than two single tickets.", "A de ida e volta custa sessenta dólares. É mais barata que duas só de ida."], ["Okay. Which platform does the train leave from?", "Certo. De qual plataforma o trem sai?"], ["Platform six, but there's a twenty-minute delay because of a signal problem.", "Plataforma seis, mas há um atraso de vinte minutos por causa de um problema de sinal."], ["That's okay. Does the train go straight to Boston?", "Tudo bem. O trem vai direto para Boston?"], ["Yes, it's direct. It arrives at ten fifteen, so you'll be there for dinner.", "Sim, é direto. Chega às dez e quinze, então você chega a tempo do jantar."]], ["/ɪ/ curto em ticket e single", "O 'i' é curto e relaxado: 'TIK-it' e 'SING-gul'. Não diga 'tíquiti' com vogal no fim.", ["ticket", "single"]], ["Two return tickets ___ Boston, please.", "to", "at", "Duas passagens de ida e volta para Boston, por favor.", "Para indicar o destino, usamos to: tickets to Boston."], [["It's peak hour, so he uses the ticket machine.", "É horário de pico, então ele usa a máquina de bilhetes."], ["Okay. Which platform does the train leave from?", "Certo. De qual plataforma o trem sai?"]], [{"t": "c", "q": "Which ___ does the train leave from?", "o": ["platform", "corner", "garden"], "pt": "De qual plataforma o trem sai?", "why": "Em estações, os trens saem de uma platform, a plataforma."}, {"t": "l", "say": "I need a return ticket for Sunday.", "o": ["I need a return ticket for Sunday.", "I need a single ticket for Sunday.", "I need a return ticket for Saturday."], "why": "Você ouviu return (ida e volta) e Sunday (domingo)."}, {"t": "b", "pt": "Há um atraso de vinte minutos.", "w": ["There", "is", "a", "delay", "of", "twenty", "minutes"]}, {"t": "b", "pt": "Eu preciso de uma passagem só de ida.", "w": ["I", "need", "a", "single", "ticket"]}]];
englishA2PhotoThemes[274]="ticket";
englishA2ExtraWordExamples[274]={"overnight": ["I took an overnight train to Boston last winter.", "Eu peguei um trem noturno para Boston no inverno passado."]};
englishA2Plans[275]={"title": "Pedindo dicas de comida local ao recepcionista", "file": "", "grammar": "Pedir e dar recomendações: What do you recommend? / You should try…", "goal": "Peça uma dica com What do you recommend? e responda com You should try…", "words": [["recommend", "recomendar"], ["hidden gem", "joia escondida"], ["must-see", "imperdível"], ["off the beaten track", "fora do roteiro comum"], ["local dish", "prato típico"], ["highly recommended", "muito recomendado"], ["tourist trap", "armadilha para turistas"], ["specialty", "especialidade"], ["worth a visit", "vale a visita"]]};
englishA2Content[275]=[[["Mia is new in Oaxaca and wants to eat something local.", "Mia é nova em Oaxaca e quer comer algo típico."], ["She asks the hotel clerk, \"What do you recommend?\"", "Ela pergunta ao recepcionista: \"O que você recomenda?\""], ["He says the main square is a tourist trap, so she should walk to a smaller street.", "Ele diz que a praça principal é uma armadilha para turistas, então ela deve ir a uma rua menor."], ["A tiny restaurant there is a hidden gem, and its specialty is chicken with a dark chocolate sauce.", "Um restaurantezinho lá é uma joia escondida, e sua especialidade é frango com molho de chocolate amargo."], ["It's off the beaten track, but locals say it's worth a visit.", "Fica fora do roteiro comum, mas os moradores dizem que vale a visita."], ["Mia tries the local dish, and she loves it.", "Mia prova o prato típico, e adora."]], [["Excuse me, what do you recommend for dinner tonight?", "Com licença, o que você recomenda para o jantar hoje?"], ["You should try Casa Lupe. It's highly recommended.", "Você deveria experimentar a Casa Lupe. É muito recomendada."], ["Is it near here? I don't want a tourist trap.", "Fica perto daqui? Não quero uma armadilha para turistas."], ["No, it's a hidden gem, about ten minutes on foot. Order the black mole.", "Não, é uma joia escondida, uns dez minutos a pé. Peça o mole negro."], ["Sounds good. Is there anything else that's a must-see?", "Parece ótimo. Tem mais alguma coisa imperdível?"], ["Definitely the Sunday market. You shouldn't miss it.", "Com certeza o mercado de domingo. Você não deve perder."], ["Great. Should I book a table?", "Ótimo. Devo reservar uma mesa?"], ["Yes, you should. I'll call them for you right now.", "Sim, deve. Vou ligar para eles agora mesmo."]], ["Acento em recommend e specialty", "Em recommend a força vai para a última sílaba: rek-uh-MEND. Em specialty a força fica no começo: SPESH-ul-tee.", ["recommend", "specialty"]], ["You should ___ the fish soup.", "try", "to try", "Você deveria experimentar a sopa de peixe.", "Depois de should o verbo fica sem to: should try."], [["She asks the hotel clerk, \"What do you recommend?\"", "Ela pergunta ao recepcionista: \"O que você recomenda?\""], ["You should try Casa Lupe. It's highly recommended.", "Você deveria experimentar a Casa Lupe. É muito recomendada."]], [{"t": "c", "q": "You should ___ the local dish.", "o": ["try", "to try", "trying"], "pt": "Você deveria experimentar o prato típico.", "why": "Should é modal e pede verbo simples, sem to e sem -ing."}, {"t": "l", "say": "What do you recommend?", "o": ["What do you recommend?", "What do you remember?", "What do you wear?"], "why": "Você ouviu recommend, pedir uma dica, e não remember."}, {"t": "b", "pt": "Você deveria experimentar o prato típico.", "w": ["You", "should", "try", "the", "local", "dish"]}, {"t": "b", "pt": "É uma joia escondida.", "w": ["It", "is", "a", "hidden", "gem"]}]];
