englishA2Plans[276]={"title": "Contando como foi a viagem ao Peru", "file": "", "grammar": "Present perfect (have you ever been?) e passado simples (I went there last summer)", "goal": "Pergunte Have you ever been to…? e conte quando foi com o passado simples.", "words": [["honeymoon", "lua de mel"], ["last summer", "verão passado"], ["the best part", "a melhor parte"], ["jet lag", "cansaço do fuso horário"], ["hiking trail", "trilha"], ["road trip", "viagem de carro"], ["tour group", "grupo de turismo"], ["cable car", "bondinho"], ["once in a lifetime", "única na vida"]]};
englishA2Content[276]=[[["Priya and Sam have been to Peru twice.", "Priya e Sam já estiveram no Peru duas vezes."], ["The first time was their honeymoon, and the second time was last summer.", "A primeira vez foi a lua de mel, e a segunda foi no verão passado."], ["Last summer they took a road trip and walked on a famous hiking trail.", "No verão passado eles fizeram uma viagem de carro e andaram numa trilha famosa."], ["They have never felt so tired, and the jet lag lasted three days.", "Eles nunca se sentiram tão cansados, e o cansaço do fuso durou três dias."], ["The best part was the ride in a cable car over the mountains.", "A melhor parte foi o passeio de bondinho sobre as montanhas."], ["It was once in a lifetime, and their tour group clapped at the top.", "Foi uma experiência única na vida, e o grupo de turismo aplaudiu lá em cima."]], [["Omar, have you ever been to Peru?", "Omar, você já esteve no Peru?"], ["Yes, I have. I went there last summer with a tour group.", "Já, sim. Fui lá no verão passado com um grupo de turismo."], ["Wow! How long did you stay, and what was the best part?", "Uau! Quanto tempo ficou, e qual foi a melhor parte?"], ["Two weeks. The best part was the cable car, and I have never seen such big mountains.", "Duas semanas. A melhor parte foi o bondinho, e nunca vi montanhas tão grandes."], ["Did you walk on the hiking trail, too?", "Você também andou na trilha?"], ["Yes, we did. It took five hours, and the jet lag didn't help.", "Sim, andamos. Levou cinco horas, e o cansaço do fuso não ajudou."], ["I've never been to South America. I'd love to go on a road trip there.", "Nunca estive na América do Sul. Eu adoraria fazer uma viagem de carro por lá."], ["You should! I'll send you my photos tonight.", "Você deveria! Vou te mandar minhas fotos hoje à noite."]], ["/dʒ/ em jet lag", "O 'j' inglês soa como 'dj' em 'djalma': 'djét'. Em lag o 'a' é aberto, entre 'é' e 'a': 'lég'.", ["jet", "lag"]], ["I have been to Peru, and I ___ there last summer.", "went", "have gone", "Já estive no Peru, e fui lá no verão passado.", "Com last summer (tempo definido) usamos o passado simples: went."], [["Priya and Sam have been to Peru twice.", "Priya e Sam já estiveram no Peru duas vezes."], ["Yes, I have. I went there last summer with a tour group.", "Já, sim. Fui lá no verão passado com um grupo de turismo."]], [{"t": "c", "q": "I have never ___ to Japan.", "o": ["been", "went", "go"], "pt": "Eu nunca estive no Japão.", "why": "Have never pede o particípio: been."}, {"t": "l", "say": "Have you ever been to Peru?", "o": ["Have you ever been to Peru?", "Has she ever been to Peru?", "Have you ever been in Paris?"], "why": "Você ouviu Have you (você) e Peru, não Paris."}, {"t": "b", "pt": "Eu fui ao Peru no verão passado.", "w": ["I", "went", "to", "Peru", "last", "summer"]}, {"t": "b", "pt": "Você já esteve no Chile?", "w": ["Have", "you", "ever", "been", "to", "Chile"]}]];
