englishA2Plans[277]={"title": "Reclamando da mala perdida no aeroporto", "file": "", "grammar": "Problemas na viagem: so e because (The flight was late, so I missed my connection)", "goal": "Explique um problema de viagem ligando causa e resultado com so e because.", "words": [["lost luggage", "bagagem perdida"], ["baggage claim", "esteira de bagagens"], ["claim form", "formulário de reclamação"], ["missed connection", "conexão perdida"], ["rebook", "remarcar"], ["compensation", "indenização"], ["stranded", "sem ter como seguir viagem"], ["overbooked", "com excesso de reservas"], ["lost property", "achados e perdidos"]]};
englishA2Content[277]=[[["Elena lands in Miami after a long flight.", "Elena pousa em Miami depois de um voo longo."], ["She waits at the baggage claim for forty minutes, but her bag never comes.", "Ela espera na esteira de bagagens por quarenta minutos, mas a mala dela nunca chega."], ["Her first flight was late, so she also had a missed connection.", "O primeiro voo dela atrasou, então ela também teve uma conexão perdida."], ["At the desk, she fills out a claim form for her lost luggage.", "No balcão, ela preenche um formulário de reclamação pela bagagem perdida."], ["The clerk is kind, but Elena feels tired and stranded.", "O atendente é gentil, mas Elena se sente cansada e sem ter como seguir."], ["The next day, the airline brings her bag to the hotel, and she smiles again.", "No dia seguinte, a companhia traz a mala dela ao hotel, e ela volta a sorrir."]], [["Excuse me, my suitcase didn't come out. Where can I ask?", "Com licença, minha mala não saiu. Onde posso perguntar?"], ["I'm sorry. Did you already check lost property?", "Sinto muito. Você já olhou nos achados e perdidos?"], ["Yes, they don't have it. Also, I missed my connection, so I'm stuck here.", "Já, e não está lá. Além disso, perdi minha conexão, então estou presa aqui."], ["Your flight to Orlando was overbooked, but I can rebook you for tomorrow at nine.", "Seu voo para Orlando estava com excesso de reservas, mas posso remarcar para amanhã às nove."], ["Tomorrow? That's a long time. Will the airline pay for a hotel?", "Amanhã? É muito tempo. A companhia paga um hotel?"], ["Yes, you'll get compensation of one hundred dollars, and we'll find your bag.", "Sim, você receberá uma indenização de cem dólares, e vamos achar sua mala."], ["Thanks. Where do I get the claim form?", "Obrigada. Onde pego o formulário de reclamação?"], ["Right here. Fill it out, and we'll call you tonight.", "Aqui mesmo. Preencha, e ligaremos para você hoje à noite."]], ["/æ/ em baggage e stranded", "O 'a' é aberto, entre 'é' e 'a': 'BÉ-gij' e 'STRÉN-did'. Não diga 'bagagi' como em português.", ["baggage", "stranded"]], ["The flight was late, ___ I missed my connection.", "so", "because", "O voo atrasou, então perdi minha conexão.", "So introduz o resultado; because introduziria a causa."], [["Her first flight was late, so she also had a missed connection.", "O primeiro voo dela atrasou, então ela também teve uma conexão perdida."], ["Yes, they don't have it. Also, I missed my connection, so I'm stuck here.", "Já, e não está lá. Além disso, perdi minha conexão, então estou presa aqui."]], [{"t": "c", "q": "My flight was late, ___ I missed my connection.", "o": ["so", "because", "or"], "pt": "Meu voo atrasou, então perdi minha conexão.", "why": "A conexão perdida é o resultado do atraso, então usamos so."}, {"t": "l", "say": "I missed my connection.", "o": ["I missed my connection.", "I made my connection.", "I missed my reservation."], "why": "Você ouviu missed (perdi) e connection, não made nem reservation."}, {"t": "b", "pt": "Minha mala não chegou.", "w": ["My", "bag", "did", "not", "arrive"]}, {"t": "b", "pt": "Preencha o formulário de reclamação, por favor.", "w": ["Please", "fill", "out", "the", "claim", "form"]}]];
