englishA2Plans[278]={"title": "Fotos no mirante e lembrancinhas para a mãe", "file": "", "grammar": "Pedidos educados: Could you take a photo of us? (take, não make nem do)", "goal": "Peça para alguém tirar uma foto com Could you take a photo of us?", "words": [["photo spot", "lugar bom para fotos"], ["group photo", "foto em grupo"], ["take photos", "tirar fotos"], ["memory card", "cartão de memória"], ["memories", "lembranças"], ["souvenir shop", "loja de souvenires"], ["fridge magnet", "ímã de geladeira"], ["handmade", "feito à mão"], ["bring back", "trazer de volta"]]};
englishA2Content[278]=[[["Kenji and Rosa find a great photo spot on top of the hill.", "Kenji e Rosa acham um ótimo lugar para fotos no alto do morro."], ["They ask a stranger to take a group photo with the whole city behind them.", "Eles pedem a um desconhecido uma foto em grupo com a cidade inteira ao fundo."], ["Kenji likes to take photos of food, doors, and cats.", "Kenji gosta de tirar fotos de comida, portas e gatos."], ["His memory card is almost full, so he deletes ten bad pictures.", "O cartão de memória dele está quase cheio, então ele apaga dez fotos ruins."], ["Rosa goes into a souvenir shop and buys a handmade fridge magnet.", "Rosa entra numa loja de souvenires e compra um ímã de geladeira feito à mão."], ["She wants to bring back something small for her mother, and the magnet keeps her memories close.", "Ela quer trazer algo pequeno para a mãe, e o ímã mantém as lembranças por perto."]], [["Excuse me, could you take a photo of us, please?", "Com licença, você poderia tirar uma foto de nós, por favor?"], ["Sure. Where do you want to stand?", "Claro. Onde vocês querem ficar?"], ["By the fountain, with the bridge behind us.", "Perto da fonte, com a ponte atrás de nós."], ["Smile! One, two, three... Oh, it's a little blurry. Let me try again.", "Sorriam! Um, dois, três... Ah, ficou meio tremida. Deixe-me tentar de novo."], ["Thanks! This is a great spot, isn't it?", "Obrigado! Este lugar é ótimo, não é?"], ["Yes, I come here every weekend. Do you want a souvenir for your family?", "Sim, venho aqui todo fim de semana. Vocês querem um souvenir para a família?"], ["Yes, for my mother. Do you know a good place?", "Sim, para minha mãe. Você conhece um lugar bom?"], ["There's a shop around the corner with cheap magnets. Turn left at the café.", "Tem uma loja na esquina com ímãs baratos. Vire à esquerda no café."]], ["/ɑ/ em shop e spot", "A boca fica bem aberta, como no 'a' de 'pá' curto. Termine em consoante: 'SHÓP' e 'SPÓT', sem 'i' no fim.", ["shop", "spot"]], ["Could you ___ a photo of us, please?", "take", "make", "Você poderia tirar uma foto de nós, por favor?", "Em inglês a foto se 'toma': take a photo, nunca make a photo."], [["Excuse me, could you take a photo of us, please?", "Com licença, você poderia tirar uma foto de nós, por favor?"], ["Kenji likes to take photos of food, doors, and cats.", "Kenji gosta de tirar fotos de comida, portas e gatos."]], [{"t": "c", "q": "She wants to ___ something back for her mom.", "o": ["bring", "carry", "put"], "pt": "Ela quer trazer algo de volta para a mãe.", "why": "A expressão fixa é bring back, trazer de volta."}, {"t": "l", "say": "Could you take a photo of us?", "o": ["Could you take a photo of us?", "Could you make a photo of us?", "Could you take a photo for us?"], "why": "Você ouviu take a photo of us, a forma natural do pedido."}, {"t": "b", "pt": "Você poderia tirar uma foto de nós?", "w": ["Could", "you", "take", "a", "photo", "of", "us"]}, {"t": "b", "pt": "Meu cartão de memória está cheio.", "w": ["My", "memory", "card", "is", "full"]}]];
