englishA2Plans[279]={"title": "Revisão: o diário de viagem de Ben no Japão", "file": "", "grammar": "Revisão: passado simples, present perfect, should e would like", "goal": "Revise a viagem inteira: planos, hospedagem, passeios, problemas e lembranças.", "words": [["travel diary", "diário de viagem"], ["bucket list", "lista de sonhos"], ["travel plans", "planos de viagem"], ["pack up", "fazer as malas"], ["last day", "último dia"], ["travel agent", "agente de viagens"], ["local market", "mercado local"], ["hostel", "albergue"], ["local guide", "guia local"]]};
englishA2Content[279]=[[["Ben has a bucket list, and Japan is first on it.", "Ben tem uma lista de sonhos, e o Japão é o primeiro dela."], ["He sees a travel agent about his travel plans.", "Ele fala com uma agente de viagens sobre seus planos de viagem."], ["He books a cheap hostel near the station.", "Ele reserva um albergue barato perto da estação."], ["Every night he is going to write in his travel diary.", "Toda noite ele vai escrever no diário de viagem."], ["A local guide shows him a local market, where he buys green tea.", "Um guia local mostra a ele um mercado local, onde ele compra chá verde."], ["On the last day, he has to pack up before breakfast, and he feels sad.", "No último dia, ele tem de fazer as malas antes do café, e fica triste."]], [["Hello, Ben. Have you made your travel plans?", "Olá, Ben. Você já fez seus planos de viagem?"], ["Not yet. Japan is on my bucket list, and I'd like to go in April.", "Ainda não. O Japão está na minha lista de sonhos, e eu gostaria de ir em abril."], ["Good choice. Do you want a hotel or a hostel?", "Boa escolha. Você quer um hotel ou um albergue?"], ["A hostel, please. I'm traveling alone, and I don't have much money.", "Um albergue, por favor. Estou viajando sozinho e não tenho muito dinheiro."], ["I know a nice one. It's near a local market, and a local guide can show you around.", "Conheço um bom. Fica perto de um mercado local, e um guia local pode mostrar a região."], ["Perfect. How much is it for a week?", "Perfeito. Quanto custa por uma semana?"], ["About four hundred dollars. You should book before March, because it gets full.", "Cerca de quatrocentos dólares. Você deveria reservar antes de março, porque lota."], ["Okay, let's do it today. I'll start my travel diary on the plane!", "Certo, vamos fazer isso hoje. Vou começar meu diário de viagem no avião!"]], ["/h/ aspirado em hostel e have", "O 'h' inglês é um sopro suave na garganta, sem o 'rr' do português. Diga 'HÓS-tel' e 'HÉV', não 'rostel'.", ["hostel", "have"]], ["Ben ___ a travel diary every night in Kyoto.", "wrote", "writed", "Ben escreveu um diário de viagem toda noite em Kyoto.", "Write é irregular: o passado é wrote, não writed."], [["He sees a travel agent about his travel plans.", "Ele fala com uma agente de viagens sobre seus planos de viagem."], ["About four hundred dollars. You should book before March, because it gets full.", "Cerca de quatrocentos dólares. Você deveria reservar antes de março, porque lota."]], [{"t": "c", "q": "Ben ___ his travel plans yesterday.", "o": ["made", "maked", "makes"], "pt": "Ben fez seus planos de viagem ontem.", "why": "Ontem pede passado, e make é irregular: made."}, {"t": "l", "say": "I have never been to Japan.", "o": ["I have never been to Japan.", "I never have been to Japan.", "I have ever been to Japan."], "why": "Você ouviu have never been, a ordem natural do present perfect."}, {"t": "b", "pt": "Ele anotou tudo no diário de viagem.", "w": ["He", "wrote", "everything", "in", "his", "travel", "diary"]}, {"t": "b", "pt": "Você deveria reservar um albergue.", "w": ["You", "should", "book", "a", "hostel"]}]];
englishA2PhotoThemes[279]="ticket";
englishA2MiniStories[279]=["O diário de viagem de Ben", "Ben wrote in his travel diary every night in Kyoto.~Ben escreveu no diário de viagem toda noite em Kyoto.|On day one, he walked on foot through the old town and visited a museum.~No primeiro dia, ele andou a pé pela cidade velha e visitou um museu.|He took an audio guide, but the battery died after an hour.~Ele pegou um audioguia, mas a bateria acabou em uma hora.|On day two, he bought a return ticket, but there was a delay of an hour.~No segundo dia, ele comprou uma passagem de ida e volta, mas houve um atraso de uma hora.|He missed his connection and felt stranded at a small station.~Ele perdeu a conexão e se sentiu sem saída numa estação pequena.|A kind woman recommended a hidden gem restaurant, and he tried the local dish.~Uma mulher gentil recomendou um restaurante escondido, e ele provou o prato típico.|The next morning, he took part in a small festival and watched a parade.~Na manhã seguinte, ele participou de um festival pequeno e assistiu a um desfile.|He asked a stranger to take a photo of him with the dancers.~Ele pediu a um desconhecido que tirasse uma foto dele com os dançarinos.|In a souvenir shop, he bought a handmade fridge magnet for his mom.~Numa loja de souvenires, ele comprou um ímã de geladeira feito à mão para a mãe.|On his last night, Ben wrote, \"I have never had such a great trip, and I want to come back.\"~Na última noite, Ben escreveu: \"Nunca fiz uma viagem tão boa, e quero voltar.\""];
englishA2Plans[280]={"title": "Pão de banana passo a passo", "file": "", "grammar": "Seguir uma receita: first, then, add, stir (imperativo em sequência)", "goal": "Explique uma receita simples em ordem usando First, Then e verbos no imperativo.", "words": [["stir in", "acrescentar mexendo"], ["chop up", "picar"], ["pour in", "despejar"], ["mix well", "misturar bem"], ["set aside", "deixar de lado"], ["bake for", "assar por"], ["preheat", "pré-aquecer"], ["sliced", "fatiado"], ["turn down", "abaixar (o fogo)"], ["bring to a boil", "levar à fervura"]]};
englishA2Content[280]=[[["Ana wants to make banana bread, so first she preheats the oven.", "Ana quer fazer pão de banana, então primeiro ela pré-aquece o forno."], ["Then she chops up three bananas and pours in some milk.", "Depois ela pica três bananas e despeja um pouco de leite."], ["Next, she needs to stir in the sugar and the flour and mix well.", "Depois, ela precisa acrescentar o açúcar e a farinha mexendo e misturar bem."], ["Then she needs to set aside the bowl and put the pan in the oven.", "Depois ela precisa deixar a tigela de lado e pôr a forma no forno."], ["She will bake for fifty minutes, and the kitchen will smell great.", "Ela vai assar por cinquenta minutos, e a cozinha vai ficar com um cheiro ótimo."], ["Ana serves the bread sliced, and her brother eats three pieces.", "Ana serve o pão fatiado, e o irmão dela come três pedaços."]], [["Ben, are you cooking lunch? I can hear the pan.", "Ben, você está fazendo o almoço? Estou ouvindo a panela."], ["Yes, I'm making tomato soup, but I don't know the steps.", "Sim, estou fazendo sopa de tomate, mas não sei os passos."], ["Easy. First, chop up two onions and fry them in a little oil.", "Fácil. Primeiro pique duas cebolas e frite em um pouco de óleo."], ["OK, the onions are in the pan. What's next?", "Certo, as cebolas estão na panela. E agora?"], ["Pour in the tomatoes and bring to a boil. Then turn down the heat.", "Despeje os tomates e leve à fervura. Depois abaixe o fogo."], ["Wait, the soup is boiling over! Is that bad?", "Espera, a sopa está transbordando! Isso é ruim?"], ["Turn down the heat now! Then stir for one minute.", "Abaixe o fogo agora! Depois mexa por um minuto."], ["Phew, it looks good. Should I add salt?", "Ufa, está com uma cara boa. Devo pôr sal?"], ["Yes, but add just a little. Then serve it with sliced bread.", "Sim, mas só um pouquinho. Depois sirva com pão fatiado."], ["Great, I have some sliced bread. I'll send you a picture in ten minutes.", "Ótimo, tenho pão fatiado. Vou mandar uma foto em dez minutos."]], ["/st/ em stir e steps", "Não coloque um 'e' antes do 'st': diga 'stir', nunca 'estir'. Comece com o 's' e já feche a língua no 't'.", ["stir", "steps"]], ["First, chop the onions. ___, fry them in oil.", "Then", "Than", "Primeiro, pique as cebolas. Depois, frite-as no óleo.", "Para a sequência 'depois' use then; than só aparece em comparações."], [["Easy. First, chop up two onions and fry them in a little oil.", "Fácil. Primeiro pique duas cebolas e frite em um pouco de óleo."], ["Pour in the tomatoes and bring to a boil. Then turn down the heat.", "Despeje os tomates e leve à fervura. Depois abaixe o fogo."]], [{"t": "c", "q": "First, preheat the oven. ___, chop up the bananas.", "o": ["Then", "Than", "Thin"], "pt": "Primeiro, pré-aqueça o forno. Depois, pique as bananas.", "why": "Then liga o próximo passo da receita."}, {"t": "l", "say": "Turn down the heat and stir for one minute.", "o": ["Turn down the heat and stir for one minute.", "Turn up the heat and stir for one minute.", "Turn down the heat and stir for ten minutes."], "why": "Você ouviu turn down (abaixar o fogo) e one minute."}, {"t": "b", "pt": "Primeiro, pique duas cebolas.", "w": ["First", "chop", "up", "two", "onions"]}, {"t": "b", "pt": "Depois, acrescente o sal.", "w": ["Then", "add", "the", "salt"]}]];
