englishA2ExtraWordExamples[280]={"stir in": ["Stir in the flour slowly.", "Misture a farinha devagar."], "mix well": ["Mix well before you bake.", "Misture bem antes de assar."], "set aside": ["Set aside half of the sauce.", "Reserve metade do molho."], "bake for": ["Bake for twenty minutes.", "Asse por vinte minutos."]};
englishA2Plans[281]={"title": "Cupcakes para a festa da escola", "file": "", "grammar": "Medidas e quantidades: a cup of, a spoonful of, a pinch of", "goal": "Use a cup of, a spoonful of e a pinch of para dizer quanto de cada ingrediente você precisa.", "words": [["a cup of", "uma xícara de"], ["a spoonful of", "uma colherada de"], ["a pinch of", "uma pitada de"], ["half a cup", "meia xícara"], ["level off", "nivelar"], ["a dozen", "uma dúzia"], ["a bunch of", "um maço de"], ["simmer", "ferver em fogo baixo"]]};
englishA2Content[281]=[[["Rosa needs a dozen cupcakes for her daughter's school party.", "Rosa precisa de uma dúzia de cupcakes para a festa da escola da filha."], ["She puts a cup of sugar and two cups of flour in a bowl.", "Ela põe uma xícara de açúcar e duas xícaras de farinha numa tigela."], ["She needs to level off the flour with a knife and add a pinch of salt.", "Ela precisa nivelar a farinha com uma faca e acrescentar uma pitada de sal."], ["Then she adds half a cup of milk and a spoonful of vanilla.", "Depois ela acrescenta meia xícara de leite e uma colherada de baunilha."], ["While the cupcakes bake, she lets the strawberry sauce simmer.", "Enquanto os cupcakes assam, ela deixa a calda de morango ferver em fogo baixo."], ["At school, the kids eat every cupcake in ten minutes.", "Na escola, as crianças comem todos os cupcakes em dez minutos."]], [["Rosa, I'm at the store. Do you need anything for the cupcakes?", "Rosa, estou no mercado. Você precisa de algo para os cupcakes?"], ["Yes, I need a bunch of strawberries and a dozen eggs.", "Sim, preciso de um maço de morangos e uma dúzia de ovos."], ["Do you need milk too? I can get a small bottle.", "Precisa de leite também? Posso pegar uma garrafinha."], ["No, I still have half a cup, and that's enough.", "Não, ainda tenho meia xícara, e é suficiente."], ["Got it. How much sugar do you use?", "Entendi. Quanto açúcar você usa?"], ["One cup for the cake, and a spoonful for the sauce.", "Uma xícara para o bolo e uma colherada para a calda."], ["Really? My grandma adds a pinch of salt to the sauce.", "Sério? Minha avó põe uma pitada de sal na calda."], ["Smart. I'll try that, and I'll let it simmer for ten minutes.", "Esperta. Vou tentar isso e deixar ferver em fogo baixo por dez minutos."], ["Sounds good. I'll be at your house in fifteen minutes.", "Combinado. Chego na sua casa em quinze minutos."], ["Perfect. I'll open the door when you get here.", "Perfeito. Vou abrir a porta quando você chegar."]], ["/ʌ/ em cup e bunch", "O 'u' de cup é curto e relaxado, com a boca meio aberta, perto de um 'â'. Não diga 'câpi': pare no 'p'.", ["cup", "bunch"]], ["Put a spoonful ___ sugar in my tea, please.", "of", "from", "Ponha uma colherada de açúcar no meu chá, por favor.", "Depois de a spoonful, a cup, a pinch e a dozen, use of antes do ingrediente."], [["Yes, I need a bunch of strawberries and a dozen eggs.", "Sim, preciso de um maço de morangos e uma dúzia de ovos."], ["Then she adds half a cup of milk and a spoonful of vanilla.", "Depois ela acrescenta meia xícara de leite e uma colherada de baunilha."]], [{"t": "c", "q": "Add a ___ of salt to the soup.", "o": ["pinch", "bunch", "dozen"], "pt": "Acrescente uma pitada de sal à sopa.", "why": "Pinch é a quantidade bem pequena de sal; bunch e dozen não servem para sal."}, {"t": "l", "say": "I need a bunch of strawberries.", "o": ["I need a bunch of strawberries.", "I need a bag of strawberries.", "I need a bunch of bananas."], "why": "Você ouviu a bunch of e strawberries."}, {"t": "b", "pt": "Eu preciso de meia xícara de leite.", "w": ["I", "need", "half", "a", "cup", "of", "milk"]}, {"t": "b", "pt": "Deixe o molho ferver em fogo baixo.", "w": ["Let", "the", "sauce", "simmer"]}]];
