englishA2Plans[282]={"title": "Lista de compras para o aniversário do pai", "file": "", "grammar": "Compras para um jantar: need, run out of, list", "goal": "Fale do que falta em casa com run out of e organize suas compras com uma lista.", "words": [["grocery list", "lista de compras"], ["run out of", "ficar sem"], ["cross off", "riscar (da lista)"], ["pick up", "pegar, comprar"], ["on sale", "em promoção"], ["out of stock", "em falta no estoque"], ["in stock", "em estoque"], ["check out", "passar no caixa"]]};
englishA2Content[282]=[[["Lia writes a grocery list for her dad's birthday dinner.", "Lia escreve uma lista de compras para o jantar de aniversário do pai."], ["She needs rice, beans, and chicken, but she doesn't need onions.", "Ela precisa de arroz, feijão e frango, mas não precisa de cebolas."], ["At the store, chicken is on sale, so she picks up two big packs.", "No mercado, o frango está em promoção, então ela pega dois pacotes grandes."], ["The lemons are out of stock, so she buys limes instead.", "Os limões estão em falta, então ela compra limas."], ["She wants to cross off each item on her list as she walks.", "Ela quer riscar cada item da lista enquanto anda."], ["Then she has to check out and carry the bags to the car.", "Depois ela tem que passar no caixa e levar as sacolas até o carro."]], [["Lia, are you at the store? I think we ran out of rice.", "Lia, você está no mercado? Acho que acabou o arroz."], ["I know. Rice is on my list, but brown rice is out of stock.", "Eu sei. Arroz está na minha lista, mas o arroz integral está em falta."], ["What about white rice?", "E o arroz branco?"], ["Yes, white rice is in stock. I'll pick up two bags.", "Sim, tem arroz branco em estoque. Vou pegar dois pacotes."], ["Great. Do we need milk for the cake?", "Ótimo. Precisamos de leite para o bolo?"], ["Yes, we're going to run out of milk tomorrow morning.", "Sim, o leite vai acabar amanhã de manhã."], ["OK. Eggs are on sale this week, so buy a dozen.", "Certo. Os ovos estão em promoção esta semana, então compre uma dúzia."], ["Good idea. I'll add them to my list right now.", "Boa ideia. Vou colocar na lista agora mesmo."], ["How long will you take? The guests come at seven.", "Quanto tempo você vai demorar? Os convidados chegam às sete."], ["I'm at the checkout now. I'll be home by six, I promise.", "Estou no caixa agora. Estarei em casa às seis, prometo."]], ["/aʊ/ em out e now", "Comece com a boca bem aberta e feche até um 'u' curto: 'aaw'. Não diga 'óut' seco; o som desliza.", ["out", "now"]], ["We ran ___ rice yesterday, so I'm going to the store.", "out of", "out from", "Ficamos sem arroz ontem, então vou ao mercado.", "A expressão fixa é run out of; out from não existe nesse sentido."], [["Lia, are you at the store? I think we ran out of rice.", "Lia, você está no mercado? Acho que acabou o arroz."], ["Yes, we're going to run out of milk tomorrow morning.", "Sim, o leite vai acabar amanhã de manhã."]], [{"t": "c", "q": "We need milk, so please pick ___ two bottles.", "o": ["up", "on", "of"], "pt": "Precisamos de leite, então pegue duas garrafas, por favor.", "why": "Pick up significa pegar ou comprar."}, {"t": "l", "say": "Brown rice is out of stock.", "o": ["Brown rice is out of stock.", "Brown rice is on sale.", "White rice is out of stock."], "why": "Você ouviu brown rice e out of stock (em falta)."}, {"t": "b", "pt": "Nós ficamos sem arroz ontem.", "w": ["We", "ran", "out", "of", "rice", "yesterday"]}, {"t": "b", "pt": "Eu risco o leite da lista.", "w": ["I", "cross", "off", "the", "milk"]}]];
