englishA2Plans[283]={"title": "Pedindo sem nozes na cantina italiana", "file": "", "grammar": "Restaurante: ready to order, would like, allergic to", "goal": "Peça uma refeição usando I'd like e avise sobre uma alergia com I'm allergic to.", "words": [["ready to order", "pronto para pedir"], ["take your order", "anotar seu pedido"], ["allergic to", "alérgico a"], ["daily special", "prato do dia"], ["on the side", "à parte"], ["to go", "para viagem"], ["for here", "para comer aqui"], ["table for two", "mesa para dois"]]};
englishA2Content[283]=[[["Elena and her son Leo get a table for two at a small Italian place.", "Elena e o filho Leo pegam uma mesa para dois num pequeno restaurante italiano."], ["The waiter asks, \"Are you ready to order?\"", "O garçom pergunta: \"Vocês estão prontos para pedir?\""], ["Elena is allergic to nuts, so she asks about the daily special.", "Elena é alérgica a nozes, então pergunta sobre o prato do dia."], ["The pasta has pine nuts, so she orders a chicken salad.", "A massa tem pinoli, então ela pede uma salada de frango."], ["She asks for the dressing on the side, and Leo orders a pizza.", "Ela pede o molho à parte, e Leo pede uma pizza."], ["The food comes quickly, and they both say thank you.", "A comida chega rápido, e os dois agradecem."]], [["Good evening! May I take your order, or do you need a few more minutes?", "Boa noite! Posso anotar o pedido, ou vocês precisam de mais uns minutos?"], ["We're ready. First, what's the daily special?", "Estamos prontos. Primeiro, qual é o prato do dia?"], ["Today it's pasta with pesto, and it comes with garlic bread.", "Hoje é massa com pesto, e vem com pão de alho."], ["Does the pesto have nuts? I'm allergic to nuts.", "O pesto tem nozes? Sou alérgica a nozes."], ["Yes, it has pine nuts. I can ask the chef, but I'd choose the chicken salad.", "Sim, tem pinoli. Posso perguntar ao chef, mas eu escolheria a salada de frango."], ["Then I'll have the chicken salad, with the dressing on the side, please.", "Então vou querer a salada de frango, com o molho à parte, por favor."], ["Sure. And for your son?", "Claro. E para o seu filho?"], ["He would like the cheese pizza, please. And a glass of water.", "Ele gostaria da pizza de queijo, por favor. E um copo de água."], ["Great. Is that for here or to go?", "Ótimo. É para comer aqui ou para viagem?"], ["For here, please. We're staying for dinner.", "Para comer aqui, por favor. Vamos ficar para o jantar."]], ["/ɔr/ em order e for", "Arredonde os lábios para o 'o' e puxe a língua para trás no 'r'. Não diga 'ordér': a palavra termina no 'r' americano.", ["order", "for"]], ["I would ___ a glass of water, please.", "like", "want", "Eu gostaria de um copo de água, por favor.", "Para pedir com educação use would like; would want soa estranho."], [["Does the pesto have nuts? I'm allergic to nuts.", "O pesto tem nozes? Sou alérgica a nozes."], ["He would like the cheese pizza, please. And a glass of water.", "Ele gostaria da pizza de queijo, por favor. E um copo de água."]], [{"t": "c", "q": "I'm allergic ___ peanuts.", "o": ["to", "with", "of"], "pt": "Sou alérgico a amendoim.", "why": "Depois de allergic, use a preposição to."}, {"t": "l", "say": "Can I have the dressing on the side?", "o": ["Can I have the dressing on the side?", "Can I have the dressing on the table?", "Can I have the dressing in the side?"], "why": "Você ouviu dressing on the side (molho à parte)."}, {"t": "b", "pt": "Eu gostaria da salada de frango.", "w": ["I", "would", "like", "the", "chicken", "salad"]}, {"t": "b", "pt": "Vocês estão prontos para pedir?", "w": ["Are", "you", "ready", "to", "order"]}]];
