englishA2Plans[284]={"title": "Frango queimado e sopa salgada", "file": "", "grammar": "Reclamar e elogiar a comida: too + adjetivo, doesn't taste like", "goal": "Reclame de um prato com too salty e burnt e elogie quando ele melhorar.", "words": [["too salty", "salgado demais"], ["overcooked", "cozido demais"], ["bland", "sem sabor"], ["send back", "devolver"], ["taste like", "ter gosto de"], ["undercooked", "malcozido"], ["burnt", "queimado"], ["greasy", "gorduroso"], ["compliments to the chef", "parabéns ao cozinheiro"]]};
englishA2Content[284]=[[["Kenji and Mia eat lunch at a small diner near the office.", "Kenji e Mia almoçam numa lanchonete perto do escritório."], ["Kenji's soup is too salty, and his rice is overcooked.", "A sopa do Kenji está salgada demais, e o arroz dele está cozido demais."], ["Mia's chicken is burnt outside and undercooked inside, and her fries are greasy.", "O frango da Mia está queimado por fora e malcozido por dentro, e as batatas fritas estão gordurosas."], ["The sauce is bland, and Mia doesn't want to eat it.", "O molho não tem sabor, e Mia não quer comer."], ["They send back the plates, and the manager gives them a free lunch.", "Eles devolvem os pratos, e o gerente oferece o almoço de graça."], ["The new food is great, so Kenji says, \"Our compliments to the chef!\"", "A comida nova está ótima, então Kenji diz: \"Parabéns ao cozinheiro!\""]], [["Hi, is everything OK with your lunch?", "Oi, está tudo bem com o almoço de vocês?"], ["Not really. My chicken is burnt on the outside. Can I send it back?", "Na verdade, não. Meu frango está queimado por fora. Posso devolver?"], ["I'm so sorry. Is anything else wrong with the meal?", "Sinto muito. Mais alguma coisa está errada com a refeição?"], ["Well, my fries are greasy, and the sauce doesn't taste like anything.", "Bem, minhas batatas estão gordurosas, e o molho não tem gosto de nada."], ["I'll tell the cook. How is your friend's soup?", "Vou avisar o cozinheiro. E a sopa do seu amigo?"], ["Kenji says it's too salty. He can't eat it, and his rice is overcooked.", "O Kenji diz que está salgada demais. Ele não consegue comer, e o arroz está cozido demais."], ["No problem. I'll bring two new plates in ten minutes. Lunch is free today.", "Sem problema. Trago dois pratos novos em dez minutos. O almoço é por conta da casa."], ["Ten minutes later, the new chicken is hot and the soup is just right.", "Dez minutos depois, o frango novo está quente e a sopa está no ponto."], ["Wonderful. The cook will be happy to hear that.", "Que bom. O cozinheiro vai ficar feliz em saber."], ["Please give our compliments to the chef. Everything is great now.", "Por favor, mande parabéns ao cozinheiro. Está tudo ótimo agora."]], ["/ɜr/ em burnt e her", "Não ponha um 'e' ou 'i' antes do 'r': o 'ur' de burnt sai com a língua curvada e os lábios relaxados. Pense em 'bârnt', sem o 'r' forte do português.", ["burnt", "her"]], ["The soup is ___ salty. I can't eat it.", "too", "too much", "A sopa está salgada demais. Não consigo comer.", "Antes de adjetivo use too (too salty); too much é para substantivos."], [["Kenji's soup is too salty, and his rice is overcooked.", "A sopa do Kenji está salgada demais, e o arroz dele está cozido demais."], ["Kenji says it's too salty. He can't eat it, and his rice is overcooked.", "O Kenji diz que está salgada demais. Ele não consegue comer, e o arroz está cozido demais."]], [{"t": "c", "q": "The fries are ___. There is too much oil.", "o": ["greasy", "bland", "undercooked"], "pt": "As batatas estão gordurosas. Tem óleo demais.", "why": "Greasy descreve comida com muito óleo."}, {"t": "l", "say": "Can I send it back?", "o": ["Can I send it back?", "Can I take it back?", "Can I send it black?"], "why": "Você ouviu send it back (devolver)."}, {"t": "b", "pt": "A sopa está salgada demais.", "w": ["The", "soup", "is", "too", "salty"]}, {"t": "b", "pt": "O frango está queimado por fora.", "w": ["The", "chicken", "is", "burnt", "on", "the", "outside"]}]];
