englishA2Plans[286]={"title": "Jantar para oito: lasanha em dobro", "file": "", "grammar": "Cozinhar para convidados: have to, in time", "goal": "Fale das tarefas antes de um jantar com have to e diga que vai terminar in time.", "words": [["dinner party", "jantar com convidados"], ["set the table", "pôr a mesa"], ["have to", "ter que"], ["in time", "a tempo"], ["just in time", "na hora certa"], ["get started", "começar"], ["on time", "pontual"], ["double the recipe", "dobrar a receita"], ["feast", "banquete"]]};
englishA2Content[286]=[[["Elena is having a dinner party for eight people tonight.", "Elena vai dar um jantar para oito pessoas hoje à noite."], ["She has to double the recipe, because her lasagna is for four.", "Ela tem que dobrar a receita, porque a lasanha dela é para quatro."], ["She wants to get started at two o'clock, and she doesn't stop.", "Ela quer começar às duas horas e não para."], ["Her husband Sam has to set the table and clean the living room.", "O marido dela, Sam, tem que pôr a mesa e limpar a sala."], ["The guests are on time, and the lasagna comes out just in time.", "Os convidados são pontuais, e a lasanha sai na hora certa."], ["It's a real feast, and everyone wants a second piece.", "É um verdadeiro banquete, e todo mundo quer mais um pedaço."]], [["Elena, it's four o'clock. Do we need to buy anything else?", "Elena, são quatro horas. Precisamos comprar mais alguma coisa?"], ["Yes, we have to get ice and bread. Can you go now?", "Sim, temos que comprar gelo e pão. Você pode ir agora?"], ["Sure, but I have to pick up my dad at five.", "Claro, mas tenho que buscar meu pai às cinco."], ["That's fine. Will you be back in time to help me?", "Tudo bem. Você volta a tempo de me ajudar?"], ["Yes, I'll be here in time. Does Rosa eat meat?", "Sim, estarei aqui a tempo. A Rosa come carne?"], ["She doesn't, so I'm making a vegetable lasagna too.", "Não come, então vou fazer uma lasanha de legumes também."], ["Another one? That's a lot of work!", "Mais uma? Dá muito trabalho!"], ["I know, but it's just a small one. I'll use the vegetables from the fridge.", "Eu sei, mas é só uma pequena. Vou usar os legumes da geladeira."], ["OK. I'll bring a big bag of ice and two loaves of bread.", "Certo. Vou trazer um saco grande de gelo e dois pães."], ["Perfect. If you're back by five, we'll finish in time.", "Perfeito. Se você voltar às cinco, vamos terminar a tempo."]], ["/h/ em have e has", "O 'h' inglês é só um sopro suave de ar, bem mais fraco que o 'rr' do português. Não diga 'rhave': deixe o ar sair sem raspar na garganta.", ["have", "has"]], ["Sam ___ set the table before six.", "has to", "have to", "Sam tem que pôr a mesa antes das seis.", "Com he, she e nomes no singular use has to."], [["Her husband Sam has to set the table and clean the living room.", "O marido dela, Sam, tem que pôr a mesa e limpar a sala."], ["Yes, we have to get ice and bread. Can you go now?", "Sim, temos que comprar gelo e pão. Você pode ir agora?"]], [{"t": "c", "q": "We'll finish ___ time if we start now.", "o": ["in", "at", "of"], "pt": "Vamos terminar a tempo se começarmos agora.", "why": "A expressão é in time, que significa a tempo."}, {"t": "l", "say": "I have to be back by five.", "o": ["I have to be back by five.", "I had to be back by five.", "I have to be back by nine."], "why": "Você ouviu have to (presente) e five."}, {"t": "b", "pt": "Eu tenho que pôr a mesa.", "w": ["I", "have", "to", "set", "the", "table"]}, {"t": "b", "pt": "Nós chegamos lá na hora certa.", "w": ["We", "got", "there", "just", "in", "time"]}]];
