englishA2Plans[289]={"title": "Revisão: sopa de domingo da Rosa", "file": "", "grammar": "Revisão: imperativo, have to, used to e pedidos à mesa", "goal": "Revise o bloco da cozinha usando Dig in!, Help yourself e have to num jantar em família.", "words": [["help yourself", "sirva-se"], ["dig in", "comece a comer"], ["second helping", "repetição do prato"], ["clear the table", "tirar a mesa"], ["do the dishes", "lavar a louça"], ["left over", "sobrando"], ["wash up", "lavar as mãos"], ["pour out", "servir (líquido)"]]};
englishA2Content[289]=[[["Rosa puts a big pot of chicken soup on the table and says, \"Dig in!\"", "Rosa põe uma panela grande de sopa de frango na mesa e diz: \"Podem comer!\""], ["Her son Tom takes a second helping, and nobody talks for five minutes.", "O filho dela, Tom, repete o prato, e ninguém fala por cinco minutos."], ["There is a lot of soup left over, so Rosa puts it in a box.", "Sobrou muita sopa, então Rosa a põe numa caixa."], ["After dinner, Tom and his dad clear the table.", "Depois do jantar, Tom e o pai dele tiram a mesa."], ["Before dessert, everyone has to wash up.", "Antes da sobremesa, todo mundo tem que lavar as mãos."], ["Then Tom has to do the dishes, and his dad helps him.", "Depois Tom tem que lavar a louça, e o pai dele ajuda."]], [["Dig in, everybody! Help yourself to bread, too.", "Podem comer, pessoal! Sirvam-se de pão também."], ["Mom, this soup is amazing. Can I have a second helping?", "Mãe, esta sopa está incrível. Posso repetir?"], ["Of course, but leave room for dessert. There's chocolate cake.", "Claro, mas deixe espaço para a sobremesa. Tem bolo de chocolate."], ["Okay. Should I pour out the juice for everyone?", "Certo. Devo servir o suco para todo mundo?"], ["Yes, please, and use the big glasses.", "Sim, por favor, e use os copos grandes."], ["Done. Oh no, I spilled some on the table!", "Pronto. Ai não, derramei um pouco na mesa!"], ["Don't worry. Wipe it up, and then we'll have dessert.", "Não se preocupe. Limpe, e depois vamos comer a sobremesa."], ["There is a lot left over. Can I take some to school tomorrow?", "Sobrou bastante. Posso levar um pouco para a escola amanhã?"], ["Sure. Put it in a box, and I'll write your name on it.", "Claro. Ponha numa caixa, e eu escrevo seu nome nela."], ["Thanks, Mom. I'll clear the table after dessert, I promise.", "Obrigado, mãe. Eu tiro a mesa depois da sobremesa, prometo."]], ["/ɪ/ em dig e dish", "O 'i' de dig é curto e frouxo, entre 'i' e 'e'. Não alongue como 'dígui': diga 'dig' com o 'g' seco.", ["dig", "dishes"]], ["Please ___ yourself to more rice.", "help", "serve", "Por favor, sirva-se de mais arroz.", "A expressão fixa é help yourself; serve yourself soa estranho."], [["Dig in, everybody! Help yourself to bread, too.", "Podem comer, pessoal! Sirvam-se de pão também."], ["Then Tom has to do the dishes, and his dad helps him.", "Depois Tom tem que lavar a louça, e o pai dele ajuda."]], [{"t": "c", "q": "After dinner, I have to do the ___.", "o": ["dishes", "feast", "bunch"], "pt": "Depois do jantar, tenho que lavar a louça.", "why": "Do the dishes significa lavar a louça."}, {"t": "l", "say": "Can I have a second helping?", "o": ["Can I have a second helping?", "Can I have a second cup?", "Can I have a second dish?"], "why": "Você ouviu second helping (repetir o prato)."}, {"t": "b", "pt": "Comece a comer e sirva-se.", "w": ["Dig", "in", "and", "help", "yourself"]}, {"t": "b", "pt": "Todo mundo tem que lavar as mãos.", "w": ["Everyone", "has", "to", "wash", "up"]}]];
englishA2PhotoThemes[289]="flag";
englishA2MiniStories[289]=["O jantar de domingo", "It is Sunday, and Rosa is making soup from her grandma's recipe.~É domingo, e Rosa está fazendo sopa com a receita da avó.|First, she chops up an onion and pours in a cup of rice.~Primeiro, ela pica uma cebola e despeja uma xícara de arroz.|Then she sees that she ran out of salt, so she sends Tom to the market.~Então ela vê que o sal acabou, e manda o Tom ao mercado.|A street vendor has a bag of salt, but it is cash only.~Um vendedor de rua tem um pacote de sal, mas é só dinheiro.|Tom has only a card, so he has to run home for cash.~Tom só tem cartão, então tem que correr para casa atrás de dinheiro.|He gets back just in time, and Rosa stirs in a pinch of salt.~Ele volta na hora certa, e Rosa acrescenta uma pitada de sal.|The soup isn't too salty, and it doesn't taste bland.~A sopa não está salgada demais, e também não está sem sabor.|The family digs in, and Tom has a second helping.~A família começa a comer, e Tom repete o prato.|After dinner, Tom clears the table and does the dishes.~Depois do jantar, Tom tira a mesa e lava a louça.|Rosa smiles and says, \"Grandma used to make it like this, too.\"~Rosa sorri e diz: \"A vovó também fazia assim.\""];
englishA2Plans[290]={"title": "Matriculando-se num curso avançado de inglês", "file": "", "grammar": "have to e want to na matrícula: sign up, fee, schedule", "goal": "Matricule-se num curso usando I'd like to sign up… e have to.", "words": [["sign up", "inscrever-se"], ["register", "matricular-se"], ["tuition fee", "mensalidade, taxa do curso"], ["fill out", "preencher"], ["advanced", "avançado"], ["attend", "assistir, frequentar"], ["reading list", "lista de leitura"], ["hand in", "entregar"]]};
englishA2Content[290]=[[["Lia wants to sign up for an advanced English course.", "Lia quer se inscrever num curso avançado de inglês."], ["She goes to the school office and asks about the tuition fee.", "Ela vai à secretaria da escola e pergunta sobre a mensalidade."], ["She has to fill out a short form.", "Ela tem de preencher um formulário curto."], ["She has to register today and hand in the form with a photo.", "Ela tem de se matricular hoje e entregar o formulário com uma foto."], ["The reading list is long, but the first class is on Monday.", "A lista de leitura é longa, mas a primeira aula é na segunda."], ["Lia will attend it at six o'clock after work.", "Lia vai assistir à aula às seis, depois do trabalho."]], [["Good morning. How can I help you?", "Bom dia. Como posso ajudar?"], ["Hi. I'd like to sign up for the advanced course, please.", "Oi. Eu gostaria de me inscrever no curso avançado, por favor."], ["Sure. First, you have to fill out this form and hand in a copy of your ID.", "Claro. Primeiro, você tem de preencher este formulário e entregar uma cópia do seu documento."], ["Okay. How much is the tuition fee for three months?", "Certo. Quanto é a mensalidade por três meses?"], ["It's $240, and you can pay in two parts. Classes are Mondays and Wednesdays at six.", "São 240 dólares, e você pode pagar em duas partes. As aulas são às segundas e quartas, às seis."], ["That works for me. I finish work at five. Is there a reading list?", "Isso funciona para mim. Saio do trabalho às cinco. Existe uma lista de leitura?"], ["Yes, you can pick it up at the desk. Please register before Friday.", "Sim, você pode pegar no balcão. Por favor, matricule-se antes de sexta."], ["Perfect. I'll register today and attend the first class on Monday.", "Perfeito. Vou me matricular hoje e assistir à primeira aula na segunda."]], ["/f/ em fill e form", "Encoste os dentes de cima no lábio de baixo e sopre o ar sem fazer a garganta vibrar. Não troque por 'p'.", ["fill", "form"]], ["Lia ___ hand in the form today.", "has to", "have to", "Lia precisa entregar o formulário hoje.", "Com she, he e nomes no singular, usa-se has to."], [["She has to fill out a short form.", "Ela tem de preencher um formulário curto."], ["Sure. First, you have to fill out this form and hand in a copy of your ID.", "Claro. Primeiro, você tem de preencher este formulário e entregar uma cópia do seu documento."]], [{"t": "c", "q": "I want to ___ for the English course.", "o": ["sign up", "signing up", "signed up"], "pt": "Eu quero me inscrever no curso de inglês.", "why": "Depois de want to vem o verbo na forma simples: sign up."}, {"t": "l", "say": "I have to hand in this form today.", "o": ["I have to hand in this form today.", "I have to hand in this form tomorrow.", "I had to hand in this form today."], "why": "Você ouviu have to (obrigação agora) e today."}, {"t": "b", "pt": "Eu preciso pagar a taxa hoje.", "w": ["I", "have", "to", "pay", "the", "fee", "today"]}, {"t": "b", "pt": "Quando começa o curso avançado?", "w": ["When", "does", "the", "advanced", "course", "start"]}]];
