englishA2Plans[291]={"title": "Estudando para a prova de sexta", "file": "", "grammar": "remember to e don't forget to: revise, remember, forget", "goal": "Combine remember e forget com to + verbo ao planejar seus estudos.", "words": [["revise", "revisar, rever a matéria"], ["remember", "lembrar"], ["memorize", "decorar"], ["highlight", "destacar, marcar com marca-texto"], ["outline", "esquema, resumo em tópicos"], ["look up", "procurar (no dicionário)"], ["anxious", "ansioso"], ["take notes", "fazer anotações"]]};
englishA2Content[291]=[[["Noah has a test on Friday, and he feels anxious.", "Noah tem uma prova na sexta e se sente ansioso."], ["He wants to revise the whole unit tonight.", "Ele quer revisar a unidade inteira hoje à noite."], ["First, he writes an outline of the main points.", "Primeiro, ele escreve um esquema dos pontos principais."], ["He has to memorize twenty new words, so he highlights them in yellow.", "Ele tem de decorar vinte palavras novas, então marca todas de amarelo."], ["If he can't remember a word, he will look up the meaning.", "Se ele não lembra uma palavra, vai procurar o significado."], ["In class tomorrow, he will take notes and ask questions.", "Na aula de amanhã, ele vai fazer anotações e perguntar."]], [["Mia, are you ready for Friday's test?", "Mia, você está pronta para a prova de sexta?"], ["Not really. I'm anxious because I can't remember the new verbs.", "Na verdade, não. Estou ansiosa porque não consigo lembrar os verbos novos."], ["Try to memorize five a day. Don't forget to say them out loud.", "Tente decorar cinco por dia. Não esqueça de dizer em voz alta."], ["Good idea. Did you take notes in the last class?", "Boa ideia. Você fez anotações na última aula?"], ["Yes, and I highlight the main points in yellow. Do you want to borrow them?", "Sim, e eu marco os pontos principais de amarelo. Quer pegar emprestado?"], ["Yes, please! I'll make an outline tonight and revise tomorrow morning.", "Quero, por favor! Vou fazer um esquema hoje à noite e revisar amanhã de manhã."], ["Remember to look up the words you don't know in the dictionary.", "Lembre de procurar no dicionário as palavras que você não conhece."], ["I will. Thanks, Noah. I feel much less anxious now.", "Vou lembrar. Obrigada, Noah. Estou bem menos ansiosa agora."]], ["/r/ em revise e remember", "No /r/ inglês a língua não encosta em lugar nenhum: puxe-a para trás e arredonde levemente os lábios. Não diga 'h' no início.", ["revise", "remember"]], ["Don't forget ___ the words out loud.", "to say", "saying", "Não esqueça de dizer as palavras em voz alta.", "Depois de forget e remember, a ação que ainda vamos fazer usa to + verbo."], [["Try to memorize five a day. Don't forget to say them out loud.", "Tente decorar cinco por dia. Não esqueça de dizer em voz alta."], ["Remember to look up the words you don't know in the dictionary.", "Lembre de procurar no dicionário as palavras que você não conhece."]], [{"t": "c", "q": "I ___ the answer, so I looked it up.", "o": ["forgot", "forget", "forgetting"], "pt": "Eu esqueci a resposta, então procurei.", "why": "A ação já passou (looked), então usa-se o passado: forgot."}, {"t": "l", "say": "I can't remember the new words.", "o": ["I can't remember the new words.", "I can't remember the old words.", "I couldn't remember the new words."], "why": "Você ouviu can't (agora) e new."}, {"t": "b", "pt": "Eu preciso revisar a unidade hoje à noite.", "w": ["I", "need", "to", "revise", "the", "unit", "tonight"]}, {"t": "b", "pt": "Não esqueça de fazer anotações.", "w": ["Don't", "forget", "to", "take", "notes"]}]];
