englishA2Plans[292]={"title": "Pedindo ajuda ao professor depois da aula", "file": "", "grammar": "Could you explain…? e I don't understand…", "goal": "Peça a um professor que explique algo usando Could you explain…?", "words": [["explain", "explicar"], ["confused", "confuso"], ["translate", "traduzir"], ["ask for help", "pedir ajuda"], ["vocabulary", "vocabulário"], ["keep up with", "acompanhar"], ["catch up", "pôr o estudo em dia"], ["pay attention", "prestar atenção"]]};
englishA2Content[292]=[[["Priya is confused after the grammar class.", "Priya está confusa depois da aula de gramática."], ["She couldn't pay attention because the room was noisy.", "Ela não conseguiu prestar atenção porque a sala estava barulhenta."], ["After class, she decides to ask for help.", "Depois da aula, ela decide pedir ajuda."], ["She doesn't understand the new vocabulary.", "Ela não entende o vocabulário novo."], ["Mr. Green explains the rule slowly and writes an example.", "O Sr. Green explica a regra devagar e escreve um exemplo."], ["Now Priya can catch up, and she can keep up with the class.", "Agora a Priya consegue se atualizar e acompanhar a turma."]], [["Mr. Green, do you have a minute? I'm a little confused.", "Sr. Green, o senhor tem um minuto? Estou um pouco confusa."], ["Of course, Priya. What don't you understand?", "Claro, Priya. O que você não entende?"], ["The homework. Could you explain this sentence, please? I can't translate it.", "A tarefa. O senhor poderia explicar esta frase, por favor? Não consigo traduzir."], ["Sure. Let's go word by word. First, tell me which word is new.", "Claro. Vamos palavra por palavra. Primeiro, diga qual palavra é nova."], ["The vocabulary is new for me, and yesterday I couldn't pay attention. The room was noisy.", "O vocabulário é novo para mim, e ontem não consegui prestar atenção. A sala estava barulhenta."], ["I understand. Don't be afraid to ask for help. Come on Thursday at four.", "Entendo. Não tenha medo de pedir ajuda. Venha na quinta, às quatro."], ["Could you explain the rules again then? I really want to catch up.", "O senhor poderia explicar as regras de novo, então? Quero muito me atualizar."], ["Of course, and you'll keep up with the class very soon.", "Claro, e você vai acompanhar a turma muito em breve."]], ["/ə/ fraco em explain e confused", "Em explain e confused a primeira sílaba é fraca e rápida (/ə/); a força cai em 'plain' e 'fused'. Não pronuncie o 'e' como 'é'.", ["explain", "confused"]], ["Could you ___ this sentence, please?", "explain", "to explain", "O senhor poderia explicar esta frase, por favor?", "Depois de could vem o verbo na forma simples, sem to."], [["The homework. Could you explain this sentence, please? I can't translate it.", "A tarefa. O senhor poderia explicar esta frase, por favor? Não consigo traduzir."], ["Could you explain the rules again then? I really want to catch up.", "O senhor poderia explicar as regras de novo, então? Quero muito me atualizar."]], [{"t": "c", "q": "I'm ___ because I don't understand the rule.", "o": ["confused", "confusing", "confuse"], "pt": "Estou confuso porque não entendo a regra.", "why": "Para sentimento de pessoa usa-se confused; confusing descreve a coisa."}, {"t": "l", "say": "Could you explain it again, please?", "o": ["Could you explain it again, please?", "Can you explain it again, please?", "Could you explain it to me, please?"], "why": "Você ouviu Could you e again."}, {"t": "b", "pt": "Você poderia traduzir esta frase?", "w": ["Could", "you", "translate", "this", "sentence"]}, {"t": "b", "pt": "Eu não consigo acompanhar a turma.", "w": ["I", "can't", "keep", "up", "with", "the", "class"]}]];
