englishA2Plans[293]={"title": "Trabalho em grupo sobre reciclagem", "file": "", "grammar": "Let's + verbo e take turns", "goal": "Organize um trabalho em grupo com Let's… e take turns.", "words": [["take turns", "revezar"], ["share ideas", "trocar ideias"], ["source", "fonte"], ["topic", "tema, assunto"], ["encourage", "encorajar"], ["absent", "ausente"], ["fall behind", "ficar para trás"], ["study group", "grupo de estudo"], ["teamwork", "trabalho em equipe"], ["hand out", "distribuir"]]};
englishA2Content[293]=[[["Elena, Tom, and Kenji are in the same study group.", "Elena, Tom e Kenji estão no mesmo grupo de estudo."], ["Their topic is recycling in the city.", "O tema deles é a reciclagem na cidade."], ["They take turns reading each source out loud.", "Eles se revezam lendo cada fonte em voz alta."], ["Kenji is absent today, so the others share ideas for him.", "Kenji está ausente hoje, então os outros trocam ideias por ele."], ["Elena wants to encourage Tom because he is shy.", "Elena quer encorajar o Tom porque ele é tímido."], ["In the end, they agree that teamwork is best, and nobody wants to fall behind.", "No fim, eles concordam que o trabalho em equipe é o melhor, e ninguém quer ficar para trás."]], [["Elena, our presentation is on Thursday. Where should we start?", "Elena, nossa apresentação é na quinta. Por onde devemos começar?"], ["Let's share ideas first, and then let's take turns writing.", "Vamos trocar ideias primeiro e depois nos revezar para escrever."], ["Okay. I found a good source: a report about plastic bags.", "Certo. Achei uma boa fonte: um relatório sobre sacolas plásticas."], ["Great. I'll hand out the notes tomorrow in the study group.", "Ótimo. Vou distribuir as anotações amanhã no grupo de estudo."], ["But Kenji is absent again. I'm afraid he will fall behind.", "Mas o Kenji está ausente de novo. Tenho medo de que ele fique para trás."], ["Don't worry. I'll call him tonight and encourage him to join us.", "Não se preocupe. Vou ligar para ele hoje à noite e encorajá-lo a participar."], ["Thanks. Good teamwork is really important for this topic.", "Obrigado. Um bom trabalho em equipe é muito importante para este tema."], ["Sure. See you at the study group at four, then.", "Claro. Até as quatro no grupo de estudo, então."]], ["/ɜr/ em turns e first", "O som /ɜr/ é um 'é' fechado com a língua levantada para trás; não separe em 'târ-ns'. Segure o som e termine com o 's'.", ["turns", "first"]], ["Let's ___ turns with the laptop.", "take", "taking", "Vamos nos revezar com o notebook.", "Depois de Let's vem o verbo na forma simples: take."], [["Let's share ideas first, and then let's take turns writing.", "Vamos trocar ideias primeiro e depois nos revezar para escrever."], ["They take turns reading each source out loud.", "Eles se revezam lendo cada fonte em voz alta."]], [{"t": "c", "q": "Kenji is ___ today, so we need to call him.", "o": ["absent", "absence", "absently"], "pt": "Kenji está ausente hoje, então precisamos ligar para ele.", "why": "Depois de is vem um adjetivo: absent."}, {"t": "l", "say": "Let's take turns reading the source.", "o": ["Let's take turns reading the source.", "Let's take turns reading the sources.", "Let's take turns writing the source."], "why": "Você ouviu reading e source no singular."}, {"t": "b", "pt": "Vamos trocar ideias primeiro.", "w": ["Let's", "share", "ideas", "first"]}, {"t": "b", "pt": "Eu tenho medo de que ele fique para trás.", "w": ["I'm", "afraid", "he", "will", "fall", "behind"]}]];
