englishA2Plans[294]={"title": "Praticando inglês num encontro de conversação", "file": "", "grammar": "practise + verbo-ing e erros comuns: improve, practise, mistakes", "goal": "Fale de como você pratica e melhora seu inglês.", "words": [["improve", "melhorar"], ["practise", "praticar"], ["fluently", "com fluência"], ["pronounce", "pronunciar"], ["error", "erro"], ["make progress", "fazer progresso"], ["native speaker", "falante nativo"], ["language exchange", "troca de idiomas"], ["word for word", "palavra por palavra"], ["slip of the tongue", "escorregão na fala"]]};
englishA2Content[294]=[[["Omar goes to a language exchange every Tuesday.", "Omar vai a um encontro de troca de idiomas toda terça."], ["He wants to practise English with a native speaker.", "Ele quer praticar inglês com um falante nativo."], ["At first, he can't pronounce the word thirty correctly.", "No começo, ele não consegue pronunciar a palavra thirty corretamente."], ["He makes an error and says dirty instead.", "Ele comete um erro e diz dirty no lugar."], ["His partner Sara laughs kindly and helps him.", "A parceira dele, Sara, ri com gentileza e o ajuda."], ["After two months, he can speak fluently about his day.", "Depois de dois meses, ele consegue falar com fluência sobre o seu dia."]], [["Omar, your English is much better than last month!", "Omar, seu inglês está muito melhor que no mês passado!"], ["Really? I practise every day, but I still make errors.", "Sério? Eu pratico todo dia, mas ainda cometo erros."], ["Everybody does. I translate my Portuguese word for word, and it sounds funny.", "Todo mundo comete. Eu traduzo meu português palavra por palavra, e fica engraçado."], ["Ha! Well, I can't pronounce comfortable yet. Listen: com-for-ta-bel.", "Ha! Bem, ainda não consigo pronunciar comfortable. Escute: com-for-ta-bel."], ["Almost! Say it again slowly. Com-fort-a-ble.", "Quase! Diga de novo, devagar. Com-fort-a-ble."], ["Comfortable. Oh, sorry, that was a slip of the tongue before.", "Comfortable. Ah, desculpe, antes foi um escorregão na fala."], ["No problem. If we meet every Tuesday, we'll both improve and make progress.", "Sem problema. Se nos encontrarmos toda terça, nós dois vamos melhorar e fazer progresso."], ["Deal! In three months, I want to speak fluently on the phone.", "Combinado! Em três meses, quero falar com fluência ao telefone."]], ["/p/ aspirado em practise e pronounce", "No início de palavra, o /p/ inglês solta um sopro de ar: segure um papel na frente da boca e ele deve mexer. Não troque por 'b'.", ["practise", "pronounce"]], ["Omar wants to ___ English with a native speaker.", "practise", "practising", "Omar quer praticar inglês com um falante nativo.", "Depois de wants to vem o verbo na forma simples: practise."], [["He wants to practise English with a native speaker.", "Ele quer praticar inglês com um falante nativo."], ["Really? I practise every day, but I still make errors.", "Sério? Eu pratico todo dia, mas ainda cometo erros."]], [{"t": "c", "q": "Everybody ___ errors when they learn a language.", "o": ["makes", "make", "making"], "pt": "Todo mundo comete erros quando aprende um idioma.", "why": "Everybody é singular e pede makes no presente."}, {"t": "l", "say": "I translate it word for word.", "o": ["I translate it word for word.", "I translate it word by word.", "I translated it word for word."], "why": "Você ouviu translate (presente) e for word."}, {"t": "b", "pt": "Eu pratico todos os dias.", "w": ["I", "practise", "every", "day"]}, {"t": "b", "pt": "Ele consegue falar com fluência.", "w": ["He", "can", "speak", "fluently"]}]];
