englishA2Plans[295]={"title": "Recebendo a nota da prova final", "file": "", "grammar": "Passado simples: passed, failed, got", "goal": "Conte o resultado de uma prova usando passed, failed e got no passado.", "words": [["grade", "nota"], ["passed", "passou (em)"], ["fail", "reprovar"], ["drop out", "abandonar o curso"], ["passing grade", "nota para passar"], ["final exam", "prova final"], ["pass an exam", "passar numa prova"], ["retake", "refazer"], ["do well", "ir bem"]]};
englishA2Content[295]=[[["Rosa studied hard for the final exam.", "Rosa estudou muito para a prova final."], ["Yesterday, the teacher posted the grades on the door.", "Ontem, o professor afixou as notas na porta."], ["Rosa looked for her name and saw a seven.", "Rosa procurou o nome dela e viu um sete."], ["The passing grade is six, so she passed!", "A nota para passar é seis, então ela passou!"], ["Her friend Mark didn't do well, and he has to retake the test.", "O amigo dela, Mark, não foi bem e tem de refazer a prova."], ["Mark wants to drop out, but Rosa says, Don't give up!", "Mark quer abandonar o curso, mas Rosa diz: Não desista!"]], [["Mark, did you see the grades? I passed the final exam!", "Mark, você viu as notas? Eu passei na prova final!"], ["Congratulations! I got a five, so I failed.", "Parabéns! Eu tirei cinco, então reprovei."], ["Oh no. I'm sorry. What happened? You studied a lot.", "Ah, não. Sinto muito. O que aconteceu? Você estudou muito."], ["I was so tired that I didn't finish the last page.", "Eu estava tão cansado que não terminei a última página."], ["You can retake it next month. Many students don't pass an exam the first time.", "Você pode refazer no mês que vem. Muitos alunos não passam numa prova na primeira vez."], ["Maybe, but I want to drop out of the course.", "Talvez, mas eu quero abandonar o curso."], ["Please don't! You do well in class every day.", "Por favor, não! Você vai bem na aula todos os dias."], ["You're right. I'll retake the exam and try to get a better grade.", "Você tem razão. Vou refazer a prova e tentar tirar uma nota melhor."]], ["-ed = /t/ em passed e looked", "Depois de som surdo (p, k, s), o -ed soa só como um 't' leve: pass-t, look-t. Não pronuncie 'ed' como sílaba.", ["passed", "looked"]], ["Rosa ___ the final exam yesterday.", "passed", "pass", "Rosa passou na prova final ontem.", "Yesterday indica passado, então usa-se passed."], [["The passing grade is six, so she passed!", "A nota para passar é seis, então ela passou!"], ["Mark, did you see the grades? I passed the final exam!", "Mark, você viu as notas? Eu passei na prova final!"]], [{"t": "c", "q": "Mark ___ the test, so he has to retake it.", "o": ["failed", "fail", "fails"], "pt": "Mark reprovou na prova, então tem de refazer.", "why": "A ação já passou: failed."}, {"t": "l", "say": "I got a five, so I failed.", "o": ["I got a five, so I failed.", "I got a five, so I passed.", "I got a six, so I failed."], "why": "Você ouviu five e failed."}, {"t": "b", "pt": "Eu passei na prova final.", "w": ["I", "passed", "the", "final", "exam"]}, {"t": "b", "pt": "Ele vai refazer a prova.", "w": ["He", "will", "retake", "the", "exam"]}]];
