englishA2Plans[296]={"title": "Usando a biblioteca da universidade", "file": "", "grammar": "Datas e prazos: due on…", "goal": "Peça livros e fale de prazos usando due on e can I…?", "words": [["library card", "cartão da biblioteca"], ["come back", "voltar"], ["look through", "dar uma olhada em"], ["database", "banco de dados"], ["call number", "código do livro na estante"], ["study room", "sala de estudo"], ["reserve a book", "reservar um livro"], ["print out", "imprimir"], ["quiet zone", "zona de silêncio"], ["overdue book", "livro atrasado"]]};
englishA2Content[296]=[[["Mia needs a library card to borrow books.", "Mia precisa de um cartão da biblioteca para pegar livros emprestados."], ["She starts to look through the online database and finds a book about birds.", "Ela começa a dar uma olhada no banco de dados on-line e acha um livro sobre pássaros."], ["The call number is 598, so she walks to the third floor.", "O código é 598, então ela sobe a pé até o terceiro andar."], ["She also wants to reserve a book for her friend.", "Ela também quer reservar um livro para a amiga."], ["Then she goes to the quiet zone and finds a free study room.", "Depois ela vai para a zona de silêncio e acha uma sala de estudo livre."], ["The books are due on May 12, so she must come back before that day.", "Os livros vencem em 12 de maio, então ela precisa voltar antes desse dia."]], [["Hi. I'd like to borrow these three books, please.", "Oi. Eu gostaria de pegar estes três livros emprestados, por favor."], ["Sure. Can I see your library card?", "Claro. Posso ver seu cartão da biblioteca?"], ["Here it is. Also, I have an overdue book. How much is the fine?", "Aqui está. Além disso, tenho um livro atrasado. Quanto é a multa?"], ["It's two dollars. The new books are due on May 12.", "São dois dólares. Os livros novos vencem em 12 de maio."], ["Okay. Can I print out some pages from the database here?", "Certo. Posso imprimir algumas páginas do banco de dados aqui?"], ["Yes, the printer is behind you. It's ten cents a page.", "Pode, a impressora está atrás de você. Custa dez centavos a página."], ["Perfect. And can I use the study room this afternoon?", "Perfeito. E posso usar a sala de estudo esta tarde?"], ["Yes, room 4 is free at two. Please keep your voice down in the quiet zone.", "Pode, a sala 4 está livre às duas. Por favor, fale baixo na zona de silêncio."]], ["/b/ em borrow e books", "Feche os lábios e faça a voz vibrar logo no início, sem 'i' antes. Em borrow, o 'r' final não é forte como no português.", ["borrow", "books"]], ["The books are due ___ May 12.", "on", "in", "Os livros vencem em 12 de maio.", "Com datas exatas (May 12) usa-se on, não in."], [["The books are due on May 12, so she must come back before that day.", "Os livros vencem em 12 de maio, então ela precisa voltar antes desse dia."], ["It's two dollars. The new books are due on May 12.", "São dois dólares. Os livros novos vencem em 12 de maio."]], [{"t": "c", "q": "I need a ___ to borrow books.", "o": ["library card", "library mark", "library paper"], "pt": "Preciso de um cartão da biblioteca para pegar livros emprestados.", "why": "O documento que se usa na biblioteca é o library card."}, {"t": "l", "say": "The new books are due on May 12.", "o": ["The new books are due on May 12.", "The new books are due on May 2.", "The new books are due in May."], "why": "Você ouviu due on e o dia 12."}, {"t": "b", "pt": "Posso usar a sala de estudo?", "w": ["Can", "I", "use", "the", "study", "room"]}, {"t": "b", "pt": "Eu preciso voltar amanhã.", "w": ["I", "need", "to", "come", "back", "tomorrow"]}]];
