englishA2Plans[297]={"title": "Candidatura a um intercâmbio no Canadá", "file": "", "grammar": "Apply for e planos com will: abroad, application", "goal": "Fale de um intercâmbio usando apply for e will.", "words": [["apply", "candidatar-se"], ["study abroad", "estudar no exterior"], ["exchange program", "programa de intercâmbio"], ["exchange student", "estudante de intercâmbio"], ["recommendation letter", "carta de recomendação"], ["application form", "formulário de inscrição"], ["acceptance letter", "carta de aceitação"], ["host family", "família anfitriã"], ["living abroad", "morar no exterior"], ["culture shock", "choque cultural"]]};
englishA2Content[297]=[[["Kenji wants to study abroad next year.", "Kenji quer estudar no exterior no ano que vem."], ["He decides to apply for an exchange program in Canada.", "Ele decide se candidatar a um programa de intercâmbio no Canadá."], ["First, he fills out the application form and asks his teacher for a recommendation letter.", "Primeiro, ele preenche o formulário de inscrição e pede uma carta de recomendação ao professor."], ["Two months later, he gets an acceptance letter by email.", "Dois meses depois, ele recebe uma carta de aceitação por e-mail."], ["He will be an exchange student, and he will live with a host family.", "Ele será estudante de intercâmbio e vai morar com uma família anfitriã."], ["He is excited, but he is a little afraid of culture shock.", "Ele está animado, mas tem um pouco de medo do choque cultural."]], [["Elena, guess what? I got the acceptance letter this morning!", "Elena, adivinha? Recebi a carta de aceitação hoje de manhã!"], ["Really? That's great! When do you leave for Canada?", "Sério? Que ótimo! Quando você parte para o Canadá?"], ["In August. I'll be an exchange student for six months.", "Em agosto. Vou ser estudante de intercâmbio por seis meses."], ["Wow. Where will you stay? Do you have a host family?", "Nossa. Onde você vai ficar? Você tem uma família anfitriã?"], ["Yes, a nice family in Toronto. They have two kids and a dog.", "Tenho, uma família simpática em Toronto. Eles têm duas crianças e um cachorro."], ["Are you nervous about living abroad? I think I'd feel culture shock.", "Você está nervoso com a ideia de morar no exterior? Acho que eu sentiria choque cultural."], ["A little. But I'll send you photos every week, I promise.", "Um pouco. Mas vou te mandar fotos toda semana, prometo."], ["Perfect! I'm so proud of you.", "Perfeito! Estou muito orgulhosa de você."]], ["/ɔ/ aberto em abroad e August", "Abra bem a boca e arredonde os lábios, quase um 'ó' longo: a-BRÓÓD, Ó-gust. Não diga 'abrôde' fechado.", ["abroad", "August"]], ["Kenji wants to apply ___ a scholarship.", "for", "to", "Kenji quer se candidatar a uma bolsa.", "O verbo apply é seguido de for quando se pede algo."], [["He decides to apply for an exchange program in Canada.", "Ele decide se candidatar a um programa de intercâmbio no Canadá."], ["In August. I'll be an exchange student for six months.", "Em agosto. Vou ser estudante de intercâmbio por seis meses."]], [{"t": "c", "q": "Kenji will be an ___ student in Canada.", "o": ["exchange", "change", "exchanged"], "pt": "Kenji vai ser estudante de intercâmbio no Canadá.", "why": "A expressão fixa é exchange student."}, {"t": "l", "say": "I got the acceptance letter this morning.", "o": ["I got the acceptance letter this morning.", "I got the recommendation letter this morning.", "I got the acceptance letter this evening."], "why": "Você ouviu acceptance e morning."}, {"t": "b", "pt": "Ele quer estudar no exterior.", "w": ["He", "wants", "to", "study", "abroad"]}, {"t": "b", "pt": "Eu vou morar com uma família anfitriã.", "w": ["I", "will", "live", "with", "a", "host", "family"]}]];
