englishA2Plans[298]={"title": "Apresentação oral curta na aula", "file": "", "grammar": "Sequência: first of all, then, to sum up", "goal": "Organize uma apresentação curta com first of all, then e to sum up.", "words": [["to sum up", "resumindo"], ["first of all", "antes de tudo"], ["in conclusion", "em conclusão"], ["rehearse", "ensaiar"], ["eye contact", "contato visual"], ["by the way", "a propósito"], ["note cards", "fichas de anotações"], ["stand up", "levantar-se"], ["speak clearly", "falar com clareza"], ["mind went blank", "deu branco"]]};
englishA2Content[298]=[[["Priya has a short presentation about her hometown.", "Priya tem uma apresentação curta sobre a cidade natal dela."], ["She wants to rehearse at home, so she asks her brother to listen.", "Ela quer ensaiar em casa, então pede ao irmão que escute."], ["She writes the main points on note cards.", "Ela escreve os pontos principais em fichas."], ["In class, she has to stand up and speak clearly.", "Na aula, ela tem de se levantar e falar com clareza."], ["First of all, she shows a map. Then she talks about food.", "Antes de tudo, ela mostra um mapa. Depois fala da comida."], ["To sum up, she says, My city is small but friendly.", "Resumindo, ela diz: Minha cidade é pequena, mas simpática."]], [["Sam, how was your presentation this morning?", "Sam, como foi sua apresentação hoje de manhã?"], ["Scary! I was shaking, and then my mind went blank.", "Assustador! Eu estava tremendo, e então deu branco."], ["Oh no! What did you do?", "Ah, não! O que você fez?"], ["I looked at my note cards, took a breath, and made eye contact with the teacher.", "Olhei para as minhas fichas, respirei e fiz contato visual com a professora."], ["Good idea. Did you speak clearly? I always talk too fast.", "Boa ideia. Você falou com clareza? Eu sempre falo rápido demais."], ["Yes. In conclusion, I think I need to rehearse more, and by the way, you should too!", "Sim. Em conclusão, acho que preciso ensaiar mais e, a propósito, você também deveria!"], ["You're right. Can you listen to me tonight at seven?", "Você tem razão. Pode me ouvir hoje à noite, às sete?"], ["Sure. Come to my house, and bring your note cards.", "Claro. Venha à minha casa e traga suas fichas."]], ["/ʃ/ em presentation e shaking", "Faça o som de 'psiu' pedindo silêncio: lábios um pouco arredondados e ar contínuo. É 'sh', não 'ch' de chuva.", ["presentation", "shaking"]], ["First, I'll show a map. ___, I'll talk about food.", "Then", "Before", "Primeiro, vou mostrar um mapa. Depois, vou falar da comida.", "Para a segunda etapa de uma sequência usa-se Then."], [["First of all, she shows a map. Then she talks about food.", "Antes de tudo, ela mostra um mapa. Depois fala da comida."], ["To sum up, she says, My city is small but friendly.", "Resumindo, ela diz: Minha cidade é pequena, mas simpática."]], [{"t": "c", "q": "___, I think we need more time.", "o": ["In conclusion", "At conclusion", "On conclusion"], "pt": "Em conclusão, acho que precisamos de mais tempo.", "why": "A expressão fixa para encerrar é In conclusion."}, {"t": "l", "say": "Please stand up and speak clearly.", "o": ["Please stand up and speak clearly.", "Please stand up and speak slowly.", "Please sit down and speak clearly."], "why": "Você ouviu stand up e clearly."}, {"t": "b", "pt": "Antes de tudo eu vou mostrar um mapa.", "w": ["First", "of", "all", "I'll", "show", "a", "map"]}, {"t": "b", "pt": "Eu preciso ensaiar hoje à noite.", "w": ["I", "need", "to", "rehearse", "tonight"]}]];
