englishA2Plans[299]={"title": "Revisão: o semestre de estudos", "file": "", "grammar": "Revisão: passado simples e vocabulário de escola", "goal": "Conte como foi seu semestre usando o passado simples.", "words": [["end of the semester", "fim do semestre"], ["study schedule", "plano de estudos"], ["all-nighter", "noite em claro estudando"], ["term paper", "trabalho do semestre"], ["hard work", "trabalho duro"], ["proud of", "orgulhoso de"], ["report card", "boletim"], ["semester break", "férias entre semestres"], ["make friends", "fazer amigos"], ["look back", "olhar para trás"]]};
englishA2Content[299]=[[["It's the end of the semester, and Sam wants to look back.", "É o fim do semestre, e Sam quer olhar para trás."], ["In September, he made a study schedule, but he often stayed up late.", "Em setembro, ele fez um plano de estudos, mas muitas vezes ficou acordado até tarde."], ["He pulled an all-nighter before his term paper was due.", "Ele passou uma noite em claro antes do prazo do trabalho do semestre."], ["His hard work paid off, and the report card showed a B plus.", "O trabalho duro valeu a pena, e o boletim mostrou um B mais."], ["He is proud of his grades, and he wants to make friends with more classmates.", "Ele tem orgulho das notas e quer fazer amizade com mais colegas."], ["Now the semester break starts, and Sam will sleep until noon.", "Agora as férias começam, e Sam vai dormir até o meio-dia."]], [["Sam, how was your first semester? Did you survive?", "Sam, como foi seu primeiro semestre? Você sobreviveu?"], ["Barely! I made a study schedule, but I never followed it.", "Por pouco! Fiz um plano de estudos, mas nunca o segui."], ["Ha! I did the same. I pulled an all-nighter for my term paper.", "Ha! Eu fiz o mesmo. Passei uma noite em claro por causa do trabalho do semestre."], ["Me too. But the hard work paid off. I got a B plus.", "Eu também. Mas o trabalho duro valeu a pena. Tirei B mais."], ["Congratulations! I'm proud of you. Did you see my report card?", "Parabéns! Estou orgulhosa de você. Viu meu boletim?"], ["No, show me! Oh, an A in history! That's amazing.", "Não, mostre! Ah, um A em história! Que incrível."], ["Thanks. Next semester, I want to make friends with more people in class.", "Obrigada. No próximo semestre, quero fazer amizade com mais gente da turma."], ["Me too. Let's start during the semester break and study together in June.", "Eu também. Vamos começar nas férias e estudar juntos em junho."]], ["/h/ em hard e history", "O /h/ inglês é só um sopro de ar saindo da garganta, sem rouquidão. Não troque por 'r' como em 'rard'.", ["hard", "history"]], ["He ___ a study schedule in September.", "made", "maked", "Ele fez um plano de estudos em setembro.", "Make é irregular: o passado é made."], [["In September, he made a study schedule, but he often stayed up late.", "Em setembro, ele fez um plano de estudos, mas muitas vezes ficou acordado até tarde."], ["Barely! I made a study schedule, but I never followed it.", "Por pouco! Fiz um plano de estudos, mas nunca o segui."]], [{"t": "c", "q": "I'm ___ my grades.", "o": ["proud of", "proud with", "proud for"], "pt": "Tenho orgulho das minhas notas.", "why": "O adjetivo proud pede a preposição of."}, {"t": "l", "say": "I pulled an all-nighter for my term paper.", "o": ["I pulled an all-nighter for my term paper.", "I pulled an all-nighter for my report card.", "I pull an all-nighter for my term paper."], "why": "Você ouviu pulled (passado) e term paper."}, {"t": "b", "pt": "Eu quero fazer amigos.", "w": ["I", "want", "to", "make", "friends"]}, {"t": "b", "pt": "É o fim do semestre.", "w": ["It's", "the", "end", "of", "the", "semester"]}]];
