englishA2MiniStories[299]=["O semestre da Lia", "Lia wants to sign up for an advanced English course, but the tuition fee is high.~Lia quer se inscrever num curso avançado de inglês, mas a mensalidade é alta.|She works extra hours, pays the fee, and goes to her first class on Monday.~Ela faz horas extras, paga a mensalidade e vai à primeira aula na segunda.|She is confused by the grammar, so she asks her teacher for help.~Ela fica confusa com a gramática, então pede ajuda ao professor.|In her study group, the students take turns reading and share ideas.~No grupo de estudo, os alunos se revezam lendo e trocam ideias.|She practises with a native speaker every Tuesday and improves her pronunciation.~Ela pratica com uma falante nativa toda terça e melhora a pronúncia.|Before the final exam, she revises with note cards and borrows two books with her library card.~Antes da prova final, ela revisa com fichas e pega dois livros emprestados com o cartão da biblioteca.|She stays up late, but she doesn't panic during the test.~Ela fica acordada até tarde, mas não entra em pânico durante a prova.|Her grade is an eight, so she passes with no problem.~A nota dela é oito, então ela passa sem problema.|Her teacher says she can apply for an exchange program abroad, and she rehearses her speech.~A professora diz que ela pode se candidatar a um intercâmbio no exterior, e ela ensaia o discurso.|In July, Lia stands up, looks at the teacher, and says, I'm ready to study abroad!~Em julho, Lia se levanta, olha para a professora e diz: Estou pronta para estudar no exterior!"];
englishA2Plans[300]={"title": "Aviso de nevasca antes da viagem", "file": "", "grammar": "Previsão do tempo: will, might, it’s going to", "goal": "Fale do tempo de amanhã usando will, might e is going to.", "words": [["weather forecast", "previsão do tempo"], ["blizzard", "nevasca"], ["chance of rain", "chance de chuva"], ["heavy rain", "chuva forte"], ["icy", "gelado, com gelo"], ["clear up", "abrir (o tempo)"], ["thaw", "derreter"], ["snowflake", "floco de neve"], ["raindrop", "gota de chuva"]]};
englishA2Content[300]=[[["Omar checked the weather forecast on Thursday morning.", "Omar viu a previsão do tempo na quinta de manhã."], ["A blizzard is going to hit the town tonight.", "Uma nevasca vai atingir a cidade esta noite."], ["There might be heavy rain first, and then the roads will be icy.", "Pode haver chuva forte primeiro, e depois as ruas vão ficar com gelo."], ["He saw one raindrop on the window, then big snowflakes.", "Ele viu uma gota de chuva na janela e depois grandes flocos de neve."], ["The forecast says the sky will clear up on Saturday.", "A previsão diz que o céu vai abrir no sábado."], ["After that, the snow will thaw, so Omar will drive home on Sunday.", "Depois disso, a neve vai derreter, então Omar vai dirigir para casa no domingo."]], [["Did you see the weather forecast for this weekend, Omar?", "Você viu a previsão do tempo para este fim de semana, Omar?"], ["Yes, I did. A blizzard is going to hit the town tonight.", "Vi, sim. Uma nevasca vai atingir a cidade esta noite."], ["Really? Is there still a chance of rain tomorrow?", "Sério? Ainda tem chance de chuva amanhã?"], ["Yes, sixty percent. It might rain until noon, then change to snow.", "Tem, sessenta por cento. Pode chover até o meio-dia e depois virar neve."], ["The roads are always icy after a storm. I’m worried about the drive.", "As ruas ficam sempre com gelo depois de uma tempestade. Estou preocupado com a viagem."], ["Me too. Let’s leave at eight tonight, before it gets bad.", "Eu também. Vamos sair às oito da noite, antes de piorar."], ["Good idea. When does it clear up? I have a meeting on Monday.", "Boa ideia. Quando o tempo abre? Tenho uma reunião na segunda."], ["Saturday afternoon. The snow will thaw on Sunday, so you’ll be fine.", "Sábado à tarde. A neve vai derreter no domingo, então você vai ficar bem."]], ["/θ/ em thaw e Thursday", "Para o /θ/, coloque a ponta da língua entre os dentes e solte o ar, sem virar /f/ nem /t/.", ["thaw", "Thursday"]], ["Look at those black clouds! It ___ rain very soon.", "is going to", "going to", "Olhe aquelas nuvens pretas! Vai chover em breve.", "Com sinais visíveis use is going to; faltou o verbo be em going to."], [["A blizzard is going to hit the town tonight.", "Uma nevasca vai atingir a cidade esta noite."], ["Yes, sixty percent. It might rain until noon, then change to snow.", "Tem, sessenta por cento. Pode chover até o meio-dia e depois virar neve."]], [{"t": "c", "q": "The snow ___ thaw on Sunday, the forecast says.", "o": ["will", "is will", "going"], "pt": "A neve vai derreter no domingo, diz a previsão.", "why": "Will vem direto antes do verbo, sem is."}, {"t": "l", "say": "The roads will be icy tonight.", "o": ["The roads will be icy tonight.", "The roads were icy tonight.", "The roads will be rainy tonight."], "why": "Will be icy fala do futuro: esta noite."}, {"t": "b", "pt": "Vai nevar muito esta noite.", "w": ["It", "is", "going", "to", "snow", "a", "lot", "tonight"]}, {"t": "b", "pt": "Talvez chova amanhã.", "w": ["It", "might", "rain", "tomorrow"]}]];
