englishA2Plans[302]={"title": "Guia do centro de natureza para crianças", "file": "", "grammar": "Animais e plantas: who, which, that", "goal": "Descreva animais e pessoas com who, which e that.", "words": [["eagle", "águia"], ["nest", "ninho"], ["beetle", "besouro"], ["wolf", "lobo"], ["fox", "raposa"], ["endangered", "em perigo de extinção"], ["hatch", "chocar, eclodir"], ["root", "raiz"]]};
englishA2Content[302]=[[["Lia works at a nature center that teaches kids about animals.", "Lia trabalha num centro de natureza que ensina crianças sobre animais."], ["Today she shows a nest which an eagle built in a tall tree.", "Hoje ela mostra um ninho que uma águia fez numa árvore alta."], ["The eggs hatch in the spring, and the baby birds leave in summer.", "Os ovos chocam na primavera, e os filhotes saem no verão."], ["A boy who loves bugs finds a green beetle under a root.", "Um menino que adora insetos acha um besouro verde debaixo de uma raiz."], ["Lia says the wolf and the fox are animals that live in the nearby forest.", "Lia diz que o lobo e a raposa são animais que vivem na floresta próxima."], ["She also explains that the eagle is endangered, so we need to be careful.", "Ela também explica que a águia está em perigo de extinção, então precisamos ter cuidado."]], [["Lia, what’s that big bird in the tree?", "Lia, que pássaro grande é aquele na árvore?"], ["It’s an eagle. It’s the bird that built the nest near the top.", "É uma águia. É a ave que fez o ninho perto do topo."], ["Wow! When do the eggs hatch?", "Uau! Quando os ovos chocam?"], ["In about two weeks. The eagle is endangered here, so every egg is important.", "Em umas duas semanas. A águia está ameaçada aqui, então cada ovo é importante."], ["I saw a beetle which was under a root. Is it dangerous?", "Vi um besouro que estava debaixo de uma raiz. Ele é perigoso?"], ["No, it’s harmless. It’s the insect that eats old leaves.", "Não, é inofensivo. É o inseto que come folhas velhas."], ["And the animals that live here, like the wolf and the fox, do they come out at night?", "E os animais que vivem aqui, como o lobo e a raposa, saem à noite?"], ["Yes, they hunt at night. Great questions, Noah!", "Sim, eles caçam à noite. Ótimas perguntas, Noah!"]], ["/h/ em hatch e who", "O /h/ inglês é um sopro suave, sem o “r” forte do português: hatch não é “rétch”.", ["hatch", "who"]], ["The boy ___ found the beetle is my cousin.", "who", "which", "O menino que achou o besouro é meu primo.", "Para pessoas use who; which é para coisas e animais."], [["Lia works at a nature center that teaches kids about animals.", "Lia trabalha num centro de natureza que ensina crianças sobre animais."], ["It’s an eagle. It’s the bird that built the nest near the top.", "É uma águia. É a ave que fez o ninho perto do topo."]], [{"t": "c", "q": "An eagle is a bird ___ builds a nest in tall trees.", "o": ["that", "who", "where"], "pt": "A águia é uma ave que faz ninho em árvores altas.", "why": "That liga a ave ao verbo que descreve o que ela faz."}, {"t": "l", "say": "It’s the bird that built the nest.", "o": ["It’s the bird that built the nest.", "It’s the bird that built the net.", "It’s the bird that burned the nest."], "why": "A ave que fez o ninho: built the nest."}, {"t": "b", "pt": "A raposa é um animal que vive aqui.", "w": ["A", "fox", "is", "an", "animal", "that", "lives", "here"]}, {"t": "b", "pt": "Conheço a menina que ama pássaros.", "w": ["I", "know", "the", "girl", "who", "loves", "birds"]}]];
