englishA2Plans[306]={"title": "Mutirão de sábado no canteiro de ervas", "file": "", "grammar": "Cuidar do jardim: imperativo, water, plant, grow", "goal": "Explique o passo a passo de um canteiro usando imperativos e have to.", "words": [["weed", "erva daninha"], ["fertilizer", "adubo, fertilizante"], ["sprinkler", "irrigador"], ["gardener", "jardineiro"], ["dig up", "cavar, revirar"], ["pull out", "arrancar"], ["crop", "colheita, plantação"], ["flower bed", "canteiro de flores"], ["garden hose", "mangueira de jardim"]]};
englishA2Content[306]=[[["Sam is a gardener, and every Saturday he works in the flower bed.", "Sam é jardineiro, e todo sábado ele trabalha no canteiro."], ["First, he has to dig up the hard ground and pull out the weeds.", "Primeiro, ele tem que cavar o chão duro e arrancar as ervas daninhas."], ["Then he puts fertilizer in the soil and plants small herbs.", "Depois ele põe adubo na terra e planta ervas pequenas."], ["He uses the garden hose to water them, and a sprinkler does the grass.", "Ele usa a mangueira de jardim para regá-las, e um irrigador cuida da grama."], ["If the weather is good, this crop will grow fast.", "Se o tempo estiver bom, esta plantação vai crescer rápido."], ["In June, Sam cuts the herbs, and his neighbors enjoy the fresh food.", "Em junho, Sam corta as ervas, e os vizinhos curtem a comida fresca."]], [["Are you ready to start your herb garden, Priya?", "Você está pronta para começar sua horta de ervas, Priya?"], ["Yes! Where do I begin?", "Sim! Por onde eu começo?"], ["First, dig up the ground in your flower bed.", "Primeiro, cave o chão do seu canteiro."], ["It’s really hard. Should I pull out the weeds first?", "Está muito duro. Devo arrancar as ervas daninhas primeiro?"], ["Yes, pull out all of them. Then add some fertilizer.", "Sim, arranque todas. Depois coloque um pouco de adubo."], ["How often do I have to water the herbs? Do I need a garden hose?", "Com que frequência tenho que regar as ervas? Preciso de uma mangueira?"], ["Every morning. Use the hose or a sprinkler. Your first crop will grow in six weeks.", "Toda manhã. Use a mangueira ou um irrigador. Sua primeira colheita cresce em seis semanas."], ["Perfect. I’ll buy the seeds tomorrow.", "Perfeito. Vou comprar as sementes amanhã."]], ["/g/ em garden e grow", "O /g/ inglês é duro, como em “gato”: garden começa com /g/, nunca com /dʒ/.", ["garden", "grow"]], ["Don’t forget to ___ the flowers every morning.", "water", "watering", "Não esqueça de regar as flores toda manhã.", "Depois de to, use o verbo na forma base: water."], [["First, dig up the ground in your flower bed.", "Primeiro, cave o chão do seu canteiro."], ["First, he has to dig up the hard ground and pull out the weeds.", "Primeiro, ele tem que cavar o chão duro e arrancar as ervas daninhas."]], [{"t": "c", "q": "First, ___ up the hard ground.", "o": ["dig", "digging", "digs"], "pt": "Primeiro, cave o chão duro.", "why": "O imperativo usa o verbo na forma base: dig."}, {"t": "l", "say": "Pull out the weeds first.", "o": ["Pull out the weeds first.", "Pull out the seeds first.", "Put out the weeds first."], "why": "Pull out the weeds é arrancar as ervas daninhas."}, {"t": "b", "pt": "Primeiro, arranque as ervas daninhas.", "w": ["First", "pull", "out", "the", "weeds"]}, {"t": "b", "pt": "Eu tenho que regar as plantas todo dia.", "w": ["I", "have", "to", "water", "the", "plants", "every", "day"]}]];
