englishA2Plans[309]={"title": "Revisão: fim de semana ao ar livre", "file": "", "grammar": "Revisão: will/might, past continuous, have to, because e so", "goal": "Revise o bloco contando um fim de semana no lago.", "words": [["go canoeing", "andar de canoa"], ["life jacket", "colete salva-vidas"], ["sleeping bag", "saco de dormir"], ["bug spray", "repelente"], ["fishing rod", "vara de pescar"], ["shoreline", "margem, orla"], ["bird watching", "observação de pássaros"], ["trail map", "mapa da trilha"], ["sandy", "arenoso"], ["starry sky", "céu estrelado"]]};
englishA2Content[309]=[[["Lia and Noah are going to spend the weekend at a lake.", "Lia e Noah vão passar o fim de semana num lago."], ["They pack a sleeping bag, bug spray, and a trail map.", "Eles levam saco de dormir, repelente e mapa da trilha."], ["On Saturday they go canoeing, and they wear a life jacket because it’s safer.", "No sábado eles andam de canoa e usam colete salva-vidas porque é mais seguro."], ["On the sandy shoreline, Noah tries his fishing rod, but he doesn’t catch anything.", "Na margem arenosa, Noah testa a vara de pescar, mas não pega nada."], ["In the evening they do some bird watching, and they see an owl.", "À noite eles observam pássaros e veem uma coruja."], ["Later they lie under a starry sky and talk for hours.", "Depois eles deitam sob um céu estrelado e conversam por horas."]], [["Did you pack the bug spray, Noah? The mosquitoes might be bad.", "Você colocou o repelente, Noah? Os mosquitos podem estar ruins."], ["Yes, it’s in my backpack, next to the sleeping bag.", "Sim, está na minha mochila, ao lado do saco de dormir."], ["Great. We have to wear a life jacket if we go canoeing tomorrow.", "Ótimo. Temos que usar colete salva-vidas se formos de canoa amanhã."], ["I know. The lake is going to be calm, so it should be fun.", "Eu sei. O lago vai estar calmo, então deve ser divertido."], ["I was checking the trail map when you called. The sandy shoreline is ten minutes away.", "Eu estava olhando o mapa da trilha quando você ligou. A margem arenosa fica a dez minutos."], ["Perfect. I want to try my new fishing rod there.", "Perfeito. Quero testar minha vara de pescar nova lá."], ["And after dinner, we can do some bird watching before it gets dark.", "E depois do jantar, podemos observar pássaros antes de escurecer."], ["Sounds like a great plan. I’ll wake you up at seven.", "Parece um ótimo plano. Eu acordo você às sete."]], ["/ŋ/ em canoeing e fishing", "No /ŋ/ final, a parte de trás da língua toca o céu da boca e o ar sai pelo nariz, sem um “g” forte no fim.", ["canoeing", "fishing"]], ["It’s going to be cold, ___ I’ll bring a sleeping bag.", "so", "because", "Vai fazer frio, então vou levar um saco de dormir.", "So liga o resultado: o frio leva à decisão."], [["On Saturday they go canoeing, and they wear a life jacket because it’s safer.", "No sábado eles andam de canoa e usam colete salva-vidas porque é mais seguro."], ["Great. We have to wear a life jacket if we go canoeing tomorrow.", "Ótimo. Temos que usar colete salva-vidas se formos de canoa amanhã."]], [{"t": "c", "q": "We were ___ when it started to rain.", "o": ["canoeing", "canoe", "canoed"], "pt": "Estávamos remando quando começou a chover.", "why": "Was/were pede o verbo com -ing: canoeing."}, {"t": "l", "say": "Don’t forget the bug spray.", "o": ["Don’t forget the bug spray.", "Don’t forget the big spray.", "Don’t forget the bug stray."], "why": "Bug spray é o repelente de insetos."}, {"t": "b", "pt": "Temos que usar colete salva-vidas.", "w": ["We", "have", "to", "wear", "life", "jackets"]}, {"t": "b", "pt": "Talvez a gente veja alguns pássaros.", "w": ["We", "might", "see", "some", "birds"]}]];
