englishA2MiniStories[309]=["Um fim de semana no lago", "Last weekend, Lia and Noah checked the weather forecast before their camping trip.~No fim de semana passado, Lia e Noah viram a previsão do tempo antes da viagem de camping.|It said there might be a little rain, but the sky was going to clear up.~Dizia que podia chover um pouco, mas o céu ia abrir.|They had to pack carefully: a tent, a sleeping bag, bug spray, and a trail map.~Eles tiveram que arrumar tudo com cuidado: barraca, saco de dormir, repelente e mapa da trilha.|On Saturday morning, they were canoeing on the lake when a sudden wind started.~No sábado de manhã, eles remavam no lago quando um vento repentino começou.|They wore life jackets, so they were safe, and they took cover under the trees.~Eles usavam coletes salva-vidas, então estavam seguros, e se abrigaram sob as árvores.|After the rain, they saw an eagle that was flying over the lake.~Depois da chuva, viram uma águia que voava sobre o lago.|They cleaned up the sandy shoreline because they wanted to give back to nature.~Eles limparam a margem arenosa porque queriam retribuir à natureza.|At night they didn’t need an electric light, because the starry sky was bright enough.~À noite eles não precisaram de luz elétrica, porque o céu estrelado estava claro o bastante.|Noah used to hate camping, but now he thinks it’s better than staying home.~Noah costumava odiar camping, mas agora acha melhor do que ficar em casa.|On Sunday they drove home without a traffic jam, and they were already planning the next trip.~No domingo eles voltaram para casa sem engarrafamento e já planejavam a próxima viagem."];
englishA2Plans[310]={"title": "Resenha de um filme de fantasia", "file": "", "grammar": "Passado simples para contar um filme: watched, chose, loved", "goal": "Conte o que aconteceu em um filme usando o passado simples.", "words": [["fantasy", "fantasia"], ["plot twist", "reviravolta"], ["special effects", "efeitos especiais"], ["main character", "personagem principal"], ["subtitles", "legendas"], ["romantic", "romântico"], ["animated", "animado"], ["spectacular", "espetacular"], ["box office", "bilheteria"]]};
englishA2Content[310]=[[["Lia watched a fantasy movie with her brother last night.", "Lia assistiu a um filme de fantasia com o irmão ontem à noite."], ["The special effects were spectacular, and the main character was a young dragon.", "Os efeitos especiais foram espetaculares, e o personagem principal era um dragão jovem."], ["Ben turned on the subtitles because the actors spoke very fast.", "Ben ligou as legendas porque os atores falavam muito rápido."], ["Then a plot twist surprised them both.", "Então uma reviravolta surpreendeu os dois."], ["The movie made millions at the box office last month.", "O filme faturou milhões na bilheteria no mês passado."], ["They didn't like the romantic scene, but they loved the ending.", "Eles não gostaram da cena romântica, mas adoraram o final."]], [["Ben, did you see the new animated movie on Saturday?", "Ben, você viu o novo filme de animação no sábado?"], ["No, I didn't. Lia and I chose a fantasy movie instead.", "Não. A Lia e eu escolhemos um filme de fantasia."], ["Really? What happened in the story?", "Sério? O que aconteceu na história?"], ["A young dragon lost his home, so he crossed the sea to find it.", "Um dragão jovem perdeu a casa, então atravessou o mar para achá-la."], ["Did you like the special effects?", "Você gostou dos efeitos especiais?"], ["I loved them! The last battle looked spectacular on the big screen.", "Adorei! A última batalha ficou espetacular na tela grande."], ["Was there a romantic part? My sister hates those.", "Tinha uma parte romântica? Minha irmã odeia isso."], ["Only a short one, and the plot twist at the end surprised us.", "Só uma curta, e a reviravolta no final nos surpreendeu."], ["Sounds great. I'll watch it tonight with the subtitles on.", "Parece ótimo. Vou assistir hoje à noite com as legendas."], ["Good idea. Some actors talk very fast.", "Boa ideia. Alguns atores falam muito rápido."]], ["/f/ em fantasy e effects", "Encoste os dentes de cima no lábio de baixo e deixe o ar sair; não troque por 'p'. Em fantasy e effects o /f/ é leve e contínuo.", ["fantasy", "effects"]], ["Lia ___ a fantasy movie last night.", "watched", "watch", "Lia assistiu a um filme de fantasia ontem à noite.", "Com last night usamos o passado simples: watched."], [["Lia watched a fantasy movie with her brother last night.", "Lia assistiu a um filme de fantasia com o irmão ontem à noite."], ["No, I didn't. Lia and I chose a fantasy movie instead.", "Não. A Lia e eu escolhemos um filme de fantasia."]], [{"t": "c", "q": "Ben ___ the plot twist at the end.", "o": ["didn't expect", "doesn't expect", "not expected"], "pt": "Ben não esperava a reviravolta no final.", "why": "A negativa do passado é didn't + verbo na forma base."}, {"t": "l", "say": "The special effects were spectacular.", "o": ["The special effects were spectacular.", "The special effects was spectacular.", "The special effect were spectacular."], "why": "Effects está no plural, então usamos were."}, {"t": "b", "pt": "Nós assistimos a um filme de fantasia ontem.", "w": ["We", "watched", "a", "fantasy", "movie", "yesterday"]}, {"t": "b", "pt": "Ben ligou as legendas.", "w": ["Ben", "turned", "on", "the", "subtitles"]}]];
