englishA2Plans[311]={"title": "Do ingresso ao autógrafo no show", "file": "", "grammar": "Present perfect com since: has loved, have been", "goal": "Fale de uma banda e de um show usando since e o passado simples.", "words": [["front row", "primeira fila"], ["sing along", "cantar junto"], ["backstage", "bastidores"], ["performer", "artista (no palco)"], ["autograph", "autógrafo"], ["fan club", "fã-clube"], ["tour bus", "ônibus da turnê"], ["sound check", "passagem de som"], ["live music", "música ao vivo"]]};
englishA2Content[311]=[[["Mia has loved the band Blue Roads since she was twelve.", "A Mia ama a banda Blue Roads desde os doze anos."], ["She joined their fan club and bought two tickets online.", "Ela entrou no fã-clube deles e comprou dois ingressos on-line."], ["At the concert, she and Omar sat in the front row.", "No show, ela e o Omar sentaram na primeira fila."], ["The performer sang her favorite song, and everyone started to sing along.", "O artista cantou a música favorita dela, e todos começaram a cantar junto."], ["After the show, Mia waited near the tour bus for an autograph.", "Depois do show, a Mia esperou perto do ônibus da turnê por um autógrafo."], ["The singer smiled and signed her ticket.", "O cantor sorriu e assinou o ingresso dela."]], [["Mia, how was the concert on Friday night?", "Mia, como foi o show na sexta à noite?"], ["It was amazing! We watched the sound check at five o'clock.", "Foi incrível! Vimos a passagem de som às cinco horas."], ["Seriously? How did you get in so early?", "Sério? Como vocês entraram tão cedo?"], ["My fan club sent us a special email, so we came early.", "Meu fã-clube mandou um e-mail especial, então chegamos cedo."], ["Lucky you! Did you go backstage after the show?", "Que sorte! Vocês foram aos bastidores depois do show?"], ["No, but we waited outside and got an autograph.", "Não, mas esperamos do lado de fora e pegamos um autógrafo."], ["I love live music, but tickets are so expensive.", "Eu adoro música ao vivo, mas os ingressos são muito caros."], ["Ours were only forty dollars, and the seats were great.", "Os nossos custaram só quarenta dólares, e os lugares eram ótimos."], ["Next time, please take me with you.", "Da próxima vez, leve-me com você, por favor."], ["Of course! The band plays here again in March.", "Claro! A banda toca aqui de novo em março."]], ["/ŋ/ em sing e along", "Em sing e along o 'ng' é um único som nasal no fundo da boca; não solte um 'g' no final.", ["sing", "along"]], ["Mia ___ the band since she was twelve.", "has loved", "loves", "A Mia ama a banda desde os doze anos.", "Com since usamos o present perfect: has loved."], [["Mia has loved the band Blue Roads since she was twelve.", "A Mia ama a banda Blue Roads desde os doze anos."], ["She joined their fan club and bought two tickets online.", "Ela entrou no fã-clube deles e comprou dois ingressos on-line."]], [{"t": "c", "q": "My brother ___ this band for three years.", "o": ["has liked", "likes", "is liking"], "pt": "Meu irmão gosta dessa banda há três anos.", "why": "Com for e um período de tempo, usamos o present perfect: has liked."}, {"t": "l", "say": "We sat in the front row.", "o": ["We sat in the front row.", "We sat in the front door.", "We saw in the front row."], "why": "Front row é a primeira fila, e sat é o passado de sit."}, {"t": "b", "pt": "Todos começaram a cantar junto.", "w": ["Everyone", "started", "to", "sing", "along"]}, {"t": "b", "pt": "Nós vimos a passagem de som.", "w": ["We", "watched", "the", "sound", "check"]}]];
