englishA2Plans[312]={"title": "Clube do livro na cafeteria", "file": "", "grammar": "I’ve just finished para ações recém-concluídas", "goal": "Diga que acabou de terminar um livro usando I’ve just finished.", "words": [["page-turner", "livro que prende"], ["pen name", "pseudônimo"], ["book club", "clube do livro"], ["literary", "literário"], ["cliffhanger", "final em suspense"], ["edition", "edição"], ["paragraph", "parágrafo"], ["tales", "contos"], ["publisher", "editora"]]};
englishA2Content[312]=[[["Ana has just finished a page-turner by a writer with a pen name.", "A Ana acabou de terminar um livro que prende, de um escritor com pseudônimo."], ["She read the last chapter on the bus this morning.", "Ela leu o último capítulo no ônibus esta manhã."], ["The first edition had a blue cover, and she loved it.", "A primeira edição tinha uma capa azul, e ela adorou."], ["Every month, she goes to a book club at the Rose Café.", "Todo mês, ela vai a um clube do livro no Café Rose."], ["Last week, the members read tales from many countries.", "Na semana passada, os membros leram contos de vários países."], ["Today, she wants to talk about the cliffhanger at the end.", "Hoje, ela quer falar do final em suspense."]], [["Ana, you look tired. Did you stay up late?", "Ana, você parece cansada. Ficou acordada até tarde?"], ["Yes! I've just finished the new novel, and I couldn't stop.", "Fiquei! Acabei de terminar o romance novo e não consegui parar."], ["Is it a page-turner?", "É um livro que prende?"], ["Totally. Every chapter ends with a surprise.", "Totalmente. Todo capítulo termina com uma surpresa."], ["Who is the author?", "Quem é o autor?"], ["Nobody knows. The publisher says it's a pen name.", "Ninguém sabe. A editora diz que é um pseudônimo."], ["Is it serious literary fiction, or more like a thriller?", "É ficção literária séria ou mais um suspense?"], ["A little of both. One paragraph on page ninety made me cry.", "Um pouco dos dois. Um parágrafo da página noventa me fez chorar."], ["Can I borrow it? I want to read it before the club meets.", "Posso pegar emprestado? Quero ler antes de o clube se reunir."], ["Sure. Just don't read the last page first!", "Claro. Só não leia a última página primeiro!"]], ["/æ/ em chapter e paragraph", "Abra bem a boca: o 'a' de chapter e paragraph fica entre o 'a' e o 'é' do português; não diga 'chápter' com 'ei'.", ["chapter", "paragraph"]], ["Ana has ___ finished a page-turner.", "just", "yet", "A Ana acabou de terminar um livro que prende.", "Just mostra algo muito recente; yet não é usado em frases afirmativas."], [["Ana has just finished a page-turner by a writer with a pen name.", "A Ana acabou de terminar um livro que prende, de um escritor com pseudônimo."], ["Yes! I've just finished the new novel, and I couldn't stop.", "Fiquei! Acabei de terminar o romance novo e não consegui parar."]], [{"t": "c", "q": "I've ___ read the first paragraph.", "o": ["just", "yet", "ago"], "pt": "Eu acabei de ler o primeiro parágrafo.", "why": "Just + present perfect fala de algo que acabou de acontecer."}, {"t": "l", "say": "I've just finished the last chapter.", "o": ["I've just finished the last chapter.", "I've just finishing the last chapter.", "I've just finished the last chapter yet."], "why": "Depois de have, usamos o particípio: finished."}, {"t": "b", "pt": "Eu acabei de terminar o livro.", "w": ["I've", "just", "finished", "the", "book"]}, {"t": "b", "pt": "Todo capítulo termina com um suspense.", "w": ["Every", "chapter", "ends", "with", "a", "cliffhanger"]}]];
