englishA2Plans[313]={"title": "Final do campeonato no bar", "file": "", "grammar": "Passado simples para contar uma partida: scored, lost", "goal": "Conte o placar e os lances de uma partida usando o passado simples.", "words": [["half-time", "intervalo"], ["extra time", "prorrogação"], ["final whistle", "apito final"], ["kick off", "começar o jogo"], ["lose to", "perder para"], ["tie game", "empate"], ["season ticket", "ingresso de temporada"], ["supporters", "torcedores"], ["penalty", "pênalti"], ["finals", "finais"]]};
englishA2Content[313]=[[["Tom and Priya watched the finals at a sports bar downtown.", "Tom e Priya assistiram às finais em um bar de esportes no centro."], ["The supporters sang loudly before the kick off.", "Os torcedores cantaram alto antes do início do jogo."], ["At half-time, the score was one to one.", "No intervalo, o placar estava um a um."], ["In extra time, the home team got a penalty.", "Na prorrogação, o time da casa ganhou um pênalti."], ["The striker scored, and the supporters jumped out of their seats.", "O atacante marcou, e os torcedores pularam das cadeiras."], ["After the final whistle, Tom's team lost to Priya's team, two to one.", "Depois do apito final, o time do Tom perdeu para o time da Priya, por dois a um."]], [["Priya, did you watch the match on Sunday?", "Priya, você assistiu à partida no domingo?"], ["Of course! I have a season ticket, but I watched it at Tom's place.", "Claro! Tenho ingresso de temporada, mas assisti na casa do Tom."], ["Who scored first?", "Quem marcou primeiro?"], ["The red team scored in the tenth minute. Then it was a tie game until half-time.", "O time vermelho marcou no décimo minuto. Depois ficou empatado até o intervalo."], ["Was the second half boring?", "O segundo tempo foi chato?"], ["Not at all! There was a penalty in extra time, and everybody screamed.", "De jeito nenhum! Teve um pênalti na prorrogação, e todo mundo gritou."], ["Who took it?", "Quem bateu?"], ["Their captain. He scored, and we lost.", "O capitão deles. Ele marcou, e nós perdemos."], ["Don't worry. We beat them in April, remember?", "Não se preocupe. Nós ganhamos deles em abril, lembra?"], ["True. I'll bring my lucky scarf next time.", "Verdade. Vou levar meu cachecol da sorte da próxima vez."]], ["/s/ inicial em sports e score", "Comece com um 's' limpo, sem 'e' na frente; não diga 'esports' nem 'escore'. O ar passa fino entre a língua e os dentes.", ["sports", "score"]], ["Tom's team ___ to Priya's team.", "lost", "lose", "O time do Tom perdeu para o time da Priya.", "Falamos de um jogo que já acabou, então usamos o passado simples: lost."], [["After the final whistle, Tom's team lost to Priya's team, two to one.", "Depois do apito final, o time do Tom perdeu para o time da Priya, por dois a um."], ["Not at all! There was a penalty in extra time, and everybody screamed.", "De jeito nenhum! Teve um pênalti na prorrogação, e todo mundo gritou."]], [{"t": "c", "q": "The supporters ___ loudly before the kick off.", "o": ["sang", "sing", "sung"], "pt": "Os torcedores cantaram alto antes do início do jogo.", "why": "Before the kick off fala de algo passado, e sang é o passado de sing."}, {"t": "l", "say": "The score was one to one at half-time.", "o": ["The score was one to one at half-time.", "The score is one to one at half-time.", "The score was won to one at half-time."], "why": "One to one é o placar, e was marca o passado."}, {"t": "b", "pt": "O time deles perdeu para nós.", "w": ["Their", "team", "lost", "to", "us"]}, {"t": "b", "pt": "Houve um pênalti na prorrogação.", "w": ["There", "was", "a", "penalty", "in", "extra", "time"]}]];
