englishA2Plans[315]={"title": "Planejando a festa dos 70 anos da vovó Rita", "file": "", "grammar": "Invite … to e celebrate para convidar e comemorar", "goal": "Convide alguém para uma festa usando invite … to e fale de uma surpresa.", "words": [["birthday party", "festa de aniversário"], ["guest list", "lista de convidados"], ["party favors", "lembrancinhas de festa"], ["make a wish", "fazer um pedido"], ["blow out", "soprar (velas)"], ["pop out", "aparecer de repente"], ["throw a party", "dar uma festa"], ["give a toast", "fazer um brinde"], ["dress code", "código de vestimenta"], ["thank-you note", "cartão de agradecimento"]]};
englishA2Content[315]=[[["Rosa and Kenji are going to throw a party for Grandma Rita.", "Rosa e Kenji vão dar uma festa para a vovó Rita."], ["They made a guest list and invited thirty people to the birthday party.", "Eles fizeram uma lista de convidados e convidaram trinta pessoas para a festa de aniversário."], ["The dress code is simple: everyone wears something red.", "O código de vestimenta é simples: todos usam algo vermelho."], ["Kenji will give a toast, and Rosa will bring the cake.", "Kenji vai fazer um brinde, e Rosa vai trazer o bolo."], ["Grandma will make a wish and blow out the candles.", "A vovó vai fazer um pedido e soprar as velas."], ["At the end, the guests will get small party favors and a thank-you note.", "No fim, os convidados vão ganhar lembrancinhas e um cartão de agradecimento."]], [["Rosa, did you invite all of Grandma's friends to the party?", "Rosa, você convidou todos os amigos da vovó para a festa?"], ["Yes, thirty people said yes, but Mr. Lee can't come.", "Sim, trinta pessoas aceitaram, mas o Sr. Lee não pode ir."], ["That's okay. Is the surprise still a secret?", "Tudo bem. A surpresa ainda é segredo?"], ["Yes! She thinks we're only going to celebrate with a small dinner.", "É! Ela acha que vamos só comemorar com um jantarzinho."], ["Perfect. When she opens the door, we'll all pop out and yell, “Surprise!”", "Perfeito. Quando ela abrir a porta, vamos todos aparecer e gritar: “Surpresa!”"], ["I love it. Dad will give a toast, and then we'll sing.", "Adorei. O papai vai fazer um brinde, e depois vamos cantar."], ["Don't forget the dress code and the party favors for the kids.", "Não esqueça o código de vestimenta e as lembrancinhas das crianças."], ["Don't worry. I already wrote the thank-you notes. See you at five!", "Fique tranquila. Eu já escrevi os cartões de agradecimento. Até as cinco!"]], ["/w/ em wish e wears", "Arredonde os lábios como em 'uau' antes da vogal; não troque por 'v' nem por 'gu' forte. Em wish e wears o /w/ é curto.", ["wish", "wears"]], ["Rosa invited thirty people ___ the birthday party.", "to", "for", "A Rosa convidou trinta pessoas para a festa de aniversário.", "Depois de invited + pessoa, usamos to para o evento."], [["They made a guest list and invited thirty people to the birthday party.", "Eles fizeram uma lista de convidados e convidaram trinta pessoas para a festa de aniversário."], ["Rosa, did you invite all of Grandma's friends to the party?", "Rosa, você convidou todos os amigos da vovó para a festa?"]], [{"t": "c", "q": "We invited our neighbors ___ the dinner.", "o": ["to", "for", "in"], "pt": "Nós convidamos nossos vizinhos para o jantar.", "why": "Invite someone to + evento."}, {"t": "l", "say": "We will pop out and yell surprise.", "o": ["We will pop out and yell surprise.", "We will pop up and yell surprise.", "We will drop out and yell surprise."], "why": "Pop out é aparecer de repente; as outras mudam o sentido."}, {"t": "b", "pt": "Nós convidamos trinta pessoas para a festa.", "w": ["We", "invited", "thirty", "people", "to", "the", "party"]}, {"t": "b", "pt": "Ela vai fazer um pedido.", "w": ["She", "will", "make", "a", "wish"]}]];
