englishA2Plans[316]={"title": "Noite de jogos na casa do Noah", "file": "", "grammar": "It’s your turn e take turns nos jogos", "goal": "Diga de quem é a vez usando It’s your turn.", "words": [["board game", "jogo de tabuleiro"], ["card game", "jogo de cartas"], ["game night", "noite de jogos"], ["roll the dice", "jogar os dados"], ["your move", "sua jogada"], ["video game", "videogame"], ["game over", "fim de jogo"], ["high score", "recorde de pontos"], ["cheat code", "código de trapaça"], ["jigsaw puzzle", "quebra-cabeça"]]};
englishA2Content[316]=[[["Noah invited three friends to game night on Friday.", "Noah convidou três amigos para a noite de jogos na sexta."], ["First, they played a card game, and Sam won twice.", "Primeiro, eles jogaram cartas, e o Sam ganhou duas vezes."], ["Then they opened a board game with three levels.", "Depois abriram um jogo de tabuleiro com três níveis."], ["It was Noah's turn to roll the dice, and he moved six squares.", "Era a vez do Noah de jogar os dados, e ele andou seis casas."], ["“Your move, Sam!” he said.", "“Sua jogada, Sam!”, ele disse."], ["Later, they finished a jigsaw puzzle together.", "Mais tarde, eles terminaram um quebra-cabeça juntos."]], [["Sam, do you want to play a video game after dinner?", "Sam, você quer jogar videogame depois do jantar?"], ["Sure, but it's your turn to choose, Noah.", "Claro, mas é a sua vez de escolher, Noah."], ["Okay. Let's try the space game. I'm on level four and I need help.", "Certo. Vamos tentar o jogo espacial. Estou no nível quatro e preciso de ajuda."], ["Careful! It says game over when the timer reaches zero.", "Cuidado! Aparece game over quando o cronômetro chega a zero."], ["Oh no, I just lost again. My high score is only twelve thousand.", "Ai, não, acabei de perder de novo. Meu recorde é só doze mil."], ["Don't use a cheat code. That's not fair!", "Não use código de trapaça. Isso não é justo!"], ["Okay, no cheat code. It's your turn now.", "Tá bom, sem código de trapaça. Agora é a sua vez."], ["Thanks. I'm going to beat your high score.", "Valeu. Vou bater o seu recorde."]], ["/dʒ/ em jigsaw e just", "Comece com 'dj' juntos, como em 'djavan' dito rápido; não troque por 'j' do francês. Em jigsaw e just a língua toca o céu da boca.", ["jigsaw", "just"]], ["It was Noah's ___ to roll the dice.", "turn", "time", "Era a vez do Noah de jogar os dados.", "Para falar de vez em um jogo, usamos turn, não time."], [["It was Noah's turn to roll the dice, and he moved six squares.", "Era a vez do Noah de jogar os dados, e ele andou seis casas."], ["Sure, but it's your turn to choose, Noah.", "Claro, mas é a sua vez de escolher, Noah."]], [{"t": "c", "q": "We take ___ with the video game.", "o": ["turns", "times", "moves"], "pt": "Nós nos revezamos no videogame.", "why": "A expressão fixa é take turns."}, {"t": "l", "say": "It's your turn to play.", "o": ["It's your turn to play.", "It's your time to play.", "It's you turn to play."], "why": "A vez de alguém é your turn; you turn estaria errado."}, {"t": "b", "pt": "Agora é a vez da Lia.", "w": ["It's", "Lia's", "turn", "now"]}, {"t": "b", "pt": "Meu recorde é doze mil.", "w": ["My", "high", "score", "is", "twelve", "thousand"]}]];
