englishA2Plans[317]={"title": "Aula de arte e exposição da escola", "file": "", "grammar": "Passado simples com draw e paint", "goal": "Conte o que você desenhou ou pintou usando o passado simples.", "words": [["oil painting", "pintura a óleo"], ["art class", "aula de arte"], ["work of art", "obra de arte"], ["photo album", "álbum de fotos"], ["take a picture", "tirar uma foto"], ["zoom in", "dar zoom"], ["art show", "exposição de arte"], ["color palette", "paleta de cores"], ["wall painting", "pintura de parede"], ["craft", "artesanato"]]};
englishA2Content[317]=[[["Elena joined an art class in September.", "A Elena entrou em uma aula de arte em setembro."], ["She likes to draw, but her favorite craft is painting.", "Ela gosta de desenhar, mas o artesanato favorito dela é a pintura."], ["Her first oil painting shows a small boat on a blue lake.", "A primeira pintura a óleo dela mostra um barquinho em um lago azul."], ["Her teacher chose it for the school exhibition.", "A professora escolheu o quadro para a exposição da escola."], ["Elena took a picture of it and put it in her photo album.", "A Elena tirou uma foto dele e colocou no álbum de fotos."], ["She says it's not a work of art, but everybody clapped.", "Ela diz que não é uma obra de arte, mas todo mundo aplaudiu."]], [["Omar, did you go to the art show yesterday?", "Omar, você foi à exposição de arte ontem?"], ["Yes! Elena painted a beautiful wall painting at the entrance.", "Fui! A Elena pintou uma linda pintura de parede na entrada."], ["How did she do it? That wall is huge.", "Como ela fez isso? Aquela parede é enorme."], ["She used a ladder and a small color palette with only four colors.", "Ela usou uma escada e uma paleta de cores pequena, com só quatro cores."], ["Impressive. I can't even draw a straight line.", "Impressionante. Eu nem consigo desenhar uma linha reta."], ["Me neither. I'll zoom in on my photos at home to see the small flowers.", "Eu também não. Vou dar zoom nas minhas fotos em casa para ver as florzinhas."], ["Is she going to teach another art class?", "Ela vai dar outra aula de arte?"], ["Yes, next month, on Thursdays. Do you want to join?", "Vai, no mês que vem, às quintas. Quer participar?"], ["Definitely! I'll sign up this week.", "Com certeza! Vou me inscrever esta semana."], ["Great, I'll send you the schedule tonight.", "Ótimo, vou te mandar os horários hoje à noite."]], ["/p/ aspirado em paint e picture", "Em paint e picture solte um sopro de ar junto com o /p/ (ponha a mão na frente da boca e sinta). Em português o 'p' é mais seco.", ["paint", "picture"]], ["Last week, she ___ a wall painting at school.", "painted", "paint", "Na semana passada, ela pintou uma pintura de parede na escola.", "Com last week usamos o passado simples: painted."], [["Elena joined an art class in September.", "A Elena entrou em uma aula de arte em setembro."], ["Yes! Elena painted a beautiful wall painting at the entrance.", "Fui! A Elena pintou uma linda pintura de parede na entrada."]], [{"t": "c", "q": "Last year, Mia ___ a big picture of the sea.", "o": ["painted", "paint", "painting"], "pt": "No ano passado, a Mia pintou um quadro grande do mar.", "why": "Last year pede o passado simples: painted."}, {"t": "l", "say": "I took a picture of the painting.", "o": ["I took a picture of the painting.", "I take a picture of the painting.", "I taken a picture of the painting."], "why": "Took é o passado de take."}, {"t": "b", "pt": "Eu entrei em uma aula de arte em setembro.", "w": ["I", "joined", "an", "art", "class", "in", "September"]}, {"t": "b", "pt": "Ela pintou um quadro a óleo.", "w": ["She", "painted", "an", "oil", "painting"]}]];
