englishA2Plans[318]={"title": "Dando a sua opinião sobre o filme", "file": "", "grammar": "I think it’s… e In my opinion para opinar", "goal": "Dê sua opinião sobre um filme usando I think it’s… e In my opinion.", "words": [["tragedy", "tragédia"], ["applaud", "aplaudir"], ["celebrity", "celebridade"], ["entertainment", "entretenimento"], ["unforgettable", "inesquecível"], ["unpredictable", "imprevisível"], ["dramatic", "dramático"], ["tale", "conto, história"], ["thumbs up", "joinha, aprovação"]]};
englishA2Content[318]=[[["Mia and Sam saw a dramatic movie about two sisters.", "Mia e Sam viram um filme dramático sobre duas irmãs."], ["In my opinion, it was a tragedy, but a beautiful one.", "Na minha opinião, foi uma tragédia, mas uma tragédia bonita."], ["Sam thinks the ending was unpredictable.", "Sam acha que o final foi imprevisível."], ["At the end, many people applauded in the theater.", "No final, muita gente aplaudiu no cinema."], ["Mia says the main actress is a celebrity now.", "Mia diz que a atriz principal agora é uma celebridade."], ["Mia gave the movie a thumbs up, and Sam did too.", "Mia deu um joinha para o filme, e o Sam também."]], [["Sam, what do you think of the movie we saw last night?", "Sam, o que você achou do filme que vimos ontem à noite?"], ["In my opinion, it was too long, but the story was great.", "Na minha opinião, foi longo demais, mas a história era ótima."], ["I think it's an unforgettable movie, and the best entertainment of the year.", "Acho que é um filme inesquecível e o melhor entretenimento do ano."], ["Really? I thought the middle part was boring.", "Sério? Achei a parte do meio chata."], ["Maybe, but the ending surprised everybody in the theater.", "Talvez, mas o final surpreendeu todo mundo no cinema."], ["True. I think it's a classic tale about family, honestly.", "Verdade. Acho que é uma história clássica sobre família, para ser sincero."], ["Exactly. Are you going to recommend it to your sister?", "Exato. Você vai recomendar para a sua irmã?"], ["Yes, I think she'll love it. I'll give it a thumbs up.", "Vou, acho que ela vai adorar. Vou dar um joinha."]], ["/ʌ/ em unforgettable e unpredictable", "O prefixo un- soa como 'an' curto, com a boca relaxada; não diga 'uni'. Em unforgettable e unpredictable a sílaba forte vem depois.", ["unforgettable", "unpredictable"]], ["___ my opinion, the ending was too sad.", "In", "On", "Na minha opinião, o final foi triste demais.", "A expressão fixa é in my opinion; on my opinion não existe."], [["In my opinion, it was a tragedy, but a beautiful one.", "Na minha opinião, foi uma tragédia, mas uma tragédia bonita."], ["I think it's an unforgettable movie, and the best entertainment of the year.", "Acho que é um filme inesquecível e o melhor entretenimento do ano."]], [{"t": "c", "q": "___ my opinion, the movie was funny.", "o": ["In", "On", "At"], "pt": "Na minha opinião, o filme foi engraçado.", "why": "Usamos in my opinion para dar uma opinião."}, {"t": "l", "say": "I think it's an unforgettable movie.", "o": ["I think it's an unforgettable movie.", "I think is an unforgettable movie.", "I thinks it's an unforgettable movie."], "why": "Depois de I think, a frase precisa do sujeito it e do verbo 's (is)."}, {"t": "b", "pt": "Na minha opinião, o final foi triste.", "w": ["In", "my", "opinion", "the", "ending", "was", "sad"]}, {"t": "b", "pt": "Eu acho que é um filme dramático.", "w": ["I", "think", "it's", "a", "dramatic", "movie"]}]];
