englishA2Plans[319]={"title": "Revisão: uma noite de cinema", "file": "", "grammar": "Revisão: passado simples, present perfect e opinião", "goal": "Revise a noite de cinema contando o que aconteceu e dando sua opinião.", "words": [["movie night", "noite de cinema"], ["movie theater", "cinema (sala)"], ["ticket booth", "bilheteria"], ["snack bar", "lanchonete"], ["closing credits", "créditos finais"], ["midnight show", "sessão da meia-noite"], ["wait in line", "esperar na fila"], ["movie poster", "pôster de filme"], ["last row", "última fileira"], ["burst into tears", "cair no choro"]]};
englishA2Content[319]=[[["Rosa and Noah planned a movie night at the new movie theater.", "Rosa e Noah planejaram uma noite de cinema no cinema novo."], ["They bought tickets at the ticket booth before nine.", "Eles compraram ingressos na bilheteria antes das nove."], ["At the snack bar, Noah bought a large popcorn.", "Na lanchonete, Noah comprou uma pipoca grande."], ["They sat in the last row because the other seats were full.", "Eles sentaram na última fileira porque os outros lugares estavam ocupados."], ["Rosa laughed at the funny parts and cried at the sad ones.", "Rosa riu das partes engraçadas e chorou nas tristes."], ["When the closing credits started, everybody clapped.", "Quando os créditos finais começaram, todo mundo bateu palmas."]], [["Noah, did you enjoy the midnight show on Friday?", "Noah, você curtiu a sessão da meia-noite na sexta?"], ["Yes! But we had to wait in line for an hour at the ticket booth.", "Curti! Mas tivemos de esperar na fila uma hora na bilheteria."], ["An hour? Wow. Did you get good seats?", "Uma hora? Nossa. Vocês conseguiram bons lugares?"], ["Just the last row, but I could see everything.", "Só na última fileira, mas eu via tudo."], ["What did you think of the movie? I saw the movie poster, and it looked funny.", "O que você achou do filme? Vi o pôster, e parecia engraçado."], ["In my opinion, it was great, but the ending was sad, and Rosa burst into tears.", "Na minha opinião, foi ótimo, mas o final foi triste, e a Rosa caiu no choro."], ["Really? I love sad endings. Did you stay for the closing credits?", "Sério? Adoro finais tristes. Vocês ficaram até os créditos finais?"], ["Yes, we did. The music was beautiful. We left at three in the morning.", "Ficamos, sim. A música era linda. Saímos às três da manhã."], ["I'm jealous. Let's go together next weekend.", "Tenho inveja. Vamos juntos no próximo fim de semana."], ["Sure! There's another midnight show on Saturday.", "Claro! Tem outra sessão da meia-noite no sábado."]], ["/aɪ/ em night e midnight", "Em night e midnight o som é o ditongo 'ai', e o t final é leve; não diga 'naite' com um 'e' no fim.", ["night", "midnight"]], ["We ___ the movie poster before the show.", "saw", "see", "Nós vimos o pôster do filme antes da sessão.", "Before the show fala de algo passado, então usamos saw."], [["They sat in the last row because the other seats were full.", "Eles sentaram na última fileira porque os outros lugares estavam ocupados."], ["Yes! But we had to wait in line for an hour at the ticket booth.", "Curti! Mas tivemos de esperar na fila uma hora na bilheteria."]], [{"t": "c", "q": "Rosa ___ into tears at the end of the movie.", "o": ["burst", "bursted", "bursting"], "pt": "A Rosa caiu no choro no final do filme.", "why": "O passado de burst é burst, igual ao presente."}, {"t": "l", "say": "We waited in line at the ticket booth.", "o": ["We waited in line at the ticket booth.", "We waited on line at the ticket booth.", "We wait in line at the ticket booth."], "why": "Em inglês americano dizemos wait in line, e o passado é waited."}, {"t": "b", "pt": "Eles sentaram na última fileira.", "w": ["They", "sat", "in", "the", "last", "row"]}, {"t": "b", "pt": "Na minha opinião, foi ótimo.", "w": ["In", "my", "opinion", "it", "was", "great"]}]];
