englishA2MiniStories[319]=["O aniversário em noite de cinema", "Rosa wanted a different birthday party, so she planned a movie night.~A Rosa queria uma festa de aniversário diferente, então planejou uma noite de cinema.|She made a short guest list and invited five friends.~Ela fez uma lista de convidados curta e convidou cinco amigos.|Omar brought a board game in case the movie was boring.~Omar trouxe um jogo de tabuleiro, caso o filme fosse chato.|Before the movie, they checked the latest news, and the weather report said rain.~Antes do filme, eles viram as últimas notícias, e a previsão do tempo dizia chuva.|Noah chose a fantasy movie, and the special effects were spectacular.~Noah escolheu um filme de fantasia, e os efeitos especiais eram espetaculares.|Suddenly the power went out, and the screen turned black.~De repente a luz acabou, e a tela ficou preta.|Nobody panicked, so they sang along to Rosa's favorite band and played a card game.~Ninguém entrou em pânico, então cantaram junto com a banda favorita da Rosa e jogaram cartas.|When the lights came back, the movie started again.~Quando a luz voltou, o filme recomeçou.|In my opinion, it was the best birthday ever, Rosa said.~Na minha opinião, foi o melhor aniversário de todos, disse a Rosa.|Noah has just ordered a movie poster for next year's party.~Noah acabou de encomendar um pôster de filme para a festa do ano que vem."];
englishA2ExtraWordExamples[319]={"wait in line": ["I don't like to wait in line for popcorn.", "Não gosto de esperar na fila da pipoca."]};
englishA2Plans[320]={"title": "Conhecendo gente no clube de corrida", "file": "", "grammar": "Fazer novos amigos: How do you know…? e have in common", "goal": "Puxe conversa com alguém novo usando How do you know…? e descubra o que vocês têm em comum.", "words": [["acquaintance", "conhecido(a)"], ["mutual", "em comum (amigo mútuo)"], ["in common", "em comum"], ["get along", "se dar bem"], ["talkative", "falante, tagarela"], ["hang out", "sair, passar tempo juntos"], ["nickname", "apelido"], ["run into", "topar com, encontrar sem querer"], ["curious", "curioso(a)"]]};
englishA2Content[320]=[[["Ben joined a running club last month, but he didn't know anyone.", "Ben entrou num clube de corrida no mês passado, mas não conhecia ninguém."], ["Yesterday he happened to run into Mia, an acquaintance from the club, at the supermarket.", "Ontem ele topou por acaso com a Mia, uma conhecida do clube, no supermercado."], ["Mia is very talkative, and she asked him about his weekends.", "A Mia é muito falante e perguntou a ele sobre os fins de semana."], ["They found out they have a lot in common: old movies and spicy food.", "Eles descobriram que têm muito em comum: filmes antigos e comida picante."], ["Her nickname in the club is Rocket, and Ben is curious about why.", "O apelido dela no clube é Rocket, e o Ben está curioso para saber por quê."], ["Now they get along well, and they hang out after every run.", "Agora eles se dão bem e saem juntos depois de toda corrida."]], [["Hi, I'm Omar. How do you know Mia?", "Oi, eu sou o Omar. De onde você conhece a Mia?"], ["We run together on Tuesdays. We're just acquaintances, really.", "Corremos juntos às terças. Somos só conhecidos, na verdade."], ["Oh, she's an old friend of mine, so we have a mutual friend!", "Ah, ela é uma velha amiga minha, então temos uma amiga em comum!"], ["Nice! She told me you play the guitar. Do you play in a band?", "Legal! Ela me disse que você toca violão. Você toca em uma banda?"], ["Yes, we practice every Friday at eight. What do you do on weekends?", "Toco, ensaiamos toda sexta às oito. O que você faz nos fins de semana?"], ["I usually hang out with friends or watch old movies.", "Eu geralmente saio com amigos ou assisto a filmes antigos."], ["Really? We have that in common! What's your favorite one?", "Sério? Temos isso em comum! Qual é o seu favorito?"], ["Casablanca. Hey, why do people call Mia Rocket?", "Casablanca. Ei, por que chamam a Mia de Rocket?"], ["It's her nickname. She runs so fast that nobody can catch her. Why don't you come to our next practice?", "É o apelido dela. Ela corre tão rápido que ninguém a alcança. Por que você não vem ao nosso próximo ensaio?"], ["Sure, I'd love to. I'll be there on Friday at eight.", "Claro, eu adoraria. Estarei lá na sexta, às oito."]], ["/ʌ/ em run e club", "O /ʌ/ de run e club é curto e vem do fundo da boca, entre 'a' e 'ó'; não diga 'rãn'.", ["run", "club"]], ["How ___ you know Mia?", "do", "are", "De onde você conhece a Mia?", "Em perguntas no presente simples, how pede o auxiliar do, não o verbo be."], [["Hi, I'm Omar. How do you know Mia?", "Oi, eu sou o Omar. De onde você conhece a Mia?"], ["Really? We have that in common! What's your favorite one?", "Sério? Temos isso em comum! Qual é o seu favorito?"]], [{"t": "c", "q": "We both love hiking. We have a lot ___.", "o": ["in common", "on common", "of common"], "pt": "Nós dois amamos fazer trilhas. Temos muito em comum.", "why": "A expressão fixa é have … in common."}, {"t": "l", "say": "How do you know Sam?", "o": ["How do you know Sam?", "How you know Sam?", "How are you know Sam?"], "why": "A pergunta correta usa do depois de how: How do you know Sam?"}, {"t": "b", "pt": "Como você conhece o Ben?", "w": ["How", "do", "you", "know", "Ben"]}, {"t": "b", "pt": "Nós temos muito em comum", "w": ["We", "have", "a", "lot", "in", "common"]}]];
