englishA2Plans[321]={"title": "Esqueci o jantar de aniversário da Lia", "file": "", "grammar": "Pedir desculpas e perdoar: I'm sorry for… e It doesn't matter", "goal": "Peça desculpas com I'm sorry for + -ing e aceite um pedido de desculpas com It doesn't matter.", "words": [["apology", "pedido de desculpas"], ["embarrassed", "envergonhado(a)"], ["let down", "decepcionar"], ["my fault", "minha culpa"], ["ashamed", "com vergonha (culpado)"], ["mean to", "ter a intenção de"], ["regret", "lamentar, arrepender-se"], ["make up", "fazer as pazes"], ["guilt", "culpa (sentimento)"]]};
englishA2Content[321]=[[["Tom forgot Lia's birthday dinner on Friday.", "O Tom esqueceu o jantar de aniversário da Lia na sexta."], ["She waited at the restaurant for an hour, and she felt let down.", "Ela esperou no restaurante por uma hora e se sentiu decepcionada."], ["Tom was embarrassed, and he felt ashamed when he saw her messages.", "O Tom ficou constrangido e sentiu vergonha quando viu as mensagens dela."], ["He called her and said, \"I'm sorry for forgetting. It's my fault.\"", "Ele ligou para ela e disse: \"Desculpe por esquecer. A culpa é minha.\""], ["\"I didn't mean to hurt you,\" he added, and he sent flowers with a written apology.", "\"Eu não quis te magoar\", acrescentou, e mandou flores com um pedido de desculpas por escrito."], ["Lia said, \"It doesn't matter now. Let's make up over cake.\"", "A Lia disse: \"Agora não importa. Vamos fazer as pazes com bolo.\""]], [["Lia, I'm so sorry for missing your dinner. It was my fault.", "Lia, sinto muito por perder o seu jantar. Foi culpa minha."], ["I waited for an hour, Tom. I really felt let down.", "Esperei por uma hora, Tom. Eu me senti muito decepcionada."], ["I know, and I feel a lot of guilt. I didn't mean to forget.", "Eu sei, e sinto muita culpa. Eu não quis esquecer."], ["Where were you? You weren't answering your phone.", "Onde você estava? Você não atendia o telefone."], ["My battery died, and I was stuck at the office until nine.", "Minha bateria acabou, e fiquei preso no escritório até as nove."], ["Hmm. Honestly, I'd prefer a real apology to excuses.", "Hmm. Sinceramente, prefiro um pedido de desculpas de verdade a desculpas esfarrapadas."], ["You're right. I regret not calling you earlier. I'm sorry for everything.", "Você tem razão. Lamento não ter ligado antes. Peço desculpas por tudo."], ["OK, it doesn't matter anymore. Let's make up and have dessert.", "Tudo bem, não importa mais. Vamos fazer as pazes e comer sobremesa."]], ["/h/ em honestly (h mudo) e hurt", "Em honestly o 'h' é mudo: diga 'ónestli'. Em hurt o 'h' é um sopro leve de ar, sem o 'r' forte do português.", ["honestly", "hurt"]], ["I'm sorry ___ being late.", "for", "by", "Desculpe por chegar atrasado.", "Depois de sorry usamos for + -ing para dizer o motivo do pedido de desculpas."], [["Lia, I'm so sorry for missing your dinner. It was my fault.", "Lia, sinto muito por perder o seu jantar. Foi culpa minha."], ["OK, it doesn't matter anymore. Let's make up and have dessert.", "Tudo bem, não importa mais. Vamos fazer as pazes e comer sobremesa."]], [{"t": "c", "q": "I'm sorry ___ breaking your cup.", "o": ["for", "to", "with"], "pt": "Desculpe por quebrar a sua xícara.", "why": "Para dar o motivo do pedido de desculpas, usamos sorry for + -ing."}, {"t": "l", "say": "It doesn't matter. Let's make up.", "o": ["It doesn't matter. Let's make up.", "It doesn't matter. Let's make out.", "It didn't matter. Let's take up."], "why": "Make up significa fazer as pazes; It doesn't matter diz que não tem problema."}, {"t": "b", "pt": "Desculpe por esquecer", "w": ["I'm", "sorry", "for", "forgetting"]}, {"t": "b", "pt": "Eu não quis te magoar", "w": ["I", "didn't", "mean", "to", "hurt", "you"]}]];
