englishA2Plans[322]={"title": "Agradecendo à vizinha pelo bolo", "file": "", "grammar": "Elogiar e agradecer: That's so kind of you", "goal": "Agradeça e elogie com That's so kind of you e It means a lot.", "words": [["compliment", "elogio"], ["generous", "generoso(a)"], ["thankful", "grato(a)"], ["grateful", "agradecido(a)"], ["kindness", "gentileza"], ["appreciate", "valorizar, agradecer"], ["thoughtful", "atencioso(a)"], ["means a lot", "significa muito"], ["modest", "modesto(a)"]]};
englishA2Content[322]=[[["Sam moved into a new apartment on Sunday, and he was very tired.", "O Sam se mudou para um apartamento novo no domingo e estava muito cansado."], ["In the evening, his neighbor Mrs. Green knocked and gave him a big chocolate cake.", "À noite, a vizinha dele, a Sra. Green, bateu na porta e lhe deu um bolo de chocolate grande."], ["\"That's so kind of you,\" Sam said. \"I'm really grateful.\"", "\"Que gentileza a sua\", disse o Sam. \"Fico muito agradecido.\""], ["She smiled and said, \"Nobody was generous to me when I moved here, so I try to be thoughtful.\"", "Ela sorriu e disse: \"Ninguém foi generoso comigo quando me mudei para cá, então tento ser atenciosa.\""], ["Sam tried the cake and gave her a compliment: \"It's the best cake I've ever had!\"", "O Sam provou o bolo e a elogiou: \"É o melhor bolo que já comi!\""], ["She is modest, so she only said, \"It's just flour, eggs, and love.\"", "Ela é modesta, então só disse: \"São só farinha, ovos e carinho.\""]], [["How was the move, Sam? Did the truck arrive on time?", "Como foi a mudança, Sam? O caminhão chegou na hora?"], ["Yes, thanks to you! It was so kind of you to drive me there.", "Sim, graças a você! Foi muita gentileza sua me levar até lá."], ["No problem. I was free on Sunday morning anyway.", "Imagina. Eu estava livre no domingo de manhã de qualquer jeito."], ["Still, I really appreciate your help. It means a lot to me.", "Mesmo assim, eu valorizo muito a sua ajuda. Significa muito para mim."], ["You're welcome. And thank you for the coffee you brought on Monday.", "De nada. E obrigada pelo café que você trouxe na segunda."], ["I'm just thankful to have a friend like you. Your kindness made everything easier.", "Só sou grato por ter uma amiga como você. Sua gentileza facilitou tudo."], ["That's so nice of you to say. Let's have lunch together on Friday.", "Que bonito você dizer isso. Vamos almoçar juntos na sexta."], ["Good idea! It's my treat, and I'll pick a place for noon.", "Boa ideia! Eu convido, e escolho um lugar para o meio-dia."]], ["/θ/ em thankful e thoughtful", "Para o /θ/ de thankful e thoughtful, ponha a ponta da língua entre os dentes e solte o ar; não troque por 't' nem 'f'.", ["thankful", "thoughtful"]], ["That's so kind ___ you.", "of", "from", "Que gentileza a sua.", "Com adjetivos sobre o caráter da pessoa usamos kind of you, não from you."], [["\"That's so kind of you,\" Sam said. \"I'm really grateful.\"", "\"Que gentileza a sua\", disse o Sam. \"Fico muito agradecido.\""], ["Yes, thanks to you! It was so kind of you to drive me there.", "Sim, graças a você! Foi muita gentileza sua me levar até lá."]], [{"t": "c", "q": "It was very thoughtful ___ you to call me.", "o": ["of", "for", "to"], "pt": "Foi muito atencioso da sua parte me ligar.", "why": "Para elogiar a atitude de alguém usamos adjetivo + of you."}, {"t": "l", "say": "I really appreciate your help.", "o": ["I really appreciate your help.", "I really appreciate you help.", "I really apologize your help."], "why": "Appreciate your help significa valorizar a ajuda; your mostra de quem é a ajuda."}, {"t": "b", "pt": "Isso significa muito para mim", "w": ["It", "means", "a", "lot", "to", "me"]}, {"t": "b", "pt": "Que gentileza a sua ajudar", "w": ["That's", "so", "kind", "of", "you", "to", "help"]}]];
