englishA2Plans[323]={"title": "Escolhendo o destino da viagem do grupo", "file": "", "grammar": "Discordar com educação: I see what you mean, but…", "goal": "Discorde sem brigar usando I see what you mean, but… e Fair enough.", "words": [["argument", "discussão, briga"], ["convince", "convencer"], ["fair enough", "justo, tudo bem"], ["reasonable", "razoável"], ["agree to disagree", "concordar em discordar"], ["debate", "debate"], ["attitude", "atitude"], ["objection", "objeção, ressalva"]]};
englishA2Content[323]=[[["Priya wants to take the group trip to the mountains, but Kenji wants the beach.", "A Priya quer levar a viagem do grupo para as montanhas, mas o Kenji quer a praia."], ["They had a long debate at lunch, and nobody wanted to change.", "Eles tiveram um longo debate no almoço, e ninguém quis mudar."], ["\"I see what you mean, but the beach is too crowded in July,\" Priya said.", "\"Entendo o que você quer dizer, mas a praia fica lotada em julho\", disse a Priya."], ["Kenji's attitude was calm, so they didn't start an argument.", "A atitude do Kenji foi calma, então eles não começaram uma briga."], ["In the end, they decided to agree to disagree and vote with the group.", "No fim, eles decidiram concordar em discordar e votar com o grupo."], ["Kenji smiled and said, \"Fair enough. Let's ask everybody.\"", "O Kenji sorriu e disse: \"Justo. Vamos perguntar a todo mundo.\""]], [["Kenji, I'd like to go to the mountains in July.", "Kenji, eu gostaria de ir para as montanhas em julho."], ["I see what you mean, but the beach is cheaper, and the hotels are bigger.", "Entendo o que você quer dizer, mas a praia é mais barata, e os hotéis são maiores."], ["Cheaper? I checked last night, and the beach hotels cost ninety dollars.", "Mais barata? Conferi ontem à noite, e os hotéis da praia custam noventa dólares."], ["Fair enough. But I have one objection: I hate hiking in the heat.", "Justo. Mas tenho uma objeção: odeio fazer trilha no calor."], ["That's reasonable. What if we start at six in the morning?", "É razoável. E se começarmos às seis da manhã?"], ["Hmm, I see your point, but I can't wake up that early.", "Hmm, entendo o seu ponto, mas não consigo acordar tão cedo."], ["Can I convince you with a lake? The water is cold, and we can swim.", "Posso te convencer com um lago? A água é fria, e podemos nadar."], ["A lake? OK, you've convinced me. Let's tell the others at dinner.", "Um lago? Tudo bem, você me convenceu. Vamos contar aos outros no jantar."]], ["/v/ em convince e vote", "No /v/ de convince e vote, os dentes de cima tocam o lábio de baixo e a voz vibra; não faça um 'b'.", ["convince", "vote"]], ["I see what you mean, ___ I don't agree.", "but", "because", "Entendo o que você quer dizer, mas não concordo.", "Para contrastar e discordar com educação usamos but, não because."], [["I see what you mean, but the beach is cheaper, and the hotels are bigger.", "Entendo o que você quer dizer, mas a praia é mais barata, e os hotéis são maiores."], ["\"I see what you mean, but the beach is too crowded in July,\" Priya said.", "\"Entendo o que você quer dizer, mas a praia fica lotada em julho\", disse a Priya."]], [{"t": "c", "q": "That's a ___ idea, but I prefer the beach.", "o": ["reasonable", "reasonably", "reason"], "pt": "É uma ideia razoável, mas prefiro a praia.", "why": "Antes de idea precisamos de um adjetivo: reasonable."}, {"t": "l", "say": "Fair enough. Let's vote.", "o": ["Fair enough. Let's vote.", "Fair enough. Let's vet.", "Far enough. Let's vote."], "why": "Fair enough aceita o argumento do outro; vote é votar."}, {"t": "b", "pt": "Entendo o que você quer dizer mas discordo", "w": ["I", "see", "what", "you", "mean", "but", "I", "disagree"]}, {"t": "b", "pt": "Você me convenceu com um lago", "w": ["You", "convinced", "me", "with", "a", "lake"]}]];
