englishA2Plans[324]={"title": "Briga por causa da louça na república", "file": "", "grammar": "Conflitos no trabalho e em casa: calm down e misunderstanding", "goal": "Resolva uma discussão com Let's calm down e Let's work it out.", "words": [["misunderstanding", "mal-entendido"], ["quarrel", "briga, discussão"], ["yell", "gritar"], ["annoyed", "irritado(a)"], ["cool off", "esfriar a cabeça"], ["lose my temper", "perder a paciência"], ["work it out", "resolver (a situação)"], ["give in", "ceder"], ["get on my nerves", "me irritar, dar nos nervos"]]};
englishA2Content[324]=[[["Noah and his roommate Ben had a quarrel about the dishes on Monday.", "O Noah e o colega de apartamento Ben brigaram por causa da louça na segunda."], ["Noah was annoyed because the sink was full of dirty plates.", "O Noah estava irritado porque a pia estava cheia de pratos sujos."], ["He started to yell, and Ben yelled back.", "Ele começou a gritar, e o Ben gritou de volta."], ["Then Noah said, \"Let's calm down. I don't want to lose my temper.\"", "Então o Noah disse: \"Vamos nos acalmar. Não quero perder a paciência.\""], ["They went for a walk to cool off.", "Eles saíram para caminhar e esfriar a cabeça."], ["It was only a misunderstanding: Ben thought it was Noah's turn.", "Foi só um mal-entendido: o Ben achou que era a vez do Noah."]], [["Ben, the dirty dishes really get on my nerves.", "Ben, a louça suja realmente me tira do sério."], ["I'm sorry. I thought you were going to wash them last night.", "Desculpe. Achei que você ia lavar ontem à noite."], ["No, it was your turn. We made a list on the fridge, remember?", "Não, era a sua vez. Fizemos uma lista na geladeira, lembra?"], ["Oh, I read it wrong. It's a misunderstanding, not a fight.", "Ah, eu li errado. É um mal-entendido, não uma briga."], ["Maybe. But I don't want to give in every time and wash everything.", "Talvez. Mas não quero ceder toda vez e lavar tudo."], ["Of course not. Let's work it out. I'll wash on Mondays and Thursdays.", "Claro que não. Vamos resolver isso. Eu lavo às segundas e quintas."], ["That sounds fair. I'll take Tuesdays and Fridays.", "Parece justo. Eu pego as terças e as sextas."], ["Deal. And I'll wash today's plates right now.", "Fechado. E vou lavar os pratos de hoje agora mesmo."]], ["/j/ em yell e yelled", "Em yell comece com um 'i' bem rápido, como em 'iéu'; não pronuncie como 'djell'.", ["yell", "yelled"]], ["It was only a ___ about the schedule.", "misunderstanding", "misunderstand", "Foi só um mal-entendido sobre o horário.", "Depois de a precisamos de um substantivo: misunderstanding; misunderstand é verbo."], [["Then Noah said, \"Let's calm down. I don't want to lose my temper.\"", "Então o Noah disse: \"Vamos nos acalmar. Não quero perder a paciência.\""], ["It was only a misunderstanding: Ben thought it was Noah's turn.", "Foi só um mal-entendido: o Ben achou que era a vez do Noah."]], [{"t": "c", "q": "Please ___ down. We can talk about it.", "o": ["calm", "cold", "quick"], "pt": "Por favor, acalme-se. Podemos conversar sobre isso.", "why": "A expressão fixa é calm down."}, {"t": "l", "say": "Don't yell at me!", "o": ["Don't yell at me!", "Don't tell at me!", "Don't yelled at me!"], "why": "Yell é gritar; depois de don't o verbo fica na forma base."}, {"t": "b", "pt": "Vamos resolver isso", "w": ["Let's", "work", "it", "out"]}, {"t": "b", "pt": "Eu não quero perder a paciência", "w": ["I", "don't", "want", "to", "lose", "my", "temper"]}]];
