englishA2Plans[325]={"title": "Cuidando do avô com gripe", "file": "", "grammar": "Cuidar de um amigo ou parente: look after e take care of", "goal": "Fale sobre cuidar de alguém com look after e take care of.", "words": [["look after", "cuidar de"], ["take care of", "tomar conta de"], ["elderly", "idoso(a)"], ["comfort", "conforto, consolo"], ["check on", "dar uma olhada em, ver como está"], ["cheer up", "animar(-se)"], ["support", "apoio"], ["patience", "paciência"], ["worry", "preocupar-se"]]};
englishA2Content[325]=[[["Elena's grandfather is elderly, and he lives alone.", "O avô da Elena é idoso e mora sozinho."], ["Last week he had the flu, so Elena went to look after him.", "Na semana passada ele teve gripe, então a Elena foi cuidar dele."], ["Every morning she went to check on him and make soup.", "Toda manhã ela ia ver como ele estava e fazer sopa."], ["He felt sad, so she smiled and said, \"Cheer up, Grandpa!\"", "Ele estava triste, então ela sorriu e disse: \"Anime-se, vovô!\""], ["\"Don't worry. I'll take care of everything,\" she told him.", "\"Não se preocupe. Eu cuido de tudo\", ela disse a ele."], ["With a little patience and a lot of tea, he felt better on Friday.", "Com um pouco de paciência e muito chá, ele se sentiu melhor na sexta."]], [["How's Grandpa today? Did he eat anything?", "Como está o vovô hoje? Ele comeu alguma coisa?"], ["He had soup and toast. He's still tired, but he's smiling.", "Ele tomou sopa e comeu torrada. Ainda está cansado, mas está sorrindo."], ["I want to take care of him too, but I live two hours away.", "Eu quero cuidar dele também, mas moro a duas horas daqui."], ["Don't feel bad. Your calls are a big comfort to him.", "Não se sinta mal. Suas ligações são um grande consolo para ele."], ["Really? Then I'll call every night. Does he need anything?", "Sério? Então vou ligar toda noite. Ele precisa de alguma coisa?"], ["Medicine from the pharmacy and some company. Can you visit on Saturday?", "Remédio da farmácia e um pouco de companhia. Você pode visitar no sábado?"], ["Of course. I'll bring lunch. You need some support too, Elena.", "Claro. Levo o almoço. Você também precisa de apoio, Elena."], ["Thanks, Aunt Rosa. See you Saturday at noon.", "Obrigada, tia Rosa. Até sábado ao meio-dia."]], ["/tʃ/ em cheer e check", "O /tʃ/ de cheer e check é como o 'tch' de 'tchau': a língua encosta no céu da boca e solta o ar de uma vez.", ["cheer", "check"]], ["Can you ___ my cat while I'm away?", "look after", "look for", "Você pode cuidar do meu gato enquanto eu estiver fora?", "Look after significa cuidar de; look for significa procurar."], [["Last week he had the flu, so Elena went to look after him.", "Na semana passada ele teve gripe, então a Elena foi cuidar dele."], ["I want to take care of him too, but I live two hours away.", "Eu quero cuidar dele também, mas moro a duas horas daqui."]], [{"t": "c", "q": "My sister will ___ my plants this week.", "o": ["take care of", "take away", "take off"], "pt": "Minha irmã vai cuidar das minhas plantas esta semana.", "why": "Take care of significa tomar conta de; os outros têm outro sentido."}, {"t": "l", "say": "Don't worry. I'll check on him.", "o": ["Don't worry. I'll check on him.", "Don't worry. I'll check him out.", "Don't hurry. I'll cheer on him."], "why": "Check on him é ver como ele está."}, {"t": "b", "pt": "Eu cuido da minha avó", "w": ["I", "look", "after", "my", "grandmother"]}, {"t": "b", "pt": "Ele precisa de um pouco de paciência", "w": ["He", "needs", "a", "little", "patience"]}]];
