englishA2Plans[326]={"title": "Despedida da Priya no aeroporto", "file": "", "grammar": "Despedidas e saudade: miss e keep in touch", "goal": "Despeça-se de um amigo com I'm going to miss you e Please keep in touch.", "words": [["say goodbye", "dizer adeus"], ["see you off", "se despedir de você (no embarque)"], ["stay in touch", "manter contato"], ["lose touch", "perder o contato"], ["write back", "responder (por escrito)"], ["far away", "muito longe"], ["get together", "se reunir"], ["bond", "laço, vínculo"], ["affection", "carinho, afeto"]]};
englishA2Content[326]=[[["Priya is moving to Canada for a new job, so her friends went to the airport on Saturday.", "A Priya está se mudando para o Canadá por causa de um novo emprego, então os amigos foram ao aeroporto no sábado."], ["It was hard to say goodbye after ten years of friendship.", "Foi difícil dizer adeus depois de dez anos de amizade."], ["Mia gave her a notebook and said, \"I'll write back to every email.\"", "A Mia deu a ela um caderno e disse: \"Vou responder a todos os e-mails.\""], ["Canada is far away, but their bond is strong.", "O Canadá é muito longe, mas o laço entre eles é forte."], ["\"I don't want to lose touch,\" Priya said, and she hugged everyone.", "\"Não quero perder o contato\", disse a Priya, e abraçou todo mundo."], ["Then she walked to the gate and waved until they couldn't see her.", "Então ela foi até o portão e acenou até não poderem mais vê-la."]], [["We came to see you off. Your flight leaves at six, right?", "Viemos nos despedir de você. Seu voo sai às seis, né?"], ["Yes, at six-fifteen. I'm going to miss you so much.", "Sim, às seis e quinze. Vou sentir tanta saudade de vocês."], ["We'll miss you too. Please keep in touch. Call us every Sunday.", "Nós também vamos sentir sua falta. Por favor, mantenha contato. Ligue para nós todo domingo."], ["I will. And let's stay in touch on video chat, too.", "Vou ligar. E vamos manter contato por videochamada também."], ["Good idea. And when you visit in December, we'll get together at my place.", "Boa ideia. E quando você nos visitar em dezembro, vamos nos reunir na minha casa."], ["I can't wait. I'll bring maple cookies and lots of affection.", "Mal posso esperar. Vou levar biscoitos de bordo e muito carinho."], ["Ha! Just bring the cookies. Now go, or you'll miss the plane.", "Ha! Só leve os biscoitos. Agora vá, ou você vai perder o avião."], ["Bye, Mia. I'll text you when I land. Love you!", "Tchau, Mia. Mando mensagem quando eu pousar. Amo você!"]], ["/ʌ/ em touch e love", "Em touch e love a letra 'o' soa como /ʌ/, curto, como o 'a' de 'cama' falado rápido; não diga 'tóch' nem 'lóv' aberto.", ["touch", "love"]], ["Please keep in ___ with me.", "touch", "contact", "Por favor, mantenha contato comigo.", "A expressão fixa é keep in touch; contact não combina com in."], [["Yes, at six-fifteen. I'm going to miss you so much.", "Sim, às seis e quinze. Vou sentir tanta saudade de vocês."], ["We'll miss you too. Please keep in touch. Call us every Sunday.", "Nós também vamos sentir sua falta. Por favor, mantenha contato. Ligue para nós todo domingo."]], [{"t": "c", "q": "I'm going to ___ you when I move away.", "o": ["miss", "lose", "lack"], "pt": "Vou sentir sua falta quando eu me mudar.", "why": "Miss you é sentir saudade de você."}, {"t": "l", "say": "Let's stay in touch.", "o": ["Let's stay in touch.", "Let's stay in town.", "Let's stay in tough."], "why": "Stay in touch é manter contato."}, {"t": "b", "pt": "Eu vou sentir saudade de você", "w": ["I'm", "going", "to", "miss", "you"]}, {"t": "b", "pt": "Por favor mantenha contato", "w": ["Please", "keep", "in", "touch"]}]];
