englishA2Plans[327]={"title": "Como conheci meu melhor amigo", "file": "", "grammar": "Contar uma história pessoal em ordem: when, while e after", "goal": "Conte uma lembrança em ordem com when, while e after.", "words": [["childhood", "infância"], ["grow up", "crescer"], ["mischief", "travessura"], ["accidentally", "sem querer"], ["end up", "acabar (fazendo)"], ["turn out", "acabar sendo, resultar"], ["eventually", "com o tempo, por fim"], ["afterwards", "depois, em seguida"], ["luckily", "felizmente"]]};
englishA2Content[327]=[[["In my childhood, I lived next to a boy named Leo.", "Na minha infância, eu morava ao lado de um menino chamado Leo."], ["When we were eight, we accidentally broke a neighbor's window with a ball.", "Quando tínhamos oito anos, quebramos sem querer a janela de um vizinho com uma bola."], ["While we were hiding behind a tree, the neighbor came out and laughed.", "Enquanto nos escondíamos atrás de uma árvore, o vizinho saiu e riu."], ["Luckily, he wasn't angry, and afterwards he gave us ice cream.", "Felizmente ele não ficou bravo e, depois, nos deu sorvete."], ["After that day, we got into mischief together every summer.", "Depois daquele dia, fazíamos travessuras juntos todo verão."], ["Today we're adults, and Leo is still my best friend.", "Hoje somos adultos, e o Leo ainda é meu melhor amigo."]], [["Kenji, where did you grow up?", "Kenji, onde você cresceu?"], ["In a small town near Osaka. When I was ten, I broke my arm.", "Numa cidade pequena perto de Osaka. Quando eu tinha dez anos, quebrei o braço."], ["Ouch! How did it happen?", "Ai! Como foi que aconteceu?"], ["While I was riding my bike down a hill, a dog ran in front of me.", "Enquanto eu descia uma ladeira de bicicleta, um cachorro correu na minha frente."], ["Poor you! What happened after that?", "Coitado! O que aconteceu depois?"], ["I stayed home for a month, and eventually I learned to draw with my left hand.", "Fiquei em casa um mês e, com o tempo, aprendi a desenhar com a mão esquerda."], ["Wow. And did you end up becoming an artist?", "Uau. E você acabou virando artista?"], ["Yes! Things turn out strange sometimes. Now I draw comics for a magazine.", "Sim! As coisas acabam de um jeito estranho às vezes. Hoje desenho quadrinhos para uma revista."]], ["/w/ em while e window", "No /w/ de while e window os lábios ficam bem arredondados, como em 'uau'; não comece com 'v' nem com 'u' mudo.", ["while", "window"]], ["I broke my arm ___ I was riding my bike.", "while", "during", "Eu quebrei o braço enquanto andava de bicicleta.", "While vem antes de um sujeito e verbo; during é seguido só de substantivo."], [["While I was riding my bike down a hill, a dog ran in front of me.", "Enquanto eu descia uma ladeira de bicicleta, um cachorro correu na minha frente."], ["While we were hiding behind a tree, the neighbor came out and laughed.", "Enquanto nos escondíamos atrás de uma árvore, o vizinho saiu e riu."]], [{"t": "c", "q": "___ I was cooking, the phone rang.", "o": ["While", "During", "Meanwhile"], "pt": "Enquanto eu cozinhava, o telefone tocou.", "why": "While liga uma ação em andamento a outra, com sujeito e verbo depois."}, {"t": "l", "say": "After dinner, we watched a movie.", "o": ["After dinner, we watched a movie.", "Before dinner, we watched a movie.", "After dinner, we watch a movie."], "why": "After dinner é depois do jantar, e watched mostra o passado."}, {"t": "b", "pt": "Quando eu tinha dez anos eu quebrei o braço", "w": ["When", "I", "was", "ten", "I", "broke", "my", "arm"]}, {"t": "b", "pt": "Eu cresci numa cidade pequena", "w": ["I", "grew", "up", "in", "a", "small", "town"]}]];
