englishA2Plans[328]={"title": "Planos depois da formatura", "file": "", "grammar": "Planos para o futuro: I hope to e I'm planning to", "goal": "Fale dos seus planos com I hope to e I'm planning to.", "words": [["ambitious", "ambicioso(a)"], ["dream job", "emprego dos sonhos"], ["go abroad", "ir para o exterior"], ["come true", "virar realidade"], ["settle down", "assentar, ter uma vida estável"], ["graduated", "formou-se"], ["independent", "independente"], ["someday", "algum dia"]]};
englishA2Content[328]=[[["Mia graduated from college in June, and she is very ambitious.", "A Mia se formou na faculdade em junho e é muito ambiciosa."], ["She hopes to find her dream job as a travel photographer.", "Ela espera encontrar o emprego dos sonhos como fotógrafa de viagens."], ["First, she's planning to go abroad for a year, maybe to Spain.", "Primeiro, ela está planejando ir para o exterior por um ano, talvez para a Espanha."], ["She wants to be independent, so she's saving money for the trip.", "Ela quer ser independente, por isso está juntando dinheiro para a viagem."], ["Her parents hope to visit her in the spring.", "Os pais dela esperam visitá-la na primavera."], ["\"Someday I'll show my photos in a museum,\" she says, \"and my dream will come true.\"", "\"Algum dia vou expor minhas fotos num museu\", diz ela, \"e meu sonho vai virar realidade.\""]], [["So, Mia, what are your plans after college?", "Então, Mia, quais são os seus planos depois da faculdade?"], ["I hope to work for a travel magazine. What about you?", "Espero trabalhar para uma revista de viagens. E você?"], ["I'm planning to move to Chicago and open a small bakery.", "Estou planejando me mudar para Chicago e abrir uma padaria pequena."], ["A bakery? That's a big plan! Are you going to live alone?", "Uma padaria? É um grande plano! Você vai morar sozinho?"], ["Yes, I'm tired of living with my parents. I want to be independent.", "Sim, cansei de morar com meus pais. Quero ser independente."], ["Me too. But someday I want to settle down and have a family.", "Eu também. Mas algum dia quero assentar e ter uma família."], ["Same here. I hope to buy a house near the beach in ten years.", "Eu também. Espero comprar uma casa perto da praia em dez anos."], ["Great! Let's meet in Chicago and have a coffee at your bakery in 2030.", "Ótimo! Vamos nos encontrar em Chicago e tomar um café na sua padaria em 2030."]], ["/dʒ/ em graduated e job", "O /dʒ/ de graduated e job é como o 'dj' de 'djavu': a língua encosta atrás dos dentes e a voz vibra.", ["graduated", "job"]], ["I'm planning ___ a small bakery.", "to open", "opening", "Estou planejando abrir uma padaria pequena.", "Depois de plan usamos to + verbo na forma base, não -ing."], [["I hope to work for a travel magazine. What about you?", "Espero trabalhar para uma revista de viagens. E você?"], ["I'm planning to move to Chicago and open a small bakery.", "Estou planejando me mudar para Chicago e abrir uma padaria pequena."]], [{"t": "c", "q": "I hope ___ Japan next year.", "o": ["to visit", "visiting", "visit"], "pt": "Espero visitar o Japão no ano que vem.", "why": "Depois de hope usamos to + verbo."}, {"t": "l", "say": "I'm planning to go abroad.", "o": ["I'm planning to go abroad.", "I'm planning go abroad.", "I planned to going abroad."], "why": "Planning é seguido de to + verbo: to go abroad."}, {"t": "b", "pt": "Espero encontrar o emprego dos sonhos", "w": ["I", "hope", "to", "find", "my", "dream", "job"]}, {"t": "b", "pt": "Estou planejando ir para o exterior", "w": ["I'm", "planning", "to", "go", "abroad"]}]];
