englishA2Plans[329]={"title": "Conversa de fim de curso com a professora", "file": "", "grammar": "Revisão final do A2: conversa sobre tudo que aprendi", "goal": "Revise o que aprendeu falando do seu progresso, de desculpas, de planos e de agradecimentos.", "words": [["progress", "progresso"], ["challenge", "desafio"], ["confidence", "confiança"], ["courage", "coragem"], ["achievement", "conquista"], ["unexpected", "inesperado"], ["keep going", "continuar, seguir em frente"], ["lifelong", "para a vida toda"]]};
englishA2Content[329]=[[["Today Noah finished his last English class, and he felt proud.", "Hoje o Noah terminou a última aula de inglês e sentiu orgulho."], ["One year ago, he was afraid to speak, and every conversation was a challenge.", "Um ano atrás, ele tinha medo de falar, e toda conversa era um desafio."], ["Now he makes friends easily, and he talks with confidence.", "Agora ele faz amigos com facilidade e fala com confiança."], ["His teacher, Ms. Lee, told him, \"You made a lot of progress.\"", "A professora dele, a Sra. Lee, disse: \"Você fez muito progresso.\""], ["The best part was unexpected: he found friends from six countries.", "A melhor parte foi inesperada: ele fez amigos de seis países."], ["\"I'm going to keep going,\" he said, \"because learning is a lifelong adventure.\"", "\"Vou continuar\", disse ele, \"porque aprender é uma aventura para a vida toda.\""]], [["Congratulations, Noah! How do you feel on the last day?", "Parabéns, Noah! Como você se sente no último dia?"], ["A little sad, but very proud. I remember my first class. I was so nervous.", "Um pouco triste, mas muito orgulhoso. Lembro da primeira aula. Eu estava tão nervoso."], ["It took courage to speak in front of everyone. I'm sorry for being strict sometimes.", "Foi preciso coragem para falar na frente de todos. Desculpe por ser rígida às vezes."], ["It doesn't matter. Your tips helped me a lot, and I really appreciate them.", "Não importa. Suas dicas me ajudaram muito, e eu valorizo muito cada uma."], ["What was your biggest achievement this year?", "Qual foi a sua maior conquista este ano?"], ["Last month I talked to an American tourist for twenty minutes. He said my English was great!", "No mês passado conversei com um turista americano por vinte minutos. Ele disse que meu inglês era ótimo!"], ["Wonderful! Did you use your phone to translate?", "Maravilhoso! Você usou o celular para traduzir?"], ["No, not once. I just asked him, \"How do you know this café?\" and we became friends.", "Não, nenhuma vez. Só perguntei: \"De onde você conhece este café?\" e viramos amigos."], ["That's the best way to learn. What are you going to do next?", "Essa é a melhor forma de aprender. O que você vai fazer agora?"], ["I hope to take the B1 course in September. I'll keep going every day.", "Espero fazer o curso B1 em setembro. Vou continuar todo dia."]], ["/tʃ/ em challenge e achievement", "O /tʃ/ de challenge e achievement é o 'tch' de 'tchau'; em challenge ele abre a palavra, em achievement fica no meio.", ["challenge", "achievement"]], ["I made a lot of ___ this year.", "progress", "progresses", "Eu fiz muito progresso este ano.", "Progress é incontável e não leva -s no plural."], [["His teacher, Ms. Lee, told him, \"You made a lot of progress.\"", "A professora dele, a Sra. Lee, disse: \"Você fez muito progresso.\""], ["I hope to take the B1 course in September. I'll keep going every day.", "Espero fazer o curso B1 em setembro. Vou continuar todo dia."]], [{"t": "c", "q": "Learning English takes ___ and patience.", "o": ["courage", "courageous", "courageously"], "pt": "Aprender inglês exige coragem e paciência.", "why": "Depois de takes e antes de and precisamos de um substantivo: courage."}, {"t": "l", "say": "I hope to keep going every day.", "o": ["I hope to keep going every day.", "I hope keep going every day.", "I hope to keeping going every day."], "why": "Depois de hope usamos to + verbo na forma base: to keep."}, {"t": "b", "pt": "Eu estou muito orgulhoso do meu progresso", "w": ["I'm", "very", "proud", "of", "my", "progress"]}, {"t": "b", "pt": "Desculpe por chegar atrasado", "w": ["I'm", "sorry", "for", "being", "late"]}]];
englishA2PhotoThemes[329]="notebook";
englishA2MiniStories[329]=["Um ano de conversas", "Last January, Priya moved to a new city, and she didn't know anyone.~Em janeiro passado, a Priya se mudou para uma cidade nova e não conhecia ninguém.|One day she ran into Omar, and they found out they have a lot in common.~Um dia ela topou com o Omar, e descobriram que têm muito em comum.|Soon they were hanging out every weekend, and Omar cooked for her.~Logo eles estavam saindo todo fim de semana, e o Omar cozinhava para ela.|When she forgot his birthday, she said, \"I'm sorry for forgetting.\"~Quando ela esqueceu o aniversário dele, disse: \"Desculpe por esquecer.\"|Omar smiled and said, \"It doesn't matter. Thanks for calling me.\"~O Omar sorriu e disse: \"Não importa. Obrigado por me ligar.\"|They disagreed about a trip, so she said, \"I see what you mean, but I prefer the mountains.\"~Eles discordaram sobre uma viagem, então ela disse: \"Entendo o que você quer dizer, mas prefiro as montanhas.\"|After they calmed down, they decided to go to a lake.~Depois que se acalmaram, decidiram ir a um lago.|While Omar was sick in June, Priya took care of him.~Enquanto o Omar estava doente em junho, a Priya cuidou dele.|In December, she went home for a visit, and Omar promised to keep in touch.~Em dezembro, ela voltou para casa para uma visita, e o Omar prometeu manter contato.|Now she hopes to open a bookshop, and she is planning to ask Omar to be her partner.~Agora ela espera abrir uma livraria e está planejando convidar o Omar para ser sócio."];
